import { z } from 'zod';
import { createEndpoint, Tugas } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create or update a tugas',
  authenticated: true,
  inputSchema: z.object({
    id: z.string().optional(),
    judulTugas: z.string(),
    deskripsi: z.string().optional(),
    jenisTugas: z.string(),
    guruId: z.string(),
    kelasId: z.string(),
    mapelId: z.string(),
    tanggalDiberikan: z.string(),
    deadline: z.string(),
    catatan: z.string().optional(),
    status: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  execute: async ({ input }) => {
    const record = {
      judulTugas: input.judulTugas,
      deskripsi: input.deskripsi || '',
      jenisTugas: input.jenisTugas as any,
      guru: input.guruId,
      kelas: input.kelasId,
      mataPelajaran: input.mapelId,
      tanggalDiberikan: input.tanggalDiberikan,
      deadline: input.deadline,
      catatan: input.catatan || '',
      status: (input.status || 'Aktif') as any,
    };

