import { z } from 'zod';
import { createEndpoint, Pengumuman, Sekolah } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Mengambil 5 pengumuman teratas dan nomor telepon admin sekolah',
  inputSchema: z.object({}),
  outputSchema: z.object({
    notifications: z.array(z.object({
      id: z.string(),
      judul: z.string().optional(),
      tanggalPublish: z.string().optional(),
      target: z.string().optional(),
    })),
    adminPhone: z.string(),
  }),
  execute: async ({ context }) => {
    const sekolahId = Array.isArray(context.user.sekolah)
      ? context.user.sekolah[0]
      : context.user.sekolah;

    const [pengResult, sekolah] = await Promise.all([
      Pengumuman.findAll({ filters: sekolahId ? { sekolah: sekolahId } : {}, limit: 50 }),
      sekolahId ? Sekolah.findOne({ id: sekolahId }) : Promise.resolve(null),
    ]);

    const sorted = [...pengResult.records].sort((a, b) => {
      const da = a.tanggalPublish ? new Date(a.tanggalPublish).getTime() : 0;
      const db = b.tanggalPublish ? new Date(b.tanggalPublish).getTime() : 0;
      return db - da;
    }).slice(0, 5);

    return {
      notifications: sorted.map(p => ({
        id: p.id,
        judul: p.judul,
        tanggalPublish: p.tanggalPublish,
        target: p.target,
      })),
      adminPhone: sekolah?.telepon || '',
    };
  },
});

