import { z } from 'zod';
import { createEndpoint, Guru } from 'zite-integrations-backend-sdk';

const guruRowSchema = z.object({
  namaLengkap: z.string(),
  nipnuptk: z.string().optional(),
  nik: z.string().optional(),
  jenisKelamin: z.string().optional(),
  tempatLahir: z.string().optional(),
  tanggalLahir: z.string().optional(),
  noHp: z.string().optional(),
  email: z.string().optional(),
  alamat: z.string().optional(),
  pendidikanTerakhir: z.string().optional(),
  tugasUtama: z.string().optional(),
  tugasTambahan: z.string().optional(),
  mulaiBertugas: z.string().optional(),
  akhirBertugas: z.string().optional(),
  usernameGuru: z.string().optional(),
  passwordGuru: z.string().optional(),
});

export default createEndpoint({
  authenticated: true,
  description: 'Import data guru & tendik dari CSV secara bulk',
  inputSchema: z.object({
    statusKepegawaian: z.string().optional(),
    kategoriPegawai: z.array(z.string()).optional(),
    rows: z.array(guruRowSchema),
  }),
  outputSchema: z.object({
    imported: z.number(),
    errors: z.array(z.string()),
  }),
  execute: async ({ input, context }) => {
    const sekolahId = Array.isArray(context.user.sekolah)
      ? context.user.sekolah[0]
      : context.user.sekolah;

    const errors: string[] = [];
    const validRecords = input.rows
      .map((row, index) => {
        if (!row.namaLengkap) {
          errors.push(`Baris ${index + 2}: Nama Lengkap wajib diisi`);
          return null;
        }
        // If multiple kategori selected, create one entry per kategori
        const kategoriList = (input.kategoriPegawai && input.kategoriPegawai.length > 0)
          ? input.kategoriPegawai
          : ['Guru'];
        return kategoriList.map(kategori => ({
          namaLengkap: row.namaLengkap,
          nipnuptk: row.nipnuptk || undefined,
          nik: row.nik || undefined,
          jenisKelamin: row.jenisKelamin || undefined,
          tempatLahir: row.tempatLahir || undefined,
          tanggalLahir: row.tanggalLahir || undefined,
          noHp: row.noHp || undefined,
          email: row.email || undefined,
          alamat: row.alamat || undefined,
          pendidikanTerakhir: row.pendidikanTerakhir || undefined,
          statusKepegawaian: input.statusKepegawaian || undefined,
          kategoriPegawai: kategori,
          tugasUtama: row.tugasUtama || undefined,
          tugasTambahan: row.tugasTambahan
            ? row.tugasTambahan.split(';').map(s => s.trim()).filter(Boolean)
            : undefined,
          mulaiBertugas: row.mulaiBertugas || undefined,
          akhirBertugas: row.akhirBertugas || undefined,
          usernameGuru: row.usernameGuru || undefined,
          passwordGuru: row.passwordGuru || undefined,
          active: true,
          sekolah: sekolahId,
        }));
      })
      .filter((r): r is NonNullable<typeof r> => r !== null)
      .flat();

    let imported = 0;
    for (let i = 0; i < validRecords.length; i += 100) {
      const chunk = validRecords.slice(i, i + 100);
      await Guru.bulkCreate({ records: chunk });
      imported += chunk.length;
    }

    return { imported, errors };
  },
});

