// ─── Legend / Keterangan table ───

function renderLegendHtml(legend: CodeEntry[]): string {
  // Split legend into columns (3 columns side by side)
  const colSize = Math.ceil(legend.length / 3);
  const cols = [legend.slice(0, colSize), legend.slice(colSize, colSize * 2), legend.slice(colSize * 2)];

  let html = `<div class="legend-section"><h3>Keterangan Kode Guru &amp; Mata Pelajaran:</h3><div style="display:flex;gap:16px;flex-wrap:wrap;">`;
  for (const col of cols) {
    if (col.length === 0) continue;
    html += `<table class="legend-table"><thead><tr><th>Kode</th><th>Guru</th><th>Mapel</th></tr></thead><tbody>`;
    for (const entry of col) {
      html += `<tr><td class="code-col">${esc(entry.code)}</td><td>${esc(entry.guruNama)}</td><td>${esc(entry.mapelNama)}</td></tr>`;
    }
    html += `</tbody></table>`;
  }
  html += `</div></div>`;
  return html;
}

// ─── Single-kelas table (full mapel/guru name – unchanged) ───

function buildSingleTable(
  jadwal: { hari: string; jamMulai: string; jamSelesai: string; mapelNama: string; mapelKode?: string; guruNama: string }[],
  settings: JadwalSettings,
): string {
  const days = settings.hariAktif.filter(h => HARI_LIST.includes(h));
  const jpSlots = settings.slots.filter(s => !isSpecialSlot(s));
  const lookup = buildFlatLookup(jadwal, jpSlots);

  let rows = '';
  for (const slot of settings.slots) {
    if (isSpecialSlot(slot)) {
      const st = getSlotType(slot);
      if (st === 'jp') continue;
      const config = SPECIAL_SLOT_CONFIG[st];
      const label = slot.label || config.label;
      const isUpacara = st === 'upacara';
      const cls = st === 'sholat' ? 'special-cell sholat-cell' : st === 'upacara' ? 'special-cell upacara-cell' : 'special-cell';
      rows += `<tr><td class="time-col">${slot.mulai}–${slot.selesai}</td><td class="jp-col">${config.icon}</td>`;
      if (isUpacara) {
        for (const d of days) rows += d === 'Senin' ? `<td class="${cls}">${config.icon} ${esc(label)}</td>` : `<td class="empty-cell">–</td>`;
      } else {
        rows += `<td colspan="${days.length}" class="${cls}">${config.icon} ${esc(label)}</td>`;
      }
      rows += `</tr>`;
      continue;
    }
    rows += `<tr><td class="time-col">${slot.mulai}–${slot.selesai}</td><td class="jp-col">${slot.jp}</td>`;
    for (const d of days) {
      const e = lookup[`${d}-${slot.jp}`];
      if (e) {
        rows += `<td class="entry-cell"><div class="entry-mapel">${esc(e.mapelNama)}</div><div class="entry-guru">${esc(e.guruNama)}</div></td>`;
      } else {
        rows += `<td class="empty-cell">–</td>`;
      }
    }
    rows += `</tr>`;
  }

  const hdr = days.map(d => `<th class="day-header">${d}</th>`).join('');
  return `<table><thead><tr><th class="time-col">Waktu</th><th class="jp-col">JP</th>${hdr}</tr></thead><tbody>${rows}</tbody></table>`;
}

// ─── All-kelas table: days as groups, classes as sub-columns, CODES in cells ───

function buildAllKelasTableCoded(
  allData: KelasJadwalData[],
  settings: JadwalSettings,
  codeMap: Record<string, string>,
): string {
  const days = settings.hariAktif.filter(h => HARI_LIST.includes(h));
  const jpSlots = settings.slots.filter(s => !isSpecialSlot(s));
  const kelasNames = allData.map(k => k.kelasNama);
  const numKelas = kelasNames.length;
  const totalDataCols = days.length * numKelas;

  const lookups = allData.map(kd => buildFlatLookup(kd.jadwal, jpSlots));

  let hdr1 = `<th class="time-col" rowspan="2">Waktu</th><th class="jp-col" rowspan="2">JP</th>`;
  for (const d of days) {
    hdr1 += `<th class="day-header" colspan="${numKelas}">${d}</th>`;
  }

  let hdr2 = '';
  for (let _d = 0; _d < days.length; _d++) {
    for (const kn of kelasNames) {
      const short = kn.replace(/Kelas\s*/i, '').replace(/\s*–\s*/g, ' ').trim();
      hdr2 += `<th class="kelas-header">${esc(short)}</th>`;
    }
  }

  let rows = '';
  for (const slot of settings.slots) {
    if (isSpecialSlot(slot)) {
      const st = getSlotType(slot);
      if (st === 'jp') continue;
      const config = SPECIAL_SLOT_CONFIG[st];
      const label = slot.label || config.label;
      const cls = st === 'sholat' ? 'special-cell sholat-cell' : st === 'upacara' ? 'special-cell upacara-cell' : 'special-cell';
      rows += `<tr><td class="time-col">${slot.mulai}–${slot.selesai}</td><td class="jp-col">${config.icon}</td><td colspan="${totalDataCols}" class="${cls}">${config.icon} ${esc(label)}</td></tr>`;
      continue;
    }

    rows += `<tr><td class="time-col">${slot.mulai}–${slot.selesai}</td><td class="jp-col">${slot.jp}</td>`;
    for (const d of days) {
      for (let ki = 0; ki < numKelas; ki++) {
        const e = lookups[ki][`${d}-${slot.jp}`];
        if (e) {
          const code = getCode(codeMap, e.guruNama, e.mapelNama);
          rows += `<td class="code-cell">${esc(code)}</td>`;
        } else {
          rows += `<td class="empty-cell">–</td>`;
        }
      }
    }
    rows += `</tr>`;
  }

  return `<table><thead><tr>${hdr1}</tr><tr>${hdr2}</tr></thead><tbody>${rows}</tbody></table>`;
}

