  const nk = kelasNames.length;
  const totalDataCols = days.length * nk;
  const cols = totalDataCols + 2;
  const lookups = allData.map(kd => buildFlatLookup(kd.jadwal, jpSlots));

  const { codeMap, legend } = buildGuruMapelCodes(allData);

  // Header row 1: day groups
  let hdr1 = `<th style="${thStyle}" rowspan="2">Waktu</th><th style="${thStyle}" rowspan="2">JP</th>`;
  for (const d of days) hdr1 += `<th style="${thStyle}" colspan="${nk}">${d}</th>`;

