import { useEffect, useState } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { Link } from 'react-router-dom';
import { getDashboardStats, GetDashboardStatsOutputType } from 'zite-endpoints-sdk';
import { Users, GraduationCap, BookOpen, DollarSign, AlertTriangle, CheckCircle2, ArrowRight } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';

type Stat = {
  label: string;
  value: string;
  icon: React.ElementType;
  accent: string;
};

function StatCard({ label, value, icon: Icon, accent }: Stat) {
  return (
    <div className="bg-card rounded-2xl border border-border p-5 flex items-center gap-4 shadow-sm">
      <div
        className="h-12 w-12 rounded-xl flex items-center justify-center flex-shrink-0"
        style={{ backgroundColor: `hsl(var(${accent}) / 0.15)` }}
      >
        <Icon className="h-6 w-6" style={{ color: `hsl(var(${accent}))` }} />
      </div>
      <div>
        <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
        <p className="text-2xl font-black text-foreground">{value}</p>
      </div>
    </div>
  );
}

export default function Dashboard() {
  const { user } = useAuth();
  const [stats, setStats] = useState<GetDashboardStatsOutputType | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getDashboardStats({})
      .then(setStats)
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const displayName = user?.firstName || user?.email?.split('@')[0] || 'Admin';
  const isGuru = user?.role === 'Guru';

  const statCards: Stat[] = stats
    ? [
        { label: 'Total Siswa',   value: stats.totalSiswa.toLocaleString('id-ID'),  icon: Users,        accent: '--chart-2' },
        { label: 'Guru & Tendik', value: stats.totalGuru.toLocaleString('id-ID'),   icon: GraduationCap, accent: '--chart-1' },
        { label: 'Rombel',        value: stats.totalKelas.toLocaleString('id-ID'),  icon: BookOpen,     accent: '--chart-3' },
        { label: 'Tagihan Pending', value: stats.tagihanBelumLunas.toLocaleString('id-ID'), icon: DollarSign, accent: '--chart-4' },
      ]
    : [];

  const jurnalPct = stats && stats.jurnalHariIni.total > 0
    ? Math.round((stats.jurnalHariIni.terisi / stats.jurnalHariIni.total) * 100)
    : 0;

  return (
    <div className="space-y-5">
      {/* Welcome Banner */}
      <div className="bg-card rounded-2xl border border-border p-6 flex items-center gap-5 shadow-sm">
        <span className="text-4xl select-none">👋</span>
        <div>
          <h2 className="text-xl font-bold text-foreground">
            Selamat datang, <span className="text-primary">{displayName}</span>
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            Berikut ringkasan aktivitas lembaga hari ini.
          </p>
        </div>
      </div>

      {/* Stat Cards */}
      {loading ? (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {[0, 1, 2, 3].map((i) => (
            <div key={i} className="bg-card rounded-2xl border border-border p-5 flex items-center gap-4">
              <Skeleton className="h-12 w-12 rounded-xl flex-shrink-0" />
              <div className="space-y-2">
                <Skeleton className="h-3 w-20" />
                <Skeleton className="h-7 w-14" />
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {statCards.map((s) => <StatCard key={s.label} {...s} />)}
        </div>
      )}

      {/* Jurnal Mengajar Reminder */}
      {!loading && stats && stats.jurnalHariIni.total > 0 && (
        <div className={`rounded-2xl border p-5 shadow-sm ${stats.jurnalHariIni.belum > 0 ? 'bg-destructive/5 border-destructive/20' : 'bg-primary/5 border-primary/20'}`}>
          <div className="flex items-start gap-4">
            <div className={`h-11 w-11 rounded-xl flex items-center justify-center flex-shrink-0 ${stats.jurnalHariIni.belum > 0 ? 'bg-destructive/10' : 'bg-primary/10'}`}>
              {stats.jurnalHariIni.belum > 0 ? (
                <AlertTriangle className="h-5 w-5 text-destructive" />
              ) : (
                <CheckCircle2 className="h-5 w-5 text-primary" />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-foreground">
                {stats.jurnalHariIni.belum > 0
                  ? `${isGuru ? 'Anda memiliki' : 'Ada'} ${stats.jurnalHariIni.belum} jurnal yang belum diisi hari ini`
                  : 'Semua jurnal mengajar hari ini sudah terisi! ✅'
                }
              </h3>
              <div className="flex items-center gap-3 mt-2">
                <Progress value={jurnalPct} className="flex-1 h-2" />
                <span className="text-sm font-medium text-muted-foreground whitespace-nowrap">
                  {stats.jurnalHariIni.terisi}/{stats.jurnalHariIni.total}
                </span>
              </div>
              {stats.jurnalHariIni.belum > 0 && (
                <Link to="/lms/jurnal">
                  <Button size="sm" variant="outline" className="mt-3 h-8">
                    {isGuru ? 'Isi Jurnal Sekarang' : 'Lihat Detail'}
                    <ArrowRight className="h-3.5 w-3.5 ml-1.5" />
                  </Button>
                </Link>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/api/getJurnalData.ts.content:
import { z } from 'zod';
import { createEndpoint, JurnalMengajar, JadwalPelajaran, Guru, Kelas, MataPelajaran } from 'zite-integrations-backend-sdk';

const jurnalItemSchema = z.object({
  id: z.string(),
  tanggal: z.string(),
  hari: z.string(),
  jamMulai: z.string(),
  jamSelesai: z.string(),
  guruId: z.string(),
  guruNama: z.string(),
  kelasId: z.string(),
  kelasNama: z.string(),
  mapelId: z.string(),
  mapelNama: z.string(),
  jadwalId: z.string(),
  tujuanPembelajaran: z.string().optional(),
  materiKonten: z.string().optional(),
  kegiatanPembelajaran: z.string().optional(),
  catatan: z.string().optional(),
  statusKehadiran: z.string().optional(),
  detailKehadiran: z.string().optional(),
  status: z.string().optional(),
  jurnalId: z.string().optional(),
});

const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

function getDatesInRange(start: string, end: string): string[] {
  const dates: string[] = [];
  const d = new Date(start + 'T00:00:00');
  const endD = new Date(end + 'T00:00:00');
  while (d <= endD) {
    dates.push(d.toISOString().split('T')[0]);
    d.setDate(d.getDate() + 1);
  }
  return dates;
}

export default createEndpoint({
  description: 'Get jurnal mengajar data with date range support',
  authenticated: true,
  inputSchema: z.object({
    tanggalMulai: z.string(),
    tanggalSelesai: z.string(),
    guruId: z.string().optional(),
    kelasId: z.string().optional(),
    mode: z.enum(['guru', 'admin']).optional(),
  }),
  outputSchema: z.object({
    items: z.array(jurnalItemSchema),
    guruList: z.array(z.object({ id: z.string(), nama: z.string() })),
    kelasList: z.array(z.object({ id: z.string(), nama: z.string() })),
  }),
  execute: async ({ input, context }) => {
    const isGuru = context.user.role === 'Guru';
    const mode = input.mode || (isGuru ? 'guru' : 'admin');

    const [guruRes, kelasRes, mapelRes] = await Promise.all([
      Guru.findAll({ fields: ['id', 'namaLengkap', 'email'], limit: 500 }),
      Kelas.findAll({ fields: ['id', 'namaKelas', 'tingkat'], limit: 500 }),
      MataPelajaran.findAll({ fields: ['id', 'namaMapel'], limit: 500 }),
    ]);

    const guruMap: Record<string, string> = {};
    const guruEmailMap: Record<string, string> = {};
    for (const g of guruRes.records) {
      guruMap[g.id] = g.namaLengkap || '';
      if (g.email) guruEmailMap[g.email] = g.id;
    }
    const kelasMap: Record<string, string> = {};
    for (const k of kelasRes.records) kelasMap[k.id] = k.namaKelas || '';
    const mapelMap: Record<string, string> = {};
    for (const m of mapelRes.records) mapelMap[m.id] = m.namaMapel || '';

    let currentGuruId: string | undefined;
    if (mode === 'guru') {
      currentGuruId = guruEmailMap[context.user.email];
      if (!currentGuruId) {
        const guru = guruRes.records.find(g =>
          g.namaLengkap && context.user.firstName &&
          g.namaLengkap.toLowerCase().includes(context.user.firstName.toLowerCase())
        );
        if (guru) currentGuruId = guru.id;
      }
    }

    const filterGuruId = mode === 'guru' ? currentGuruId : input.guruId;

    // Fetch all jadwal (filter by guru/kelas if needed)
    const jadwalFilters: Record<string, any> = {};
    if (filterGuruId) jadwalFilters.guru = filterGuruId;
    if (input.kelasId) jadwalFilters.kelas = input.kelasId;
    const jadwalRes = await JadwalPelajaran.findAll({ filters: jadwalFilters, limit: 2000 });

    // Group jadwal by day name
    const jadwalByDay: Record<string, typeof jadwalRes.records> = {};
    for (const j of jadwalRes.records) {
      const hari = j.hari || '';
      if (!jadwalByDay[hari]) jadwalByDay[hari] = [];
      jadwalByDay[hari].push(j);
    }

    // Fetch jurnal for the date range
    const jurnalRes = await JurnalMengajar.findAll({
      filters: {
        tanggal: { gte: input.tanggalMulai as any, lte: input.tanggalSelesai as any },
        ...(filterGuruId ? { guru: filterGuruId } : {}),
        ...(input.kelasId ? { kelas: input.kelasId } : {}),
      },
      limit: 2000,
    });

    // Map jurnal by "jadwalId-tanggal"
    const jurnalMap: Record<string, typeof jurnalRes.records[0]> = {};
    for (const j of jurnalRes.records) {
      const jid = Array.isArray(j.jadwalPelajaran) ? j.jadwalPelajaran[0] : j.jadwalPelajaran;
      if (jid && j.tanggal) jurnalMap[`${jid}-${j.tanggal}`] = j;
    }

    const dates = getDatesInRange(input.tanggalMulai, input.tanggalSelesai);
    const items: z.infer<typeof jurnalItemSchema>[] = [];

    for (const date of dates) {
      const dow = new Date(date + 'T00:00:00').getDay();
      const hariName = DAY_NAMES[dow];
      const dayJadwal = jadwalByDay[hariName] || [];

      for (const jadwal of dayJadwal) {
        const guruId = Array.isArray(jadwal.guru) ? jadwal.guru[0] : jadwal.guru;
        const kelasId = Array.isArray(jadwal.kelas) ? jadwal.kelas[0] : jadwal.kelas;
        const mapelId = Array.isArray(jadwal.mataPelajaran) ? jadwal.mataPelajaran[0] : jadwal.mataPelajaran;
        const jurnal = jurnalMap[`${jadwal.id}-${date}`];

        items.push({
          id: jadwal.id,
          tanggal: date,
          hari: hariName,
          jamMulai: jadwal.jamMulai || '',
          jamSelesai: jadwal.jamSelesai || '',
          guruId: guruId || '',
          guruNama: guruId ? (guruMap[guruId] || '-') : '-',
          kelasId: kelasId || '',
          kelasNama: kelasId ? (kelasMap[kelasId] || '-') : '-',
          mapelId: mapelId || '',
          mapelNama: mapelId ? (mapelMap[mapelId] || '-') : '-',
          jadwalId: jadwal.id,
          tujuanPembelajaran: jurnal?.tujuanPembelajaran,
          materiKonten: jurnal?.materiKonten,
          kegiatanPembelajaran: jurnal?.kegiatanPembelajaran,
          catatan: jurnal?.catatan,
          statusKehadiran: jurnal?.statusKehadiran,
          detailKehadiran: jurnal?.detailKehadiran,
          status: jurnal?.status || 'Belum Diisi',
          jurnalId: jurnal?.id,
        });
      }
    }

    // Sort by date desc, then time asc
    items.sort((a, b) => {
      const dc = b.tanggal.localeCompare(a.tanggal);
      if (dc !== 0) return dc;
      return a.jamMulai.localeCompare(b.jamMulai);
    });

    const guruList = guruRes.records
      .filter(g => g.namaLengkap)
      .map(g => ({ id: g.id, nama: g.namaLengkap! }))
      .sort((a, b) => a.nama.localeCompare(b.nama));
    const kelasList = kelasRes.records
      .map(k => ({ id: k.id, nama: `${k.tingkat || ''} – ${k.namaKelas || ''}` }))
      .sort((a, b) => a.nama.localeCompare(b.nama));

    return { items, guruList, kelasList };
  },
});

