src/api/exportJurnalPdf.ts.content:
import { z } from 'zod';
import { createEndpoint, ZitePdf, Guru, Kelas, MataPelajaran, JadwalPelajaran, JurnalMengajar, Sekolah, TahunAjaran } from 'zite-integrations-backend-sdk';

const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

function esc(s: unknown) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function getDatesInRange(start: string, end: string): string[] {
  const dates: string[] = [];
  const d = new Date(start + 'T00:00:00');
  const endD = new Date(end + 'T00:00:00');
  while (d <= endD) {
    dates.push(d.toISOString().split('T')[0]);
    d.setDate(d.getDate() + 1);
  }
  return dates;
}

export default createEndpoint({
  description: 'Export jurnal mengajar to PDF for a guru in a date range',
  authenticated: true,
  inputSchema: z.object({
    guruId: z.string().optional(),
    tanggalMulai: z.string(),
    tanggalSelesai: z.string(),
    format: z.enum(['pdf', 'excel']),
  }),
  outputSchema: z.object({
    url: z.string().optional(),
    html: z.string().optional(),
  }),
  execute: async ({ input, context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah) ? context.user.sekolah[0] : context.user.sekolah;

    const [guruRes, kelasRes, mapelRes] = await Promise.all([
      Guru.findAll({ fields: ['id', 'namaLengkap', 'email', 'nipnuptk'], limit: 500 }),
      Kelas.findAll({ fields: ['id', 'namaKelas', 'tingkat'], limit: 500 }),
      MataPelajaran.findAll({ fields: ['id', 'namaMapel'], limit: 500 }),
    ]);

    let sekolahData: { nama: string; alamat?: string; npsn?: string } = { nama: 'Sekolah' };
    let tahunAjaran = '';
    if (userSekolahId) {
      const [sekolah, taRes] = await Promise.all([
        Sekolah.findOne({ id: userSekolahId }),
        TahunAjaran.findAll({ filters: { sekolah: userSekolahId, active: true }, limit: 1 }),
      ]);
      if (sekolah) sekolahData = { nama: sekolah.namaSekolah || 'Sekolah', alamat: sekolah.alamat, npsn: sekolah.npsn };
      if (taRes.records[0]) tahunAjaran = taRes.records[0].namaTahunAjaran || '';
    }

    const guruMap: Record<string, { nama: string; nip?: string }> = {};
    for (const g of guruRes.records) guruMap[g.id] = { nama: g.namaLengkap || '', nip: g.nipnuptk };
    const kelasMap: Record<string, string> = {};
    for (const k of kelasRes.records) kelasMap[k.id] = k.namaKelas || '';
    const mapelMap: Record<string, string> = {};
    for (const m of mapelRes.records) mapelMap[m.id] = m.namaMapel || '';

    // Filter jadwal + jurnal
    const jadwalFilters: Record<string, any> = {};
    if (input.guruId) jadwalFilters.guru = input.guruId;
    const [jadwalRes, jurnalRes] = await Promise.all([
      JadwalPelajaran.findAll({ filters: jadwalFilters, limit: 2000 }),
      JurnalMengajar.findAll({
        filters: {
          tanggal: { gte: input.tanggalMulai as any, lte: input.tanggalSelesai as any },
          ...(input.guruId ? { guru: input.guruId } : {}),
        },
        limit: 2000,
      }),
    ]);

    const jadwalByDay: Record<string, typeof jadwalRes.records> = {};
    for (const j of jadwalRes.records) {
      const h = j.hari || '';
      if (!jadwalByDay[h]) jadwalByDay[h] = [];
      jadwalByDay[h].push(j);
    }

    const jurnalMap: Record<string, typeof jurnalRes.records[0]> = {};
    for (const j of jurnalRes.records) {
      const jid = Array.isArray(j.jadwalPelajaran) ? j.jadwalPelajaran[0] : j.jadwalPelajaran;
      if (jid && j.tanggal) jurnalMap[`${jid}-${j.tanggal}`] = j;
    }

    const dates = getDatesInRange(input.tanggalMulai, input.tanggalSelesai);
    interface Row {
      tanggal: string; hari: string; jamMulai: string; jamSelesai: string;
      kelas: string; mapel: string; guru: string;
      tujuan: string; materi: string; kegiatan: string; catatan: string;
      kehadiran: string; status: string;
    }
    const rows: Row[] = [];

    for (const date of dates) {
      const dow = new Date(date + 'T00:00:00').getDay();
      const hariName = DAY_NAMES[dow];
      const dayJadwal = jadwalByDay[hariName] || [];
      for (const jadwal of dayJadwal) {
        const gid = Array.isArray(jadwal.guru) ? jadwal.guru[0] : jadwal.guru;
        const kid = Array.isArray(jadwal.kelas) ? jadwal.kelas[0] : jadwal.kelas;
        const mid = Array.isArray(jadwal.mataPelajaran) ? jadwal.mataPelajaran[0] : jadwal.mataPelajaran;
        const jurnal = jurnalMap[`${jadwal.id}-${date}`];
        rows.push({
          tanggal: new Date(date + 'T00:00:00').toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' }),
          hari: hariName,
          jamMulai: jadwal.jamMulai || '',
          jamSelesai: jadwal.jamSelesai || '',
          kelas: kid ? (kelasMap[kid] || '-') : '-',
          mapel: mid ? (mapelMap[mid] || '-') : '-',
          guru: gid ? (guruMap[gid]?.nama || '-') : '-',
          tujuan: jurnal?.tujuanPembelajaran || '-',
          materi: jurnal?.materiKonten || '-',
          kegiatan: jurnal?.kegiatanPembelajaran || '-',
          catatan: jurnal?.catatan || '-',
          kehadiran: jurnal?.statusKehadiran || '-',
          status: jurnal?.status || 'Belum Diisi',
        });
      }
    }

    rows.sort((a, b) => a.tanggal.localeCompare(b.tanggal) || a.jamMulai.localeCompare(b.jamMulai));

    const guruInfo = input.guruId ? guruMap[input.guruId] : undefined;
    const subtitle = guruInfo ? `Guru: ${esc(guruInfo.nama)}${guruInfo.nip ? ` (NIP: ${esc(guruInfo.nip)})` : ''}` : 'Semua Guru';
    const periodLabel = `Periode: ${esc(input.tanggalMulai)} s/d ${esc(input.tanggalSelesai)}`;

    const rowsHtml = rows.map((r, i) => `<tr>
      <td style="text-align:center;">${i + 1}</td>
      <td style="white-space:nowrap;">${esc(r.tanggal)}</td>
      <td>${esc(r.hari)}</td>
      <td style="white-space:nowrap;">${esc(r.jamMulai)}-${esc(r.jamSelesai)}</td>
      <td>${esc(r.kelas)}</td>
      <td>${esc(r.mapel)}</td>
      ${!input.guruId ? `<td>${esc(r.guru)}</td>` : ''}
      <td>${esc(r.tujuan)}</td>
      <td>${esc(r.materi)}</td>
      <td>${esc(r.kegiatan)}</td>
      <td>${esc(r.kehadiran)}</td>
      <td style="text-align:center;"><span style="padding:2px 6px;border-radius:4px;font-size:7pt;font-weight:bold;${r.status === 'Sudah Diisi' ? 'background:#d1fae5;color:#065f46;' : 'background:#fee2e2;color:#991b1b;'}">${esc(r.status)}</span></td>
    </tr>`).join('');

    const guruCol = !input.guruId ? '<th>Guru</th>' : '';

    if (input.format === 'pdf') {
      const html = `<!doctype html><html><head><meta charset="utf-8"/><style>
        @page { size: A4 landscape; margin: 1cm; }
        body { font-family: 'Times New Roman', serif; font-size: 9pt; color: #000; }
        h2 { text-align: center; font-size: 14pt; margin: 0 0 2px; }
        .sub { text-align: center; font-size: 10pt; margin: 2px 0; }
        table { width: 100%; border-collapse: collapse; margin-top: 10px; }
        th, td { border: 1px solid #000; padding: 4px 5px; vertical-align: top; font-size: 8pt; }
        th { background: #e5e7eb; font-weight: bold; text-align: center; }
      </style></head><body>
        <h2>${esc(sekolahData.nama)}</h2>
        ${sekolahData.alamat ? `<p class="sub">${esc(sekolahData.alamat)}</p>` : ''}
        <hr style="border-top:2px solid #000;margin:6px 0 10px;"/>
        <h2>JURNAL MENGAJAR</h2>
        ${tahunAjaran ? `<p class="sub">Tahun Ajaran ${esc(tahunAjaran)}</p>` : ''}
        <p class="sub">${subtitle}</p>
        <p class="sub">${periodLabel}</p>
        <table>
          <thead><tr><th>No</th><th>Tanggal</th><th>Hari</th><th>Jam</th><th>Kelas</th><th>Mapel</th>${guruCol}<th>Tujuan Pembelajaran</th><th>Materi/Konten</th><th>Kegiatan</th><th>Kehadiran</th><th>Status</th></tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </body></html>`;

      const result = await ZitePdf.renderHtml({ html, filename: `Jurnal_Mengajar_${input.tanggalMulai}_${input.tanggalSelesai}.pdf` });
      return { url: result.url };
    }

    // Excel format
    const excelHtml = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:spreadsheet" xmlns="http://www.w3.org/TR/REC-html40">
    <head><meta charset="utf-8"/>
    <!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Jurnal</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->
    <style>td,th{border:1px solid #000;padding:4px 6px;font-family:Arial;font-size:10pt;vertical-align:top;}th{text-align:center;}</style></head><body>
    <table>
      <tr><td colspan="12" style="font-size:14pt;font-weight:bold;text-align:center;border:none;">${esc(sekolahData.nama)}</td></tr>
      <tr><td colspan="12" style="font-size:12pt;font-weight:bold;text-align:center;border:none;">JURNAL MENGAJAR</td></tr>
      <tr><td colspan="12" style="text-align:center;border:none;">${subtitle}</td></tr>
      <tr><td colspan="12" style="text-align:center;border:none;">${periodLabel}</td></tr>
      <tr><td colspan="12" style="border:none;">&nbsp;</td></tr>
      <tr><th style="background:#2563eb;color:white;">No</th><th style="background:#2563eb;color:white;">Tanggal</th><th style="background:#2563eb;color:white;">Hari</th><th style="background:#2563eb;color:white;">Jam</th><th style="background:#2563eb;color:white;">Kelas</th><th style="background:#2563eb;color:white;">Mapel</th>${!input.guruId ? '<th style="background:#2563eb;color:white;">Guru</th>' : ''}<th style="background:#2563eb;color:white;">Tujuan Pembelajaran</th><th style="background:#2563eb;color:white;">Materi/Konten</th><th style="background:#2563eb;color:white;">Kegiatan</th><th style="background:#2563eb;color:white;">Kehadiran</th><th style="background:#2563eb;color:white;">Status</th></tr>
      ${rowsHtml}
    </table></body></html>`;

    return { html: excelHtml };
  },
});

src/api/getGuruDropdown.ts.content:
import { z } from 'zod';
import { createEndpoint, Guru } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Mengambil daftar guru untuk dropdown',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    guru: z.array(z.object({
      id: z.string(),
      nama: z.string(),
    })),
  }),
  execute: async () => {
    const result = await Guru.findAll({
      fields: ['id', 'namaLengkap'],
      limit: 500,
    });
    const guru = result.records
      .filter(g => g.namaLengkap)
      .map(g => ({ id: g.id, nama: g.namaLengkap! }))
      .sort((a, b) => a.nama.localeCompare(b.nama));
    return { guru };
  },
});

src/api/saveJadwalEntry.ts.content:
import { z } from 'zod';
import { createEndpoint, JadwalPelajaran } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create or update a jadwal pelajaran entry',
  authenticated: true,
  inputSchema: z.object({
    id: z.string().optional(),
    kelasId: z.string(),
    hari: z.string(),
    jamMulai: z.string(),
    jamSelesai: z.string(),
    mapelId: z.string(),
    guruId: z.string(),
  }),
  outputSchema: z.object({ id: z.string(), success: z.boolean() }),
  execute: async ({ input }) => {
    const jadwalLabel = `${input.hari} ${input.jamMulai}-${input.jamSelesai}`;
    if (input.id) {
      await JadwalPelajaran.update({
        id: input.id,
        record: {
          jadwal: jadwalLabel,
          kelas: input.kelasId,
          hari: input.hari as any,
          jamMulai: input.jamMulai,
          jamSelesai: input.jamSelesai,
          mataPelajaran: input.mapelId,
          guru: input.guruId,
        },
      });
      return { id: input.id, success: true };
    } else {
      const rec = await JadwalPelajaran.create({
        record: {
          jadwal: jadwalLabel,
          kelas: input.kelasId,
          hari: input.hari as any,
          jamMulai: input.jamMulai,
          jamSelesai: input.jamSelesai,
          mataPelajaran: input.mapelId,
          guru: input.guruId,
        },
      });
      return { id: rec.id, success: true };
    }
  },
});

src/api/createPengumuman.ts.content:
import { z } from 'zod';
import { createEndpoint, Pengumuman } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Membuat pengumuman baru',
  inputSchema: z.object({
    judul: z.string(),
    konten: z.string(),
    target: z.string(),
  }),
  outputSchema: z.object({
    id: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah) 
      ? context.user.sekolah[0] 
      : context.user.sekolah;

    const record = await Pengumuman.create({
      record: {
        judul: input.judul,
        konten: input.konten,
        target: input.target,
        sekolah: userSekolahId,
        tanggalPublish: new Date().toISOString(),
        published: true,
      },
    });

    return { id: record.id };
  },
});

src/api/createRuangKelas.ts.content:
import { z } from 'zod';
import { createEndpoint, Kelas, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Membuat ruang kelas baru dan assign siswa',
  authenticated: true,
  inputSchema: z.object({
    namaKelas: z.string().min(1),
    tingkat: z.string().min(1),
    waliKelasId: z.string().optional(),
    siswaIds: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({ id: z.string(), success: z.boolean() }),
  execute: async ({ input }) => {
    const record = await Kelas.create({
      record: {
        namaKelas: input.namaKelas,
        tingkat: input.tingkat as any,
        waliKelas: input.waliKelasId || undefined,
      },
    });

    // Assign students to this kelas
    if (input.siswaIds && input.siswaIds.length > 0) {
      for (const sId of input.siswaIds) {
        await Siswa.update({ id: sId, record: { kelas: record.id } });
      }
    }

    return { id: record.id, success: true };
  },
});

