src/api/updateRuangKelas.ts.content:
import { z } from 'zod';
import { createEndpoint, Kelas, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Update ruang kelas dan assign/unassign siswa',
  authenticated: true,
  inputSchema: z.object({
    id: z.string(),
    namaKelas: z.string().min(1).optional(),
    tingkat: z.string().optional(),
    waliKelasId: z.string().nullable().optional(),
    siswaIds: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const updateFields: any = {};
    if (input.namaKelas !== undefined) updateFields.namaKelas = input.namaKelas;
    if (input.tingkat !== undefined) updateFields.tingkat = input.tingkat;
    if (input.waliKelasId !== undefined) updateFields.waliKelas = input.waliKelasId || undefined;

    await Kelas.update({ id: input.id, record: updateFields });

    // Re-assign students if provided
    if (input.siswaIds !== undefined) {
      // Remove current students from this kelas
      const currentSiswa = await Siswa.findAll({
        filters: { kelas: input.id },
        fields: ['id'],
        limit: 500,
      });
      for (const s of currentSiswa.records) {
        if (!input.siswaIds.includes(s.id)) {
          await Siswa.update({ id: s.id, record: { kelas: '' } });
        }
      }
      // Add new students
      const currentIds = new Set(currentSiswa.records.map(s => s.id));
      for (const sId of input.siswaIds) {
        if (!currentIds.has(sId)) {
          await Siswa.update({ id: sId, record: { kelas: input.id } });
        }
      }
    }

    return { success: true };
  },
});

src/lib/generatePdfPrint.ts.content:
export interface SekolahInfo {
  namaSekolah?: string;
  alamat?: string;
  telepon?: string;
  logoUrl?: string;
  npsn?: string;
}

export interface PdfColumn {
  label: string;
  key: string;
  width?: string; // CSS width, e.g. '120px'
}

export function printToPdf(
  title: string,
  sekolah: SekolahInfo,
  columns: PdfColumn[],
  rows: Record<string, unknown>[]
): void {
  const today = new Date().toLocaleDateString('id-ID', {
    day: '2-digit', month: 'long', year: 'numeric',
  });

  const colWidths = columns.map(c => `<col style="width:${c.width ?? 'auto'}">`).join('');
  const headerCells = columns.map(c => `<th>${esc(c.label)}</th>`).join('');
  const dataRows = rows.map((row, i) =>
    `<tr class="${i % 2 === 1 ? 'alt' : ''}">
      <td class="center">${i + 1}</td>
      ${columns.map(c => `<td>${esc(String(row[c.key] ?? ''))}</td>`).join('')}
    </tr>`
  ).join('');

  const logoHtml = sekolah.logoUrl
    ? `<img src="${esc(sekolah.logoUrl)}" alt="Logo" class="logo" />`
    : '';

  const html = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<title>${esc(title)}</title>
<style>
  @page { size: A4 landscape; margin: 12mm 14mm; }
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #111; margin: 0; }

  /* Kop surat */
  .kop { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-bottom: 10px; border-bottom: 3px solid #111; margin-bottom: 14px; }
  .kop-left { flex: 1; }
  .kop-left .school-name { font-size: 15pt; font-weight: bold; margin: 0 0 3px; line-height: 1.2; }
  .kop-left .school-info { font-size: 9pt; margin: 2px 0; color: #333; }
  .logo { width: 72px; height: 72px; object-fit: contain; flex-shrink: 0; }

  /* Title */
  .doc-title { text-align: center; font-size: 12pt; font-weight: bold; text-transform: uppercase; letter-spacing: 0.8px; margin: 0 0 3px; }
  .doc-date  { text-align: center; font-size: 8pt; color: #666; margin: 0 0 14px; }

  /* Table */
  table { width: 100%; border-collapse: collapse; table-layout: fixed; }
  col.num { width: 32px; }
  th { background: #166534; color: #fff; padding: 5px 7px; text-align: left; border: 1px solid #0f4d27; font-size: 8.5pt; white-space: nowrap; }
  td { padding: 4px 7px; border: 1px solid #ddd; font-size: 8.5pt; vertical-align: top; word-break: break-word; }
  tr.alt td { background: #f7f9f7; }
  td.center { text-align: center; }

  /* Footer */
  .footer { margin-top: 12px; font-size: 8pt; color: #888; text-align: right; }

  @media print { .no-print { display: none !important; } }
</style>
</head>
<body>

<!-- Kop Surat -->
<div class="kop">
  <div class="kop-left">
    <p class="school-name">${esc(sekolah.namaSekolah || 'Nama Sekolah')}</p>
    ${sekolah.npsn ? `<p class="school-info">NPSN: ${esc(sekolah.npsn)}</p>` : ''}
    ${sekolah.alamat ? `<p class="school-info">${esc(sekolah.alamat)}</p>` : ''}
    ${sekolah.telepon ? `<p class="school-info">Telp: ${esc(sekolah.telepon)}</p>` : ''}
  </div>
  ${logoHtml}
</div>

<!-- Judul Dokumen -->
<p class="doc-title">${esc(title)}</p>
<p class="doc-date">Dicetak pada: ${today} &nbsp;|&nbsp; Jumlah data: ${rows.length}</p>

<!-- Tabel Data -->
<table>
  <colgroup>
    <col class="num">
    ${colWidths}
  </colgroup>
  <thead>
    <tr>
      <th style="text-align:center">No</th>
      ${headerCells}
    </tr>
  </thead>
  <tbody>
    ${dataRows}
  </tbody>
</table>

<div class="footer">SIMSEKOLAH &mdash; ${esc(sekolah.namaSekolah || '')} &mdash; ${today}</div>

<script>
  // Wait for images to load before printing
  window.onload = function() {
    var imgs = document.querySelectorAll('img');
    var loaded = 0;
    if (imgs.length === 0) { setTimeout(function(){ window.print(); }, 300); return; }
    imgs.forEach(function(img) {
      if (img.complete) { loaded++; if (loaded === imgs.length) setTimeout(function(){ window.print(); }, 300); }
      else { img.onload = img.onerror = function() { loaded++; if (loaded === imgs.length) setTimeout(function(){ window.print(); }, 300); }; }
    });
  };
</script>
</body>
</html>`;

  const win = window.open('', '_blank', 'width=1100,height=780');
  if (win) {
    win.document.write(html);
    win.document.close();
  } else {
    alert('Popup diblokir browser. Izinkan popup pada browser Anda untuk menggunakan fitur cetak PDF.');
  }
}

function esc(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

src/pages/lms/TugasPage.tsx.content:
import { useState, useEffect, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getTugas, deleteTugas, saveTugas } from 'zite-endpoints-sdk';
import type { GetTugasOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Plus, Search, ClipboardList, MoreVertical, Pencil, Trash2, CheckCircle, XCircle, Calendar, GraduationCap, Users, BookOpen, Clock, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';
import TugasFormDialog from '@/components/tugas/TugasFormDialog';

type TugasItem = GetTugasOutputType['tugas'][0];

const JENIS_COLORS: Record<string, string> = {
  'Tugas Harian': 'bg-blue-500/10 text-blue-700 dark:text-blue-400',
  'PR (Pekerjaan Rumah)': 'bg-green-500/10 text-green-700 dark:text-green-400',
  'Proyek': 'bg-purple-500/10 text-purple-700 dark:text-purple-400',
  'Latihan': 'bg-orange-500/10 text-orange-700 dark:text-orange-400',
  'Ulangan': 'bg-red-500/10 text-red-700 dark:text-red-400',
  'Kuis': 'bg-cyan-500/10 text-cyan-700 dark:text-cyan-400',
};

export default function TugasPage() {
  const { user } = useAuth();
  const [tugas, setTugas] = useState<TugasItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [formOpen, setFormOpen] = useState(false);
  const [editItem, setEditItem] = useState<TugasItem | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const isGuru = user?.role === 'Guru';

  const loadTugas = useCallback(async (q?: string) => {
    setLoading(true);
    try {
      const res = await getTugas({
        search: q || undefined,
        status: statusFilter !== 'all' ? statusFilter : undefined,
      });
      setTugas(res.tugas);
    } catch { /* ignore */ }
    setLoading(false);
  }, [statusFilter]);

  useEffect(() => { loadTugas(search); }, [loadTugas, search]);

  const debouncedSearch = useDebouncedCallback((val: string) => setSearch(val), 400);

  const handleDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      await deleteTugas({ id: deleteId });
      toast.success('Tugas berhasil dihapus');
      setTugas(prev => prev.filter(t => t.id !== deleteId));
      setDeleteId(null);
    } catch { toast.error('Gagal menghapus tugas'); }
    setDeleting(false);
  };

  const handleStatusChange = async (item: TugasItem, newStatus: string) => {
    try {
      await saveTugas({
        id: item.id,
        judulTugas: item.judulTugas,
        jenisTugas: item.jenisTugas,
        guruId: item.guruId,
        kelasId: item.kelasId,
        mapelId: item.mapelId,
        tanggalDiberikan: item.tanggalDiberikan,
        deadline: item.deadline,
        status: newStatus,
      });
      setTugas(prev => prev.map(t => t.id === item.id ? { ...t, status: newStatus } : t));
      toast.success(`Status diubah ke "${newStatus}"`);
    } catch { toast.error('Gagal mengubah status'); }
  };

  const today = new Date().toISOString().split('T')[0];
  const aktifTugas = tugas.filter(t => t.status === 'Aktif');
  const overdueTugas = aktifTugas.filter(t => t.deadline && t.deadline < today);
  const upcomingTugas = aktifTugas.filter(t => t.deadline && t.deadline >= today);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Tugas</h2>
          <p className="text-muted-foreground">Kelola penugasan & pekerjaan rumah siswa</p>
        </div>
        <Button className="gap-2" onClick={() => { setEditItem(null); setFormOpen(true); }}>
          <Plus className="h-4 w-4" /> Buat Tugas
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <StatCard label="Total Tugas" value={tugas.length} icon={ClipboardList} color="text-primary" />
        <StatCard label="Aktif" value={aktifTugas.length} icon={Clock} color="text-blue-600" />
        <StatCard label="Mendekati Deadline" value={overdueTugas.length} icon={AlertTriangle} color="text-destructive" />
        <StatCard label="Selesai" value={tugas.filter(t => t.status === 'Selesai').length} icon={CheckCircle} color="text-green-600" />
      </div>

      {/* Filters */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Cari tugas..." className="pl-9" onChange={e => debouncedSearch(e.target.value)} />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[160px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Status</SelectItem>
              <SelectItem value="Aktif">Aktif</SelectItem>
              <SelectItem value="Selesai">Selesai</SelectItem>
              <SelectItem value="Dibatalkan">Dibatalkan</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </Card>

      {/* Tugas List */}
      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <Skeleton key={i} className="h-28 w-full rounded-xl" />)}</div>
      ) : tugas.length === 0 ? (
        <EmptyState />
      ) : (
        <div className="space-y-3">
          {tugas.map(t => (
            <TugasCard
              key={t.id}
              item={t}
              today={today}
              onEdit={() => { setEditItem(t); setFormOpen(true); }}
              onDelete={() => setDeleteId(t.id)}
              onStatusChange={handleStatusChange}
            />
          ))}
        </div>
      )}

      <TugasFormDialog
        open={formOpen}
        item={editItem}
        onClose={() => setFormOpen(false)}
        onSaved={() => loadTugas(search)}
      />

      <AlertDialog open={!!deleteId} onOpenChange={v => { if (!v) setDeleteId(null); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Tugas?</AlertDialogTitle>
            <AlertDialogDescription>Tugas yang dihapus tidak dapat dikembalikan.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting ? 'Menghapus...' : 'Hapus'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

function StatCard({ label, value, icon: Icon, color }: { label: string; value: number; icon: React.ElementType; color: string }) {
  return (
    <Card className="p-4 flex items-center gap-3">
      <div className={`h-10 w-10 rounded-xl bg-muted flex items-center justify-center ${color}`}>
        <Icon className="h-5 w-5" />
      </div>
      <div>
        <p className="text-2xl font-bold">{value}</p>
        <p className="text-xs text-muted-foreground">{label}</p>
      </div>
    </Card>
  );
}

function TugasCard({ item, today, onEdit, onDelete, onStatusChange }: {
  item: TugasItem;
  today: string;
  onEdit: () => void;
  onDelete: () => void;
  onStatusChange: (item: TugasItem, status: string) => void;
}) {
  const isOverdue = item.status === 'Aktif' && item.deadline && item.deadline < today;
  const daysLeft = item.deadline ? Math.ceil((new Date(item.deadline + 'T00:00:00').getTime() - new Date(today + 'T00:00:00').getTime()) / 86400000) : null;
  const fmtDate = (d: string) => d ? new Date(d + 'T00:00:00').toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) : '-';

  const statusBadge = item.status === 'Aktif'
    ? isOverdue
      ? <Badge variant="destructive" className="text-xs">Melewati Deadline</Badge>
      : <Badge className="bg-blue-500/10 text-blue-700 border-0 text-xs">Aktif</Badge>
    : item.status === 'Selesai'
      ? <Badge className="bg-green-500/10 text-green-700 border-0 text-xs">Selesai</Badge>
      : <Badge variant="secondary" className="text-xs">Dibatalkan</Badge>;

  return (
    <Card className={`p-4 hover:shadow-md transition-shadow ${isOverdue ? 'border-destructive/40' : ''}`}>
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0 space-y-2">
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className="font-semibold text-base truncate">{item.judulTugas}</h3>
            {statusBadge}
            <Badge variant="outline" className={`text-xs border-0 ${JENIS_COLORS[item.jenisTugas] || 'bg-muted text-foreground'}`}>
              {item.jenisTugas}
            </Badge>
          </div>
          {item.deskripsi && <p className="text-sm text-muted-foreground line-clamp-2">{item.deskripsi}</p>}
          <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
            <span className="inline-flex items-center gap-1"><GraduationCap className="h-3 w-3" />{item.mapelNama}</span>
            <span className="inline-flex items-center gap-1"><Users className="h-3 w-3" />{item.kelasNama}</span>
            <span className="inline-flex items-center gap-1"><BookOpen className="h-3 w-3" />{item.guruNama}</span>
            <span className="inline-flex items-center gap-1"><Calendar className="h-3 w-3" />Diberikan: {fmtDate(item.tanggalDiberikan)}</span>
            <span className={`inline-flex items-center gap-1 font-medium ${isOverdue ? 'text-destructive' : daysLeft !== null && daysLeft <= 2 ? 'text-orange-600' : ''}`}>
              <Clock className="h-3 w-3" />
              Deadline: {fmtDate(item.deadline)}
              {item.status === 'Aktif' && daysLeft !== null && (
                <span className="ml-1">
                  ({isOverdue ? `${Math.abs(daysLeft)} hari lalu` : daysLeft === 0 ? 'Hari ini' : `${daysLeft} hari lagi`})
                </span>
              )}
            </span>
          </div>
        </div>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="h-8 w-8 flex-shrink-0">
              <MoreVertical className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={onEdit}><Pencil className="h-4 w-4 mr-2" />Edit</DropdownMenuItem>
            {item.status === 'Aktif' && (
              <DropdownMenuItem onClick={() => onStatusChange(item, 'Selesai')}><CheckCircle className="h-4 w-4 mr-2" />Tandai Selesai</DropdownMenuItem>
            )}
            {item.status === 'Selesai' && (
              <DropdownMenuItem onClick={() => onStatusChange(item, 'Aktif')}><Clock className="h-4 w-4 mr-2" />Aktifkan Kembali</DropdownMenuItem>
            )}
            {item.status === 'Aktif' && (
              <DropdownMenuItem onClick={() => onStatusChange(item, 'Dibatalkan')}><XCircle className="h-4 w-4 mr-2" />Batalkan</DropdownMenuItem>
            )}
            <DropdownMenuItem onClick={onDelete} className="text-destructive"><Trash2 className="h-4 w-4 mr-2" />Hapus</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </Card>
  );
}

function EmptyState() {
  return (
    <Card className="p-12">
      <div className="flex flex-col items-center justify-center text-center">
        <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
          <ClipboardList className="h-8 w-8 text-muted-foreground" />
        </div>
        <h3 className="text-lg font-semibold mb-1">Belum Ada Tugas</h3>
        <p className="text-sm text-muted-foreground max-w-md">
          Buat tugas baru dengan tombol di atas, atau tambahkan tugas langsung saat mengisi Jurnal Mengajar.
        </p>
      </div>
    </Card>
  );
}

