src/lib/useIndonesiaRegions.ts.content:
import { useState, useEffect } from 'react';

export interface Region {
  id: string;
  name: string;
}

const BASE_URL = 'https://www.emsifa.com/api-wilayah-indonesia/api';

export const PROVINCE_ID_MAP: Record<string, string> = {
  'Aceh': '11',
  'Sumatera Utara': '12',
  'Sumatera Barat': '13',
  'Riau': '14',
  'Jambi': '15',
  'Sumatera Selatan': '16',
  'Bengkulu': '17',
  'Lampung': '18',
  'Kepulauan Bangka Belitung': '19',
  'Kepulauan Riau': '21',
  'DKI Jakarta': '31',
  'Jawa Barat': '32',
  'Jawa Tengah': '33',
  'DI Yogyakarta': '34',
  'Jawa Timur': '35',
  'Banten': '36',
  'Bali': '51',
  'Nusa Tenggara Barat': '52',
  'Nusa Tenggara Timur': '53',
  'Kalimantan Barat': '61',
  'Kalimantan Tengah': '62',
  'Kalimantan Selatan': '63',
  'Kalimantan Timur': '64',
  'Kalimantan Utara': '65',
  'Sulawesi Utara': '71',
  'Sulawesi Tengah': '72',
  'Sulawesi Selatan': '73',
  'Sulawesi Tenggara': '74',
  'Gorontalo': '75',
  'Sulawesi Barat': '76',
  'Maluku': '81',
  'Maluku Utara': '82',
  'Papua Barat': '91',
  'Papua': '94',
  'Papua Selatan': '95',
  'Papua Tengah': '96',
  'Papua Pegunungan': '97',
  'Papua Barat Daya': '98',
};

export function useIndonesiaRegions(
  provinsi: string,
  kabupaten: string,
  kecamatan: string
) {
  const [kabupatenList, setKabupatenList] = useState<Region[]>([]);
  const [kecamatanList, setKecamatanList] = useState<Region[]>([]);
  const [kelurahanList, setKelurahanList] = useState<Region[]>([]);
  const [loadingKabupaten, setLoadingKabupaten] = useState(false);
  const [loadingKecamatan, setLoadingKecamatan] = useState(false);
  const [loadingKelurahan, setLoadingKelurahan] = useState(false);

  useEffect(() => {
    if (!provinsi) {
      setKabupatenList([]);
      setKecamatanList([]);
      setKelurahanList([]);
      return;
    }
    const id = PROVINCE_ID_MAP[provinsi];
    if (!id) return;
    setLoadingKabupaten(true);
    fetch(`${BASE_URL}/regencies/${id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKabupatenList(data))
      .catch(() => setKabupatenList([]))
      .finally(() => setLoadingKabupaten(false));
  }, [provinsi]);

  useEffect(() => {
    if (!kabupaten || !kabupatenList.length) {
      setKecamatanList([]);
      setKelurahanList([]);
      return;
    }
    const item = kabupatenList.find((k) => k.name === kabupaten);
    if (!item) return;
    setLoadingKecamatan(true);
    fetch(`${BASE_URL}/districts/${item.id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKecamatanList(data))
      .catch(() => setKecamatanList([]))
      .finally(() => setLoadingKecamatan(false));
  }, [kabupaten, kabupatenList]);

  useEffect(() => {
    if (!kecamatan || !kecamatanList.length) {
      setKelurahanList([]);
      return;
    }
    const item = kecamatanList.find((k) => k.name === kecamatan);
    if (!item) return;
    setLoadingKelurahan(true);
    fetch(`${BASE_URL}/villages/${item.id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKelurahanList(data))
      .catch(() => setKelurahanList([]))
      .finally(() => setLoadingKelurahan(false));
  }, [kecamatan, kecamatanList]);

  return {
    kabupatenList,
    kecamatanList,
    kelurahanList,
    loadingKabupaten,
    loadingKecamatan,
    loadingKelurahan,
  };
}

src/api/getAllJadwalForPrint.ts.content:
import { z } from 'zod';
import { createEndpoint, JadwalPelajaran, Kelas, MataPelajaran, Guru, Sekolah, TahunAjaran } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get jadwal for all classes plus school info for printing/export',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    sekolah: z.object({
      namaSekolah: z.string().optional(),
      alamat: z.string().optional(),
      telepon: z.string().optional(),
      kepalaSekolah: z.string().optional(),
      logoUrl: z.string().optional(),
      npsn: z.string().optional(),
    }).nullable(),
    tahunAjaran: z.string().optional(),
    semester: z.string().optional(),
    kelasJadwal: z.array(z.object({
      kelasId: z.string(),
      kelasNama: z.string(),
      tingkat: z.string(),
      jadwal: z.array(z.object({
        id: z.string(),
        hari: z.string(),
        jamMulai: z.string(),
        jamSelesai: z.string(),
        mapelNama: z.string(),
        mapelKode: z.string().optional(),
        guruNama: z.string(),
      })),
    })),
  }),
  execute: async ({ context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah)
      ? context.user.sekolah[0]
      : context.user.sekolah;

    const [kelasRes, mapelRes, guruRes, jadwalRes] = await Promise.all([
      Kelas.findAll({ fields: ['id', 'namaKelas', 'tingkat'], limit: 500 }),
      MataPelajaran.findAll({ fields: ['id', 'namaMapel', 'kodeMapel'], limit: 500 }),
      Guru.findAll({ fields: ['id', 'namaLengkap'], limit: 500 }),
      JadwalPelajaran.findAll({ limit: 2000 }),
    ]);

    let sekolahData: { namaSekolah?: string; alamat?: string; telepon?: string; kepalaSekolah?: string; logoUrl?: string; npsn?: string } | null = null;
    let tahunAjaran: string | undefined;
    let semester: string | undefined;

    if (userSekolahId) {
      const [sekolah, taRes] = await Promise.all([
        Sekolah.findOne({ id: userSekolahId }),
        TahunAjaran.findAll({ filters: { sekolah: userSekolahId, active: true }, limit: 1 }),
      ]);
      if (sekolah) {
        sekolahData = {
          namaSekolah: sekolah.namaSekolah,
          alamat: sekolah.alamat,
          telepon: sekolah.telepon,
          kepalaSekolah: sekolah.kepalaSekolah,
          logoUrl: sekolah.logo?.[0]?.url,
          npsn: sekolah.npsn,
        };
      }
      const ta = taRes.records[0];
      if (ta) {
        tahunAjaran = ta.namaTahunAjaran;
        semester = ta.semester;
      }
    }

    const mapelMap: Record<string, { nama: string; kode?: string }> = {};
    for (const m of mapelRes.records) mapelMap[m.id] = { nama: m.namaMapel || '', kode: m.kodeMapel };

    const guruMap: Record<string, string> = {};
    for (const g of guruRes.records) guruMap[g.id] = g.namaLengkap || '';

    const tingkatOrder = (t: string) => { const m = t.match(/(\d+)/); return m ? parseInt(m[1], 10) : 99; };

    const kelasSorted = kelasRes.records
      .map(k => ({ id: k.id, nama: k.namaKelas || '', tingkat: k.tingkat || '' }))
      .sort((a, b) => {
        const ta = tingkatOrder(a.tingkat); const tb = tingkatOrder(b.tingkat);
        if (ta !== tb) return ta - tb;
        return a.nama.localeCompare(b.nama);
      });

    const dayOrder: Record<string, number> = { Senin: 1, Selasa: 2, Rabu: 3, Kamis: 4, Jumat: 5, Sabtu: 6 };

    const kelasJadwal = kelasSorted.map(kelas => {
      const entries = jadwalRes.records
        .filter(j => {
          const kid = Array.isArray(j.kelas) ? j.kelas[0] : j.kelas;
          return kid === kelas.id;
        })
        .map(j => {
          const mid = Array.isArray(j.mataPelajaran) ? j.mataPelajaran[0] : j.mataPelajaran;
          const gid = Array.isArray(j.guru) ? j.guru[0] : j.guru;
          const mapel = mid ? mapelMap[mid] : undefined;
          return {
            id: j.id,
            hari: j.hari || '',
            jamMulai: j.jamMulai || '',
            jamSelesai: j.jamSelesai || '',
            mapelNama: mapel?.nama || '-',
            mapelKode: mapel?.kode,
            guruNama: gid ? (guruMap[gid] || '-') : '-',
          };
        })
        .sort((a, b) => {
          const da = dayOrder[a.hari] ?? 99; const db = dayOrder[b.hari] ?? 99;
          if (da !== db) return da - db;
          return a.jamMulai.localeCompare(b.jamMulai);
        });

      return {
        kelasId: kelas.id,
        kelasNama: `${kelas.tingkat} – ${kelas.nama}`,
        tingkat: kelas.tingkat,
        jadwal: entries,
      };
    }).filter(k => k.jadwal.length > 0);

    return { sekolah: sekolahData, tahunAjaran, semester, kelasJadwal };
  },
});

src/api/getStudentsForJurnal.ts.content:
import { z } from 'zod';
import { createEndpoint, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get students for a class (for jurnal attendance)',
  authenticated: true,
  inputSchema: z.object({
    kelasId: z.string(),
  }),
  outputSchema: z.object({
    students: z.array(z.object({
      id: z.string(),
      nama: z.string(),
      nisn: z.string(),
    })),
  }),
  execute: async ({ input }) => {
    const res = await Siswa.findAll({
      filters: { kelas: input.kelasId, status: 'Aktif' },
      fields: ['id', 'namaLengkap', 'nisn'],
      limit: 500,
    });

    const students = res.records
      .map(s => ({ id: s.id, nama: s.namaLengkap || '-', nisn: s.nisn || '-' }))
      .sort((a, b) => a.nama.localeCompare(b.nama));

    return { students };
  },
});

src/pages/akademik/MapelTab.tsx.content:
import { useState, useEffect, useCallback } from 'react';
import { Plus, Pencil, Trash2, Loader2, Search, GripVertical, BookOpen } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Skeleton } from '@/components/ui/skeleton';
import { toast } from 'sonner';
import { getMataPelajaran, createMataPelajaran, updateMataPelajaran, deleteMataPelajaran, reorderMapel, toggleMapelAktif } from 'zite-endpoints-sdk';
import type { GetMataPelajaranOutputType } from 'zite-endpoints-sdk';
import MapelFormDialog from '@/components/mapel/MapelFormDialog';
import SortableMapelList from '@/components/mapel/SortableMapelList';

type MapelRecord = GetMataPelajaranOutputType['records'][0];

export default function MapelTab() {
  const [records, setRecords] = useState<MapelRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editData, setEditData] = useState<MapelRecord | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getMataPelajaran({ search });
      setRecords(res.records);
    } catch {
      toast.error('Gagal memuat data');
    } finally {
      setLoading(false);
    }
  }, [search]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSave = async (data: { namaMapel: string; kodeMapel?: string; kelompok?: string; aktif: boolean }) => {
    try {
      if (editData) {
        await updateMataPelajaran({ id: editData.id, ...data });
        toast.success('Mata pelajaran berhasil diperbarui');
      } else {
        await createMataPelajaran(data);
        toast.success('Mata pelajaran berhasil ditambahkan');
      }
      setShowForm(false);
      setEditData(null);
      fetchData();
    } catch {
      toast.error('Gagal menyimpan data');
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      await deleteMataPelajaran({ id: deleteId });
      toast.success('Mata pelajaran berhasil dihapus');
      setDeleteId(null);
      fetchData();
    } catch {
      toast.error('Gagal menghapus data');
    } finally {
      setDeleting(false);
    }
  };

  const handleToggleAktif = async (id: string, aktif: boolean) => {
    // Optimistic update
    setRecords(prev => prev.map(r => r.id === id ? { ...r, aktif } : r));
    try {
      await toggleMapelAktif({ id, aktif });
    } catch {
      setRecords(prev => prev.map(r => r.id === id ? { ...r, aktif: !aktif } : r));
      toast.error('Gagal mengubah status');
    }
  };

  const handleReorder = async (newOrder: MapelRecord[]) => {
    setRecords(newOrder);
    try {
      await reorderMapel({ orderedIds: newOrder.map(r => r.id) });
    } catch {
      toast.error('Gagal menyimpan urutan');
      fetchData();
    }
  };

  return (
    <>
      <Card className="p-5">
        <div className="flex items-center justify-between flex-wrap gap-3 mb-5">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Cari mata pelajaran..."
              className="pl-9"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <Button className="gap-2" onClick={() => { setEditData(null); setShowForm(true); }}>
            <Plus className="h-4 w-4" /> Tambah Mapel
          </Button>
        </div>

        {loading ? (
          <div className="space-y-3">
            {[1,2,3,4].map(i => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
          </div>
        ) : records.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-center">
            <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
              <BookOpen className="h-8 w-8 text-muted-foreground" />
            </div>
            <h3 className="text-lg font-semibold text-foreground mb-1">
              {search ? 'Tidak ditemukan' : 'Belum Ada Mata Pelajaran'}
            </h3>
            <p className="text-sm text-muted-foreground max-w-md">
              {search ? 'Coba ubah kata kunci pencarian.' : 'Tambahkan mata pelajaran baru dengan menekan tombol "Tambah Mapel" di atas.'}
            </p>
          </div>
        ) : (
          <SortableMapelList
            records={records}
            onReorder={handleReorder}
            onToggleAktif={handleToggleAktif}
            onEdit={(r) => { setEditData(r); setShowForm(true); }}
            onDelete={(id) => setDeleteId(id)}
            isDraggable={!search}
          />
        )}
      </Card>

      {showForm && (
        <MapelFormDialog
          data={editData}
          onSave={handleSave}
          onClose={() => { setShowForm(false); setEditData(null); }}
        />
      )}

      <AlertDialog open={!!deleteId} onOpenChange={v => !v && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Mata Pelajaran</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus mata pelajaran ini? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

