src/components/layout/Topbar.tsx.content:
import { useState, useEffect } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { useLocation } from 'react-router-dom';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { Bell, MessageCircle, Menu, CalendarDays, ChevronLeft, ChevronRight, Megaphone } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Link } from 'react-router-dom';
import { getTopInfo, GetTopInfoOutputType } from 'zite-endpoints-sdk';

type NotifType = GetTopInfoOutputType['notifications'][0];

const pageTitles: Record<string, string> = {
  '/': 'Dashboard', '/lembaga': 'Lembaga',
  '/manajemen/siswa': 'Siswa', '/manajemen/guru': 'Guru & Tendik',
  '/manajemen/kelas': 'Rombongan Belajar',
  '/akademik': 'Akademik',
  '/sarana': 'Sarana & Prasarana',
  '/lms/jurnal': 'Jurnal Mengajar', '/lms/tugas': 'Tugas',
  '/evaluasi/buku-nilai': 'Buku Nilai',
  '/pengaturan': 'Pengaturan', '/absensi': 'Absensi', '/nilai': 'Penilaian',
  '/keuangan/tagihan': 'Tagihan SPP', '/kesiswaan/ekstrakurikuler': 'Ekstrakurikuler',
  '/kesiswaan/prestasi': 'Prestasi', '/konten/pengumuman': 'Pengumuman',
};

// ── Elegant mini-calendar ──────────────────────────────────────────────────
function ElegantCalendar({ agendaDates }: { agendaDates: Date[] }) {
  const [view, setView] = useState(new Date());
  const today = new Date();
  const yr = view.getFullYear();
  const mo = view.getMonth();
  const firstDay = new Date(yr, mo, 1).getDay();
  const daysInMo = new Date(yr, mo + 1, 0).getDate();
  const cells: (number | null)[] = Array(firstDay).fill(null);
  for (let d = 1; d <= daysInMo; d++) cells.push(d);
  while (cells.length % 7 !== 0) cells.push(null);
  const headers = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
  const monthLabel = format(view, 'MMMM yyyy', { locale: id });

  return (
    <div className="w-72 overflow-hidden rounded-xl shadow-lg border border-border bg-card">
      {/* Coloured header */}
      <div className="bg-primary px-4 py-3 flex items-center justify-between">
        <button onClick={() => setView(new Date(yr, mo - 1, 1))}
          className="h-7 w-7 rounded-lg bg-primary-foreground/10 hover:bg-primary-foreground/20 flex items-center justify-center transition-colors">
          <ChevronLeft className="h-4 w-4 text-primary-foreground" />
        </button>
        <span className="text-primary-foreground font-bold text-sm capitalize">{monthLabel}</span>
        <button onClick={() => setView(new Date(yr, mo + 1, 1))}
          className="h-7 w-7 rounded-lg bg-primary-foreground/10 hover:bg-primary-foreground/20 flex items-center justify-center transition-colors">
          <ChevronRight className="h-4 w-4 text-primary-foreground" />
        </button>
      </div>

      <div className="p-3">
        {/* Day headers */}
        <div className="grid grid-cols-7 mb-1">
          {headers.map((h, i) => (
            <div key={h} className={`text-center text-[11px] font-bold py-1 ${i === 0 ? 'text-destructive' : 'text-muted-foreground'}`}>{h}</div>
          ))}
        </div>
        {/* Day cells */}
        <div className="grid grid-cols-7 gap-y-0.5">
          {cells.map((day, i) => {
            if (!day) return <div key={`e-${i}`} className="h-8" />;
            const date = new Date(yr, mo, day);
            const isSun = date.getDay() === 0;
            const isTodayCell = day === today.getDate() && mo === today.getMonth() && yr === today.getFullYear();
            const hasAgenda = agendaDates.some(d => d.getDate() === day && d.getMonth() === mo && d.getFullYear() === yr);
            return (
              <div key={`d-${day}`} className="flex justify-center">
                <div className={`relative h-8 w-8 flex items-center justify-center rounded-full text-xs font-medium select-none transition-colors
                  ${isTodayCell ? 'bg-primary text-primary-foreground font-bold shadow-md' : ''}
                  ${isSun && !isTodayCell ? 'text-destructive font-semibold' : ''}
                  ${!isTodayCell && !isSun ? 'text-foreground hover:bg-muted' : ''}
                  ${hasAgenda && !isTodayCell ? 'ring-1 ring-primary/40 bg-primary/5' : ''}
                `}>
                  {day}
                  {hasAgenda && (
                    <span className={`absolute bottom-0.5 left-1/2 -translate-x-1/2 h-1 w-1 rounded-full ${isTodayCell ? 'bg-primary-foreground' : 'bg-primary'}`} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
        {/* Legend */}
        <div className="mt-3 pt-2.5 border-t border-border/60 flex items-center gap-4 text-[10px] text-muted-foreground">
          <div className="flex items-center gap-1"><span className="h-1.5 w-1.5 rounded-full bg-destructive" />Libur</div>
          {agendaDates.length > 0 && <div className="flex items-center gap-1"><span className="h-1.5 w-1.5 rounded-full bg-primary" />Agenda</div>}
          <div className="flex items-center gap-1"><span className="h-4 w-4 rounded-full bg-primary/20 flex items-center justify-center text-[9px] font-bold text-primary">{today.getDate()}</span>Hari ini</div>
        </div>
      </div>
    </div>
  );
}

// ── Main Topbar ────────────────────────────────────────────────────────────
interface TopbarProps { onMenuClick: () => void; }

export default function Topbar({ onMenuClick }: TopbarProps) {
  const { user } = useAuth();
  const location = useLocation();
  const [calOpen, setCalOpen] = useState(false);
  const [bellOpen, setBellOpen] = useState(false);
  const [notifications, setNotifications] = useState<NotifType[]>([]);
  const [adminPhone, setAdminPhone] = useState('');

  const displayName = user?.firstName || user?.email?.split('@')[0] || 'Admin';
  const initials = (user?.firstName?.[0] || user?.email?.[0] || 'A').toUpperCase();
  const pageTitle = pageTitles[location.pathname] ?? 'Dashboard';
  const today = new Date();
  const formattedDate = format(today, 'EEE, dd MMM yyyy', { locale: id });

  useEffect(() => {
    if (!user) return;
    getTopInfo({}).then(data => {
      setNotifications(data.notifications);
      setAdminPhone(data.adminPhone || '');
    }).catch(() => {});
  }, [user]);

  const handleWhatsApp = () => {
    if (!adminPhone) return;
    const num = adminPhone.replace(/\D/g, '');
    const wa = num.startsWith('0') ? '62' + num.slice(1) : num;
    window.open(`https://wa.me/${wa}`, '_blank');
  };

  const agendaDates = notifications
    .filter(n => n.tanggalPublish)
    .map(n => new Date(n.tanggalPublish!));

  return (
    <div className="sticky top-0 z-40 flex h-16 items-center gap-4 bg-card border-b border-border px-5">
      <Button variant="ghost" size="icon" className="lg:hidden flex-shrink-0" onClick={onMenuClick}>
        <Menu className="h-5 w-5" />
      </Button>
      <div className="hidden lg:block flex-shrink-0">
        <p className="text-[15px] font-bold text-foreground leading-none">Hi, {displayName}</p>
        <p className="text-[11px] text-muted-foreground mt-0.5 leading-none">{pageTitle}</p>
      </div>
      <p className="lg:hidden text-base font-bold text-foreground flex-1">{pageTitle}</p>
      <div className="flex-1" />

      <div className="flex items-center gap-1.5 flex-shrink-0">
        {/* Date → Calendar popup */}
        <Popover open={calOpen} onOpenChange={setCalOpen}>
          <PopoverTrigger asChild>
            <button className="hidden lg:flex items-center gap-1.5 text-[12px] font-medium text-primary bg-primary/8 hover:bg-primary/15 px-3 py-1.5 rounded-lg border border-primary/20 capitalize cursor-pointer transition-colors select-none">
              <CalendarDays className="h-3.5 w-3.5" />
              {formattedDate}
            </button>
          </PopoverTrigger>
          <PopoverContent className="w-auto p-0 border-0 shadow-xl" align="end">
            <ElegantCalendar agendaDates={agendaDates} />
          </PopoverContent>
        </Popover>

        {/* WhatsApp Admin */}
        <button
          onClick={handleWhatsApp}
          title={adminPhone ? `Chat Admin: ${adminPhone}` : 'Nomor admin belum diatur'}
          className={`rounded-xl h-9 w-9 flex items-center justify-center transition-colors ${adminPhone ? 'text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50 cursor-pointer' : 'text-muted-foreground cursor-not-allowed opacity-50'}`}
        >
          <MessageCircle className="h-4 w-4" />
        </button>

        {/* Bell → Notification dropdown */}
        <Popover open={bellOpen} onOpenChange={setBellOpen}>
          <PopoverTrigger asChild>
            <button className="rounded-xl h-9 w-9 flex items-center justify-center text-orange-500 hover:text-orange-600 hover:bg-orange-50 relative transition-colors">
              <Bell className="h-4 w-4" />
              {notifications.length > 0 && (
                <span className="absolute top-1.5 right-1.5 h-2 w-2 rounded-full bg-orange-500 border-2 border-card animate-pulse" />
              )}
            </button>
          </PopoverTrigger>
          <PopoverContent className="w-80 p-0 shadow-xl" align="end">
            <div className="flex items-center justify-between px-4 py-3 border-b border-border bg-gradient-to-r from-orange-50 to-amber-50">
              <span className="font-semibold text-sm text-foreground">Informasi Terkini</span>
              {notifications.length > 0 && (
                <span className="text-xs bg-orange-500 text-white px-2 py-0.5 rounded-full font-medium">
                  {notifications.length}
                </span>
              )}
            </div>
            <div className="max-h-72 overflow-y-auto">
              {notifications.length === 0 ? (
                <div className="py-10 text-center">
                  <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
                  <p className="text-sm text-muted-foreground">Belum ada informasi terbaru</p>
                </div>
              ) : (
                notifications.map((n, i) => (
                  <div key={n.id} className={`px-4 py-3 hover:bg-muted/40 transition-colors ${i < notifications.length - 1 ? 'border-b border-border/40' : ''}`}>
                    <div className="flex gap-3">
                      <div className="h-8 w-8 rounded-lg bg-orange-100 flex items-center justify-center flex-shrink-0 mt-0.5">
                        <Megaphone className="h-3.5 w-3.5 text-orange-500" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium leading-snug line-clamp-2">{n.judul || 'Pengumuman'}</p>
                        <div className="flex items-center gap-2 mt-1 flex-wrap">
                          {n.target && (
                            <span className="text-[10px] bg-muted px-1.5 py-0.5 rounded text-muted-foreground font-medium">{n.target}</span>
                          )}
                          {n.tanggalPublish && (
                            <span className="text-[10px] text-muted-foreground">
                              {format(new Date(n.tanggalPublish), 'dd MMM yyyy', { locale: id })}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
            <div className="border-t border-border p-2">
              <Link
                to="/konten/pengumuman"
                onClick={() => setBellOpen(false)}
                className="w-full text-sm text-orange-500 hover:text-orange-600 py-1.5 font-semibold flex items-center justify-center gap-1.5 hover:bg-orange-50 rounded-md transition-colors"
              >
                Lihat Semua Informasi
                <ChevronRight className="h-3.5 w-3.5" />
              </Link>
            </div>
          </PopoverContent>
        </Popover>

        {/* Avatar */}
        <div className="h-9 w-9 rounded-full bg-primary flex items-center justify-center shadow-sm ml-1 cursor-pointer">
          <span className="text-sm font-bold text-primary-foreground">{initials}</span>
        </div>
      </div>
    </div>
  );
}

