import { useState, useEffect, useCallback } from 'react';
import { Plus, CalendarDays, Loader2, List, Settings2, Printer, FileSpreadsheet, ChevronDown, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { getJadwalPelajaran, saveJadwalEntry, deleteJadwalEntry, getAllJadwalForPrint } from 'zite-endpoints-sdk';
import type { GetJadwalPelajaranOutputType, GetAllJadwalForPrintOutputType } from 'zite-endpoints-sdk';
import JadwalFormDialog, { type JadwalFormData } from '@/components/jadwal/JadwalFormDialog';
import TimetableGrid, { type JadwalEntry } from '@/components/jadwal/TimetableGrid';
import JadwalTableView from '@/components/jadwal/JadwalTableView';
import PengaturanJadwalSheet, { loadSettings, isSpecialSlot, type JadwalSettings } from '@/components/jadwal/PengaturanJadwalSheet';
import { printJadwal, printAllKelas, exportJadwalExcel, exportAllKelasExcel } from '@/lib/printJadwal';
import GenerateJadwalDialog from '@/components/jadwal/GenerateJadwalDialog';

type KelasItem = GetJadwalPelajaranOutputType['kelasList'][0];
type MapelItem = GetJadwalPelajaranOutputType['mapelList'][0];
type GuruItem = GetJadwalPelajaranOutputType['guruList'][0];

export default function JadwalTab() {
  const [kelasId, setKelasId] = useState('');
  const [jadwal, setJadwal] = useState<JadwalEntry[]>([]);
  const [kelasList, setKelasList] = useState<KelasItem[]>([]);
  const [mapelList, setMapelList] = useState<MapelItem[]>([]);
  const [guruList, setGuruList] = useState<GuruItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [initialLoad, setInitialLoad] = useState(true);
  const [formOpen, setFormOpen] = useState(false);
  const [editEntry, setEditEntry] = useState<JadwalFormData | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [settings, setSettings] = useState<JadwalSettings>(loadSettings);
  const [printLoading, setPrintLoading] = useState(false);
  const [generateOpen, setGenerateOpen] = useState(false);

  useEffect(() => {
    setLoading(true);
    getJadwalPelajaran({})
      .then(res => {
        setKelasList(res.kelasList);
        setMapelList(res.mapelList);
        setGuruList(res.guruList);
        if (res.kelasList.length > 0) setKelasId(res.kelasList[0].id);
      })
      .catch(() => toast.error('Gagal memuat data'))
      .finally(() => { setLoading(false); setInitialLoad(false); });
  }, []);

  const fetchJadwal = useCallback(async () => {
    if (!kelasId) return;
    setLoading(true);
    try {
      const res = await getJadwalPelajaran({ kelasId });
      setJadwal(res.jadwal);
      setMapelList(res.mapelList);
      setGuruList(res.guruList);
    } catch {
      toast.error('Gagal memuat jadwal');
    } finally {
      setLoading(false);
    }
  }, [kelasId]);

  useEffect(() => {
    if (!initialLoad) fetchJadwal();
  }, [fetchJadwal, initialLoad]);

  const handleSave = async (data: JadwalFormData) => {
    await saveJadwalEntry({
      id: data.id, kelasId, hari: data.hari,
      jamMulai: data.jamMulai, jamSelesai: data.jamSelesai,
      mapelId: data.mapelId, guruId: data.guruId,
    });
    toast.success(data.id ? 'Jadwal berhasil diperbarui' : 'Jadwal berhasil ditambahkan');
    fetchJadwal();
  };

  const handleSaveMulti = async (entries: JadwalFormData[]) => {
    for (const data of entries) {
      await saveJadwalEntry({
        kelasId, hari: data.hari,
        jamMulai: data.jamMulai, jamSelesai: data.jamSelesai,
        mapelId: data.mapelId, guruId: data.guruId,
      });
    }
    toast.success(`${entries.length} sesi jadwal berhasil ditambahkan`);
    fetchJadwal();
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      await deleteJadwalEntry({ id: deleteId });
      toast.success('Jadwal berhasil dihapus');
      setDeleteId(null);
      fetchJadwal();
    } catch {
      toast.error('Gagal menghapus jadwal');
    } finally {
      setDeleting(false);
    }
  };

  const openAdd = (hari?: string) => {
    setEditEntry(hari ? { hari, jamMulai: '', jamSelesai: '', mapelId: '', guruId: '' } : { hari: settings.hariAktif[0] || 'Senin', jamMulai: '', jamSelesai: '', mapelId: '', guruId: '' });
    setFormOpen(true);
  };

  const openEdit = (entry: JadwalEntry) => {
    setEditEntry({
      id: entry.id, hari: entry.hari,
      jamMulai: entry.jamMulai, jamSelesai: entry.jamSelesai,
      mapelId: entry.mapelId, guruId: entry.guruId,
    });
    setFormOpen(true);
  };

  const selectedKelas = kelasList.find(k => k.id === kelasId);
  const kelasLabel = selectedKelas ? `${selectedKelas.tingkat} – ${selectedKelas.nama}` : '';

  // Fetch school info + all kelas data for print/export actions
  const fetchPrintData = async () => {
    setPrintLoading(true);
    try {
      const data = await getAllJadwalForPrint({});
      return data;
    } catch {
      toast.error('Gagal memuat data cetak');
      return null;
    } finally {
      setPrintLoading(false);
    }
  };

  const handlePrintSingle = async () => {
    const data = await fetchPrintData();
    printJadwal(jadwal, settings, kelasLabel, data?.sekolah, data?.tahunAjaran, data?.semester);
  };

  const handlePrintAll = async () => {
    const data = await fetchPrintData();
    if (!data) return;
    printAllKelas(data.kelasJadwal, settings, data.sekolah, data.tahunAjaran, data.semester);
  };

  const handleExportSingle = async () => {
    const data = await fetchPrintData();
    exportJadwalExcel(jadwal, settings, kelasLabel, data?.sekolah, data?.tahunAjaran, data?.semester);
  };

  const handleExportAll = async () => {
    const data = await fetchPrintData();
    if (!data) return;
    exportAllKelasExcel(data.kelasJadwal, settings, data.sekolah, data.tahunAjaran, data.semester);
  };

  if (initialLoad) {
    return (
      <Card className="p-6">
        <div className="space-y-4">
          <Skeleton className="h-10 w-64" />
          <div className="grid grid-cols-5 gap-3">
            {[1,2,3,4,5].map(i => <Skeleton key={i} className="h-48 rounded-xl" />)}
          </div>
        </div>
      </Card>
    );
  }

  if (kelasList.length === 0) {
    return (
      <Card className="p-6">
        <div className="flex flex-col items-center justify-center py-16 text-center">
          <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
            <CalendarDays className="h-8 w-8 text-muted-foreground" />
          </div>
          <h3 className="text-lg font-semibold text-foreground mb-1">Belum Ada Kelas</h3>
          <p className="text-sm text-muted-foreground max-w-md">
            Tambahkan kelas terlebih dahulu di menu Sarana & Prasarana sebelum mengatur jadwal pelajaran.
          </p>
        </div>
      </Card>
    );
  }

  const totalJpSlots = settings.slots.filter(s => !isSpecialSlot(s)).length;

  return (
    <>
      <Card className="p-5">
        {/* Toolbar */}
        <div className="flex items-center justify-between flex-wrap gap-3 mb-5">
          <div className="flex items-center gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-muted-foreground whitespace-nowrap">Kelas:</span>
              <Select value={kelasId} onValueChange={setKelasId}>
                <SelectTrigger className="w-48">
                  <SelectValue placeholder="Pilih kelas" />
                </SelectTrigger>
                <SelectContent>
                  {kelasList.map(k => (
                    <SelectItem key={k.id} value={k.id}>
                      {k.tingkat} – {k.nama}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <div className="flex items-center border border-border rounded-lg overflow-hidden">
              <button
                onClick={() => setViewMode('grid')}
                className={`px-3 py-1.5 text-xs font-medium transition-colors ${viewMode === 'grid' ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}
              >
                <CalendarDays className="h-3.5 w-3.5" />
              </button>
              <button
                onClick={() => setViewMode('table')}
                className={`px-3 py-1.5 text-xs font-medium transition-colors ${viewMode === 'table' ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}
              >
                <List className="h-3.5 w-3.5" />
              </button>
            </div>

            {/* Print dropdown */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="gap-2" disabled={loading || printLoading}>
                  {printLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Printer className="h-4 w-4" />}
                  Cetak
                  <ChevronDown className="h-3 w-3" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={handlePrintSingle}>
                  <Printer className="h-4 w-4 mr-2" />
                  Cetak Kelas Ini
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handlePrintAll}>
                  <Printer className="h-4 w-4 mr-2" />
                  Cetak Semua Kelas
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            {/* Export dropdown */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="gap-2" disabled={loading || printLoading}>
                  {printLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <FileSpreadsheet className="h-4 w-4" />}
                  Export
                  <ChevronDown className="h-3 w-3" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={handleExportSingle}>
                  <FileSpreadsheet className="h-4 w-4 mr-2" />
                  Export Kelas Ini (.xls)
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handleExportAll}>
                  <FileSpreadsheet className="h-4 w-4 mr-2" />
                  Export Semua Kelas (.xls)
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            <Button variant="outline" className="gap-2 border-primary/30 text-primary hover:bg-primary/5" onClick={() => setGenerateOpen(true)}>
              <Sparkles className="h-4 w-4" /> Generate AI
            </Button>
            <Button variant="outline" className="gap-2" onClick={() => setSettingsOpen(true)}>
              <Settings2 className="h-4 w-4" /> Pengaturan
            </Button>
            <Button className="gap-2" onClick={() => openAdd()}>
              <Plus className="h-4 w-4" /> Tambah
            </Button>
          </div>
        </div>

        {/* JP Info bar */}
        <div className="flex items-center gap-3 mb-4 px-3 py-2 rounded-lg bg-muted/50 border border-border text-xs text-muted-foreground flex-wrap">
          <span><strong className="text-foreground">{settings.durasiJp}</strong> menit/JP</span>
          <span className="text-border">|</span>
          <span><strong className="text-foreground">{totalJpSlots}</strong> JP/hari</span>
          <span className="text-border">|</span>
          <span>{settings.jamMulai} – {settings.slots[settings.slots.length - 1]?.selesai || '–'}</span>
          <span className="text-border">|</span>
          <span>{settings.hariAktif.length} hari aktif</span>
        </div>

        {/* Content */}
        {loading && !initialLoad ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
          </div>
        ) : viewMode === 'grid' ? (
          <TimetableGrid
            jadwal={jadwal}
            activeDays={settings.hariAktif}
            settings={settings}
            onEdit={openEdit}
            onDelete={id => setDeleteId(id)}
            onAddToDay={hari => openAdd(hari)}
          />
        ) : (
          <JadwalTableView
            jadwal={jadwal}
            onEdit={openEdit}
            onDelete={id => setDeleteId(id)}
          />
        )}

        {/* Summary */}
        {!loading && jadwal.length > 0 && (
          <div className="mt-4 pt-4 border-t border-border flex items-center gap-4 text-xs text-muted-foreground">
            <span><strong className="text-foreground">{jadwal.length}</strong> jam pelajaran</span>
            <span><strong className="text-foreground">{new Set(jadwal.map(j => j.hari)).size}</strong> hari aktif</span>
            <span><strong className="text-foreground">{new Set(jadwal.map(j => j.mapelId)).size}</strong> mata pelajaran</span>
          </div>
        )}
      </Card>

      <JadwalFormDialog
        open={formOpen}
        onClose={() => { setFormOpen(false); setEditEntry(null); }}
        onSubmit={handleSave}
        onSubmitMulti={handleSaveMulti}
        initial={editEntry}
        mapelList={mapelList}
        guruList={guruList}
        settings={settings}
        existingJadwal={jadwal}
      />

      <GenerateJadwalDialog
        open={generateOpen}
        onClose={() => setGenerateOpen(false)}
        onGenerated={() => fetchJadwal()}
        kelasId={kelasId}
        kelasLabel={kelasLabel}
        mapelList={mapelList}
        guruList={guruList}
        settings={settings}
      />

      <PengaturanJadwalSheet
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        onSave={setSettings}
        initialSettings={settings}
      />

      <AlertDialog open={!!deleteId} onOpenChange={v => !v && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Jadwal?</AlertDialogTitle>
            <AlertDialogDescription>
              Jadwal pelajaran ini akan dihapus. Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

