import { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Skeleton } from '@/components/ui/skeleton';
import { Plus, Search, MoreVertical, Eye, Pencil, KeyRound, Trash2, Download, Upload, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { toast } from 'sonner';
import { Toaster } from '@/components/ui/sonner';
import { getGuru, deleteGuru, exportGuru, updateGuru } from 'zite-endpoints-sdk';
import ExportFormatDialog, { ExportFormat } from '@/components/shared/ExportFormatDialog';
import { generateDataExcel } from '@/lib/generateExcelTemplate';
import { printToPdf } from '@/lib/generatePdfPrint';
import type { GetGuruOutputType } from 'zite-endpoints-sdk';
import { useAuth } from 'zite-auth-sdk';
import GuruFormDialog from '@/components/guru/GuruFormDialog';
import GuruDetailDialog from '@/components/guru/GuruDetailDialog';
import ResetAkunDialog from '@/components/guru/ResetAkunDialog';
import ImportGuruWizard from '@/components/guru/ImportGuruWizard';

type GuruType = GetGuruOutputType['guru'][0];

function ActiveToggle({ active, onToggle }: { active: boolean; onToggle: () => void }) {
  return (
    <button
      type="button"
      onClick={onToggle}
      title="Klik untuk mengubah status aktif"
      className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all cursor-pointer hover:opacity-80 select-none ${active ? 'bg-green-600 text-white' : 'bg-red-500 text-white'}`}
    >
      <span className={`w-2 h-2 rounded-full bg-white opacity-80 ${active ? '' : 'order-last'}`} />
      {active ? 'Aktif' : 'Non Aktif'}
    </button>
  );
}

const TUGAS_UTAMA_COLORS: Record<string, string> = {
  'Kepala Sekolah/Madrasah': 'bg-purple-100 text-purple-800 border border-purple-200',
  'Guru Kelas': 'bg-blue-100 text-blue-800 border border-blue-200',
  'Guru Mata Pelajaran': 'bg-sky-100 text-sky-800 border border-sky-200',
  'Guru BK': 'bg-indigo-100 text-indigo-800 border border-indigo-200',
  'Tata Usaha': 'bg-amber-100 text-amber-800 border border-amber-200',
  'Operator': 'bg-cyan-100 text-cyan-800 border border-cyan-200',
  'Bendahara': 'bg-orange-100 text-orange-800 border border-orange-200',
  'Petugas Keamanan': 'bg-red-100 text-red-800 border border-red-200',
  'Petugas Kebersihan': 'bg-teal-100 text-teal-800 border border-teal-200',
  'Pembina Ekskul': 'bg-lime-100 text-lime-800 border border-lime-200',
  'Lainnya': 'bg-gray-100 text-gray-700 border border-gray-200',
};

const TUGAS_TAMBAHAN_COLORS: Record<string, string> = {
  'Wakil Kepala Sekolah/Madrasah': 'bg-violet-100 text-violet-800 border border-violet-200',
  'Kepala Pustakawan': 'bg-pink-100 text-pink-800 border border-pink-200',
  'Kepala Laboratorium': 'bg-fuchsia-100 text-fuchsia-800 border border-fuchsia-200',
  'Wali Kelas': 'bg-emerald-100 text-emerald-800 border border-emerald-200',
  'Guru Piket': 'bg-yellow-100 text-yellow-800 border border-yellow-200',
  'Koordinator Projek': 'bg-rose-100 text-rose-800 border border-rose-200',
  'Guru Wali': 'bg-green-100 text-green-800 border border-green-200',
};

function TugasUtamaBadge({ value }: { value?: string }) {
  if (!value) return <span className="text-muted-foreground text-xs">-</span>;
  const cls = TUGAS_UTAMA_COLORS[value] || 'bg-blue-100 text-blue-800 border border-blue-200';
  return <span className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-medium ${cls}`}>{value}</span>;
}

function TugasTambahanList({ items }: { items?: string[] }) {
  if (!items || items.length === 0) return <span className="text-muted-foreground text-xs">-</span>;
  return (
    <div className="flex flex-wrap gap-1">
      {items.map((t) => {
        const cls = TUGAS_TAMBAHAN_COLORS[t] || 'bg-slate-100 text-slate-700 border border-slate-200';
        return <span key={t} className={`inline-flex items-center px-2 py-0.5 rounded-md text-xs font-medium ${cls}`}>{t}</span>;
      })}
    </div>
  );
}

function getPaginationPages(current: number, total: number): (number | '...')[] {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  const pages: (number | '...')[] = [1];
  if (current > 3) pages.push('...');
  for (let i = Math.max(2, current - 1); i <= Math.min(total - 1, current + 1); i++) pages.push(i);
  if (current < total - 2) pages.push('...');
  pages.push(total);
  return pages;
}

export default function GuruPage() {
  const { user } = useAuth();
  const [guruList, setGuruList] = useState<GuruType[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [kategoriFilter, setKategoriFilter] = useState('');
  const [pageLimit, setPageLimit] = useState('25');
  const [currentPage, setCurrentPage] = useState(1);
  const [formOpen, setFormOpen] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [selected, setSelected] = useState<GuruType | null>(null);
  const [importOpen, setImportOpen] = useState(false);
  const [exportDialogOpen, setExportDialogOpen] = useState(false);

  const sekolahId = Array.isArray(user?.sekolah) ? user.sekolah[0] : user?.sekolah;

  const fetchGuru = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getGuru({ search, kategori: kategoriFilter || undefined, sekolahId });
      setGuruList(res.guru);
      setCurrentPage(1);
    } finally {
      setLoading(false);
    }
  }, [search, kategoriFilter, sekolahId]);

  useEffect(() => { fetchGuru(); }, [fetchGuru]);

  const handlePageLimitChange = (value: string) => {
    setPageLimit(value);
    setCurrentPage(1);
  };

  const EXCEL_COLS = [
    { label: 'Nama Lengkap', key: 'namaLengkap', width: 200 },
    { label: 'NIP/NUPTK', key: 'nipnuptk', isText: true, width: 170 },
    { label: 'NIK', key: 'nik', isText: true, width: 160 },
    { label: 'Jenis Kelamin', key: 'jenisKelamin', width: 130 },
    { label: 'Tempat Lahir', key: 'tempatLahir', width: 140 },
    { label: 'Tanggal Lahir', key: 'tanggalLahir', width: 130 },
    { label: 'No HP', key: 'noHp', isText: true, width: 150 },
    { label: 'Email', key: 'email', width: 190 },
    { label: 'Alamat', key: 'alamat', width: 210 },
    { label: 'Pendidikan Terakhir', key: 'pendidikanTerakhir', width: 160 },
    { label: 'Status Kepegawaian', key: 'statusKepegawaian', width: 170 },
    { label: 'Kategori Pegawai', key: 'kategoriPegawai', width: 150 },
    { label: 'Tugas Utama', key: 'tugasUtama', width: 180 },
    { label: 'Tugas Tambahan', key: 'tugasTambahan', width: 220 },
    { label: 'JP', key: 'jp', width: 60 },
    { label: 'Mulai Bertugas', key: 'mulaiBertugas', width: 130 },
    { label: 'Akhir Bertugas', key: 'akhirBertugas', width: 130 },
    { label: 'Username', key: 'usernameGuru', width: 150 },
    { label: 'Status Aktif', key: '_aktif', width: 110 },
  ];

  const PDF_COLS = [
    { label: 'Nama Lengkap', key: 'namaLengkap', width: '150px' },
    { label: 'NIP/NUPTK', key: 'nipnuptk', width: '110px' },
    { label: 'JK', key: 'jenisKelamin', width: '45px' },
    { label: 'Kategori', key: 'kategoriPegawai', width: '65px' },
    { label: 'Tugas Utama', key: 'tugasUtama', width: '130px' },
    { label: 'JP', key: 'jp', width: '40px' },
    { label: 'Status Kpgw.', key: 'statusKepegawaian', width: '110px' },
    { label: 'Username', key: 'usernameGuru', width: '100px' },
    { label: 'Status', key: '_aktif', width: '55px' },
  ];

  const handleExport = async (format: ExportFormat) => {
    const result = await exportGuru({});
    const dateStr = new Date().toISOString().slice(0, 10);
    const enriched = result.data.map(g => ({ ...g, _aktif: g.active !== false ? 'Aktif' : 'Non Aktif' }));
    if (format === 'excel') {
      generateDataExcel({ filename: `data_guru_${dateStr}.xls`, title: 'DAFTAR DATA GURU & TENAGA KEPENDIDIKAN', schoolName: result.sekolah.namaSekolah, schoolAddress: result.sekolah.alamat, schoolPhone: result.sekolah.telepon, columns: EXCEL_COLS, data: enriched });
      toast.success(`${result.data.length} data guru berhasil diekspor ke Excel`);
    } else {
      printToPdf('DAFTAR DATA GURU & TENAGA KEPENDIDIKAN', result.sekolah, PDF_COLS, enriched);
      toast.success('Halaman cetak PDF dibuka di tab baru');
    }
  };

  const handleDelete = async () => {
    if (!selected) return;
    try {
      await deleteGuru({ id: selected.id });
      toast.success('Data berhasil dihapus');
      fetchGuru();
    } catch {
      toast.error('Gagal menghapus data');
    } finally {
      setDeleteOpen(false);
    }
  };

  const handleToggleActive = async (guru: GuruType) => {
    const newActive = !(guru.active !== false);
    try {
      await updateGuru({ id: guru.id, active: newActive });
      setGuruList((prev) => prev.map((g) => g.id === guru.id ? { ...g, active: newActive } : g));
    } catch {
      toast.error('Gagal mengubah status aktif');
    }
  };

  // Pagination
  const limit = pageLimit === 'all' ? null : parseInt(pageLimit);
  const totalPages = limit ? Math.ceil(guruList.length / limit) : 1;
  const displayedGuru = limit
    ? guruList.slice((currentPage - 1) * limit, currentPage * limit)
    : guruList;

  return (
    <div className="space-y-6">
      <Toaster />
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Data Guru & Tendik</h2>
          <p className="text-muted-foreground">Kelola data guru dan tenaga kependidikan</p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={() => setExportDialogOpen(true)} className="gap-2">
            <Download className="h-4 w-4" />Export
          </Button>
          <Button variant="outline" onClick={() => setImportOpen(true)} className="gap-2">
            <Upload className="h-4 w-4" />Import
          </Button>
          <Button onClick={() => { setSelected(null); setFormOpen(true); }}>
            <Plus className="h-4 w-4 mr-2" />Tambah
          </Button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input className="pl-9" placeholder="Cari nama, NIP/NUPTK, username..." value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
        <Select value={kategoriFilter || '__all__'} onValueChange={(v) => setKategoriFilter(v === '__all__' ? '' : v)}>
          <SelectTrigger className="w-[160px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__all__">Semua Kategori</SelectItem>
            <SelectItem value="Guru">Guru</SelectItem>
            <SelectItem value="Tendik">Tendik</SelectItem>
          </SelectContent>
        </Select>
        {/* Row limit selector — inline style */}
        <div className="flex items-center gap-0 bg-muted rounded-lg border border-border overflow-hidden h-9 text-sm">
          <span className="px-2.5 text-muted-foreground whitespace-nowrap select-none">Tampilkan</span>
          <Select value={pageLimit} onValueChange={handlePageLimitChange}>
            <SelectTrigger className="h-full border-0 border-l border-border rounded-none bg-card w-[70px] text-foreground font-medium focus:ring-0 focus:ring-offset-0">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua</SelectItem>
              <SelectItem value="10">10</SelectItem>
              <SelectItem value="25">25</SelectItem>
              <SelectItem value="50">50</SelectItem>
              <SelectItem value="100">100</SelectItem>
            </SelectContent>
          </Select>
          <span className="px-2.5 text-muted-foreground whitespace-nowrap select-none">baris</span>
        </div>
      </div>

      {/* Table */}
      <div className="rounded-lg border bg-card overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/50">
              <TableHead className="w-10">No</TableHead>
              <TableHead>NIP/NUPTK</TableHead>
              <TableHead>Nama</TableHead>
              <TableHead>Username</TableHead>
              <TableHead>Tugas Utama</TableHead>
              <TableHead>Tugas Tambahan</TableHead>
              <TableHead className="w-14 text-center">JP</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <TableRow key={i}>
                  {Array.from({ length: 9 }).map((_, j) => (
                    <TableCell key={j}><Skeleton className="h-4 w-full" /></TableCell>
                  ))}
                </TableRow>
              ))
            ) : displayedGuru.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} className="text-center py-12 text-muted-foreground">
                  Belum ada data guru/tendik
                </TableCell>
              </TableRow>
            ) : (
              displayedGuru.map((guru, idx) => {
                const rowNum = limit ? (currentPage - 1) * limit + idx + 1 : idx + 1;
                return (
                  <TableRow key={guru.id} className="hover:bg-muted/30">
                    <TableCell className="text-muted-foreground">{rowNum}</TableCell>
                    <TableCell className="font-mono text-sm tracking-wider">
                      {guru.nipnuptk || '-'}
                    </TableCell>
                    <TableCell>
                      <div>
                        <p className="font-medium">{guru.namaLengkap}</p>
                        {guru.kategoriPegawai && (
                          <span className="text-xs text-muted-foreground">{guru.kategoriPegawai}</span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-sm">{guru.usernameGuru || '-'}</TableCell>
                    <TableCell><TugasUtamaBadge value={guru.tugasUtama} /></TableCell>
                    <TableCell><TugasTambahanList items={guru.tugasTambahan} /></TableCell>
                    <TableCell className="text-center">
                      {(guru as any).jp != null ? (
                        <span className="inline-flex items-center justify-center w-8 h-8 rounded-md bg-primary/10 text-primary font-bold text-sm border border-primary/20">
                          {(guru as any).jp}
                        </span>
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <ActiveToggle active={guru.active !== false} onToggle={() => handleToggleActive(guru)} />
                    </TableCell>
                    <TableCell className="text-right">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon"><MoreVertical className="h-4 w-4" /></Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => { setSelected(guru); setDetailOpen(true); }}>
                            <Eye className="h-4 w-4 mr-2" />Detail
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => { setSelected(guru); setFormOpen(true); }}>
                            <Pencil className="h-4 w-4 mr-2" />Edit
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => { setSelected(guru); setResetOpen(true); }}>
                            <KeyRound className="h-4 w-4 mr-2" />Reset Akun
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem className="text-destructive" onClick={() => { setSelected(guru); setDeleteOpen(true); }}>
                            <Trash2 className="h-4 w-4 mr-2" />Hapus
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* Footer: info + pagination */}
      {!loading && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 -mt-2">
          <p className="text-sm text-muted-foreground">
            {limit
              ? `Halaman ${currentPage} dari ${totalPages} · ${guruList.length} total data`
              : `${guruList.length} total data`}
          </p>
          {totalPages > 1 && (
            <div className="flex items-center gap-1">
              <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === 1} onClick={() => setCurrentPage(1)}>
                <ChevronsLeft className="h-4 w-4" />
              </Button>
              <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)}>
                <ChevronLeft className="h-4 w-4" />
              </Button>
              {getPaginationPages(currentPage, totalPages).map((page, i) =>
                page === '...'
                  ? <span key={`e-${i}`} className="px-1.5 text-muted-foreground text-sm">…</span>
                  : <Button
                      key={page}
                      variant={currentPage === page ? 'default' : 'outline'}
                      size="icon"
                      className="h-8 w-8 text-sm"
                      onClick={() => setCurrentPage(page as number)}
                    >
                      {page}
                    </Button>
              )}
              <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)}>
                <ChevronRight className="h-4 w-4" />
              </Button>
              <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === totalPages} onClick={() => setCurrentPage(totalPages)}>
                <ChevronsRight className="h-4 w-4" />
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Dialogs */}
      <GuruFormDialog open={formOpen} onClose={() => setFormOpen(false)} onSuccess={fetchGuru} guru={selected} sekolahId={sekolahId} />
      <GuruDetailDialog open={detailOpen} onClose={() => setDetailOpen(false)} guru={selected} />
      {selected && (
        <ResetAkunDialog open={resetOpen} onClose={() => setResetOpen(false)} onSuccess={fetchGuru} guruId={selected.id} currentUsername={selected.usernameGuru || ''} />
      )}
      <ImportGuruWizard open={importOpen} onOpenChange={setImportOpen} onSuccess={fetchGuru} />
      <ExportFormatDialog open={exportDialogOpen} onOpenChange={setExportDialogOpen} onExport={handleExport} title="Export Data Guru & Tendik" />

      <AlertDialog open={deleteOpen} onOpenChange={setDeleteOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Data?</AlertDialogTitle>
            <AlertDialogDescription>
              Data <strong>{selected?.namaLengkap}</strong> akan dihapus permanen. Lanjutkan?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

