import { useEffect, useState } from 'react';
import { getPengumuman, GetPengumumanOutputType, createPengumuman, deletePengumuman } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Plus, Megaphone, Trash2, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

type PengumumanType = GetPengumumanOutputType[0];

export default function PengumumanPage() {
  const [pengumuman, setPengumuman] = useState<PengumumanType[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  useEffect(() => {
    loadPengumuman();
  }, []);

  const loadPengumuman = async () => {
    try {
      setLoading(true);
      const data = await getPengumuman({});
      setPengumuman(data);
    } catch (error) {
      toast.error('Gagal memuat pengumuman');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;

    try {
      await deletePengumuman({ id: deleteId });
      toast.success('Pengumuman berhasil dihapus');
      loadPengumuman();
      setDeleteId(null);
    } catch (error) {
      toast.error('Gagal menghapus pengumuman');
    }
  };

  const handleSave = async (data: any) => {
    try {
      await createPengumuman(data);
      toast.success('Pengumuman berhasil ditambahkan');
      setDialogOpen(false);
      loadPengumuman();
    } catch (error) {
      toast.error('Gagal menyimpan pengumuman');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Pengumuman</h2>
          <p className="text-muted-foreground">Kelola pengumuman sekolah</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogTrigger asChild>
            <Button className="gap-2">
              <Plus className="h-4 w-4" />
              Buat Pengumuman
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <PengumumanForm onSave={handleSave} />
          </DialogContent>
        </Dialog>
      </div>

      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      ) : pengumuman.length === 0 ? (
        <Card className="p-12 text-center">
          <Megaphone className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
          <h3 className="text-xl font-semibold mb-2">Belum Ada Pengumuman</h3>
          <p className="text-muted-foreground mb-4">
            Mulai buat pengumuman untuk dibagikan ke siswa, guru, atau orang tua
          </p>
          <Button onClick={() => setDialogOpen(true)}>
            <Plus className="h-4 w-4 mr-2" />
            Buat Pengumuman Pertama
          </Button>
        </Card>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {pengumuman.map((p) => (
            <Card key={p.id} className="relative">
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <CardTitle className="text-lg">{p.judul}</CardTitle>
                    <CardDescription className="mt-1">
                      Target: {p.target}
                    </CardDescription>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => setDeleteId(p.id)}
                    className="h-8 w-8"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground line-clamp-3">
                  {typeof p.konten === 'string' ? p.konten : 'Konten pengumuman'}
                </p>
                {p.tanggalPublish && (
                  <p className="text-xs text-muted-foreground mt-3">
                    {new Date(p.tanggalPublish).toLocaleDateString('id-ID', {
                      day: 'numeric',
                      month: 'long',
                      year: 'numeric',
                    })}
                  </p>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Pengumuman</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus pengumuman ini? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Hapus</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

interface PengumumanFormProps {
  onSave: (data: any) => void;
}

function PengumumanForm({ onSave }: PengumumanFormProps) {
  const [formData, setFormData] = useState({
    judul: '',
    konten: '',
    target: 'Semua',
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    await onSave(formData);
    setSaving(false);
  };

  return (
    <>
      <DialogHeader>
        <DialogTitle>Buat Pengumuman Baru</DialogTitle>
        <DialogDescription>
          Buat pengumuman untuk dibagikan kepada siswa, guru, atau orang tua
        </DialogDescription>
      </DialogHeader>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="judul">Judul Pengumuman *</Label>
          <Input
            id="judul"
            required
            value={formData.judul}
            onChange={(e) => setFormData({ ...formData, judul: e.target.value })}
            placeholder="Contoh: Libur Nasional"
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="target">Target Penerima *</Label>
          <Select
            value={formData.target}
            onValueChange={(value) => setFormData({ ...formData, target: value })}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Semua">Semua</SelectItem>
              <SelectItem value="Guru">Guru</SelectItem>
              <SelectItem value="Siswa">Siswa</SelectItem>
              <SelectItem value="Orang Tua">Orang Tua</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="konten">Isi Pengumuman *</Label>
          <Textarea
            id="konten"
            required
            value={formData.konten}
            onChange={(e) => setFormData({ ...formData, konten: e.target.value })}
            rows={6}
            placeholder="Tulis isi pengumuman di sini..."
          />
        </div>

        <div className="flex justify-end gap-2 pt-4">
          <Button type="submit" disabled={saving}>
            {saving ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Menyimpan...
              </>
            ) : (
              'Publikasikan'
            )}
          </Button>
        </div>
      </form>
    </>
  );
}

