import { useState, useEffect, useMemo, useCallback } from 'react';
import { Plus, Search, Pencil, Trash2, Loader2, School } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Skeleton } from '@/components/ui/skeleton';
import { toast } from 'sonner';
import { getRuangKelas, GetRuangKelasOutputType, createRuangKelas, updateRuangKelas, deleteRuangKelas } from 'zite-endpoints-sdk';
import KelasFormDialog, { KelasFormData } from '@/components/kelas/KelasFormDialog';

type KelasItem = GetRuangKelasOutputType['kelas'][0];

const TINGKAT_ROMAN: Record<string, string> = {
  'Kelas 1': 'I', 'Kelas 2': 'II', 'Kelas 3': 'III', 'Kelas 4': 'IV',
  'Kelas 5': 'V', 'Kelas 6': 'VI', 'Kelas 7': 'VII', 'Kelas 8': 'VIII',
  'Kelas 9': 'IX', 'Kelas 10': 'X', 'Kelas 11': 'XI', 'Kelas 12': 'XII',
};

export default function RuangKelasPage() {
  const [data, setData] = useState<KelasItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [formOpen, setFormOpen] = useState(false);
  const [editItem, setEditItem] = useState<KelasFormData | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = useCallback(() => {
    setLoading(true);
    getRuangKelas({}).then(res => setData(res.kelas)).catch(() => toast.error('Gagal memuat data')).finally(() => setLoading(false));
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const filtered = useMemo(() => {
    if (!search) return data;
    const q = search.toLowerCase();
    return data.filter(k =>
      k.namaKelas.toLowerCase().includes(q) ||
      (TINGKAT_ROMAN[k.tingkat] || k.tingkat).toLowerCase().includes(q) ||
      (k.waliKelasNama || '').toLowerCase().includes(q)
    );
  }, [data, search]);

  const handleCreate = async (fd: KelasFormData) => {
    await createRuangKelas({ namaKelas: fd.namaKelas, tingkat: fd.tingkat, waliKelasId: fd.waliKelasId, siswaIds: fd.siswaIds });
    toast.success('Ruang kelas berhasil ditambahkan');
    fetchData();
  };

  const handleUpdate = async (fd: KelasFormData) => {
    if (!fd.id) return;
    await updateRuangKelas({ id: fd.id, namaKelas: fd.namaKelas, tingkat: fd.tingkat, waliKelasId: fd.waliKelasId ?? null, siswaIds: fd.siswaIds });
    toast.success('Ruang kelas berhasil diperbarui');
    fetchData();
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      await deleteRuangKelas({ id: deleteId });
      toast.success('Ruang kelas berhasil dihapus');
      fetchData();
    } catch { toast.error('Gagal menghapus'); }
    finally { setDeleting(false); setDeleteId(null); }
  };

  const openEdit = (k: KelasItem) => {
    setEditItem({
      id: k.id,
      namaKelas: k.namaKelas,
      tingkat: k.tingkat,
      waliKelasId: k.waliKelasId,
      siswaIds: [],
    });
    setFormOpen(true);
  };

  const openCreate = () => {
    setEditItem(null);
    setFormOpen(true);
  };

  return (
    <>
      <Card className="p-5">
        <div className="flex items-center justify-between flex-wrap gap-3 mb-5">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Cari kelas, tingkat, wali kelas..."
              className="pl-9"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <Button className="gap-2" onClick={openCreate}>
            <Plus className="h-4 w-4" /> Tambah Ruangan
          </Button>
        </div>

        {loading ? (
          <div className="space-y-3">
            {[1,2,3].map(i => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
          </div>
        ) : filtered.length === 0 ? (
          <EmptyState hasData={data.length > 0} />
        ) : (
          <div className="rounded-lg border border-border overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/40">
                  <TableHead className="w-14 text-center">No</TableHead>
                  <TableHead className="w-24">Tingkat</TableHead>
                  <TableHead>Nama Kelas</TableHead>
                  <TableHead className="text-center w-28">Jumlah Siswa</TableHead>
                  <TableHead>Wali Kelas</TableHead>
                  <TableHead className="text-center w-28">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((k, i) => (
                  <TableRow key={k.id} className="group">
                    <TableCell className="text-center text-muted-foreground text-sm">{i + 1}</TableCell>
                    <TableCell>
                      <span className="inline-flex items-center justify-center h-7 min-w-[2rem] px-2 rounded-md bg-primary/10 text-primary text-xs font-bold">
                        {TINGKAT_ROMAN[k.tingkat] || k.tingkat}
                      </span>
                    </TableCell>
                    <TableCell className="font-medium">{k.namaKelas}</TableCell>
                    <TableCell className="text-center">
                      <span className="inline-flex items-center justify-center h-7 min-w-[2rem] px-2 rounded-full bg-muted text-sm font-semibold">
                        {k.jumlahSiswa}
                      </span>
                    </TableCell>
                    <TableCell className="text-muted-foreground">{k.waliKelasNama || '-'}</TableCell>
                    <TableCell>
                      <div className="flex items-center justify-center gap-1">
                        <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => openEdit(k)}>
                          <Pencil className="h-3.5 w-3.5 text-muted-foreground" />
                        </Button>
                        <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setDeleteId(k.id)}>
                          <Trash2 className="h-3.5 w-3.5 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </Card>

      <KelasFormDialog
        open={formOpen}
        onClose={() => setFormOpen(false)}
        onSubmit={editItem ? handleUpdate : handleCreate}
        initial={editItem}
      />

      <AlertDialog open={!!deleteId} onOpenChange={v => !v && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Ruang Kelas?</AlertDialogTitle>
            <AlertDialogDescription>
              Data kelas akan dihapus dan siswa yang terdaftar akan dilepas dari kelas ini. Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

function EmptyState({ hasData }: { hasData: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
        <School className="h-8 w-8 text-muted-foreground" />
      </div>
      <h3 className="text-lg font-semibold text-foreground mb-1">
        {hasData ? 'Tidak ditemukan' : 'Belum Ada Ruang Kelas'}
      </h3>
      <p className="text-sm text-muted-foreground max-w-md">
        {hasData
          ? 'Coba ubah kata kunci pencarian.'
          : 'Tambahkan ruang kelas baru dengan menekan tombol "Tambah Ruangan" di atas.'}
      </p>
    </div>
  );
}

