src/components/guru/GuruFormDialog.tsx.content:
import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from 'sonner';
import { createGuru, updateGuru } from 'zite-endpoints-sdk';
import type { GetGuruOutputType } from 'zite-endpoints-sdk';
import GuruFormInfoTab from './GuruFormInfoTab';
import GuruFormKepegawaianTab from './GuruFormKepegawaianTab';

type GuruType = GetGuruOutputType['guru'][0];

interface Props {
  open: boolean;
  onClose: () => void;
  onSuccess: () => void;
  guru?: GuruType | null;
  sekolahId?: string;
}

const defaultForm = {
  nipnuptk: '', nik: '', namaLengkap: '', jenisKelamin: '', tempatLahir: '',
  tanggalLahir: '', noHp: '', email: '', pendidikanTerakhir: '', usernameGuru: '',
  passwordGuru: '', statusKepegawaian: '', kategoriPegawai: 'Guru', tugasUtama: '',
  tugasTambahan: [] as string[], jp: undefined as number | undefined,
  mulaiBertugas: '', akhirBertugas: '',
  active: true, foto: [] as { url: string }[], alamat: '',
};

export default function GuruFormDialog({ open, onClose, onSuccess, guru, sekolahId }: Props) {
  const [form, setForm] = useState<Record<string, unknown>>(() =>
    guru ? { ...guru } : { ...defaultForm }
  );
  const [saving, setSaving] = useState(false);

  const handleChange = (key: string, value: unknown) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const handleSubmit = async () => {
    if (!form.namaLengkap) return toast.error('Nama lengkap wajib diisi');
    if (!form.usernameGuru) return toast.error('Username wajib diisi');
    if (!form.passwordGuru) return toast.error('Password wajib diisi');
    setSaving(true);
    try {
      if (guru) {
        await updateGuru({ id: guru.id, ...form } as Parameters<typeof updateGuru>[0]);
        toast.success('Data berhasil diperbarui');
      } else {
        await createGuru({ ...form, sekolahId, namaLengkap: form.namaLengkap as string, usernameGuru: form.usernameGuru as string, passwordGuru: form.passwordGuru as string });
        toast.success('Data berhasil disimpan');
      }
      onSuccess();
      onClose();
    } catch (e: unknown) {
      toast.error((e as Error).message || 'Gagal menyimpan data');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{guru ? 'Edit Data Guru/Tendik' : 'Tambah Guru/Tendik'}</DialogTitle>
        </DialogHeader>
        <Tabs defaultValue="info">
          <TabsList className="w-full">
            <TabsTrigger value="info" className="flex-1">Informasi Utama</TabsTrigger>
            <TabsTrigger value="kepegawaian" className="flex-1">Data Kepegawaian</TabsTrigger>
          </TabsList>
          <TabsContent value="info" className="pt-4">
            <GuruFormInfoTab form={form} onChange={handleChange} />
          </TabsContent>
          <TabsContent value="kepegawaian" className="pt-4">
            <GuruFormKepegawaianTab form={form} onChange={handleChange} />
          </TabsContent>
        </Tabs>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving}>
            {saving ? 'Menyimpan...' : 'Simpan'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/siswa/DataAlamatTab.tsx.content:
import { Label } from '@/components/ui/label';
