  provinsiAyah: string;
  kabupatenKotaAyah: string;
  kecamatanAyah: string;
  kelurahanDesaAyah: string;
  rtAyah: string;
  rwAyah: string;
  alamatLengkapAyah: string;
  kodePosAyah: string;
