const PROVINSI_LIST = [
  'Aceh', 'Sumatera Utara', 'Sumatera Barat', 'Riau', 'Kepulauan Riau', 'Jambi',
  'Sumatera Selatan', 'Kepulauan Bangka Belitung', 'Bengkulu', 'Lampung',
  'DKI Jakarta', 'Jawa Barat', 'Banten', 'Jawa Tengah', 'DI Yogyakarta', 'Jawa Timur',
  'Bali', 'Nusa Tenggara Barat', 'Nusa Tenggara Timur',
  'Kalimantan Barat', 'Kalimantan Tengah', 'Kalimantan Selatan', 'Kalimantan Timur', 'Kalimantan Utara',
  'Sulawesi Utara', 'Gorontalo', 'Sulawesi Tengah', 'Sulawesi Barat', 'Sulawesi Selatan', 'Sulawesi Tenggara',
  'Maluku', 'Maluku Utara', 'Papua', 'Papua Barat', 'Papua Tengah', 'Papua Pegunungan', 'Papua Selatan', 'Papua Barat Daya'
];
const PROVINSI_OPTIONS = PROVINSI_LIST.map((p) => ({ id: p, name: p }));

export default function DataAlamatTab({ formData, onUpdate }: DataAlamatTabProps) {
  const handleAlamatIbuSameAsAyah = (checked: boolean) => {
    if (checked) {
      onUpdate({
        alamatIbuSamaDenganAyah: true,
        statusKepemilikanRumahIbu: formData.statusKepemilikanRumahAyah,
        provinsiIbu: formData.provinsiAyah,
        kabupatenKotaIbu: formData.kabupatenKotaAyah,
        kecamatanIbu: formData.kecamatanAyah,
        kelurahanDesaIbu: formData.kelurahanDesaAyah,
        rtIbu: formData.rtAyah,
        rwIbu: formData.rwAyah,
        alamatLengkapIbu: formData.alamatLengkapAyah,
        kodePosIbu: formData.kodePosAyah,
      });
    } else {
      onUpdate({ alamatIbuSamaDenganAyah: false });
    }
  };

  const handleStatusAlamatWali = (value: string) => {
    if (value === 'Sama dengan ayah kandung') {
      onUpdate({
        statusAlamatWali: value,
        statusKepemilikanRumahWali: formData.statusKepemilikanRumahAyah,
        provinsiWali: formData.provinsiAyah,
        kabupatenKotaWali: formData.kabupatenKotaAyah,
        kecamatanWali: formData.kecamatanAyah,
        kelurahanDesaWali: formData.kelurahanDesaAyah,
        rtWali: formData.rtAyah,
        rwWali: formData.rwAyah,
        alamatLengkapWali: formData.alamatLengkapAyah,
        kodePosWali: formData.kodePosAyah,
      });
    } else if (value === 'Sama dengan ibu kandung') {
      onUpdate({
        statusAlamatWali: value,
        statusKepemilikanRumahWali: formData.statusKepemilikanRumahIbu,
        provinsiWali: formData.provinsiIbu,
        kabupatenKotaWali: formData.kabupatenKotaIbu,
        kecamatanWali: formData.kecamatanIbu,
        kelurahanDesaWali: formData.kelurahanDesaIbu,
        rtWali: formData.rtIbu,
        rwWali: formData.rwIbu,
