          onKecamatanChange={(kec, kel) => onUpdate({ kecamatanAyah: kec, kelurahanDesaAyah: kel })}
          onKelurahanChange={(v) => onUpdate({ kelurahanDesaAyah: v })}
        />

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="rtAyah">RT</Label>
            <Input id="rtAyah" placeholder="000" value={formData.rtAyah} onChange={(e) => onUpdate({ rtAyah: e.target.value })} />
          </div>
          <div className="space-y-2">
            <Label htmlFor="rwAyah">RW</Label>
            <Input id="rwAyah" placeholder="000" value={formData.rwAyah} onChange={(e) => onUpdate({ rwAyah: e.target.value })} />
          </div>
