src/components/guru/GuruFormInfoTab.tsx.content:
import { useRef, useState } from 'react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Upload, X, User, Eye, EyeOff } from 'lucide-react';
import { uploadFile } from 'zite-file-upload-sdk';

interface Props {
  form: Record<string, unknown>;
  onChange: (key: string, value: unknown) => void;
}

export default function GuruFormInfoTab({ form, onChange }: Props) {
  const [uploading, setUploading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const fotoUrl = (form.foto as { url: string }[] | undefined)?.[0]?.url;

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: file, filename: file.name });
      onChange('foto', [{ url: fileUrl }]);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-4">
      {/* Foto */}
      <div className="flex flex-col items-center gap-3 py-2">
        <div className="h-24 w-24 rounded-full border-2 border-dashed border-border flex items-center justify-center overflow-hidden bg-muted">
          {fotoUrl ? (
            <img src={fotoUrl} className="h-full w-full object-cover" />
          ) : (
            <User className="h-10 w-10 text-muted-foreground" />
          )}
        </div>
        <div className="flex gap-2">
          <Button type="button" size="sm" variant="outline" onClick={() => fileRef.current?.click()} disabled={uploading}>
            <Upload className="h-3 w-3 mr-1" />{uploading ? 'Uploading...' : 'Upload Foto'}
          </Button>
          {fotoUrl && (
            <Button type="button" size="sm" variant="outline" onClick={() => onChange('foto', [])}>
              <X className="h-3 w-3" />
            </Button>
          )}
        </div>
        <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleUpload} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>NIP/NUPTK</Label>
          <Input value={(form.nipnuptk as string) || ''} onChange={(e) => onChange('nipnuptk', e.target.value)} placeholder="Bisa diisi jika belum punya" />
        </div>
        <div className="space-y-1">
          <Label>NIK <span className="text-destructive">*</span></Label>
          <Input value={(form.nik as string) || ''} onChange={(e) => onChange('nik', e.target.value)} placeholder="16 digit angka" maxLength={16} />
        </div>
        <div className="col-span-2 space-y-1">
          <Label>Nama Lengkap <span className="text-destructive">*</span></Label>
          <Input value={(form.namaLengkap as string) || ''} onChange={(e) => onChange('namaLengkap', e.target.value)} placeholder="Contoh: Ahmad Fauzi, S.Pd." />
        </div>
        <div className="space-y-1">
          <Label>Jenis Kelamin <span className="text-destructive">*</span></Label>
          <Select value={(form.jenisKelamin as string) || ''} onValueChange={(v) => onChange('jenisKelamin', v)}>
            <SelectTrigger><SelectValue placeholder="Pilih" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="Laki-laki">Laki-laki</SelectItem>
              <SelectItem value="Perempuan">Perempuan</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1">
          <Label>Tempat Lahir</Label>
          <Input value={(form.tempatLahir as string) || ''} onChange={(e) => onChange('tempatLahir', e.target.value)} />
        </div>
        <div className="space-y-1">
          <Label>Tanggal Lahir</Label>
          <Input type="date" value={(form.tanggalLahir as string) || ''} onChange={(e) => onChange('tanggalLahir', e.target.value)} />
        </div>
        <div className="space-y-1">
          <Label>No HP/Whatsapp</Label>
          <Input value={(form.noHp as string) || ''} onChange={(e) => onChange('noHp', e.target.value)} placeholder="08xx" />
        </div>
        <div className="col-span-2 space-y-1">
          <Label>Email</Label>
          <Input type="email" value={(form.email as string) || ''} onChange={(e) => onChange('email', e.target.value)} placeholder="harus mengandung tanda @" />
        </div>
        <div className="space-y-1">
          <Label>Username <span className="text-destructive">*</span></Label>
          <Input value={(form.usernameGuru as string) || ''} onChange={(e) => onChange('usernameGuru', e.target.value)} />
        </div>
        <div className="space-y-1">
          <Label>Password <span className="text-destructive">*</span></Label>
          <div className="relative">
            <Input
              type={showPassword ? 'text' : 'password'}
              value={(form.passwordGuru as string) || ''}
              onChange={(e) => onChange('passwordGuru', e.target.value)}
              className="pr-10"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
            >
              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

src/components/guru/ResetAkunDialog.tsx.content:
import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Eye, EyeOff } from 'lucide-react';
import { toast } from 'sonner';
import { resetAkunGuru } from 'zite-endpoints-sdk';

interface Props {
  open: boolean;
  onClose: () => void;
  onSuccess: () => void;
  guruId: string;
  currentUsername: string;
}

export default function ResetAkunDialog({ open, onClose, onSuccess, guruId, currentUsername }: Props) {
  const [username, setUsername] = useState(currentUsername);
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [saving, setSaving] = useState(false);

  const handleSubmit = async () => {
    if (!username) return toast.error('Username wajib diisi');
    if (!password) return toast.error('Password wajib diisi');
    if (password !== confirm) return toast.error('Konfirmasi password tidak sesuai');
    setSaving(true);
    try {
      await resetAkunGuru({ id: guruId, usernameGuru: username, passwordGuru: password });
      toast.success('Akun berhasil direset');
      onSuccess();
      onClose();
    } catch (e: unknown) {
      toast.error((e as Error).message || 'Gagal reset akun');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Reset Akun</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-1">
            <Label>Username Baru</Label>
            <Input value={username} onChange={(e) => setUsername(e.target.value)} />
          </div>
          <div className="space-y-1">
            <Label>Password Baru</Label>
            <div className="relative">
              <Input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="pr-10"
              />
              <button type="button" onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
                {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>
          <div className="space-y-1">
            <Label>Konfirmasi Password</Label>
            <div className="relative">
              <Input
                type={showConfirm ? 'text' : 'password'}
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                className={`pr-10 ${confirm && password !== confirm ? 'border-destructive' : ''}`}
              />
              <button type="button" onClick={() => setShowConfirm(!showConfirm)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
                {showConfirm ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
            {confirm && password !== confirm && (
              <p className="text-xs text-destructive">Password tidak sesuai</p>
            )}
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving}>
            {saving ? 'Menyimpan...' : 'Reset Akun'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

