import { useMemo } from 'react';
import { Pencil, Trash2, Clock, User } from 'lucide-react';
import type { JadwalSettings, JpSlot } from './PengaturanJadwalSheet';
import { isSpecialSlot, getSlotType, SPECIAL_SLOT_CONFIG, timeDiffMinutes } from './PengaturanJadwalSheet';

const HARI_LIST = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

const DAY_COLORS: Record<string, string> = {
  Senin: 'bg-primary/8 border-primary/20',
  Selasa: 'bg-accent/60 border-accent',
  Rabu: 'bg-primary/8 border-primary/20',
  Kamis: 'bg-accent/60 border-accent',
  Jumat: 'bg-primary/8 border-primary/20',
  Sabtu: 'bg-accent/60 border-accent',
};

const DAY_HEADER_COLORS: Record<string, string> = {
  Senin: 'bg-primary text-primary-foreground',
  Selasa: 'bg-primary/80 text-primary-foreground',
  Rabu: 'bg-primary text-primary-foreground',
  Kamis: 'bg-primary/80 text-primary-foreground',
  Jumat: 'bg-primary text-primary-foreground',
  Sabtu: 'bg-primary/80 text-primary-foreground',
};

export interface JadwalEntry {
  id: string;
  hari: string;
  jamMulai: string;
  jamSelesai: string;
  mapelId: string;
  mapelNama: string;
  mapelKode?: string;
  guruId: string;
  guruNama: string;
}

interface Props {
  jadwal: JadwalEntry[];
  activeDays: string[];
  settings: JadwalSettings;
  onEdit: (entry: JadwalEntry) => void;
  onDelete: (id: string) => void;
  onAddToDay: (hari: string) => void;
}

function getJpLabel(entry: JadwalEntry, jpSlots: JpSlot[]): string | null {
  const startSlot = jpSlots.find(s => !isSpecialSlot(s) && s.mulai === entry.jamMulai);
  const endSlot = jpSlots.find(s => !isSpecialSlot(s) && s.selesai === entry.jamSelesai);
  if (!startSlot || !endSlot) return null;
  if (startSlot.jp === endSlot.jp) return `JP ${startSlot.jp}`;
  return `JP ${startSlot.jp}–${endSlot.jp}`;
}

// Merge jadwal entries with special slots into a timeline
type TimelineItem =
  | { type: 'jadwal'; entry: JadwalEntry; jpLabel: string | null }
  | { type: 'special'; slot: JpSlot };

function buildTimeline(entries: JadwalEntry[], slots: JpSlot[], hari: string): TimelineItem[] {
  const items: TimelineItem[] = [];
  const jpSlots = slots.filter(s => !isSpecialSlot(s));

  // Get special slots applicable to this day
  const specialSlots = slots.filter(s => {
    if (!isSpecialSlot(s)) return false;
    const type = getSlotType(s);
    // Upacara only on Senin
    if (type === 'upacara' && hari !== 'Senin') return false;
    return true;
  });

  // Create timeline: mix special slots and jadwal entries sorted by time
  const allItems: TimelineItem[] = [];

  for (const ss of specialSlots) {
    allItems.push({ type: 'special', slot: ss });
  }
  for (const entry of entries) {
    allItems.push({ type: 'jadwal', entry, jpLabel: getJpLabel(entry, jpSlots) });
  }

  // Sort by start time
  allItems.sort((a, b) => {
    const ta = a.type === 'special' ? a.slot.mulai : a.entry.jamMulai;
    const tb = b.type === 'special' ? b.slot.mulai : b.entry.jamMulai;
    return ta.localeCompare(tb);
  });

  return allItems;
}

export default function TimetableGrid({ jadwal, activeDays, settings, onEdit, onDelete, onAddToDay }: Props) {
  const displayDays = activeDays.length > 0
    ? HARI_LIST.filter(h => activeDays.includes(h))
    : HARI_LIST.slice(0, 5);

  const byDay: Record<string, JadwalEntry[]> = {};
  for (const h of displayDays) byDay[h] = [];
  for (const j of jadwal) {
    if (byDay[j.hari]) byDay[j.hari].push(j);
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 2xl:grid-cols-6 gap-3">
      {displayDays.map(hari => (
        <DayColumn
          key={hari}
          hari={hari}
          entries={byDay[hari] || []}
          settings={settings}
          onEdit={onEdit}
          onDelete={onDelete}
          onAdd={() => onAddToDay(hari)}
        />
      ))}
    </div>
  );
}

function DayColumn({
  hari, entries, settings, onEdit, onDelete, onAdd,
}: {
  hari: string;
  entries: JadwalEntry[];
  settings: JadwalSettings;
  onEdit: (e: JadwalEntry) => void;
  onDelete: (id: string) => void;
  onAdd: () => void;
}) {
  const timeline = useMemo(() => buildTimeline(entries, settings.slots, hari), [entries, settings.slots, hari]);
  const hasEntries = entries.length > 0 || timeline.some(t => t.type === 'special');

  return (
    <div className="rounded-xl border border-border overflow-hidden bg-card shadow-sm">
      <div className={`px-4 py-2.5 text-center font-bold text-sm ${DAY_HEADER_COLORS[hari] || 'bg-primary text-primary-foreground'}`}>
        {hari}
      </div>
      <div className="p-2 space-y-1.5 min-h-[120px]">
        {!hasEntries ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <p className="text-xs text-muted-foreground mb-2">Belum ada jadwal</p>
          </div>
        ) : (
          timeline.map((item, idx) => {
            if (item.type === 'special') {
              return <SpecialSlotCard key={`special-${idx}`} slot={item.slot} />;
            }
            return (
              <JadwalCard
                key={item.entry.id}
                entry={item.entry}
                jpLabel={item.jpLabel}
                hari={hari}
                onEdit={onEdit}
                onDelete={onDelete}
              />
            );
          })
        )}
      </div>
      <div className="px-2 pb-2">
        <button
          onClick={onAdd}
          className="w-full py-1.5 rounded-lg border border-dashed border-border text-xs text-muted-foreground hover:border-primary hover:text-primary hover:bg-primary/5 transition-all font-medium"
        >
          + Tambah
        </button>
      </div>
    </div>
  );
}

function SpecialSlotCard({ slot }: { slot: JpSlot }) {
  const type = getSlotType(slot);
  if (type === 'jp') return null;
  const config = SPECIAL_SLOT_CONFIG[type];
  return (
    <div className={`rounded-lg px-2.5 py-1.5 border text-center ${config.color} ${config.borderColor}`}>
      <div className="flex items-center justify-center gap-1.5">
        <span className="text-sm">{config.icon}</span>
        <span className="text-xs font-semibold text-foreground/70">{slot.label || config.label}</span>
      </div>
      <p className="text-[10px] text-muted-foreground mt-0.5">{slot.mulai} – {slot.selesai}</p>
    </div>
  );
}

function JadwalCard({ entry, jpLabel, hari, onEdit, onDelete }: {
  entry: JadwalEntry;
  jpLabel: string | null;
  hari: string;
  onEdit: (e: JadwalEntry) => void;
  onDelete: (id: string) => void;
}) {
  return (
    <div className={`rounded-lg p-2.5 border transition-all hover:shadow-sm group ${DAY_COLORS[hari] || 'bg-muted/30 border-border'}`}>
      <div className="flex items-start justify-between gap-1">
        <div className="flex-1 min-w-0">
          <p className="font-semibold text-sm text-foreground leading-tight truncate">
            {entry.mapelNama}
          </p>
          <div className="flex items-center gap-1.5 mt-1 flex-wrap">
            {jpLabel && (
              <span className="text-[10px] font-bold bg-primary/10 text-primary px-1.5 py-0.5 rounded">
                {jpLabel}
              </span>
            )}
            <div className="flex items-center gap-1">
              <Clock className="h-3 w-3 text-muted-foreground flex-shrink-0" />
              <span className="text-xs text-muted-foreground font-medium">
                {entry.jamMulai} – {entry.jamSelesai}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-1 mt-0.5">
            <User className="h-3 w-3 text-muted-foreground flex-shrink-0" />
            <span className="text-xs text-muted-foreground truncate">
              {entry.guruNama}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button
            onClick={() => onEdit(entry)}
            className="h-6 w-6 rounded flex items-center justify-center hover:bg-background/80 transition-colors"
          >
            <Pencil className="h-3 w-3 text-muted-foreground" />
          </button>
          <button
            onClick={() => onDelete(entry.id)}
            className="h-6 w-6 rounded flex items-center justify-center hover:bg-destructive/10 transition-colors"
          >
            <Trash2 className="h-3 w-3 text-destructive" />
          </button>
        </div>
      </div>
    </div>
  );
}

