import { useEffect, useState } from 'react';
import { getProfilSekolah, GetProfilSekolahOutputType } from 'zite-endpoints-sdk';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import { User, Mail, Globe, RefreshCw, ImageIcon } from 'lucide-react';
import { toast } from 'sonner';

type ProfilData = GetProfilSekolahOutputType;

function InfoItem({ icon: Icon, label, value }: { icon: React.ElementType; label: string; value?: string }) {
  return (
    <div className="flex items-start gap-3">
      <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
        <Icon className="h-4 w-4 text-primary" />
      </div>
      <div className="min-w-0">
        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">{label}</p>
        <p className="text-sm font-medium text-foreground break-all">{value || '—'}</p>
      </div>
    </div>
  );
}

function DetailRow({ label, value }: { label: string; value?: string }) {
  return (
    <div>
      <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-sm font-semibold text-foreground">{value || '—'}</p>
    </div>
  );
}

export default function ProfilLembagaPage() {
  const [data, setData] = useState<ProfilData | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const load = async () => {
    try {
      setLoading(true);
      const res = await getProfilSekolah({});
      setData(res);
    } catch {
      toast.error('Gagal memuat profil sekolah');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const jenjangLabel = (jenjang?: string) => {
    const map: Record<string, string> = {
      TK: 'TK (Taman Kanak-kanak)',
      SD: 'SD (Sekolah Dasar)',
      SMP: 'SMP (Sekolah Menengah Pertama)',
      SMA: 'SMA (Sekolah Menengah Atas)',
      SMK: 'SMK (Sekolah Menengah Kejuruan)',
      MTS: 'MTS (Madrasah Tsanawiyah)',
      MA: 'MA (Madrasah Aliyah)',
      MI: 'MI (Madrasah Ibtidaiyah)',
    };
    return jenjang ? (map[jenjang] || jenjang) : '—';
  };

  const handleUpdate = async () => {
    setSaving(true);
    await new Promise(r => setTimeout(r, 1000));
    setSaving(false);
    toast.success('Data berhasil diperbarui');
    load();
  };

  if (loading) {
    return (
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
        <div className="lg:col-span-2 bg-card rounded-2xl border border-border p-6 space-y-4">
          <Skeleton className="h-28 w-28 rounded-full mx-auto" />
          <Skeleton className="h-6 w-40 mx-auto" />
          <Skeleton className="h-4 w-28 mx-auto" />
        </div>
        <div className="lg:col-span-3 bg-card rounded-2xl border border-border p-6 space-y-4">
          {[...Array(6)].map((_, i) => <Skeleton key={i} className="h-10 w-full" />)}
        </div>
      </div>
    );
  }

  const sekolah = data?.sekolah;
  const ta = data?.tahunAjaranAktif;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
      {/* Left Card */}
      <div className="lg:col-span-2 bg-card rounded-2xl border border-border p-6 flex flex-col items-center gap-5">
        {/* Logo */}
        <div className="h-28 w-28 rounded-full border-2 border-border bg-muted flex items-center justify-center overflow-hidden">
          {sekolah?.logo?.[0]?.url ? (
            <img src={sekolah.logo[0].url} alt="Logo" className="h-full w-full object-cover" />
          ) : (
            <ImageIcon className="h-10 w-10 text-muted-foreground" />
          )}
        </div>

        {/* Name */}
        <div className="text-center">
          <h2 className="text-xl font-black text-foreground uppercase tracking-wide">
            {sekolah?.namaSekolah || '—'}
          </h2>
          {sekolah?.npsn && (
            <p className="text-sm font-semibold text-primary mt-1">NPSN: {sekolah.npsn}</p>
          )}
        </div>

        {/* Badges */}
        {(sekolah?.akreditasi || sekolah?.kurikulum) && (
          <div className="flex flex-wrap gap-2 justify-center">
            {sekolah?.akreditasi && (
              <span className="flex items-center gap-1 text-xs font-bold px-3 py-1 rounded-full border border-yellow-400 text-yellow-600 bg-yellow-50">
                ⭐ AKREDITASI {sekolah.akreditasi}
              </span>
            )}
            {sekolah?.kurikulum && (
              <span className="flex items-center gap-1 text-xs font-bold px-3 py-1 rounded-full border border-primary/40 text-primary bg-primary/5">
                📋 {sekolah.kurikulum.replace('Kurikulum ', '').toUpperCase()}
              </span>
            )}
          </div>
        )}

        {/* Divider */}
        <div className="w-full border-t border-border" />

        {/* Contact Info */}
        <div className="w-full space-y-4">
          <InfoItem icon={User} label="Kepala Sekolah" value={sekolah?.kepalaSekolah} />
          <InfoItem icon={Mail} label="Email Resmi" value={sekolah?.emailSekolah} />
          {sekolah?.situsWeb && (
            <div className="flex items-start gap-3">
              <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                <Globe className="h-4 w-4 text-primary" />
              </div>
              <div className="min-w-0">
                <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">Situs Web</p>
                <a href={sekolah.situsWeb} target="_blank" rel="noreferrer"
                  className="text-sm font-medium text-primary hover:underline break-all">
                  {sekolah.situsWeb.replace(/^https?:\/\//, '')}
                </a>
              </div>
            </div>
          )}
          {!sekolah?.situsWeb && <InfoItem icon={Globe} label="Situs Web" value={undefined} />}
        </div>
      </div>

      {/* Right Card */}
      <div className="lg:col-span-3 bg-card rounded-2xl border border-border p-6 flex flex-col">
        {/* Header */}
        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-border">
          <div className="w-1 h-5 rounded-full bg-primary flex-shrink-0" />
          <h3 className="text-xs font-black text-foreground uppercase tracking-widest">
            Detail Identitas Lembaga
          </h3>
        </div>

        {/* Detail Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-5 flex-1">
          <DetailRow label="Jenjang Pendidikan" value={jenjangLabel(sekolah?.jenjang)} />
          <DetailRow label="Status Sekolah" value={sekolah?.statusSekolah} />
          <DetailRow label="Penyelenggara" value={sekolah?.penyelenggara} />
          <DetailRow label="Kurikulum" value={sekolah?.kurikulum} />
          <DetailRow label="Kontak / No. Telp" value={sekolah?.telepon} />
          <DetailRow
            label="Tahun Ajaran Aktif"
            value={ta?.namaTahunAjaran
              ? `${ta.namaTahunAjaran}${ta.semester ? ` (Semester ${ta.semester})` : ''}`
              : undefined}
          />
          <div className="sm:col-span-2">
            <DetailRow label="Alamat Lengkap" value={sekolah?.alamat} />
          </div>
        </div>

        {/* Footer */}
        <div className="mt-6 pt-4 border-t border-border flex items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <span className="h-2 w-2 rounded-full bg-primary animate-pulse" />
            <span className="text-xs font-semibold text-muted-foreground uppercase tracking-widest">
              Status: Data Sinkron
            </span>
          </div>
          <Button
            onClick={handleUpdate}
            disabled={saving}
            className="gap-2 font-semibold"
          >
            <RefreshCw className={`h-4 w-4 ${saving ? 'animate-spin' : ''}`} />
            Update Data
          </Button>
        </div>
      </div>
    </div>
  );
}

