  try { return new Date(date).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }); }
  catch { return date; }
}

function InfoCard({ icon, label, value, accent }: { icon: React.ReactNode; label: string; value?: string | null; accent: string }) {
