import { useState, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { importGuru } from 'zite-endpoints-sdk';
import {
  Users, AlignJustify, FileSpreadsheet, Monitor, LayoutGrid,
  ArrowRight, Download, Upload, Loader2, ChevronRight,
  CheckCircle2, Zap, ClipboardList, AlertCircle
} from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { generateExcelTemplate, ExcelColumn } from '@/lib/generateExcelTemplate';

// Only "Informasi Utama" fields (no kepegawaian)
const QUICK_COLUMNS: (ExcelColumn & { key: string; required: boolean })[] = [
  { key: 'namaLengkap', label: 'Nama Lengkap', required: true, example: 'Ahmad Fauzi S.Pd.', width: 200 },
  { key: 'usernameGuru', label: 'Username', required: true, example: 'ahmad.fauzi', width: 140 },
  { key: 'passwordGuru', label: 'Password', required: true, example: 'password123', width: 140 },
];

const REGULAR_COLUMNS: (ExcelColumn & { key: string; required: boolean })[] = [
  { key: 'namaLengkap', label: 'Nama Lengkap', required: true, example: 'Ahmad Fauzi S.Pd.', width: 200 },
  { key: 'nipnuptk', label: 'NIP/NUPTK', required: false, example: '198503152010011001', isText: true, width: 170 },
  { key: 'nik', label: 'NIK', required: false, example: '3201234567890001', isText: true, width: 160 },
  { key: 'jenisKelamin', label: 'Jenis Kelamin', required: false, example: 'Laki-laki', width: 140 },
  { key: 'tempatLahir', label: 'Tempat Lahir', required: false, example: 'Jakarta', width: 140 },
  { key: 'tanggalLahir', label: 'Tanggal Lahir', required: false, example: '1985-03-15', width: 140 },
  { key: 'noHp', label: 'No HP/Whatsapp', required: false, example: '08123456789', isText: true, width: 160 },
  { key: 'email', label: 'Email', required: false, example: 'ahmad@sekolah.com', width: 190 },
  { key: 'usernameGuru', label: 'Username', required: false, example: 'ahmad.fauzi', width: 140 },
  { key: 'passwordGuru', label: 'Password', required: false, example: 'password123', width: 140 },
];

type ColumnDef = typeof QUICK_COLUMNS[0];

function parseCSV(text: string): Record<string, string>[] {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim().split('\n');
  if (lines.length < 2) return [];
  const parseRow = (line: string): string[] => {
    const cells: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
        else inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        cells.push(current.trim()); current = '';
      } else { current += char; }
    }
    cells.push(current.trim());
    return cells;
  };
  const headers = parseRow(lines[0]).map(h => h.replace(/^\uFEFF/, ''));
  return lines.slice(1)
    .map(line => {
      const cells = parseRow(line);
      const obj: Record<string, string> = {};
      headers.forEach((h, i) => { obj[h] = cells[i] || ''; });
      return obj;
    })
    .filter(row => Object.values(row).some(v => v !== ''));
}

function mapRowToFields(row: Record<string, string>, columns: ColumnDef[]): Record<string, string> {
  const result: Record<string, string> = {};
  columns.forEach(col => {
    const value = row[col.label];
    if (value !== undefined) result[col.key] = value;
  });
  return result;
}

const STEPS = [
  { num: 1, label: '1. Jenis Import', Icon: AlignJustify },
  { num: 2, label: '2. Download Sample', Icon: FileSpreadsheet },
  { num: 3, label: '3. Upload Data', Icon: Monitor },
  { num: 4, label: '4. Preview & Import', Icon: LayoutGrid },
];

function StepIndicator({ currentStep }: { currentStep: number }) {
  return (
    <div className="flex items-start justify-center gap-1 py-4 border-b overflow-x-auto">
      {STEPS.map((step, idx) => (
        <div key={step.num} className="flex items-center gap-1">
          <div className={cn(
            'flex flex-col items-center gap-1 min-w-[90px]',
            currentStep >= step.num ? 'text-primary' : 'text-muted-foreground'
          )}>
            <step.Icon className={cn(
              'h-7 w-7',
              currentStep >= step.num ? 'text-primary' : 'text-muted-foreground/50'
            )} />
            <span className="text-[10px] font-medium text-center leading-tight">{step.label}</span>
          </div>
          {idx < STEPS.length - 1 && (
            <ArrowRight className={cn(
              'h-4 w-4 mb-4 flex-shrink-0',
              currentStep > step.num ? 'text-primary' : 'text-muted-foreground/40'
            )} />
          )}
        </div>
      ))}
    </div>
  );
}

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export default function ImportGuruWizard({ open, onOpenChange, onSuccess }: Props) {
  const [step, setStep] = useState(1);
  const [importType, setImportType] = useState<'quick' | 'regular'>('regular');
  const [parsedRows, setParsedRows] = useState<Record<string, string>[]>([]);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ imported: number; errors: string[] } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const columns = importType === 'quick' ? QUICK_COLUMNS : REGULAR_COLUMNS;

  const handleOpen = (o: boolean) => {
    if (!o) {
      setStep(1); setImportType('regular');
      setParsedRows([]); setImportResult(null);
    }
    onOpenChange(o);
  };

  const handleDownloadSample = () => {
    generateExcelTemplate(`template_import_guru_${importType}.xls`, columns);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const rawRows = parseCSV(text);
      const mapped = rawRows.map(row => mapRowToFields(row, columns));
      setParsedRows(mapped);
      if (mapped.length > 0) toast.success(`${mapped.length} baris data berhasil dibaca`);
      else toast.error('Tidak ada data yang dapat dibaca dari file');
    };
    reader.readAsText(file, 'UTF-8');
    e.target.value = '';
  };

  const handleImport = async () => {
    setImporting(true);
    try {
      const result = await importGuru({
        statusKepegawaian: '',
        kategoriPegawai: [],
        rows: parsedRows.map(row => ({ namaLengkap: row.namaLengkap || '', ...row })),
      });
      setImportResult(result);
      toast.success(`${result.imported} data guru/tendik berhasil diimport`);
      if (result.errors.length > 0) toast.warning(`${result.errors.length} baris gagal diimport`);
      onSuccess();
    } catch {
      toast.error('Gagal mengimport data guru/tendik');
    } finally {
      setImporting(false);
    }
  };

  const canNext = () => {
    if (step === 3) return parsedRows.length > 0;
    return true;
  };

  return (
    <Dialog open={open} onOpenChange={handleOpen}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto p-0">
        <DialogHeader className="px-6 pt-6 pb-0">
          <DialogTitle className="flex items-center gap-2 text-primary">
            <Users className="h-5 w-5" />
            Import Data Guru & Tendik
          </DialogTitle>
        </DialogHeader>

        <StepIndicator currentStep={step} />

        <div className="px-6 py-6 min-h-[320px]">
          {/* Step 1: Jenis Import */}
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="text-center text-lg font-semibold">Pilih Jenis Import</h3>
              <div className="grid grid-cols-2 gap-4">
                {(['quick', 'regular'] as const).map(type => (
                  <div
                    key={type}
                    className={cn(
                      'border-2 rounded-lg p-6 cursor-pointer transition-all',
                      importType === type ? 'border-primary bg-primary/5' : 'border-border'
                    )}
                    onClick={() => setImportType(type)}
                  >
                    <div className="flex items-center gap-3 mb-3">
                      <div className={cn(
                        'w-5 h-5 rounded-full border-2 flex items-center justify-center flex-shrink-0',
                        importType === type ? 'border-primary' : 'border-muted-foreground'
                      )}>
                        {importType === type && <div className="w-3 h-3 rounded-full bg-primary" />}
                      </div>
                      <span className="font-semibold">{type === 'quick' ? 'Quick Import' : 'Regular Import'}</span>
                      {type === 'quick'
                        ? <Zap className="h-5 w-5 ml-auto text-yellow-500" />
                        : <ClipboardList className="h-5 w-5 ml-auto text-blue-500" />
                      }
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {type === 'quick'
                        ? 'Quick Import adalah format import dengan kebutuhan data-data dasar saja (nama, username, password), lebih cepat dan efisien'
                        : 'Regular Import membutuhkan data informasi utama lengkap (NIP/NUPTK, NIK, kontak, dll)'}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Step 2: Download Sample */}
          {step === 2 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Download Template Excel</h3>
              <p className="text-sm text-muted-foreground">
                Download file template untuk <strong>{importType === 'quick' ? 'Quick Import' : 'Regular Import'}</strong>.
                Isi data guru/tendik sesuai format, lalu simpan sebagai <strong>.csv</strong> sebelum diupload.
              </p>
              <div className="border rounded-lg p-8 space-y-4">
                <FileSpreadsheet className="h-16 w-16 text-green-600 mx-auto" />
                <p className="font-medium">template_import_guru_{importType}.xls</p>
                <p className="text-xs text-muted-foreground">{columns.length} kolom · {columns.filter(c => c.required).length} wajib diisi</p>
                <div className="text-left bg-muted/40 rounded-lg p-3 space-y-1 max-h-40 overflow-y-auto">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Kolom yang tersedia:</p>
                  {columns.map(col => (
                    <div key={col.key} className="flex items-center gap-2 text-xs">
                      <span className={cn('w-2 h-2 rounded-full flex-shrink-0', col.required ? 'bg-destructive' : 'bg-muted-foreground/40')} />
                      <span>{col.label}</span>
                      {col.required && <span className="text-destructive text-[10px]">*wajib</span>}
                      {col.isText && <span className="text-muted-foreground text-[10px]">(format teks)</span>}
                    </div>
                  ))}
                </div>
                <Button onClick={handleDownloadSample} className="gap-2 w-full">
                  <Download className="h-4 w-4" />
                  Download Template Excel
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                * Kolom NIK, NIP/NUPTK, dan No HP sudah diformat sebagai teks agar angkanya tidak berubah
              </p>
            </div>
          )}

          {/* Step 3: Upload Data */}
          {step === 3 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Upload Data Guru/Tendik</h3>
              <p className="text-sm text-muted-foreground">
                Upload file CSV yang sudah diisi dengan data guru/tendik
                <br />
                <span className="text-xs">(simpan file Excel sebagai .csv terlebih dahulu)</span>
              </p>
              <div
                className="border-2 border-dashed rounded-lg p-10 cursor-pointer hover:border-primary/50 transition-colors"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="font-medium">Klik untuk upload file CSV</p>
                <p className="text-xs text-muted-foreground mt-1">Format: .csv</p>
                <input ref={fileInputRef} type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </div>
              {parsedRows.length > 0 && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4 flex items-center gap-3">
                  <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  <p className="text-sm text-green-700 font-medium">{parsedRows.length} baris data berhasil dibaca</p>
                </div>
              )}
            </div>
          )}

          {/* Step 4: Preview & Import */}
          {step === 4 && !importResult && (
            <div className="space-y-4">
              <h3 className="text-lg font-semibold">Preview Data ({parsedRows.length} data guru/tendik)</h3>
              <ScrollArea className="h-64 border rounded-lg">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-8">No</TableHead>
                      <TableHead>Nama Lengkap</TableHead>
                      <TableHead>NIP/NUPTK</TableHead>
                      <TableHead>NIK</TableHead>
                      <TableHead>No HP</TableHead>
                      <TableHead>Username</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {parsedRows.map((row, idx) => (
                      <TableRow key={idx}>
                        <TableCell>{idx + 1}</TableCell>
                        <TableCell className="font-medium">{row.namaLengkap || '-'}</TableCell>
                        <TableCell>{row.nipnuptk || '-'}</TableCell>
                        <TableCell>{row.nik || '-'}</TableCell>
                        <TableCell>{row.noHp || '-'}</TableCell>
                        <TableCell>{row.usernameGuru || '-'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollArea>
            </div>
          )}

          {/* Step 4: Result */}
          {step === 4 && importResult && (
            <div className="space-y-4 max-w-md mx-auto">
              <div className="flex items-center gap-4 p-5 rounded-lg bg-muted">
                <CheckCircle2 className="h-10 w-10 text-primary flex-shrink-0" />
                <div>
                  <p className="font-semibold text-lg">{importResult.imported} data berhasil diimport</p>
                  {importResult.errors.length > 0 && (
                    <p className="text-sm text-muted-foreground">{importResult.errors.length} baris dilewati karena error</p>
                  )}
                </div>
              </div>
              {importResult.errors.length > 0 && (
                <ScrollArea className="max-h-40 border rounded-lg p-3">
                  {importResult.errors.map((err, i) => (
                    <div key={i} className="flex items-start gap-2 text-sm text-destructive py-0.5">
                      <AlertCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
                      <span>{err}</span>
                    </div>
                  ))}
                </ScrollArea>
              )}
              <Button className="w-full" onClick={() => handleOpen(false)}>Selesai</Button>
            </div>
          )}
        </div>

        <div className="flex justify-between px-6 pb-6 pt-4 border-t">
          {step === 4 && importResult ? (
            <div />
          ) : (
            <>
              <Button variant="outline" onClick={() => step > 1 ? setStep(s => s - 1) : handleOpen(false)}>
                {step > 1 ? 'Kembali' : 'Batal'}
              </Button>
              {step < 4 ? (
                <Button onClick={() => setStep(s => s + 1)} disabled={!canNext()} className="gap-2">
                  Selanjutnya <ChevronRight className="h-4 w-4" />
                </Button>
              ) : (
                <Button onClick={handleImport} disabled={importing || parsedRows.length === 0} className="gap-2">
                  {importing
                    ? <><Loader2 className="h-4 w-4 animate-spin" />Mengimport...</>
                    : <><Upload className="h-4 w-4" />Import {parsedRows.length} Data</>
                  }
                </Button>
              )}
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

src/components/kelas/KelasFormDialog.tsx.content:
import { useState, useEffect, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Loader2, X, Search, UserPlus } from 'lucide-react';
import { getGuruDropdown, GetGuruDropdownOutputType } from 'zite-endpoints-sdk';
import { getSiswaForKelas, GetSiswaForKelasOutputType } from 'zite-endpoints-sdk';

type GuruItem = GetGuruDropdownOutputType['guru'][0];
type SiswaItem = GetSiswaForKelasOutputType['unassigned'][0];

const TINGKAT_OPTIONS = [
  { value: 'Kelas 1', label: 'I' },
  { value: 'Kelas 2', label: 'II' },
  { value: 'Kelas 3', label: 'III' },
  { value: 'Kelas 4', label: 'IV' },
  { value: 'Kelas 5', label: 'V' },
  { value: 'Kelas 6', label: 'VI' },
  { value: 'Kelas 7', label: 'VII' },
  { value: 'Kelas 8', label: 'VIII' },
  { value: 'Kelas 9', label: 'IX' },
  { value: 'Kelas 10', label: 'X' },
  { value: 'Kelas 11', label: 'XI' },
  { value: 'Kelas 12', label: 'XII' },
];

export interface KelasFormData {
  id?: string;
  namaKelas: string;
  tingkat: string;
  waliKelasId?: string;
  siswaIds: string[];
}

interface Props {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: KelasFormData) => Promise<void>;
  initial?: KelasFormData | null;
}

export default function KelasFormDialog({ open, onClose, onSubmit, initial }: Props) {
  const [tingkat, setTingkat] = useState('');
  const [namaKelas, setNamaKelas] = useState('');
  const [waliKelasId, setWaliKelasId] = useState('');
  const [selectedSiswa, setSelectedSiswa] = useState<SiswaItem[]>([]);
  const [guruList, setGuruList] = useState<GuruItem[]>([]);
  const [availableSiswa, setAvailableSiswa] = useState<SiswaItem[]>([]);
  const [siswaSearch, setSiswaSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    setTingkat(initial?.tingkat || '');
    setNamaKelas(initial?.namaKelas || '');
    setWaliKelasId(initial?.waliKelasId || '');
    setSelectedSiswa([]);
    setSiswaSearch('');

    Promise.all([
      getGuruDropdown({}),
      getSiswaForKelas({ kelasId: initial?.id }),
    ]).then(([guruRes, siswaRes]) => {
      setGuruList(guruRes.guru);
      setAvailableSiswa(siswaRes.unassigned);
      setSelectedSiswa(siswaRes.assigned);
    }).finally(() => setLoading(false));
  }, [open, initial]);

  const filteredSiswa = useMemo(() => {
    if (!siswaSearch) return availableSiswa;
    const q = siswaSearch.toLowerCase();
    return availableSiswa.filter(s =>
      s.nama.toLowerCase().includes(q) || s.nisn.toLowerCase().includes(q)
    );
  }, [availableSiswa, siswaSearch]);

  const addSiswa = (s: SiswaItem) => {
    setSelectedSiswa(prev => [...prev, s]);
    setAvailableSiswa(prev => prev.filter(x => x.id !== s.id));
  };

  const removeSiswa = (s: SiswaItem) => {
    setSelectedSiswa(prev => prev.filter(x => x.id !== s.id));
    setAvailableSiswa(prev => [...prev, s].sort((a, b) => a.nama.localeCompare(b.nama)));
  };

  const handleSubmit = async () => {
    if (!tingkat || !namaKelas.trim()) return;
    setSaving(true);
    try {
      await onSubmit({
        id: initial?.id,
        namaKelas: namaKelas.trim(),
        tingkat,
        waliKelasId: waliKelasId || undefined,
        siswaIds: selectedSiswa.map(s => s.id),
      });
      onClose();
    } finally {
      setSaving(false);
    }
  };

  const isEdit = !!initial?.id;

  return (
    <Dialog open={open} onOpenChange={v => !v && onClose()}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{isEdit ? 'Edit Ruang Kelas' : 'Tambah Ruang Kelas'}</DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
          </div>
        ) : (
          <div className="space-y-4">
            {/* Tingkat */}
            <div className="space-y-1.5">
              <Label>Tingkat <span className="text-destructive">*</span></Label>
              <Select value={tingkat} onValueChange={setTingkat}>
                <SelectTrigger><SelectValue placeholder="Pilih tingkat" /></SelectTrigger>
                <SelectContent>
                  {TINGKAT_OPTIONS.map(t => (
                    <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Nama Kelas */}
            <div className="space-y-1.5">
              <Label>Nama Kelas <span className="text-destructive">*</span></Label>
              <Input
                placeholder="Contoh: A, B, Unggulan..."
                value={namaKelas}
                onChange={e => setNamaKelas(e.target.value)}
              />
            </div>

            {/* Wali Kelas */}
            <div className="space-y-1.5">
              <Label>Wali Kelas</Label>
              <Select value={waliKelasId} onValueChange={setWaliKelasId}>
                <SelectTrigger><SelectValue placeholder="Pilih wali kelas" /></SelectTrigger>
                <SelectContent>
                  {guruList.map(g => (
                    <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Tambah Siswa */}
            <div className="space-y-1.5">
              <Label className="flex items-center gap-1.5">
                <UserPlus className="h-3.5 w-3.5" />
                Tambah Siswa
              </Label>

              {/* Selected */}
              {selectedSiswa.length > 0 && (
                <div className="flex flex-wrap gap-1.5 p-2 rounded-lg bg-muted/50 border border-border">
                  {selectedSiswa.map(s => (
                    <Badge key={s.id} variant="secondary" className="gap-1 pr-1">
                      {s.nama}
                      <button
                        onClick={() => removeSiswa(s)}
                        className="ml-0.5 rounded-full hover:bg-foreground/10 p-0.5"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                </div>
              )}

              {/* Search */}
              <div className="relative">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Cari siswa yang belum punya kelas..."
                  className="pl-8"
                  value={siswaSearch}
                  onChange={e => setSiswaSearch(e.target.value)}
                />
              </div>

              {/* Dropdown list */}
              {filteredSiswa.length > 0 ? (
                <div className="max-h-40 overflow-y-auto border border-border rounded-lg divide-y divide-border">
                  {filteredSiswa.slice(0, 50).map(s => (
                    <button
                      key={s.id}
                      onClick={() => addSiswa(s)}
                      className="w-full text-left px-3 py-2 text-sm hover:bg-muted transition-colors flex justify-between items-center"
                    >
                      <span className="font-medium">{s.nama}</span>
                      <span className="text-xs text-muted-foreground">{s.nisn}</span>
                    </button>
                  ))}
                </div>
              ) : (
                <p className="text-xs text-muted-foreground text-center py-2">
                  {availableSiswa.length === 0 ? 'Semua siswa sudah memiliki kelas' : 'Tidak ditemukan'}
                </p>
              )}
            </div>
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving || !tingkat || !namaKelas.trim()}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {isEdit ? 'Simpan' : 'Tambah'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/mapel/MapelFormDialog.tsx.content:
import { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

const KELOMPOK_OPTIONS = [
  'Mata Pelajaran Wajib',
  'Mata Pelajaran Pilihan',
  'Muatan Lokal',
];

interface Props {
  data: {
    id: string;
    namaMapel?: string;
    kodeMapel?: string;
    kelompok?: string;
    aktif?: boolean;
  } | null;
  onSave: (data: { namaMapel: string; kodeMapel?: string; kelompok?: string; aktif: boolean }) => Promise<void>;
  onClose: () => void;
}

export default function MapelFormDialog({ data, onSave, onClose }: Props) {
  const [namaMapel, setNamaMapel] = useState('');
  const [kodeMapel, setKodeMapel] = useState('');
  const [kelompok, setKelompok] = useState('');
  const [aktif, setAktif] = useState('Aktif');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (data) {
      setNamaMapel(data.namaMapel ?? '');
      setKodeMapel(data.kodeMapel ?? '');
      setKelompok(data.kelompok ?? '');
      setAktif(data.aktif !== false ? 'Aktif' : 'Tidak Aktif');
    }
  }, [data]);

  const handleSubmit = async () => {
    if (!namaMapel.trim()) return;
    setSaving(true);
    try {
      await onSave({
        namaMapel: namaMapel.trim(),
        kodeMapel: kodeMapel.trim() || undefined,
        kelompok: kelompok || undefined,
        aktif: aktif === 'Aktif',
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
      <div className="bg-background rounded-lg shadow-xl w-full max-w-md mx-4">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border">
          <h3 className="font-semibold text-foreground">Form Mata Pelajaran</h3>
          <button onClick={onClose} className="text-muted-foreground hover:text-foreground transition-colors">
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Body */}
        <div className="px-6 py-5 space-y-4">
          <div className="flex items-center gap-4">
            <Label className="w-20 text-right flex-shrink-0">Nama</Label>
            <Input
              placeholder="Nama"
              value={namaMapel}
              onChange={e => setNamaMapel(e.target.value)}
              className="flex-1"
            />
          </div>

          <div className="flex items-center gap-4">
            <Label className="w-20 text-right flex-shrink-0">Kode</Label>
            <Input
              placeholder="Kode Mata Pelajaran"
              value={kodeMapel}
              onChange={e => setKodeMapel(e.target.value)}
              className="flex-1"
            />
          </div>

          <div className="flex items-center gap-4">
            <Label className="w-20 text-right flex-shrink-0">Kelompok</Label>
            <Select value={kelompok} onValueChange={setKelompok}>
              <SelectTrigger className="flex-1">
                <SelectValue placeholder="Pilih Kelompok" />
              </SelectTrigger>
              <SelectContent>
                {KELOMPOK_OPTIONS.map(opt => (
                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-center gap-4">
            <Label className="w-20 text-right flex-shrink-0">Status</Label>
            <Select value={aktif} onValueChange={setAktif}>
              <SelectTrigger className="flex-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Aktif">Aktif</SelectItem>
                <SelectItem value="Tidak Aktif">Tidak Aktif</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        {/* Footer */}
        <div className="flex justify-end gap-2 px-6 py-4 border-t border-border">
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving || !namaMapel.trim()}>
            {saving ? 'Menyimpan...' : 'Simpan'}
          </Button>
        </div>
      </div>
    </div>
  );
}

src/components/tugas/TugasFormDialog.tsx.content:
import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, ClipboardList } from 'lucide-react';
import { toast } from 'sonner';
import { saveTugas, getGuruDropdown, getKelas, getMataPelajaran, type GetTugasOutputType } from 'zite-endpoints-sdk';

type TugasItem = GetTugasOutputType['tugas'][0];

interface Props {
  item?: TugasItem | null;
  open: boolean;
  onClose: () => void;
  onSaved: () => void;
  defaultGuruId?: string;
}

interface DropdownOption { id: string; label: string; }

export default function TugasFormDialog({ item, open, onClose, onSaved, defaultGuruId }: Props) {
  const [judulTugas, setJudulTugas] = useState('');
  const [deskripsi, setDeskripsi] = useState('');
  const [jenisTugas, setJenisTugas] = useState('');
  const [guruId, setGuruId] = useState('');
  const [kelasId, setKelasId] = useState('');
  const [mapelId, setMapelId] = useState('');
  const [tanggalDiberikan, setTanggalDiberikan] = useState('');
  const [deadline, setDeadline] = useState('');
  const [catatan, setCatatan] = useState('');
  const [saving, setSaving] = useState(false);

  const [guruList, setGuruList] = useState<DropdownOption[]>([]);
  const [kelasList, setKelasList] = useState<DropdownOption[]>([]);
  const [mapelList, setMapelList] = useState<DropdownOption[]>([]);

  useEffect(() => {
    if (!open) return;
    Promise.all([
      getGuruDropdown({}),
      getKelas({}),
      getMataPelajaran({}),
    ]).then(([g, k, m]) => {
      setGuruList(g.guru.map(x => ({ id: x.id, label: x.nama })));
      setKelasList((k as any[]).map((x: any) => ({ id: x.id, label: x.namaKelas || '' })));
      setMapelList(m.records.map(x => ({ id: x.id, label: x.namaMapel || '' })));
    });
  }, [open]);

  useEffect(() => {
    if (open) {
      if (item) {
        setJudulTugas(item.judulTugas);
        setDeskripsi(item.deskripsi);
        setJenisTugas(item.jenisTugas);
        setGuruId(item.guruId);
        setKelasId(item.kelasId);
        setMapelId(item.mapelId);
        setTanggalDiberikan(item.tanggalDiberikan);
        setDeadline(item.deadline);
        setCatatan(item.catatan);
      } else {
        setJudulTugas('');
        setDeskripsi('');
        setJenisTugas('');
        setGuruId(defaultGuruId || '');
        setKelasId('');
        setMapelId('');
        const today = new Date().toISOString().split('T')[0];
        setTanggalDiberikan(today);
        setDeadline('');
        setCatatan('');
      }
    }
  }, [open, item, defaultGuruId]);

  const handleSave = async () => {
    if (!judulTugas.trim()) { toast.error('Judul tugas wajib diisi'); return; }
    if (!jenisTugas) { toast.error('Jenis tugas wajib dipilih'); return; }
    if (!guruId) { toast.error('Guru wajib dipilih'); return; }
    if (!kelasId) { toast.error('Kelas wajib dipilih'); return; }
    if (!mapelId) { toast.error('Mata pelajaran wajib dipilih'); return; }
    if (!deadline) { toast.error('Deadline wajib diisi'); return; }
    setSaving(true);
    try {
      await saveTugas({
        id: item?.id,
        judulTugas,
        deskripsi: deskripsi || undefined,
        jenisTugas,
        guruId,
        kelasId,
        mapelId,
        tanggalDiberikan,
        deadline,
        catatan: catatan || undefined,
        status: item?.status,
      });
      toast.success(item ? 'Tugas berhasil diperbarui' : 'Tugas berhasil dibuat');
      onSaved();
      onClose();
    } catch {
      toast.error('Gagal menyimpan tugas');
    }
    setSaving(false);
  };

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-lg max-h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 pt-5 pb-3 flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-lg">
            <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
              <ClipboardList className="h-4 w-4 text-primary" />
            </div>
            {item ? 'Edit Tugas' : 'Buat Tugas Baru'}
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 pb-4">
          <div className="space-y-4">
            <FieldWrap label="Judul Tugas" required>
              <Input value={judulTugas} onChange={e => setJudulTugas(e.target.value)} placeholder="Contoh: Latihan Soal Bab 3" />
            </FieldWrap>

            <div className="grid grid-cols-2 gap-3">
              <FieldWrap label="Jenis Tugas" required>
                <Select value={jenisTugas} onValueChange={setJenisTugas}>
                  <SelectTrigger><SelectValue placeholder="Pilih jenis" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Tugas Harian">Tugas Harian</SelectItem>
                    <SelectItem value="PR (Pekerjaan Rumah)">PR</SelectItem>
                    <SelectItem value="Proyek">Proyek</SelectItem>
                    <SelectItem value="Latihan">Latihan</SelectItem>
                    <SelectItem value="Ulangan">Ulangan</SelectItem>
                    <SelectItem value="Kuis">Kuis</SelectItem>
                  </SelectContent>
                </Select>
              </FieldWrap>
              <FieldWrap label="Guru" required>
                <Select value={guruId} onValueChange={setGuruId}>
                  <SelectTrigger><SelectValue placeholder="Pilih guru" /></SelectTrigger>
                  <SelectContent>
                    {guruList.map(g => <SelectItem key={g.id} value={g.id}>{g.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </FieldWrap>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <FieldWrap label="Kelas" required>
                <Select value={kelasId} onValueChange={setKelasId}>
                  <SelectTrigger><SelectValue placeholder="Pilih kelas" /></SelectTrigger>
                  <SelectContent>
                    {kelasList.map(k => <SelectItem key={k.id} value={k.id}>{k.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </FieldWrap>
              <FieldWrap label="Mata Pelajaran" required>
                <Select value={mapelId} onValueChange={setMapelId}>
                  <SelectTrigger><SelectValue placeholder="Pilih mapel" /></SelectTrigger>
                  <SelectContent>
                    {mapelList.map(m => <SelectItem key={m.id} value={m.id}>{m.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </FieldWrap>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <FieldWrap label="Tanggal Diberikan" required>
                <Input type="date" value={tanggalDiberikan} onChange={e => setTanggalDiberikan(e.target.value)} />
              </FieldWrap>
              <FieldWrap label="Deadline" required>
                <Input type="date" value={deadline} onChange={e => setDeadline(e.target.value)} min={tanggalDiberikan} />
              </FieldWrap>
            </div>

            <FieldWrap label="Deskripsi Tugas" optional>
              <Textarea value={deskripsi} onChange={e => setDeskripsi(e.target.value)} placeholder="Jelaskan tugas yang diberikan..." rows={3} className="resize-none" />
            </FieldWrap>

            <FieldWrap label="Catatan" optional>
              <Textarea value={catatan} onChange={e => setCatatan(e.target.value)} placeholder="Catatan tambahan..." rows={2} className="resize-none" />
            </FieldWrap>
          </div>
        </div>

        <div className="flex justify-end gap-2 px-6 py-3 border-t bg-card flex-shrink-0">
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {item ? 'Simpan Perubahan' : 'Buat Tugas'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function FieldWrap({ label, required, optional, children }: { label: string; required?: boolean; optional?: boolean; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-sm">
        {label}
        {required && <span className="text-destructive ml-0.5">*</span>}
        {optional && <span className="text-muted-foreground text-xs ml-1">(opsional)</span>}
      </Label>
      {children}
    </div>
  );
}

src/components/jadwal/JadwalTableView.ts.content:
import { Pencil, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { JadwalEntry } from './TimetableGrid';

const DAY_BADGE: Record<string, string> = {
  Senin: 'bg-primary/10 text-primary',
  Selasa: 'bg-primary/10 text-primary',
  Rabu: 'bg-primary/10 text-primary',
  Kamis: 'bg-primary/10 text-primary',
  Jumat: 'bg-primary/10 text-primary',
  Sabtu: 'bg-accent text-accent-foreground',
};

interface Props {
  jadwal: JadwalEntry[];
  onEdit: (e: JadwalEntry) => void;
  onDelete: (id: string) => void;
}

export default function JadwalTableView({ jadwal, onEdit, onDelete }: Props) {
  if (jadwal.length === 0) {
    return (
      <div className="text-center py-16 text-muted-foreground text-sm">
        Belum ada jadwal pelajaran untuk kelas ini
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-muted/40 border-b border-border">
            <th className="w-12 text-center px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">No</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider w-24">Hari</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider w-32">Waktu</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Mata Pelajaran</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Guru Pengampu</th>
            <th className="text-center px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider w-24">Aksi</th>
          </tr>
        </thead>
        <tbody>
          {jadwal.map((j, i) => (
            <tr key={j.id} className="border-b border-border last:border-0 hover:bg-muted/30 transition-colors group">
              <td className="text-center px-4 py-2.5 text-muted-foreground">{i + 1}</td>
              <td className="px-4 py-2.5">
                <span className={`inline-block px-2.5 py-0.5 rounded-full text-xs font-semibold ${DAY_BADGE[j.hari] || 'bg-muted text-muted-foreground'}`}>
                  {j.hari}
                </span>
              </td>
              <td className="px-4 py-2.5 font-medium text-foreground">
                {j.jamMulai} – {j.jamSelesai}
              </td>
              <td className="px-4 py-2.5 font-medium">{j.mapelNama}</td>
              <td className="px-4 py-2.5 text-muted-foreground">{j.guruNama}</td>
              <td className="px-4 py-2.5">
                <div className="flex items-center justify-center gap-1">
                  <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(j)}>
                    <Pencil className="h-3.5 w-3.5 text-muted-foreground" />
                  </Button>
                  <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onDelete(j.id)}>
                    <Trash2 className="h-3.5 w-3.5 text-destructive" />
                  </Button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

src/components/siswa/SearchableSelect.ts.content:
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Check, ChevronsUpDown, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface Option {
  id: string;
  name: string;
}

interface Props {
  options: Option[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  disabledPlaceholder?: string;
  disabled?: boolean;
  loading?: boolean;
}

function toDisplayName(name: string): string {
  if (name !== name.toUpperCase()) return name;
  const prefixes = ['KABUPATEN ', 'KOTA ', 'KECAMATAN ', 'KELURAHAN ', 'DESA '];
  let display = name;
  for (const prefix of prefixes) {
    if (display.startsWith(prefix)) {
      display = display.substring(prefix.length);
      break;
    }
  }
  return display.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());
}

export default function SearchableSelect({
  options,
  value,
  onChange,
  placeholder = 'Pilih...',
  disabledPlaceholder,
  disabled = false,
  loading = false,
}: Props) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');

  const handleOpenChange = (v: boolean) => {
    if (disabled || loading) return;
    setOpen(v);
    if (!v) setSearch('');
  };

  const filtered = options.filter((o) =>
    toDisplayName(o.name).toLowerCase().includes(search.toLowerCase())
  );

  const selectedLabel = value
    ? toDisplayName(options.find((o) => o.name === value)?.name ?? value)
    : '';

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled || loading}
          className="w-full justify-between font-normal"
        >
          {loading ? (
            <span className="flex items-center gap-2 text-muted-foreground text-sm">
              <Loader2 className="h-3 w-3 animate-spin" /> Memuat...
            </span>
          ) : value ? (
            <span className="truncate">{selectedLabel}</span>
          ) : (
            <span className="text-muted-foreground">
              {disabled && disabledPlaceholder ? disabledPlaceholder : placeholder}
            </span>
          )}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="p-2"
        align="start"
        sideOffset={4}
        style={{ width: 'var(--radix-popover-trigger-width)' }}
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <Input
          placeholder="Ketik untuk mencari..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="mb-2"
          autoFocus
        />
        <div className="overflow-y-auto max-h-60">
          {filtered.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-4">Tidak ditemukan.</p>
          ) : (
            filtered.map((option) => (
              <div
                key={option.id}
                className={cn(
                  'flex items-center gap-2 px-2 py-1.5 rounded-sm text-sm cursor-pointer hover:bg-accent hover:text-accent-foreground',
                  value === option.name && 'bg-accent text-accent-foreground'
                )}
                onMouseDown={(e) => {
                  e.preventDefault();
                  onChange(option.name);
                  setOpen(false);
                  setSearch('');
                }}
              >
                <Check className={cn('h-4 w-4 shrink-0', value === option.name ? 'opacity-100' : 'opacity-0')} />
                {toDisplayName(option.name)}
              </div>
            ))
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

src/pages/manajemen/MataPelajaranPage.ts.content:
import { useState, useEffect, useCallback } from 'react';
import { Plus, Pencil, Trash2, Check, X, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { Toaster } from '@/components/ui/sonner';
import { getMataPelajaran, createMataPelajaran, updateMataPelajaran, deleteMataPelajaran } from 'zite-endpoints-sdk';
import type { GetMataPelajaranOutputType } from 'zite-endpoints-sdk';
import MapelFormDialog from '@/components/mapel/MapelFormDialog';

type MapelRecord = GetMataPelajaranOutputType['records'][0];

const KELOMPOK_COLORS: Record<string, string> = {
  'Mata Pelajaran Wajib': 'bg-blue-100 text-blue-700',
  'Mata Pelajaran Pilihan': 'bg-orange-100 text-orange-700',
  'Muatan Lokal': 'bg-green-100 text-green-700',
};

const PAGE_SIZE_OPTIONS = [
  { label: 'Tampilkan 10', value: 10 },
  { label: 'Tampilkan 25', value: 25 },
  { label: 'Tampilkan 100', value: 100 },
  { label: 'Semuanya', value: 99999 },
];

export default function MataPelajaranPage() {
  const [records, setRecords] = useState<MapelRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editData, setEditData] = useState<MapelRecord | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getMataPelajaran({ search, page, pageSize });
      setRecords(res.records);
      setTotal(res.total);
    } catch {
      toast.error('Gagal memuat data');
    } finally {
      setLoading(false);
    }
  }, [search, page, pageSize]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSave = async (data: { namaMapel: string; kodeMapel?: string; kelompok?: string; aktif: boolean }) => {
    try {
      if (editData) {
        await updateMataPelajaran({ id: editData.id, ...data });
        toast.success('Mata pelajaran berhasil diperbarui');
      } else {
        await createMataPelajaran(data);
        toast.success('Mata pelajaran berhasil ditambahkan');
      }
      setShowForm(false);
      setEditData(null);
      fetchData();
    } catch {
      toast.error('Gagal menyimpan data');
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await deleteMataPelajaran({ id: deleteId });
      toast.success('Mata pelajaran berhasil dihapus');
      setDeleteId(null);
      fetchData();
    } catch {
      toast.error('Gagal menghapus data');
    }
  };

  const totalPages = Math.ceil(total / pageSize);
  const startIndex = (page - 1) * pageSize + 1;
  const endIndex = Math.min(page * pageSize, total);

  return (
    <div className="space-y-4">
      <Toaster />

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Mata Pelajaran</h2>
          <p className="text-muted-foreground">Kelola data mata pelajaran</p>
        </div>
        <div className="flex items-center gap-2">
          <select
            className="border border-border rounded px-3 py-1.5 text-sm bg-background"
            value={pageSize}
            onChange={e => { setPageSize(Number(e.target.value)); setPage(1); }}
          >
            {PAGE_SIZE_OPTIONS.map(s => (
              <option key={s.value} value={s.value}>{s.label}</option>
            ))}
          </select>
          <Button variant="outline" size="sm" className="gap-1.5">
            <Download className="h-4 w-4" />
            Export
          </Button>
          <Button size="sm" className="gap-1.5" onClick={() => { setEditData(null); setShowForm(true); }}>
            <Plus className="h-4 w-4" />
            Tambah
          </Button>
        </div>
      </div>

      {/* Search */}
      <div className="flex justify-end">
        <div className="flex items-center gap-2">
          <span className="text-sm text-muted-foreground">Pencarian:</span>
          <Input
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(1); }}
            className="w-48 h-8 text-sm"
          />
        </div>
      </div>

      {/* Table */}
      <div className="border border-border rounded overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-4 py-2.5 font-semibold text-foreground w-12">No</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground">Nama</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground w-28">Kode</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground">Kelompok</th>
              <th className="text-center px-4 py-2.5 font-semibold text-foreground w-20">Aktif</th>
              <th className="text-center px-4 py-2.5 font-semibold text-foreground w-24">Action</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="text-center py-10 text-muted-foreground">Memuat data...</td>
              </tr>
            ) : records.length === 0 ? (
              <tr>
                <td colSpan={6} className="text-center py-10 text-muted-foreground">Tidak ada data</td>
              </tr>
            ) : (
              records.map((r, i) => (
                <tr key={r.id} className={i % 2 === 0 ? 'bg-background' : 'bg-muted/20'}>
                  <td className="px-4 py-2.5 text-primary font-medium">{startIndex + i}</td>
                  <td className="px-4 py-2.5 text-primary font-medium">{r.namaMapel}</td>
                  <td className="px-4 py-2.5 text-foreground">{r.kodeMapel}</td>
                  <td className="px-4 py-2.5">
                    {r.kelompok ? (
                      <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${KELOMPOK_COLORS[r.kelompok] ?? 'bg-muted text-muted-foreground'}`}>
                        {r.kelompok}
                      </span>
                    ) : '-'}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    {r.aktif !== false ? (
                      <Check className="h-4 w-4 text-primary mx-auto" />
                    ) : (
                      <X className="h-4 w-4 text-destructive mx-auto" />
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => { setEditData(r); setShowForm(true); }}
                        className="text-primary hover:text-primary/70 transition-colors"
                      >
                        <Pencil className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => setDeleteId(r.id)}
                        className="text-destructive hover:text-destructive/70 transition-colors"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span>
          {total === 0 ? 'Tidak ada data' : `Menampilkan ${startIndex} sampai ${endIndex} dari ${total}`}
        </span>
        <div className="flex items-center gap-1">
          <button
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
            className="px-2 py-1 rounded border border-border disabled:opacity-40 hover:bg-muted"
          >
            &lt;
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
            <button
              key={p}
              onClick={() => setPage(p)}
              className={`px-2.5 py-1 rounded border text-sm ${p === page ? 'bg-primary text-primary-foreground border-primary' : 'border-border hover:bg-muted'}`}
            >
              {p}
            </button>
          ))}
          <button
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page === totalPages || totalPages === 0}
            className="px-2 py-1 rounded border border-border disabled:opacity-40 hover:bg-muted"
          >
            &gt;
          </button>
        </div>
      </div>

      {/* Form Dialog */}
      {showForm && (
        <MapelFormDialog
          data={editData}
          onSave={handleSave}
          onClose={() => { setShowForm(false); setEditData(null); }}
        />
      )}

      {/* Delete Dialog */}
      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Mata Pelajaran</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus mata pelajaran ini? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

src/components/jadwal/JadwalFormDialog.t.content:
import { useState, useEffect, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Clock, AlertCircle, Split } from 'lucide-react';
import type { JpSlot, JadwalSettings } from './PengaturanJadwalSheet';
import { isSpecialSlot } from './PengaturanJadwalSheet';
import type { JadwalEntry } from './TimetableGrid';

interface MapelItem { id: string; nama: string; kode?: string }
interface GuruItem { id: string; nama: string }

export interface JadwalFormData {
  id?: string;
  hari: string;
  jamMulai: string;
  jamSelesai: string;
  mapelId: string;
  guruId: string;
  jpMulai?: number;
  jpCount?: number;
}

export interface JpSegment {
  jpStart: number;
  jpEnd: number;
  jpCount: number;
  jamMulai: string;
  jamSelesai: string;
}

interface Props {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: JadwalFormData) => Promise<void>;
  onSubmitMulti?: (segments: JadwalFormData[]) => Promise<void>;
  initial?: JadwalFormData | null;
  mapelList: MapelItem[];
  guruList: GuruItem[];
  settings: JadwalSettings;
  existingJadwal: JadwalEntry[];
}

function computeSegments(startJp: number, count: number, allSlots: JpSlot[]): JpSegment[] {
  const jpSlots = allSlots.filter(s => !isSpecialSlot(s));
  const startIdx = jpSlots.findIndex(s => s.jp === startJp);
  if (startIdx < 0 || count <= 0) return [];

  const selectedJps = jpSlots.slice(startIdx, startIdx + count);
  if (selectedJps.length === 0) return [];

  const segments: JpSegment[] = [];
  let segStart = 0;

  for (let i = 0; i < selectedJps.length; i++) {
    const isLast = i === selectedJps.length - 1;
    let hasBreakAfter = false;

    if (!isLast) {
      const thisAllIdx = allSlots.findIndex(s => !isSpecialSlot(s) && s.jp === selectedJps[i].jp);
      const nextAllIdx = allSlots.findIndex(s => !isSpecialSlot(s) && s.jp === selectedJps[i + 1].jp);
      for (let j = thisAllIdx + 1; j < nextAllIdx; j++) {
        if (isSpecialSlot(allSlots[j])) {
          hasBreakAfter = true;
          break;
        }
      }
    }

    if (hasBreakAfter || isLast) {
      const segJps = selectedJps.slice(segStart, i + 1);
      segments.push({
        jpStart: segJps[0].jp,
        jpEnd: segJps[segJps.length - 1].jp,
        jpCount: segJps.length,
        jamMulai: segJps[0].mulai,
        jamSelesai: segJps[segJps.length - 1].selesai,
      });
      segStart = i + 1;
    }
  }
  return segments;
}

export default function JadwalFormDialog({
  open, onClose, onSubmit, onSubmitMulti, initial, mapelList, guruList, settings, existingJadwal,
}: Props) {
  const [hari, setHari] = useState('Senin');
  const [jpMulai, setJpMulai] = useState('');
  const [jpCount, setJpCount] = useState('1');
  const [mapelId, setMapelId] = useState('');
  const [guruId, setGuruId] = useState('');
  const [saving, setSaving] = useState(false);

  const isEditing = !!initial?.id;

  const jpSlots = useMemo(() => settings.slots.filter(s => !isSpecialSlot(s)), [settings.slots]);

  // Occupied JPs for selected day (excluding current entry when editing)
  const occupiedJps = useMemo(() => {
    const occupied = new Set<number>();
    const entriesForDay = existingJadwal.filter(j => j.hari === hari && j.id !== initial?.id);
    for (const entry of entriesForDay) {
      const startIdx = jpSlots.findIndex(s => s.mulai === entry.jamMulai);
      const endIdx = jpSlots.findIndex(s => s.selesai === entry.jamSelesai);
      if (startIdx >= 0 && endIdx >= 0) {
        for (let i = startIdx; i <= endIdx; i++) {
          occupied.add(jpSlots[i].jp);
        }
      }
    }
    return occupied;
  }, [existingJadwal, hari, initial?.id, jpSlots]);

  // Available JP slots (free slots the user can pick as start)
  const availableJpStarts = useMemo(() => {
    return jpSlots.filter(s => !occupiedJps.has(s.jp));
  }, [jpSlots, occupiedJps]);

  // First available JP
  const firstAvailableJp = useMemo(() => {
    return availableJpStarts.length > 0 ? availableJpStarts[0].jp : 0;
  }, [availableJpStarts]);

  // For editing, find the JP from the initial data
  const editJpMulai = useMemo(() => {
    if (!initial?.jamMulai) return 0;
    const match = jpSlots.find(s => s.mulai === initial.jamMulai);
    return match?.jp || 0;
  }, [initial, jpSlots]);

  const selectedJpMulai = jpMulai ? Number(jpMulai) : 0;

  // Max consecutive available JPs from selected start
  const maxConsecutive = useMemo(() => {
    if (!selectedJpMulai) return 0;
    const startIdx = jpSlots.findIndex(s => s.jp === selectedJpMulai);
    if (startIdx < 0) return 0;
    let count = 0;
    for (let i = startIdx; i < jpSlots.length && count < 8; i++) {
      if (occupiedJps.has(jpSlots[i].jp)) break;
      count++;
    }
    return count;
  }, [selectedJpMulai, jpSlots, occupiedJps]);

  const jpCountOptions = useMemo(() => {
    return Array.from({ length: Math.min(Math.max(maxConsecutive, 0), 8) }, (_, i) => i + 1);
  }, [maxConsecutive]);

  // Segments
  const segments = useMemo(() => {
    if (!selectedJpMulai || Number(jpCount) <= 0) return [];
    return computeSegments(selectedJpMulai, Number(jpCount), settings.slots);
  }, [selectedJpMulai, jpCount, settings.slots]);

  const hasSplit = segments.length > 1;

  const totalDuration = useMemo(() => {
    let total = 0;
    for (const seg of segments) {
      const [h1, m1] = seg.jamMulai.split(':').map(Number);
      const [h2, m2] = seg.jamSelesai.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  }, [segments]);

  // Initialize form
  useEffect(() => {
    if (!open) return;
    if (initial) {
      setHari(initial.hari || 'Senin');
      setMapelId(initial.mapelId || '');
      setGuruId(initial.guruId || '');
      if (isEditing && editJpMulai) {
        setJpMulai(String(editJpMulai));
        // Calculate JP count from times
        const matchStart = jpSlots.findIndex(s => s.mulai === initial.jamMulai);
        const matchEnd = jpSlots.findIndex(s => s.selesai === initial.jamSelesai);
        if (matchStart >= 0 && matchEnd >= 0) {
          setJpCount(String(matchEnd - matchStart + 1));
        } else {
          setJpCount('1');
        }
      } else {
        // New entry - auto-select first available
        setJpCount('1');
      }
    } else {
      setHari('Senin');
      setJpCount('1');
      setMapelId('');
      setGuruId('');
    }
  }, [open, initial, jpSlots, isEditing, editJpMulai]);

  // Set jpMulai after hari changes (delayed because availableJpStarts depends on hari)
  useEffect(() => {
    if (!open) return;
    if (isEditing && editJpMulai) {
      setJpMulai(String(editJpMulai));
    } else if (firstAvailableJp) {
      setJpMulai(String(firstAvailableJp));
    } else {
      setJpMulai('');
    }
  }, [open, hari, firstAvailableJp, isEditing, editJpMulai]);

  const handleHariChange = (newHari: string) => {
    setHari(newHari);
    setJpCount('1');
  };

  const handleJpMulaiChange = (val: string) => {
    setJpMulai(val);
    setJpCount('1');
  };

  // Adjust jpCount if it exceeds max
  useEffect(() => {
    if (Number(jpCount) > maxConsecutive && maxConsecutive > 0) {
      setJpCount(String(maxConsecutive));
    }
  }, [maxConsecutive, jpCount]);

  const handleSubmit = async () => {
    if (!hari || !mapelId || !guruId || segments.length === 0) return;
    setSaving(true);
    try {
      if (isEditing) {
        const seg = segments[0];
        await onSubmit({
          id: initial?.id,
          hari,
          jamMulai: seg.jamMulai,
          jamSelesai: seg.jamSelesai,
          mapelId,
          guruId,
          jpMulai: seg.jpStart,
          jpCount: seg.jpCount,
        });
        // If editing changed JP count and created extra segments, save them
        if (segments.length > 1 && onSubmitMulti) {
          const extraSegments: JadwalFormData[] = segments.slice(1).map(s => ({
            hari, jamMulai: s.jamMulai, jamSelesai: s.jamSelesai, mapelId, guruId,
            jpMulai: s.jpStart, jpCount: s.jpCount,
          }));
          await onSubmitMulti(extraSegments);
        } else if (segments.length > 1) {
          for (const s of segments.slice(1)) {
            await onSubmit({
              hari, jamMulai: s.jamMulai, jamSelesai: s.jamSelesai, mapelId, guruId,
              jpMulai: s.jpStart, jpCount: s.jpCount,
            });
          }
        }
      } else if (segments.length === 1) {
        const seg = segments[0];
        await onSubmit({
          hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
          jpMulai: seg.jpStart, jpCount: seg.jpCount,
        });
      } else if (onSubmitMulti) {
        const entries: JadwalFormData[] = segments.map(seg => ({
          hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
          jpMulai: seg.jpStart, jpCount: seg.jpCount,
        }));
        await onSubmitMulti(entries);
      } else {
        for (const seg of segments) {
          await onSubmit({
            hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
            jpMulai: seg.jpStart, jpCount: seg.jpCount,
          });
        }
      }
      onClose();
    } finally {
      setSaving(false);
    }
  };

  const isValid = hari && mapelId && guruId && segments.length > 0;
  const noSlots = availableJpStarts.length === 0 && !isEditing;

  return (
    <Dialog open={open} onOpenChange={v => !v && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{isEditing ? 'Edit Jadwal' : 'Tambah Jadwal'}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Hari */}
          <div className="space-y-1.5">
            <Label>Hari <span className="text-destructive">*</span></Label>
            <Select value={hari} onValueChange={handleHariChange}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {settings.hariAktif.map(h => (
                  <SelectItem key={h} value={h}>{h}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* JP Mulai */}
          <div className="space-y-1.5">
            <Label>JP Mulai <span className="text-destructive">*</span></Label>
            <Select value={jpMulai} onValueChange={handleJpMulaiChange} disabled={noSlots}>
              <SelectTrigger>
                <SelectValue placeholder="Pilih JP" />
              </SelectTrigger>
              <SelectContent>
                {availableJpStarts.map(s => (
                  <SelectItem key={s.jp} value={String(s.jp)}>
                    JP {s.jp} ({s.mulai} – {s.selesai})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Jumlah JP */}
          <div className="space-y-1.5">
            <Label>Jumlah JP <span className="text-destructive">*</span></Label>
            <Select value={jpCount} onValueChange={setJpCount} disabled={noSlots || !selectedJpMulai}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {jpCountOptions.map(n => (
                  <SelectItem key={n} value={String(n)}>
                    {n} JP
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* No slots warning */}
          {noSlots && (
            <div className="flex items-center gap-2 px-3 py-2.5 rounded-lg bg-destructive/5 border border-destructive/15 text-sm text-destructive">
              <AlertCircle className="h-4 w-4 flex-shrink-0" />
              Semua JP pada hari {hari} sudah terisi
            </div>
          )}

          {/* Time preview */}
          {segments.length > 0 && (
            <div className="space-y-1.5">
              {hasSplit && (
                <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <Split className="h-3.5 w-3.5" />
                  <span>Terbagi {segments.length} sesi karena jeda istirahat/sholat</span>
                </div>
              )}
              {segments.map((seg, i) => (
                <div key={i} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-primary/5 border border-primary/15">
                  <Clock className="h-4 w-4 text-primary flex-shrink-0" />
                  <div className="flex-1">
                    <span className="text-sm font-medium text-foreground">
                      {seg.jamMulai} – {seg.jamSelesai}
                    </span>
                    <span className="text-[10px] font-bold bg-primary/10 text-primary px-1.5 py-0.5 rounded ml-2">
                      JP {seg.jpStart === seg.jpEnd ? seg.jpStart : `${seg.jpStart}–${seg.jpEnd}`}
                    </span>
                  </div>
                  <span className="text-xs text-muted-foreground">
                    {seg.jpCount} JP
                  </span>
                </div>
              ))}
              <p className="text-xs text-muted-foreground text-right">
                Total: {totalDuration} menit ({segments.reduce((s, seg) => s + seg.jpCount, 0)} JP)
              </p>
            </div>
          )}

          {/* Mapel */}
          <div className="space-y-1.5">
            <Label>Mata Pelajaran <span className="text-destructive">*</span></Label>
            <Select value={mapelId} onValueChange={setMapelId}>
              <SelectTrigger><SelectValue placeholder="Pilih mata pelajaran" /></SelectTrigger>
              <SelectContent>
                {mapelList.map(m => (
                  <SelectItem key={m.id} value={m.id}>
                    {m.nama}{m.kode ? ` (${m.kode})` : ''}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Guru */}
          <div className="space-y-1.5">
            <Label>Guru Pengampu <span className="text-destructive">*</span></Label>
            <Select value={guruId} onValueChange={setGuruId}>
              <SelectTrigger><SelectValue placeholder="Pilih guru" /></SelectTrigger>
              <SelectContent>
                {guruList.map(g => (
                  <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving || !isValid}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {isEditing ? 'Simpan' : hasSplit ? `Tambah (${segments.length} sesi)` : 'Tambah'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/components/jurnal/JurnalFormDialog.t.content:
import { useState, useEffect, useCallback } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Skeleton } from '@/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, CheckCircle2, BookOpen, Users, Clock, GraduationCap, ClipboardList } from 'lucide-react';
import { toast } from 'sonner';
import { getStudentsForJurnal, saveJurnal } from 'zite-endpoints-sdk';

export interface JurnalItem {
  id: string;
  tanggal: string;
  hari: string;
  jamMulai: string;
  jamSelesai: string;
  guruId: string;
  guruNama: string;
  kelasId: string;
  kelasNama: string;
  mapelId: string;
  mapelNama: string;
  jadwalId: string;
  tujuanPembelajaran?: string;
  materiKonten?: string;
  kegiatanPembelajaran?: string;
  catatan?: string;
  statusKehadiran?: string;
  detailKehadiran?: string;
  status?: string;
  jurnalId?: string;
}

interface Props {
  item: JurnalItem | null;
  open: boolean;
  onClose: () => void;
  onSaved: () => void;
}

interface StudentAttendance {
  id: string;
  nama: string;
  nisn: string;
  status: 'H' | 'I' | 'S' | 'A';
}

export default function JurnalFormDialog({ item, open, onClose, onSaved }: Props) {
  const [tujuan, setTujuan] = useState('');
  const [materi, setMateri] = useState('');
  const [kegiatan, setKegiatan] = useState('');
  const [catatan, setCatatan] = useState('');
  const [hadirSemua, setHadirSemua] = useState(true);
  const [students, setStudents] = useState<StudentAttendance[]>([]);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [saving, setSaving] = useState(false);

  // Penugasan state
  const [tambahTugas, setTambahTugas] = useState(false);
  const [judulTugas, setJudulTugas] = useState('');
  const [deskripsiTugas, setDeskripsiTugas] = useState('');
  const [jenisTugas, setJenisTugas] = useState('');
  const [deadlineTugas, setDeadlineTugas] = useState('');
  const [catatanTugas, setCatatanTugas] = useState('');

  const loadStudents = useCallback(async (kelasId: string) => {
    setLoadingStudents(true);
    try {
      const res = await getStudentsForJurnal({ kelasId });
      let parsed: Record<string, string> = {};
      if (item?.detailKehadiran) {
        try { parsed = JSON.parse(item.detailKehadiran); } catch {}
      }
      setStudents(res.students.map(s => ({
        id: s.id, nama: s.nama, nisn: s.nisn,
        status: (parsed[s.id] as any) || 'H',
      })));
    } catch { /* ignore */ }
    setLoadingStudents(false);
  }, [item?.detailKehadiran]);

  useEffect(() => {
    if (open && item) {
      setTujuan(item.tujuanPembelajaran || '');
      setMateri(item.materiKonten || '');
      setKegiatan(item.kegiatanPembelajaran || '');
      setCatatan(item.catatan || '');
      setHadirSemua(item.statusKehadiran !== 'Tidak Semua Hadir');
      loadStudents(item.kelasId);
      // Reset penugasan
      setTambahTugas(false);
      setJudulTugas('');
      setDeskripsiTugas('');
      setJenisTugas('');
      setDeadlineTugas('');
      setCatatanTugas('');
    }
  }, [open, item, loadStudents]);

  const updateStudentStatus = (studentId: string, status: 'H' | 'I' | 'S' | 'A') => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, status } : s));
  };

  const handleSave = async () => {
    if (!item) return;
    if (!tujuan.trim()) { toast.error('Tujuan Pembelajaran wajib diisi'); return; }
    if (!materi.trim()) { toast.error('Materi/Konten wajib diisi'); return; }
    if (tambahTugas) {
      if (!judulTugas.trim()) { toast.error('Judul tugas wajib diisi'); return; }
      if (!jenisTugas) { toast.error('Jenis tugas wajib dipilih'); return; }
      if (!deadlineTugas) { toast.error('Deadline tugas wajib diisi'); return; }
    }
    setSaving(true);
    try {
      const detailMap: Record<string, string> = {};
      if (!hadirSemua) {
        for (const s of students) detailMap[s.id] = s.status;
      }
      await saveJurnal({
        jurnalId: item.jurnalId,
        tanggal: item.tanggal,
        guruId: item.guruId,
        kelasId: item.kelasId,
        mapelId: item.mapelId,
        jadwalId: item.jadwalId,
        jamMulai: item.jamMulai,
        jamSelesai: item.jamSelesai,
        tujuanPembelajaran: tujuan,
        materiKonten: materi,
        kegiatanPembelajaran: kegiatan || undefined,
        catatan: catatan || undefined,
        statusKehadiran: hadirSemua ? 'Hadir Semua' : 'Tidak Semua Hadir',
        detailKehadiran: hadirSemua ? undefined : JSON.stringify(detailMap),
        penugasan: tambahTugas ? {
          judulTugas,
          deskripsi: deskripsiTugas || undefined,
          jenisTugas,
          deadline: deadlineTugas,
          catatan: catatanTugas || undefined,
        } : undefined,
      });
      toast.success(tambahTugas ? 'Jurnal & tugas berhasil disimpan' : 'Jurnal berhasil disimpan');
      onSaved();
      onClose();
    } catch {
      toast.error('Gagal menyimpan jurnal');
    }
    setSaving(false);
  };

  if (!item) return null;

  const absentCount = students.filter(s => s.status !== 'H').length;
  const dateStr = new Date(item.tanggal + 'T00:00:00').toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-2xl h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 pt-5 pb-3 flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-lg">
            <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
              <BookOpen className="h-4 w-4 text-primary" />
            </div>
            {item.jurnalId ? 'Edit' : 'Isi'} Jurnal Mengajar
          </DialogTitle>
        </DialogHeader>

        <div className="px-6 pb-3 flex-shrink-0">
          <div className="flex flex-wrap gap-2">
            <InfoChip icon={GraduationCap} label={item.mapelNama} />
            <InfoChip icon={Users} label={item.kelasNama} />
            <InfoChip icon={Clock} label={`${item.jamMulai}–${item.jamSelesai}`} />
            <InfoChip label={`${item.hari}, ${dateStr}`} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-6 pb-4">
          <div className="space-y-5">
            <FormField label="Tujuan Pembelajaran" required>
              <Textarea value={tujuan} onChange={e => setTujuan(e.target.value)} placeholder="Tuliskan tujuan pembelajaran..." rows={3} className="resize-none" />
            </FormField>

            <FormField label="Materi / Konten" required>
              <Textarea value={materi} onChange={e => setMateri(e.target.value)} placeholder="Tuliskan materi yang diajarkan..." rows={3} className="resize-none" />
            </FormField>

            <FormField label="Kegiatan Pembelajaran" optional>
              <Textarea value={kegiatan} onChange={e => setKegiatan(e.target.value)} placeholder="Deskripsi kegiatan pembelajaran..." rows={2} className="resize-none" />
            </FormField>

            <FormField label="Catatan" optional>
              <Textarea value={catatan} onChange={e => setCatatan(e.target.value)} placeholder="Catatan tambahan..." rows={2} className="resize-none" />
            </FormField>

            {/* Kehadiran */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">Kehadiran Siswa</Label>
                <div className="flex items-center gap-2">
                  <Switch checked={hadirSemua} onCheckedChange={setHadirSemua} />
                  <span className="text-sm font-medium">{hadirSemua ? 'Hadir Semua' : 'Ada yang tidak hadir'}</span>
                </div>
              </div>
              {hadirSemua ? (
                <div className="flex items-center gap-2 rounded-lg border bg-accent/30 p-3">
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                  <span className="text-sm">Semua siswa hadir ({students.length} siswa)</span>
                </div>
              ) : (
                <AttendanceList students={students} loading={loadingStudents} absentCount={absentCount} onUpdate={updateStudentStatus} />
              )}
            </div>

            {/* Penugasan Section */}
            <div className="space-y-3 border-t pt-5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="h-7 w-7 rounded-md bg-accent flex items-center justify-center">
                    <ClipboardList className="h-3.5 w-3.5 text-accent-foreground" />
                  </div>
                  <Label className="text-sm font-semibold">Tambah Penugasan</Label>
                </div>
                <Switch checked={tambahTugas} onCheckedChange={setTambahTugas} />
              </div>

              {!tambahTugas ? (
                <p className="text-xs text-muted-foreground">Aktifkan untuk memberikan tugas langsung dari jurnal ini. Tugas akan otomatis masuk ke menu Tugas.</p>
              ) : (
                <div className="space-y-4 rounded-lg border bg-muted/20 p-4">
                  <FormField label="Judul Tugas" required>
                    <Input value={judulTugas} onChange={e => setJudulTugas(e.target.value)} placeholder="Contoh: Latihan Soal Bab 3" />
                  </FormField>
                  <div className="grid grid-cols-2 gap-3">
                    <FormField label="Jenis Tugas" required>
                      <Select value={jenisTugas} onValueChange={setJenisTugas}>
                        <SelectTrigger><SelectValue placeholder="Pilih jenis" /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Tugas Harian">Tugas Harian</SelectItem>
                          <SelectItem value="PR (Pekerjaan Rumah)">PR</SelectItem>
                          <SelectItem value="Proyek">Proyek</SelectItem>
                          <SelectItem value="Latihan">Latihan</SelectItem>
                          <SelectItem value="Ulangan">Ulangan</SelectItem>
                          <SelectItem value="Kuis">Kuis</SelectItem>
                        </SelectContent>
                      </Select>
                    </FormField>
                    <FormField label="Deadline" required>
                      <Input type="date" value={deadlineTugas} onChange={e => setDeadlineTugas(e.target.value)} min={item.tanggal} />
                    </FormField>
                  </div>
                  <FormField label="Deskripsi Tugas" optional>
                    <Textarea value={deskripsiTugas} onChange={e => setDeskripsiTugas(e.target.value)} placeholder="Jelaskan tugas yang diberikan..." rows={2} className="resize-none" />
                  </FormField>
                  <FormField label="Catatan untuk Siswa" optional>
                    <Textarea value={catatanTugas} onChange={e => setCatatanTugas(e.target.value)} placeholder="Catatan tambahan..." rows={2} className="resize-none" />
                  </FormField>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-2 px-6 py-3 border-t bg-card flex-shrink-0">
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {tambahTugas ? 'Simpan Jurnal & Tugas' : 'Simpan Jurnal'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function InfoChip({ icon: Icon, label }: { icon?: React.ElementType; label: string }) {
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-3 py-1 text-xs font-medium text-foreground">
      {Icon && <Icon className="h-3 w-3 text-muted-foreground" />}
      {label}
    </span>
  );
}

function FormField({ label, required, optional, children }: { label: string; required?: boolean; optional?: boolean; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-sm">
        {label}
        {required && <span className="text-destructive ml-0.5">*</span>}
        {optional && <span className="text-muted-foreground text-xs ml-1">(opsional)</span>}
      </Label>
      {children}
    </div>
  );
}

function AttendanceList({ students, loading, absentCount, onUpdate }: {
  students: StudentAttendance[];
  loading: boolean;
  absentCount: number;
  onUpdate: (id: string, status: 'H' | 'I' | 'S' | 'A') => void;
}) {
  if (loading) return <div className="space-y-2">{[1,2,3].map(i => <Skeleton key={i} className="h-10 w-full" />)}</div>;
  if (students.length === 0) return <p className="text-sm text-muted-foreground py-3">Tidak ada data siswa di kelas ini</p>;

  const statusColors: Record<string, string> = {
    H: 'bg-primary text-primary-foreground',
    I: 'bg-accent text-accent-foreground ring-1 ring-border',
    S: 'bg-muted text-foreground ring-1 ring-border',
    A: 'bg-destructive text-destructive-foreground',
  };

  return (
    <div className="space-y-2">
      {absentCount > 0 && <p className="text-xs text-destructive font-medium">{absentCount} siswa tidak hadir</p>}
      <div className="border rounded-lg overflow-hidden">
        <div className="grid grid-cols-[1fr_auto] bg-muted px-3 py-2 text-xs font-semibold text-muted-foreground">
          <div>Nama Siswa</div>
          <div className="w-[140px] text-center">Status</div>
        </div>
        <div className="max-h-[200px] overflow-y-auto divide-y divide-border">
          {students.map((s, idx) => (
            <div key={s.id} className="grid grid-cols-[1fr_auto] items-center px-3 py-1.5 hover:bg-muted/30">
              <div className="text-sm truncate">
                <span className="text-muted-foreground mr-1.5 text-xs">{idx + 1}.</span>
                {s.nama}
              </div>
              <div className="w-[140px] flex gap-1 justify-center">
                {(['H', 'I', 'S', 'A'] as const).map(st => (
                  <button
                    key={st}
                    type="button"
                    onClick={() => onUpdate(s.id, st)}
                    className={`w-8 h-7 rounded text-xs font-bold transition-all ${
                      s.status === st ? statusColors[st] : 'bg-muted/50 text-muted-foreground hover:bg-muted'
                    }`}
                  >
                    {st}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

src/components/mapel/SortableMapelList.t.content:
import { useMemo } from 'react';
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable,
  arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Pencil, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { GetMataPelajaranOutputType } from 'zite-endpoints-sdk';

type MapelRecord = GetMataPelajaranOutputType['records'][0];

const KELOMPOK_COLORS: Record<string, string> = {
  'Mata Pelajaran Wajib': 'bg-primary/10 text-primary',
  'Mata Pelajaran Pilihan': 'bg-accent text-accent-foreground',
  'Muatan Lokal': 'bg-muted text-muted-foreground',
};

interface Props {
  records: MapelRecord[];
  onReorder: (newOrder: MapelRecord[]) => void;
  onToggleAktif: (id: string, aktif: boolean) => void;
  onEdit: (r: MapelRecord) => void;
  onDelete: (id: string) => void;
  isDraggable: boolean;
}

export default function SortableMapelList({ records, onReorder, onToggleAktif, onEdit, onDelete, isDraggable }: Props) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  const ids = useMemo(() => records.map(r => r.id), [records]);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const oldIndex = records.findIndex(r => r.id === active.id);
    const newIndex = records.findIndex(r => r.id === over.id);
    if (oldIndex === -1 || newIndex === -1) return;
    onReorder(arrayMove(records, oldIndex, newIndex));
  };

  const tableContent = (
    <div className="rounded-lg border border-border overflow-hidden">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-muted/40 border-b border-border">
            {isDraggable && <th className="w-10 px-2 py-3" />}
            <th className="w-14 text-center px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">No</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Nama Mapel</th>
            <th className="w-28 text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Kode</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Kelompok</th>
            <th className="text-center w-28 px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Status</th>
            <th className="text-center w-24 px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Aksi</th>
          </tr>
        </thead>
        {isDraggable ? (
          <SortableContext items={ids} strategy={verticalListSortingStrategy}>
            <tbody>
              {records.map((r, i) => (
                <SortableRow key={r.id} record={r} index={i} onToggleAktif={onToggleAktif} onEdit={onEdit} onDelete={onDelete} isDraggable />
              ))}
            </tbody>
          </SortableContext>
        ) : (
          <tbody>
            {records.map((r, i) => (
              <SortableRow key={r.id} record={r} index={i} onToggleAktif={onToggleAktif} onEdit={onEdit} onDelete={onDelete} isDraggable={false} />
            ))}
          </tbody>
        )}
      </table>
    </div>
  );

  if (isDraggable) {
    return (
      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        {tableContent}
      </DndContext>
    );
  }

  return tableContent;
}

function SortableRow({
  record: r,
  index: i,
  onToggleAktif,
  onEdit,
  onDelete,
  isDraggable,
}: {
  record: MapelRecord;
  index: number;
  onToggleAktif: (id: string, aktif: boolean) => void;
  onEdit: (r: MapelRecord) => void;
  onDelete: (id: string) => void;
  isDraggable: boolean;
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: r.id,
    disabled: !isDraggable,
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  const isAktif = r.aktif !== false;

  return (
    <tr ref={setNodeRef} style={style} className="group border-b border-border last:border-0 hover:bg-muted/30 transition-colors">
      {isDraggable && (
        <td className="w-10 px-2">
          <button {...attributes} {...listeners} className="cursor-grab active:cursor-grabbing p-1 text-muted-foreground hover:text-foreground">
            <GripVertical className="h-4 w-4" />
          </button>
        </td>
      )}
      <td className="text-center text-muted-foreground text-sm px-4 py-2.5">{i + 1}</td>
      <td className="font-medium px-4 py-2.5">{r.namaMapel}</td>
      <td className="text-muted-foreground px-4 py-2.5">{r.kodeMapel || '-'}</td>
      <td className="px-4 py-2.5">
        {r.kelompok ? (
          <span className={`inline-block px-2.5 py-0.5 rounded-full text-xs font-medium ${KELOMPOK_COLORS[r.kelompok] ?? 'bg-muted text-muted-foreground'}`}>
            {r.kelompok}
          </span>
        ) : '-'}
      </td>
      <td className="text-center px-4 py-2.5">
        <button
          onClick={() => onToggleAktif(r.id, !isAktif)}
          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 cursor-pointer select-none ${
            isAktif
              ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400'
              : 'bg-muted text-muted-foreground hover:bg-muted/80'
          }`}
        >
          <span className={`h-2 w-2 rounded-full ${isAktif ? 'bg-emerald-500' : 'bg-muted-foreground/50'}`} />
          {isAktif ? 'Aktif' : 'Tidak Aktif'}
        </button>
      </td>
      <td className="px-4 py-2.5">
        <div className="flex items-center justify-center gap-1">
          <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(r)}>
            <Pencil className="h-3.5 w-3.5 text-muted-foreground" />
          </Button>
          <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onDelete(r.id)}>
            <Trash2 className="h-3.5 w-3.5 text-destructive" />
          </Button>
        </div>
      </td>
    </tr>
  );
}

