import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import CascadingAddressFields from './CascadingAddressFields';
import SearchableSelect from './SearchableSelect';

interface AlamatFormData {
  statusKepemilikanRumah?: string;
  provinsi?: string;
  kabupatenKota?: string;
  kecamatan?: string;
  kelurahanDesa?: string;
  rt?: string;
  rw?: string;
  alamatLengkap?: string;
  kodePos?: string;
}

interface AlamatFormSectionProps {
  title: string;
  data: AlamatFormData;
  onChange: (data: AlamatFormData) => void;
  showCheckbox?: boolean;
  checkboxLabel?: string;
  checkboxValue?: boolean;
  onCheckboxChange?: (checked: boolean) => void;
  disabled?: boolean;
}

const PROVINSI_LIST = [
  'Aceh', 'Sumatera Utara', 'Sumatera Barat', 'Riau', 'Jambi', 'Sumatera Selatan',
  'Bengkulu', 'Lampung', 'Kepulauan Bangka Belitung', 'Kepulauan Riau',
  'DKI Jakarta', 'Jawa Barat', 'Jawa Tengah', 'DI Yogyakarta', 'Jawa Timur', 'Banten',
  'Bali', 'Nusa Tenggara Barat', 'Nusa Tenggara Timur',
  'Kalimantan Barat', 'Kalimantan Tengah', 'Kalimantan Selatan', 'Kalimantan Timur', 'Kalimantan Utara',
  'Sulawesi Utara', 'Sulawesi Tengah', 'Sulawesi Selatan', 'Sulawesi Tenggara', 'Gorontalo', 'Sulawesi Barat',
  'Maluku', 'Maluku Utara', 'Papua', 'Papua Barat', 'Papua Tengah', 'Papua Pegunungan', 'Papua Selatan', 'Papua Barat Daya'
];
const PROVINSI_OPTIONS = PROVINSI_LIST.map((p) => ({ id: p, name: p }));

export default function AlamatFormSection({
  title,
  data,
  onChange,
  showCheckbox,
  checkboxLabel,
  checkboxValue,
  onCheckboxChange,
  disabled
}: AlamatFormSectionProps) {
  const updateField = (field: keyof AlamatFormData, value: string) => {
    onChange({ ...data, [field]: value });
  };

  return (
    <div className="border rounded-lg p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-lg">{title}</h3>
        {showCheckbox && checkboxLabel && onCheckboxChange && (
          <div className="flex items-center space-x-2">
            <Checkbox
              id={`checkbox-${title}`}
              checked={checkboxValue}
              onCheckedChange={onCheckboxChange}
            />
            <Label htmlFor={`checkbox-${title}`} className="cursor-pointer">
              {checkboxLabel}
            </Label>
          </div>
        )}
      </div>

      {!disabled && (
        <>
          {/* Row 1: Kepemilikan Rumah | Provinsi */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Status Kepemilikan Rumah</Label>
              <Select value={data.statusKepemilikanRumah} onValueChange={(v) => updateField('statusKepemilikanRumah', v)}>
                <SelectTrigger><SelectValue placeholder="Pilih" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="Milik Sendiri">Milik Sendiri</SelectItem>
                  <SelectItem value="Rumah Orang Tua">Rumah Orang Tua</SelectItem>
                  <SelectItem value="Rumah Saudara/Kerabat">Rumah Saudara/Kerabat</SelectItem>
                  <SelectItem value="Rumah Dinas">Rumah Dinas</SelectItem>
                  <SelectItem value="Sewa/Kontrak">Sewa/Kontrak</SelectItem>
                  <SelectItem value="Lainnya">Lainnya</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Provinsi</Label>
              <SearchableSelect
                options={PROVINSI_OPTIONS}
                value={data.provinsi || ''}
                onChange={(v) => onChange({ ...data, provinsi: v, kabupatenKota: '', kecamatan: '', kelurahanDesa: '' })}
                placeholder="Pilih Provinsi"
              />
            </div>
          </div>

          {/* Row 2+3: Kabupaten/Kecamatan/Kelurahan via CascadingAddressFields */}
          <CascadingAddressFields
            provinsi={data.provinsi || ''}
            kabupaten={data.kabupatenKota || ''}
            kecamatan={data.kecamatan || ''}
            kelurahan={data.kelurahanDesa || ''}
            onKabupatenChange={(kab, kec, kel) => onChange({ ...data, kabupatenKota: kab, kecamatan: kec, kelurahanDesa: kel })}
            onKecamatanChange={(kec, kel) => onChange({ ...data, kecamatan: kec, kelurahanDesa: kel })}
            onKelurahanChange={(v) => onChange({ ...data, kelurahanDesa: v })}
          />

          {/* Row: RT | RW | Kode Pos */}
          <div className="grid grid-cols-3 gap-3">
            <div className="space-y-2">
              <Label>RT</Label>
              <Input
                maxLength={3}
                value={data.rt || ''}
                onChange={(e) => updateField('rt', e.target.value.replace(/\D/g, ''))}
                placeholder="000"
                className="font-mono text-center tracking-widest"
              />
            </div>
            <div className="space-y-2">
              <Label>RW</Label>
              <Input
                maxLength={3}
                value={data.rw || ''}
                onChange={(e) => updateField('rw', e.target.value.replace(/\D/g, ''))}
                placeholder="000"
                className="font-mono text-center tracking-widest"
              />
            </div>
            <div className="space-y-2">
              <Label>Kode Pos</Label>
              <Input
                maxLength={5}
                value={data.kodePos || ''}
                onChange={(e) => updateField('kodePos', e.target.value.replace(/\D/g, ''))}
                placeholder="00000"
                className="font-mono text-center tracking-widest"
              />
            </div>
          </div>

          {/* Row: Alamat Lengkap */}
          <div className="space-y-2">
            <Label>Alamat Lengkap</Label>
            <Textarea
              rows={3}
              value={data.alamatLengkap || ''}
              onChange={(e) => updateField('alamatLengkap', e.target.value)}
              placeholder="Masukkan alamat lengkap (nama jalan, nomor rumah, dll)"
            />
          </div>
        </>
      )}

      {disabled && (
        <div className="bg-muted p-4 rounded-lg">
          <p className="text-sm text-muted-foreground">
            {checkboxLabel}
          </p>
        </div>
      )}
    </div>
  );
}

