import { useState, useEffect, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { getKelas, GetKelasOutputType, importSiswa } from 'zite-endpoints-sdk';
import {
  GraduationCap, AlignJustify, Building2, FileSpreadsheet,
  Monitor, LayoutGrid, ArrowRight, Download, Upload,
  Loader2, ChevronRight, CheckCircle2, Zap, ClipboardList
} from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { generateExcelTemplate, ExcelColumn } from '@/lib/generateExcelTemplate';

const QUICK_COLUMNS: (ExcelColumn & { key: string; required: boolean })[] = [
  { key: 'namaLengkap', label: 'Nama Lengkap', required: true, example: 'Ahmad Fauzi', width: 180 },
  { key: 'usernameSiswa', label: 'Username', required: true, example: 'ahmad.fauzi', width: 140 },
  { key: 'passwordSiswa', label: 'Password', required: true, example: 'password123', width: 140 },
];

const REGULAR_COLUMNS: (ExcelColumn & { key: string; required: boolean })[] = [
  { key: 'namaLengkap', label: 'Nama Lengkap', required: true, example: 'Ahmad Fauzi', width: 180 },
  { key: 'nisn', label: 'NISN', required: false, example: '1234567890', isText: true, width: 130 },
  { key: 'nisLokal', label: 'NIS', required: false, example: '2024001', isText: true, width: 110 },
  { key: 'usernameSiswa', label: 'Username', required: true, example: 'ahmad.fauzi', width: 140 },
  { key: 'passwordSiswa', label: 'Password', required: true, example: 'password123', width: 140 },
  { key: 'tempatLahir', label: 'Tempat Lahir', required: false, example: 'Jakarta', width: 140 },
  { key: 'tanggalLahir', label: 'Tanggal Lahir', required: false, example: '2010-01-15', width: 140 },
  { key: 'namaAyah', label: 'Nama Ayah', required: false, example: 'Budi Santoso', width: 160 },
  { key: 'namaIbu', label: 'Nama Ibu', required: false, example: 'Siti Rahayu', width: 160 },
];

type ColumnDef = typeof QUICK_COLUMNS[0];

function parseCSV(text: string): Record<string, string>[] {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim().split('\n');
  if (lines.length < 2) return [];

  const parseRow = (line: string): string[] => {
    const cells: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
        else inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        cells.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    cells.push(current.trim());
    return cells;
  };

  const headers = parseRow(lines[0]);
  return lines.slice(1)
    .map(line => {
      const cells = parseRow(line);
      const obj: Record<string, string> = {};
      headers.forEach((h, i) => { obj[h] = cells[i] || ''; });
      return obj;
    })
    .filter(row => Object.values(row).some(v => v !== ''));
}

function mapRowToFields(row: Record<string, string>, columns: ColumnDef[]): Record<string, string> {
  const result: Record<string, string> = {};
  columns.forEach(col => {
    const value = row[col.label];
    if (value !== undefined) result[col.key] = value;
  });
  return result;
}

const STEPS = [
  { num: 1, label: '1. Jenis Import', Icon: AlignJustify },
  { num: 2, label: '2. Pilih Kelas', Icon: Building2 },
  { num: 3, label: '3. Download Sample', Icon: FileSpreadsheet },
  { num: 4, label: '4. Upload Data Siswa', Icon: Monitor },
  { num: 5, label: '5. Preview & Import', Icon: LayoutGrid },
];

function StepIndicator({ currentStep }: { currentStep: number }) {
  return (
    <div className="flex items-start justify-center gap-1 py-4 border-b overflow-x-auto">
      {STEPS.map((step, idx) => (
        <div key={step.num} className="flex items-center gap-1">
          <div className={cn(
            'flex flex-col items-center gap-1 min-w-[80px]',
            currentStep >= step.num ? 'text-primary' : 'text-muted-foreground'
          )}>
            <step.Icon className={cn(
              'h-7 w-7',
              currentStep >= step.num ? 'text-primary' : 'text-muted-foreground/50'
            )} />
            <span className="text-[10px] font-medium text-center leading-tight">{step.label}</span>
          </div>
          {idx < STEPS.length - 1 && (
            <ArrowRight className={cn(
              'h-4 w-4 mb-4 flex-shrink-0',
              currentStep > step.num ? 'text-primary' : 'text-muted-foreground/40'
            )} />
          )}
        </div>
      ))}
    </div>
  );
}

interface ImportSiswaWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export default function ImportSiswaWizard({ open, onOpenChange, onSuccess }: ImportSiswaWizardProps) {
  const [step, setStep] = useState(1);
  const [importType, setImportType] = useState<'quick' | 'regular'>('regular');
  const [kelasList, setKelasList] = useState<GetKelasOutputType>([]);
  const [selectedKelas, setSelectedKelas] = useState('');
  const [parsedRows, setParsedRows] = useState<Record<string, string>[]>([]);
  const [importing, setImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      setStep(1);
      setImportType('regular');
      setSelectedKelas('');
      setParsedRows([]);
      getKelas({}).then(setKelasList).catch(console.error);
    }
  }, [open]);

  const columns = importType === 'quick' ? QUICK_COLUMNS : REGULAR_COLUMNS;

  const handleDownloadSample = () => {
    generateExcelTemplate(`template_import_siswa_${importType}.xls`, columns);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const rawRows = parseCSV(text);
      const mapped = rawRows.map(row => mapRowToFields(row, columns));
      setParsedRows(mapped);
      if (mapped.length > 0) toast.success(`${mapped.length} baris data berhasil dibaca`);
      else toast.error('Tidak ada data yang dapat dibaca dari file');
    };
    reader.readAsText(file, 'UTF-8');
    e.target.value = '';
  };

  const handleImport = async () => {
    setImporting(true);
    try {
      const result = await importSiswa({
        kelasId: selectedKelas,
        rows: parsedRows.map(row => ({ namaLengkap: row.namaLengkap || '', ...row })),
      });
      toast.success(`${result.imported} data siswa berhasil diimport`);
      if (result.errors.length > 0) toast.warning(`${result.errors.length} baris gagal diimport`);
      onSuccess();
      onOpenChange(false);
    } catch {
      toast.error('Gagal mengimport data siswa');
    } finally {
      setImporting(false);
    }
  };

  const canNext = () => {
    if (step === 2) return !!selectedKelas;
    if (step === 4) return parsedRows.length > 0;
    return true;
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto p-0">
        <DialogHeader className="px-6 pt-6 pb-0">
          <DialogTitle className="flex items-center gap-2 text-primary">
            <GraduationCap className="h-5 w-5" />
            Daftar Import Data Siswa
          </DialogTitle>
        </DialogHeader>

        <StepIndicator currentStep={step} />

        <div className="px-6 py-6 min-h-[320px]">
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="text-center text-lg font-semibold">Pilih Jenis Import</h3>
              <div className="grid grid-cols-2 gap-4">
                {(['quick', 'regular'] as const).map(type => (
                  <div
                    key={type}
                    className={cn(
                      'border-2 rounded-lg p-6 cursor-pointer transition-all',
                      importType === type ? 'border-primary bg-primary/5' : 'border-border'
                    )}
                    onClick={() => setImportType(type)}
                  >
                    <div className="flex items-center gap-3 mb-3">
                      <div className={cn(
                        'w-5 h-5 rounded-full border-2 flex items-center justify-center flex-shrink-0',
                        importType === type ? 'border-primary' : 'border-muted-foreground'
                      )}>
                        {importType === type && <div className="w-3 h-3 rounded-full bg-primary" />}
                      </div>
                      <span className="font-semibold">{type === 'quick' ? 'Quick Import' : 'Regular Import'}</span>
                      {type === 'quick'
                        ? <Zap className="h-5 w-5 ml-auto text-yellow-500" />
                        : <ClipboardList className="h-5 w-5 ml-auto text-blue-500" />
                      }
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {type === 'quick'
                        ? 'Quick Import adalah format import dengan kebutuhan data-data dasar saja, jadi lebih cepat dan efisien'
                        : 'Regular Import adalah format import yang membutuhkan data lengkap, dibutuhkan waktu lebih lama'}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4 max-w-md mx-auto">
              <h3 className="text-center text-lg font-semibold">Pilih Kelas</h3>
              <p className="text-center text-sm text-muted-foreground">
                Pilih kelas yang akan diterapkan untuk semua siswa yang diimport
              </p>
              <div className="space-y-2">
                <Label>Kelas *</Label>
                <Select value={selectedKelas} onValueChange={setSelectedKelas}>
                  <SelectTrigger><SelectValue placeholder="Pilih Kelas" /></SelectTrigger>
                  <SelectContent>
                    {kelasList.map(k => (
                      <SelectItem key={k.id} value={k.id}>{k.namaKelas}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Download Sample File</h3>
              <p className="text-sm text-muted-foreground">
                Download file template CSV untuk <strong>{importType === 'quick' ? 'Quick Import' : 'Regular Import'}</strong>.
                Isi data siswa sesuai format yang tersedia, lalu simpan sebagai .csv.
              </p>
              <div className="border rounded-lg p-8 space-y-4">
                <FileSpreadsheet className="h-16 w-16 text-green-600 mx-auto" />
                <p className="font-medium">template_import_siswa_{importType}.xls</p>
                <p className="text-xs text-muted-foreground">{columns.length} kolom · {columns.filter(c => c.required).length} wajib diisi</p>
                <Button onClick={handleDownloadSample} className="gap-2 w-full">
                  <Download className="h-4 w-4" />
                  Download Template Excel
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                * File CSV dapat dibuka dan diedit menggunakan Microsoft Excel atau Google Sheets
              </p>
            </div>
          )}

          {step === 4 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Upload Data Siswa</h3>
              <p className="text-sm text-muted-foreground">Upload file CSV yang sudah diisi dengan data siswa</p>
              <div
                className="border-2 border-dashed rounded-lg p-10 cursor-pointer hover:border-primary/50 transition-colors"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="font-medium">Klik untuk upload file CSV</p>
                <p className="text-xs text-muted-foreground mt-1">Format: .csv (simpan template Excel sebagai CSV sebelum upload)</p>
                <input ref={fileInputRef} type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </div>
              {parsedRows.length > 0 && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4 flex items-center gap-3">
                  <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  <p className="text-sm text-green-700 font-medium">{parsedRows.length} baris data berhasil dibaca</p>
                </div>
              )}
            </div>
          )}

          {step === 5 && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-semibold">Preview Data ({parsedRows.length} siswa)</h3>
                <span className="text-sm text-muted-foreground">
                  Kelas: {kelasList.find(k => k.id === selectedKelas)?.namaKelas || '-'}
                </span>
              </div>
              <ScrollArea className="h-64 border rounded-lg">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-8">No</TableHead>
                      <TableHead>Nama Lengkap</TableHead>
                      <TableHead>NISN</TableHead>
                      <TableHead>NIS</TableHead>
                      <TableHead>Username</TableHead>
                      <TableHead>Jenis Kelamin</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {parsedRows.map((row, idx) => (
                      <TableRow key={idx}>
                        <TableCell>{idx + 1}</TableCell>
                        <TableCell className="font-medium">{row.namaLengkap || '-'}</TableCell>
                        <TableCell>{row.nisn || '-'}</TableCell>
                        <TableCell>{row.nisLokal || '-'}</TableCell>
                        <TableCell>{row.usernameSiswa || '-'}</TableCell>
                        <TableCell>{row.jenisKelamin || '-'}</TableCell>
                        <TableCell>{row.status || 'Aktif'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollArea>
            </div>
          )}
        </div>

        <div className="flex justify-between px-6 pb-6 pt-4 border-t">
          <Button variant="outline" onClick={() => step > 1 ? setStep(s => s - 1) : onOpenChange(false)}>
            {step > 1 ? 'Kembali' : 'Batal'}
          </Button>
          {step < 5 ? (
            <Button onClick={() => setStep(s => s + 1)} disabled={!canNext()} className="gap-2">
              Selanjutnya
              <ChevronRight className="h-4 w-4" />
            </Button>
          ) : (
            <Button onClick={handleImport} disabled={importing || parsedRows.length === 0} className="gap-2">
              {importing ? <><Loader2 className="h-4 w-4 animate-spin" />Mengimport...</> : <><Upload className="h-4 w-4" />Import {parsedRows.length} Siswa</>}
            </Button>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

src/components/siswa/SiswaDetailDialog.t.content:
import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Printer, User } from 'lucide-react';

interface SiswaDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  siswa: any | null;
}

function fmt(date?: string) {
  if (!date) return '-';
  try { return new Date(date).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }); }
  catch { return date; }
}

function DataRow({ label, value }: { label: string; value?: any }) {
  return (
    <div className="flex gap-2 py-1.5 border-b border-border/40 last:border-0 text-sm">
      <span className="w-40 flex-shrink-0 text-muted-foreground text-xs leading-5">{label}</span>
      <span className="flex-1 font-medium text-xs leading-5">{value ?? '-'}</span>
    </div>
  );
}

function SectionBlock({ title, color, children }: { title: string; color: string; children: React.ReactNode }) {
  return (
    <div className="rounded-xl overflow-hidden border border-border">
      <div className={`px-4 py-2 ${color}`}>
        <h4 className="text-xs font-bold uppercase tracking-wider">{title}</h4>
      </div>
      <div className="p-3">{children}</div>
    </div>
  );
}

function buildPrintHtml(siswa: any, fotoUrl?: string) {
  const row = (label: string, val: any) => `<div class="row"><span class="rl">${label}</span><span class="rv">${val || '-'}</span></div>`;
  const sec = (title: string, cls: string, rows: string) =>
    `<div class="sec"><div class="sh ${cls}">${title}</div><div class="sb">${rows}</div></div>`;

  return `<!DOCTYPE html><html><head><meta charset="utf-8"/>
  <title>Buku Induk - ${siswa.namaLengkap || ''}</title>
  <style>
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Segoe UI',Arial,sans-serif;background:#fff;color:#1a1a1a;padding:20px;font-size:11px}
    .hero{display:flex;gap:16px;align-items:center;padding:16px;background:linear-gradient(135deg,#10b981,#059669);color:white;border-radius:12px;margin-bottom:16px}
    .photo{width:72px;height:90px;border-radius:8px;border:2px solid rgba(255,255,255,0.5);overflow:hidden;background:rgba(255,255,255,0.2);display:flex;align-items:center;justify-content:center;flex-shrink:0}
    .photo img{width:100%;height:100%;object-fit:cover}
    .hi h2{font-size:17px;font-weight:700}
    .hi p{font-size:11px;opacity:.85;margin-top:3px}
    .badges{display:flex;gap:6px;margin-top:6px;flex-wrap:wrap}
    .badge{padding:2px 8px;border-radius:20px;font-size:10px;font-weight:600}
    .b-green{background:#dcfce7;color:#166534}
    .b-blue{background:#dbeafe;color:#1e40af}
    .b-gray{background:#f1f5f9;color:#475569}
    .grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}
    .sec{border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;margin-bottom:12px}
    .sh{padding:6px 12px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em}
    .s-green{background:#dcfce7;color:#065f46}
    .s-blue{background:#dbeafe;color:#1e40af}
    .s-purple{background:#ede9fe;color:#5b21b6}
    .s-orange{background:#ffedd5;color:#9a3412}
    .s-rose{background:#ffe4e6;color:#9f1239}
    .s-cyan{background:#cffafe;color:#164e63}
    .sb{padding:6px 12px}
    .row{display:flex;gap:6px;padding:3px 0;border-bottom:1px solid #f8fafc;font-size:10.5px}
    .row:last-child{border-bottom:none}
    .rl{width:140px;flex-shrink:0;color:#64748b}
    .rv{font-weight:500;flex:1}
    @media print{body{padding:10px}}
  </style></head><body>
  <div class="hero">
    <div class="photo">${fotoUrl ? `<img src="${fotoUrl}"/>` : '<span style="font-size:28px;color:rgba(255,255,255,.7)">👤</span>'}</div>
    <div class="hi">
      <h2>${siswa.namaLengkap || '-'}</h2>
      <p>NISN: ${siswa.nisn || '-'} &nbsp;|&nbsp; ${siswa.kelasNama || '-'}</p>
      <div class="badges">
        ${siswa.status === 'Aktif' ? `<span class="badge b-green">${siswa.status}</span>` : `<span class="badge b-gray">${siswa.status || '-'}</span>`}
        ${siswa.jenisKelamin ? `<span class="badge b-blue">${siswa.jenisKelamin}</span>` : ''}
        ${siswa.agama ? `<span class="badge b-gray">${siswa.agama}</span>` : ''}
      </div>
    </div>
  </div>
  <div class="grid2">
    <div>
      ${sec('A. Data Pribadi Siswa', 's-green', [
        row('NISN', siswa.nisn), row('NIS Lokal', siswa.nisLokal), row('NIK', siswa.nik),
        row('Kewarganegaraan', siswa.kewarganegaraan), row('Tempat Lahir', siswa.tempatLahir),
        row('Tanggal Lahir', fmt(siswa.tanggalLahir)), row('Agama', siswa.agama),
        row('Cita-cita', siswa.citacita), row('Hobi', siswa.hobi),
        row('Jumlah Saudara', siswa.jumlahSaudara), row('Anak Ke', siswa.anakKe),
        row('No HP/WA', siswa.noHpWhatsapp), row('Email', siswa.emailSiswa),
        row('Yang Membiayai', siswa.pembiayaanSekolah), row('Alamat', siswa.alamat),
        row('Sekolah Asal', siswa.sekolahAsal), row('Diterima Tanggal', fmt(siswa.diterimaPadaTanggal)),
      ].join(''))}
      ${sec('B. Wali', 's-cyan', [
        row('Status Wali', siswa.statusWali), row('Nama Wali', siswa.namaWali),
        row('NIK', siswa.nikWali), row('Tempat, Tgl Lahir', [siswa.tempatLahirWali, fmt(siswa.tanggalLahirWali)].filter(v => v && v !== '-').join(', ')),
        row('Pendidikan', siswa.pendidikanWali), row('Pekerjaan', siswa.pekerjaanWali),
        row('Penghasilan', siswa.penghasilanWali), row('No HP', siswa.noHpWali),
      ].join(''))}
      ${sec('C. Tempat Tinggal', 's-orange', [
        row('Status Tinggal', siswa.statusTempatTinggalSiswa),
        row('Jarak ke Sekolah', siswa.jarakTempatTinggalKeSekolah),
        row('Transportasi', siswa.transportasiKeSekolah),
        row('Waktu Tempuh', siswa.waktuTempuhKeSekolah),
      ].join(''))}
    </div>
    <div>
      ${sec('D. Ayah Kandung', 's-blue', [
        row('Nama Ayah', siswa.namaAyah), row('Status', siswa.statusAyah),
        row('NIK', siswa.nikAyah), row('Kewarganegaraan', siswa.kewarganegaraanAyah),
        row('Tempat, Tgl Lahir', [siswa.tempatLahirAyah, fmt(siswa.tanggalLahirAyah)].filter(v => v && v !== '-').join(', ')),
        row('Pendidikan', siswa.pendidikanAyah), row('Pekerjaan', siswa.pekerjaanAyah),
        row('Penghasilan', siswa.penghasilanAyah), row('No HP', siswa.noHpAyah),
        row('Alamat', siswa.alamatLengkapAyah),
      ].join(''))}
      ${sec('E. Ibu Kandung', 's-rose', [
        row('Nama Ibu', siswa.namaIbu), row('Status', siswa.statusIbu),
        row('NIK', siswa.nikIbu), row('Kewarganegaraan', siswa.kewarganegaraanIbu),
        row('Tempat, Tgl Lahir', [siswa.tempatLahirIbu, fmt(siswa.tanggalLahirIbu)].filter(v => v && v !== '-').join(', ')),
        row('Pendidikan', siswa.pendidikanIbu), row('Pekerjaan', siswa.pekerjaanIbu),
        row('Penghasilan', siswa.penghasilanIbu), row('No HP', siswa.noHpIbu),
        row('Alamat', siswa.alamatLengkapIbu),
      ].join(''))}
      ${sec('F. Kartu Keluarga', 's-purple', [
        row('No Kartu Keluarga', siswa.noKartuKeluargaSiswa),
        row('Nama Kepala Keluarga', siswa.namaKepalaKeluargaSiswa),
      ].join(''))}
    </div>
  </div>
  </body></html>`;
}

export default function SiswaDetailDialog({ open, onOpenChange, siswa }: SiswaDetailDialogProps) {
  const printRef = useRef<HTMLDivElement>(null);
  if (!siswa) return null;

  const fotoUrl = siswa.foto?.[0]?.url;

  const handlePrint = () => {
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(buildPrintHtml(siswa, fotoUrl));
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-center justify-between pr-6">
            <DialogTitle>Detail Siswa</DialogTitle>
            <Button variant="outline" size="sm" onClick={handlePrint} className="gap-2">
              <Printer className="h-4 w-4" />Cetak PDF
            </Button>
          </div>
        </DialogHeader>

        <div ref={printRef} className="space-y-4 pb-2">
          {/* Hero */}
          <div className="flex items-center gap-5 p-5 rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-600 text-white">
            <div className="w-20 h-24 rounded-xl border-2 border-white/40 overflow-hidden bg-white/20 flex items-center justify-center flex-shrink-0 shadow-lg">
              {fotoUrl ? <img src={fotoUrl} alt={siswa.namaLengkap} className="w-full h-full object-cover" /> : <User className="w-10 h-10 text-white/60" />}
            </div>
            <div>
              <h3 className="text-xl font-bold">{siswa.namaLengkap || '-'}</h3>
              <p className="text-emerald-100 text-sm mt-0.5">NISN: {siswa.nisn || '-'} &nbsp;·&nbsp; {siswa.kelasNama || '-'}</p>
              <div className="flex gap-2 mt-2 flex-wrap">
                <Badge className={`text-xs ${siswa.status === 'Aktif' ? 'bg-green-100 text-green-800' : 'bg-slate-100 text-slate-700'}`}>{siswa.status || '-'}</Badge>
                {siswa.jenisKelamin && <Badge className="text-xs bg-blue-100 text-blue-800">{siswa.jenisKelamin}</Badge>}
                {siswa.agama && <Badge className="text-xs bg-white/20 text-white">{siswa.agama}</Badge>}
              </div>
            </div>
          </div>

          {/* Two column layout */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-4">
              <SectionBlock title="A. Data Pribadi Siswa" color="bg-emerald-50 text-emerald-800">
                <DataRow label="NISN" value={siswa.nisn} />
                <DataRow label="NIS Lokal" value={siswa.nisLokal} />
                <DataRow label="NIK" value={siswa.nik} />
                <DataRow label="Kewarganegaraan" value={siswa.kewarganegaraan} />
                <DataRow label="Tempat Lahir" value={siswa.tempatLahir} />
                <DataRow label="Tanggal Lahir" value={fmt(siswa.tanggalLahir)} />
                <DataRow label="Agama" value={siswa.agama} />
                <DataRow label="Cita-cita" value={siswa.citacita} />
                <DataRow label="Hobi" value={siswa.hobi} />
                <DataRow label="No HP/WA" value={siswa.noHpWhatsapp} />
                <DataRow label="Email" value={siswa.emailSiswa} />
                <DataRow label="Yang Membiayai" value={siswa.pembiayaanSekolah} />
                <DataRow label="Sekolah Asal" value={siswa.sekolahAsal} />
                <DataRow label="Diterima Tanggal" value={fmt(siswa.diterimaPadaTanggal)} />
              </SectionBlock>

              <SectionBlock title="B. Data Wali" color="bg-cyan-50 text-cyan-800">
                <DataRow label="Status Wali" value={siswa.statusWali} />
                <DataRow label="Nama Wali" value={siswa.namaWali} />
                <DataRow label="Pendidikan" value={siswa.pendidikanWali} />
                <DataRow label="Pekerjaan" value={siswa.pekerjaanWali} />
                <DataRow label="No HP" value={siswa.noHpWali} />
              </SectionBlock>

              <SectionBlock title="C. Tempat Tinggal Siswa" color="bg-orange-50 text-orange-800">
                <DataRow label="Status Tinggal" value={siswa.statusTempatTinggalSiswa} />
                <DataRow label="Jarak ke Sekolah" value={siswa.jarakTempatTinggalKeSekolah} />
                <DataRow label="Transportasi" value={siswa.transportasiKeSekolah} />
                <DataRow label="Waktu Tempuh" value={siswa.waktuTempuhKeSekolah} />
              </SectionBlock>
            </div>

            <div className="space-y-4">
              <SectionBlock title="D. Ayah Kandung" color="bg-blue-50 text-blue-800">
                <DataRow label="Nama Ayah" value={siswa.namaAyah} />
                <DataRow label="Status" value={siswa.statusAyah} />
                <DataRow label="NIK" value={siswa.nikAyah} />
                <DataRow label="Kewarganegaraan" value={siswa.kewarganegaraanAyah} />
                <DataRow label="Tempat Lahir" value={siswa.tempatLahirAyah} />
                <DataRow label="Tanggal Lahir" value={fmt(siswa.tanggalLahirAyah)} />
                <DataRow label="Pendidikan" value={siswa.pendidikanAyah} />
                <DataRow label="Pekerjaan" value={siswa.pekerjaanAyah} />
                <DataRow label="Penghasilan" value={siswa.penghasilanAyah} />
                <DataRow label="No HP" value={siswa.noHpAyah} />
                <DataRow label="Alamat" value={siswa.alamatLengkapAyah} />
              </SectionBlock>

              <SectionBlock title="E. Ibu Kandung" color="bg-rose-50 text-rose-800">
                <DataRow label="Nama Ibu" value={siswa.namaIbu} />
                <DataRow label="Status" value={siswa.statusIbu} />
                <DataRow label="NIK" value={siswa.nikIbu} />
                <DataRow label="Kewarganegaraan" value={siswa.kewarganegaraanIbu} />
                <DataRow label="Tempat Lahir" value={siswa.tempatLahirIbu} />
                <DataRow label="Tanggal Lahir" value={fmt(siswa.tanggalLahirIbu)} />
                <DataRow label="Pendidikan" value={siswa.pendidikanIbu} />
                <DataRow label="Pekerjaan" value={siswa.pekerjaanIbu} />
                <DataRow label="Penghasilan" value={siswa.penghasilanIbu} />
                <DataRow label="No HP" value={siswa.noHpIbu} />
                <DataRow label="Alamat" value={siswa.alamatLengkapIbu} />
              </SectionBlock>

              <SectionBlock title="F. Kartu Keluarga" color="bg-purple-50 text-purple-800">
                <DataRow label="No Kartu Keluarga" value={siswa.noKartuKeluargaSiswa} />
                <DataRow label="Nama Kepala Keluarga" value={siswa.namaKepalaKeluargaSiswa} />
              </SectionBlock>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

