import { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from 'zite-auth-sdk';
import { Toaster } from '@/components/ui/sonner';
import MainLayout from './components/layout/MainLayout';
import Dashboard from './pages/Dashboard';
import ProfilLembagaPage from './pages/lembaga/ProfilLembagaPage';
import TahunAjaranPage from './pages/lembaga/TahunAjaranPage';
import KurikulumPage from './pages/lembaga/KurikulumPage';
import SiswaPage from './pages/manajemen/SiswaPage';
import GuruPage from './pages/manajemen/GuruPage';
import KelasPage from './pages/manajemen/KelasPage';
import AkademikPage from './pages/akademik/AkademikPage';
import AbsensiPage from './pages/absensi/AbsensiPage';
import NilaiPage from './pages/nilai/NilaiPage';
import TagihanPage from './pages/keuangan/TagihanPage';
import EkstrakurikulerPage from './pages/kesiswaan/EkstrakurikulerPage';
import PrestasiPage from './pages/kesiswaan/PrestasiPage';
import PengumumanPage from './pages/konten/PengumumanPage';
import SaranaPage from './pages/sarana/SaranaPage';
import JurnalMengajarPage from './pages/lms/JurnalMengajarPage';
import TugasPage from './pages/lms/TugasPage';
import BukuNilaiPage from './pages/evaluasi/BukuNilaiPage';
import { Loader2 } from 'lucide-react';

export default function App() {
  const { user, isLoading, loginWithRedirect } = useAuth();

  useEffect(() => {
    if (!isLoading && !user) {
      loginWithRedirect({ redirectUrl: window.location.href });
    }
  }, [isLoading, user, loginWithRedirect]);

  if (isLoading || !user) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-background">
        <div className="text-center space-y-4">
          <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto" />
          <p className="text-muted-foreground">Memuat aplikasi...</p>
        </div>
      </div>
    );
  }

  return (
    <Router>
      <MainLayout>
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/lembaga" element={<ProfilLembagaPage />} />
          <Route path="/lembaga/profil" element={<Navigate to="/lembaga" replace />} />
          <Route path="/lembaga/tahun-ajaran" element={<TahunAjaranPage />} />
          <Route path="/lembaga/kurikulum" element={<KurikulumPage />} />
          <Route path="/manajemen/siswa" element={<SiswaPage />} />
          <Route path="/manajemen/guru" element={<GuruPage />} />
          <Route path="/manajemen/kelas" element={<KelasPage />} />
          {/* Akademik */}
          <Route path="/akademik" element={<AkademikPage />} />
          <Route path="/akademik/mata-pelajaran" element={<Navigate to="/akademik" replace />} />
          <Route path="/akademik/jadwal" element={<Navigate to="/akademik" replace />} />
          <Route path="/manajemen/mata-pelajaran" element={<Navigate to="/akademik" replace />} />
          {/* Sarana & Prasarana */}
          <Route path="/sarana" element={<SaranaPage />} />
          <Route path="/sarana/ruang-kelas" element={<Navigate to="/sarana" replace />} />
          {/* LMS */}
          <Route path="/lms" element={<Navigate to="/lms/jurnal" replace />} />
          <Route path="/lms/jurnal" element={<JurnalMengajarPage />} />
          <Route path="/lms/tugas" element={<TugasPage />} />
          {/* Evaluasi Pembelajaran */}
          <Route path="/evaluasi" element={<Navigate to="/evaluasi/buku-nilai" replace />} />
          <Route path="/evaluasi/buku-nilai" element={<BukuNilaiPage />} />
          {/* Existing */}
          <Route path="/absensi" element={<AbsensiPage />} />
          <Route path="/nilai" element={<NilaiPage />} />
          <Route path="/keuangan/tagihan" element={<TagihanPage />} />
          <Route path="/kesiswaan/ekstrakurikuler" element={<EkstrakurikulerPage />} />
          <Route path="/kesiswaan/prestasi" element={<PrestasiPage />} />
          <Route path="/konten/pengumuman" element={<PengumumanPage />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </MainLayout>
      <Toaster position="top-right" />
    </Router>
  );
}

