import { z } from 'zod';
import { createEndpoint, Guru, Sekolah } from 'zite-integrations-backend-sdk';

const guruSchema = z.object({
  id: z.string(),
  nipnuptk: z.string().optional(),
  nik: z.string().optional(),
  namaLengkap: z.string().optional(),
  jenisKelamin: z.string().optional(),
  tempatLahir: z.string().optional(),
  tanggalLahir: z.string().optional(),
  noHp: z.string().optional(),
  email: z.string().optional(),
  pendidikanTerakhir: z.string().optional(),
  usernameGuru: z.string().optional(),
  passwordGuru: z.string().optional(),
  statusKepegawaian: z.string().optional(),
  kategoriPegawai: z.string().optional(),
  tugasUtama: z.string().optional(),
  tugasTambahan: z.array(z.string()).optional(),
  jp: z.number().optional(),
  mulaiBertugas: z.string().optional(),
  akhirBertugas: z.string().optional(),
  active: z.boolean().optional(),
  foto: z.array(z.object({ url: z.string() })).optional(),
  alamat: z.string().optional(),
});

export default createEndpoint({
  description: 'Get list of guru/tendik',
  inputSchema: z.object({
    search: z.string().optional(),
    kategori: z.string().optional(),
    sekolahId: z.string().optional(),
  }),
  outputSchema: z.object({
    guru: z.array(guruSchema),
  }),
  execute: async ({ input }) => {
    const filters: Record<string, unknown> = {};
    if (input.sekolahId) filters.sekolah = input.sekolahId;

    const { records } = await Guru.findAll({ filters, limit: 500 });

    let guru = records.map((r) => ({
      id: r.id,
      nipnuptk: r.nipnuptk,
      nik: r.nik,
      namaLengkap: r.namaLengkap,
      jenisKelamin: r.jenisKelamin,
      tempatLahir: r.tempatLahir,
      tanggalLahir: r.tanggalLahir,
      noHp: r.noHp,
      email: r.email,
      pendidikanTerakhir: r.pendidikanTerakhir,
      usernameGuru: r.usernameGuru,
      passwordGuru: r.passwordGuru,
      statusKepegawaian: r.statusKepegawaian,
      kategoriPegawai: r.kategoriPegawai,
      tugasUtama: r.tugasUtama,
      tugasTambahan: Array.isArray(r.tugasTambahan) ? r.tugasTambahan : [],
      jp: (r as any).jp,
      mulaiBertugas: r.mulaiBertugas,
      akhirBertugas: r.akhirBertugas,
      active: r.active,
      foto: r.foto,
      alamat: r.alamat,
    }));

    if (input.search) {
      const q = input.search.toLowerCase();
      guru = guru.filter(
        (g) =>
          g.namaLengkap?.toLowerCase().includes(q) ||
          g.nipnuptk?.toLowerCase().includes(q) ||
          g.usernameGuru?.toLowerCase().includes(q)
      );
    }

    if (input.kategori) {
      guru = guru.filter((g) => g.kategoriPegawai === input.kategori);
    }

    return { guru };
  },
});

