import { z } from 'zod';
import { createEndpoint, Kelas } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Mengambil daftar kelas',
  inputSchema: z.object({
    sekolahId: z.string().optional(),
  }),
  outputSchema: z.array(z.object({
    id: z.string(),
    namaKelas: z.string().optional(),
  })),
  execute: async ({ input }) => {
    const result = await Kelas.findAll({
      limit: 500,
    });

    const records = result.records.filter((k) => {
      if (!input.sekolahId) return true;
      const sekolah = k.sekolah;
      if (!sekolah) return false;
      if (Array.isArray(sekolah)) return sekolah.includes(input.sekolahId);
      return sekolah === input.sekolahId;
    });

    return records.map((k) => ({
      id: k.id,
      namaKelas: k.namaKelas,
    }));
  },
});

import { z } from 'zod';
import { createEndpoint, Siswa, Kelas } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Mengambil daftar siswa dengan filter',
  inputSchema: z.object({
    search: z.string().optional(),
    status: z.string().optional(),
    kelas: z.string().optional(),
  }),
  outputSchema: z.array(z.object({
    id: z.string(),
    nisn: z.string().optional(),
    nisLokal: z.string().optional(),
    namaLengkap: z.string().optional(),
    usernameSiswa: z.string().optional(),
    passwordSiswa: z.string().optional(),
    jenisKelamin: z.string().optional(),
    tanggalLahir: z.string().optional(),
    tempatLahir: z.string().optional(),
    status: z.string().optional(),
    kelas: z.union([z.array(z.string()), z.string()]).optional(),
    kelasNama: z.string().optional(),
    sekolah: z.union([z.array(z.string()), z.string()]).optional(),
    foto: z.array(z.object({ url: z.string() })).optional(),
    sekolahAsal: z.string().optional(),
    diterimaPadaTanggal: z.string().optional(),
    nik: z.string().optional(),
    kewarganegaraan: z.string().optional(),
    agama: z.string().optional(),
    citacita: z.string().optional(),
    hobi: z.string().optional(),
    noHpWhatsapp: z.string().optional(),
    emailSiswa: z.string().optional(),
    pembiayaanSekolah: z.string().optional(),
    alamat: z.string().optional(),
    jumlahSaudara: z.number().optional(),
    anakKe: z.number().optional(),
    noKartuKeluargaSiswa: z.string().optional(),
    namaKepalaKeluargaSiswa: z.string().optional(),
    namaAyah: z.string().optional(),
    statusAyah: z.string().optional(),
    kewarganegaraanAyah: z.string().optional(),
    nikAyah: z.string().optional(),
    tempatLahirAyah: z.string().optional(),
    tanggalLahirAyah: z.string().optional(),
    pendidikanAyah: z.string().optional(),
    pekerjaanAyah: z.string().optional(),
    penghasilanAyah: z.string().optional(),
    noHpAyah: z.string().optional(),
    alamatLengkapAyah: z.string().optional(),
    namaIbu: z.string().optional(),
    statusIbu: z.string().optional(),
    kewarganegaraanIbu: z.string().optional(),
    nikIbu: z.string().optional(),
    tempatLahirIbu: z.string().optional(),
    tanggalLahirIbu: z.string().optional(),
    pendidikanIbu: z.string().optional(),
    pekerjaanIbu: z.string().optional(),
    penghasilanIbu: z.string().optional(),
    noHpIbu: z.string().optional(),
    alamatLengkapIbu: z.string().optional(),
    statusWali: z.string().optional(),
    namaWali: z.string().optional(),
    kewarganegaraanWali: z.string().optional(),
    nikWali: z.string().optional(),
    tempatLahirWali: z.string().optional(),
    tanggalLahirWali: z.string().optional(),
    pendidikanWali: z.string().optional(),
    pekerjaanWali: z.string().optional(),
    penghasilanWali: z.string().optional(),
    noHpWali: z.string().optional(),
    statusTempatTinggalSiswa: z.string().optional(),
    jarakTempatTinggalKeSekolah: z.string().optional(),
    transportasiKeSekolah: z.string().optional(),
    waktuTempuhKeSekolah: z.string().optional(),
    statusKepemilikanRumahAyah: z.string().optional(),
    provinsiAyah: z.string().optional(),
    kabupatenKotaAyah: z.string().optional(),
    kecamatanAyah: z.string().optional(),
    kelurahanDesaAyah: z.string().optional(),
    rtAyah: z.string().optional(),
    rwAyah: z.string().optional(),
    kodePosAyah: z.string().optional(),
    alamatIbuSamaDenganAyah: z.boolean().optional(),
    statusKepemilikanRumahIbu: z.string().optional(),
    provinsiIbu: z.string().optional(),
    kabupatenKotaIbu: z.string().optional(),
    kecamatanIbu: z.string().optional(),
    kelurahanDesaIbu: z.string().optional(),
    rtIbu: z.string().optional(),
    rwIbu: z.string().optional(),
    kodePosIbu: z.string().optional(),
    statusAlamatWali: z.string().optional(),
    statusKepemilikanRumahWali: z.string().optional(),
    provinsiWali: z.string().optional(),
    kabupatenKotaWali: z.string().optional(),
    kecamatanWali: z.string().optional(),
    kelurahanDesaWali: z.string().optional(),
    rtWali: z.string().optional(),
    rwWali: z.string().optional(),
    alamatLengkapWali: z.string().optional(),
    kodePosWali: z.string().optional(),
  })),
  execute: async ({ input, context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah) 
      ? context.user.sekolah[0] 
      : context.user.sekolah;

    const filters: any = userSekolahId ? { sekolah: userSekolahId } : {};

    if (input.status) {
      if (input.status === 'Aktif tanpa kelas') {
        filters.status = 'Aktif';
      } else if (input.status === 'Belum Teridentifikasi') {
        filters.status = { in: ['', null] };
      } else {
        filters.status = input.status;
      }
    }

    if (input.kelas) {
      filters.kelas = input.kelas;
    }

    if (input.search) {
      filters.namaLengkap = { contains: input.search };
    }

    const result = await Siswa.findAll({ 
      filters,
      limit: 500 
    });

    let records = result.records;

    if (input.status === 'Aktif tanpa kelas') {
      records = records.filter(s => !s.kelas || (Array.isArray(s.kelas) && s.kelas.length === 0));
    }

    if (input.search && /\d/.test(input.search)) {
      const searchTerm = input.search;
      const searchLower = searchTerm.toLowerCase();
      records = records.filter(s => 
        s.namaLengkap?.toLowerCase().includes(searchLower) ||
        s.nisn?.includes(searchTerm) ||
        s.nisLokal?.includes(searchTerm)
      );
    }

    const kelasIds = records
      .map(s => Array.isArray(s.kelas) ? s.kelas[0] : s.kelas)
      .filter(Boolean) as string[];

    const kelasMap: Record<string, string> = {};
    if (kelasIds.length > 0) {
      const kelasResult = await Kelas.findAll({
        filters: { id: { in: kelasIds } },
        limit: 500
      });
      kelasResult.records.forEach(k => {
        kelasMap[k.id] = k.namaKelas || '';
      });
    }

    return records.map(s => ({
      ...s,
      kelasNama: kelasMap[Array.isArray(s.kelas) ? s.kelas[0] : s.kelas || ''] || '-',
    }));
  },
});

import { z } from 'zod';
import { createEndpoint, Tugas, Guru, Kelas, MataPelajaran } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get tugas list with filters',
  authenticated: true,
  inputSchema: z.object({
    guruId: z.string().optional(),
    kelasId: z.string().optional(),
    status: z.string().optional(),
    search: z.string().optional(),
    offset: z.number().optional(),
    limit: z.number().optional(),
  }),
  outputSchema: z.object({
    tugas: z.array(z.object({
      id: z.string(),
      judulTugas: z.string(),
      deskripsi: z.string(),
      jenisTugas: z.string(),
      guruId: z.string(),
      guruNama: z.string(),
      kelasId: z.string(),
      kelasNama: z.string(),
      mapelId: z.string(),
      mapelNama: z.string(),
      jurnalId: z.string().optional(),
      tanggalDiberikan: z.string(),
      deadline: z.string(),
      status: z.string(),
      catatan: z.string(),
      dibuatPada: z.string(),
    })),
    hasMore: z.boolean(),
    total: z.number(),
  }),
  execute: async ({ input }) => {
    const filters: Record<string, any> = {};
    if (input.guruId) filters.guru = input.guruId;
    if (input.kelasId) filters.kelas = input.kelasId;
    if (input.status) filters.status = input.status;
    if (input.search) filters.judulTugas = { contains: input.search };

    const [tugasRes, guruRes, kelasRes, mapelRes] = await Promise.all([
      Tugas.findAll({ filters, offset: input.offset || 0, limit: input.limit || 50 }),
      Guru.findAll({ filters: {}, fields: ['id', 'namaLengkap'], limit: 500 }),
      Kelas.findAll({ filters: {}, fields: ['id', 'namaKelas'], limit: 500 }),
      MataPelajaran.findAll({ filters: {}, fields: ['id', 'namaMapel'], limit: 500 }),
    ]);

    const guruMap = new Map(guruRes.records.map(g => [g.id, g.namaLengkap || '']));
    const kelasMap = new Map(kelasRes.records.map(k => [k.id, k.namaKelas || '']));
    const mapelMap = new Map(mapelRes.records.map(m => [m.id, m.namaMapel || '']));

    const getId = (v?: string[] | string) => Array.isArray(v) ? v[0] || '' : v || '';

    const tugas = tugasRes.records.map(t => ({
      id: t.id,
      judulTugas: t.judulTugas || '',
      deskripsi: t.deskripsi || '',
      jenisTugas: t.jenisTugas || '',
      guruId: getId(t.guru),
      guruNama: guruMap.get(getId(t.guru)) || '',
      kelasId: getId(t.kelas),
      kelasNama: kelasMap.get(getId(t.kelas)) || '',
      mapelId: getId(t.mataPelajaran),
      mapelNama: mapelMap.get(getId(t.mataPelajaran)) || '',
      jurnalId: getId(t.jurnalMengajar) || undefined,
      tanggalDiberikan: t.tanggalDiberikan || '',
      deadline: t.deadline || '',
      status: t.status || 'Aktif',
      catatan: t.catatan || '',
      dibuatPada: t.dibuatPada || '',
    }));

    // Sort by deadline descending
    tugas.sort((a, b) => (b.deadline || '').localeCompare(a.deadline || ''));

    return { tugas, hasMore: tugasRes.hasMore, total: tugas.length };
  },
});

