export default createEndpoint({
  description: 'Save or update a jurnal mengajar entry, optionally create a tugas',
  authenticated: true,
  inputSchema: z.object({
    jurnalId: z.string().optional(),
    tanggal: z.string(),
    guruId: z.string(),
    kelasId: z.string(),
    mapelId: z.string(),
    jadwalId: z.string(),
    jamMulai: z.string(),
    jamSelesai: z.string(),
    tujuanPembelajaran: z.string(),
    materiKonten: z.string(),
    kegiatanPembelajaran: z.string().optional(),
    catatan: z.string().optional(),
    statusKehadiran: z.string(),
    detailKehadiran: z.string().optional(),
    // Penugasan fields
    penugasan: z.object({
      judulTugas: z.string(),
      deskripsi: z.string().optional(),
      jenisTugas: z.string(),
      deadline: z.string(),
      catatan: z.string().optional(),
    }).optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    id: z.string(),
    tugasId: z.string().optional(),
  }),
  execute: async ({ input }) => {
    const record = {
      judulJurnal: `Jurnal ${input.tanggal}`,
      tanggal: input.tanggal,
      guru: input.guruId,
      kelas: input.kelasId,
      mataPelajaran: input.mapelId,
      jadwalPelajaran: input.jadwalId,
      jamMulai: input.jamMulai,
      jamSelesai: input.jamSelesai,
      tujuanPembelajaran: input.tujuanPembelajaran,
      materiKonten: input.materiKonten,
      kegiatanPembelajaran: input.kegiatanPembelajaran || '',
      catatan: input.catatan || '',
      statusKehadiran: input.statusKehadiran as any,
      detailKehadiran: input.detailKehadiran || '',
      status: 'Sudah Diisi' as const,
    };

    let jurnalId: string;
    if (input.jurnalId) {
      await JurnalMengajar.update({ id: input.jurnalId, record });
      jurnalId = input.jurnalId;
    } else {
      const created = await JurnalMengajar.create({ record });
      jurnalId = created.id;
    }

    // Create tugas if penugasan is provided
    let tugasId: string | undefined;
    if (input.penugasan) {
      const tugas = await Tugas.create({
        record: {
          judulTugas: input.penugasan.judulTugas,
          deskripsi: input.penugasan.deskripsi || '',
          jenisTugas: input.penugasan.jenisTugas as any,
          guru: input.guruId,
          kelas: input.kelasId,
          mataPelajaran: input.mapelId,
          jurnalMengajar: jurnalId,
          tanggalDiberikan: input.tanggal,
          deadline: input.penugasan.deadline,
          catatan: input.penugasan.catatan || '',
          status: 'Aktif' as const,
        },
      });
      tugasId = tugas.id;
    }

    return { success: true, id: jurnalId, tugasId };
  },
});

