// ─── Guru-Mapel Code System ───
// Each guru gets a number (1, 2, 3...). If they teach multiple mapels,
// the codes are "1", "1a", "1b" for guru 1's 1st, 2nd, 3rd mapel, etc.

interface CodeEntry {
  code: string;
  guruNama: string;
  mapelNama: string;
}

function buildGuruMapelCodes(allData: KelasJadwalData[]): { codeMap: Record<string, string>; legend: CodeEntry[] } {
  // Collect unique guru → mapel pairs
  const guruMapelSet = new Map<string, Set<string>>();
  for (const kd of allData) {
    for (const j of kd.jadwal) {
      if (!j.guruNama || j.guruNama === '-') continue;
      if (!guruMapelSet.has(j.guruNama)) guruMapelSet.set(j.guruNama, new Set());
      guruMapelSet.get(j.guruNama)!.add(j.mapelNama);
    }
  }

  // Sort gurus alphabetically for consistent numbering
  const guruNames = Array.from(guruMapelSet.keys()).sort((a, b) => a.localeCompare(b));

  const codeMap: Record<string, string> = {}; // "guruNama|||mapelNama" → code
  const legend: CodeEntry[] = [];
  const suffix = 'abcdefghijklmnopqrstuvwxyz';

  guruNames.forEach((guru, idx) => {
    const guruNum = idx + 1;
    const mapels = Array.from(guruMapelSet.get(guru)!).sort();
    if (mapels.length === 1) {
      const code = `${guruNum}`;
      codeMap[`${guru}|||${mapels[0]}`] = code;
      legend.push({ code, guruNama: guru, mapelNama: mapels[0] });
    } else {
      mapels.forEach((mapel, mi) => {
        const code = mi === 0 ? `${guruNum}` : `${guruNum}${suffix[mi - 1] || mi}`;
        codeMap[`${guru}|||${mapel}`] = code;
        legend.push({ code, guruNama: guru, mapelNama: mapel });
      });
    }
  });

  return { codeMap, legend };
}

function getCode(codeMap: Record<string, string>, guruNama: string, mapelNama: string): string {
  return codeMap[`${guruNama}|||${mapelNama}`] || '?';
}

/**
 * Flat lookup: maps "hari-jpNumber" → { mapelNama, guruNama }.
 */
function buildFlatLookup(
  jadwal: { hari: string; jamMulai: string; jamSelesai: string; mapelNama: string; guruNama: string }[],
  jpSlots: JpSlot[],
): Record<string, EntryLike> {
  const lookup: Record<string, EntryLike> = {};
  for (const j of jadwal) {
    const startIdx = jpSlots.findIndex(s => s.mulai === j.jamMulai);
    const endIdx = jpSlots.findIndex(s => s.selesai === j.jamSelesai);
    if (startIdx >= 0 && endIdx >= 0) {
      for (let i = startIdx; i <= endIdx; i++) {
        lookup[`${j.hari}-${jpSlots[i].jp}`] = { mapelNama: j.mapelNama, guruNama: j.guruNama };
      }
    }
  }
  return lookup;
}

