  }

  let rows = '';
  for (const slot of settings.slots) {
    if (isSpecialSlot(slot)) {
      const st = getSlotType(slot);
      if (st === 'jp') continue;
      const config = SPECIAL_SLOT_CONFIG[st];
      const label = slot.label || config.label;
      rows += `<tr><td style="background:#fef3c7;font-weight:bold;">${slot.mulai}–${slot.selesai}</td><td style="background:#fef3c7;">${config.icon}</td><td colspan="${totalDataCols}" style="background:#fef3c7;text-align:center;font-weight:bold;">${esc(label)}</td></tr>`;
      continue;
    }
    rows += `<tr><td>${slot.mulai}–${slot.selesai}</td><td style="font-weight:bold;text-align:center;">JP ${slot.jp}</td>`;
    for (const d of days) {
      for (let ki = 0; ki < nk; ki++) {
        const e = lookups[ki][`${d}-${slot.jp}`];
        if (e) {
          const code = getCode(codeMap, e.guruNama, e.mapelNama);
          rows += `<td style="text-align:center;font-weight:bold;font-size:11pt;">${esc(code)}</td>`;
        } else {
          rows += `<td style="text-align:center;color:#ccc;">–</td>`;
        }
      }
    }
    rows += `</tr>`;
  }

  const html = `${xlHead}<table>
${excelHeader(cols, sekolah, tahunAjaran, semester)}
<tr>${hdr1}</tr><tr>${hdr2}</tr>
${rows}
${excelLegendRows(legend, cols)}
${excelSignatures(cols, sekolah?.kepalaSekolah)}
</table></body></html>`;

  downloadBlob(html, 'Jadwal_Pelajaran_Semua_Kelas.xls');
}

// ─── Helpers ───

function openPrint(html: string) {
  const w = window.open('', '_blank');
  if (w) { w.document.write(html); w.document.close(); setTimeout(() => w.print(), 500); }
}

function downloadBlob(html: string, filename: string) {
  const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

