import { z } from 'zod';
import { createEndpoint, Kelas, Guru, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Mengambil daftar ruang kelas dengan jumlah siswa dan nama wali kelas',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    kelas: z.array(z.object({
      id: z.string(),
      namaKelas: z.string(),
      tingkat: z.string(),
      tingkatNum: z.number(),
      waliKelasId: z.string().optional(),
      waliKelasNama: z.string().optional(),
      jumlahSiswa: z.number(),
    })),
  }),
  execute: async () => {
    const kelasResult = await Kelas.findAll({ limit: 500 });

    // Collect wali kelas IDs
    const waliIds = new Set<string>();
    for (const k of kelasResult.records) {
      const wId = Array.isArray(k.waliKelas) ? k.waliKelas[0] : k.waliKelas;
      if (wId) waliIds.add(wId);
    }

    // Fetch guru names
    const guruMap: Record<string, string> = {};
    if (waliIds.size > 0) {
      const guruResult = await Guru.findAll({
        filters: { id: { in: Array.from(waliIds) } },
        fields: ['id', 'namaLengkap'],
        limit: 500,
      });
      for (const g of guruResult.records) {
        guruMap[g.id] = g.namaLengkap || '-';
      }
    }

    // Count students per kelas
    const siswaResult = await Siswa.findAll({
      fields: ['id', 'kelas'],
      limit: 2000,
    });
    const siswaCountMap: Record<string, number> = {};
    for (const s of siswaResult.records) {
      const kelasId = Array.isArray(s.kelas) ? s.kelas[0] : s.kelas;
      if (kelasId) {
        siswaCountMap[kelasId] = (siswaCountMap[kelasId] || 0) + 1;
      }
    }

    const tingkatToNum = (t: string): number => {
      const match = t.match(/(\d+)/);
      return match ? parseInt(match[1], 10) : 0;
    };

    const kelas = kelasResult.records.map(k => {
      const wId = Array.isArray(k.waliKelas) ? k.waliKelas[0] : k.waliKelas;
      return {
        id: k.id,
        namaKelas: k.namaKelas || '',
        tingkat: k.tingkat || '',
        tingkatNum: tingkatToNum(k.tingkat || ''),
        waliKelasId: wId || undefined,
        waliKelasNama: wId ? guruMap[wId] : undefined,
        jumlahSiswa: siswaCountMap[k.id] || 0,
      };
    });

    // Sort by tingkat ASC then namaKelas ASC
    kelas.sort((a, b) => {
      if (a.tingkatNum !== b.tingkatNum) return a.tingkatNum - b.tingkatNum;
      return a.namaKelas.localeCompare(b.namaKelas);
    });

    return { kelas };
  },
});

import { z } from 'zod';
import { createEndpoint, Guru, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Reset username and password for guru/tendik',
  inputSchema: z.object({
    id: z.string(),
    usernameGuru: z.string(),
    passwordGuru: z.string(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // Check username uniqueness (exclude self)
    const { records: existing } = await Guru.findAll({
      filters: { usernameGuru: input.usernameGuru },
    });
    const conflict = existing.find((r) => r.id !== input.id);
    if (conflict) {
      throw new ZiteError({ code: 'CONFLICT', message: 'Username sudah digunakan' });
    }

    await Guru.update({
      id: input.id,
      record: {
        usernameGuru: input.usernameGuru,
        passwordGuru: input.passwordGuru,
      },
    });
    return { success: true };
  },
});

