import { createEndpoint, JadwalPelajaran } from 'zite-integrations-backend-sdk';

const constraintSchema = z.object({
  guruId: z.string(),
  hari: z.string(),
  jpList: z.array(z.number()), // JP numbers where guru is unavailable
});

const mapelAssignmentSchema = z.object({
  mapelId: z.string(),
  mapelNama: z.string(),
  guruId: z.string(),
  guruNama: z.string(),
  jpPerWeek: z.number().min(1).max(20),
});

export default createEndpoint({
  description: 'Auto-generate jadwal pelajaran for a kelas using constraint-based scheduling',
  authenticated: true,
  inputSchema: z.object({
    kelasId: z.string(),
    assignments: z.array(mapelAssignmentSchema),
    constraints: z.array(constraintSchema).optional(),
    hariAktif: z.array(z.string()),
    jpPerDay: z.number(),
    clearExisting: z.boolean().optional(),
    // Slot info for time mapping
    slots: z.array(z.object({
      jp: z.number(),
      mulai: z.string(),
      selesai: z.string(),
      isSpecial: z.boolean(),
    })),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    generated: z.number(),
    conflicts: z.array(z.string()),
    message: z.string(),
  }),
  execute: async ({ input }) => {
    const { kelasId, assignments, constraints = [], hariAktif, jpPerDay, slots } = input;

    // Build JP slots (non-special only)
    const jpSlots = slots.filter(s => !s.isSpecial);

    // Build constraint map: guruId -> Set of "hari-jp"
    const blocked = new Map<string, Set<string>>();
    for (const c of constraints) {
      if (!blocked.has(c.guruId)) blocked.set(c.guruId, new Set());
      const set = blocked.get(c.guruId)!;
      for (const jp of c.jpList) {
        set.add(`${c.hari}-${jp}`);
      }
    }

    // Fetch existing jadwal for ALL kelas to check cross-class guru conflicts
    const existingRes = await JadwalPelajaran.findAll({ limit: 2000 });
    const existingRecords = existingRes.records;

    // Build global guru occupancy: guruId -> Set of "hari-jp"
    const guruOccupancy = new Map<string, Set<string>>();
    for (const rec of existingRecords) {
      const kid = Array.isArray(rec.kelas) ? rec.kelas[0] : rec.kelas;
      if (kid === kelasId) continue; // Skip same kelas (we'll overwrite)
      const gid = Array.isArray(rec.guru) ? rec.guru[0] : rec.guru;
      if (!gid) continue;
      if (!guruOccupancy.has(gid)) guruOccupancy.set(gid, new Set());
      const set = guruOccupancy.get(gid)!;
      // Map time to JP
      for (const jp of jpSlots) {
        if (rec.jamMulai && rec.jamSelesai) {
          if (rec.jamMulai! <= jp.mulai && rec.jamSelesai! > jp.mulai) {
            set.add(`${rec.hari}-${jp.jp}`);
          }
        }
      }
    }

    // If clearExisting, delete existing jadwal for this kelas
    if (input.clearExisting) {
      const toDelete = existingRecords.filter(r => {
        const kid = Array.isArray(r.kelas) ? r.kelas[0] : r.kelas;
        return kid === kelasId;
      });
      for (const r of toDelete) {
        await JadwalPelajaran.delete({ id: r.id });
      }
    }

    // --- Scheduling Algorithm ---
    // Grid: hariAktif x jpPerDay
    // Each cell: { mapelId, guruId } or null
    type Cell = { mapelId: string; guruId: string; mapelNama: string; guruNama: string } | null;
    const grid: Record<string, Cell[]> = {};
    for (const h of hariAktif) {
      grid[h] = new Array(jpPerDay).fill(null);
    }

    // Track guru usage in our grid for this kelas
    const localGuruUsage = new Map<string, Set<string>>();
    const addLocal = (guruId: string, hari: string, jpNum: number) => {
      if (!localGuruUsage.has(guruId)) localGuruUsage.set(guruId, new Set());
      localGuruUsage.get(guruId)!.add(`${hari}-${jpNum}`);
    };

    const isAvailable = (guruId: string, hari: string, jpNum: number): boolean => {
      const key = `${hari}-${jpNum}`;
      // Check constraint
      if (blocked.get(guruId)?.has(key)) return false;
      // Check cross-class occupancy
      if (guruOccupancy.get(guruId)?.has(key)) return false;
      // Check local occupancy (same kelas, already scheduled)
      if (localGuruUsage.get(guruId)?.has(key)) return false;
      return true;
    };

    // Sort assignments by JP descending (harder to place first)
    const sorted = [...assignments].sort((a, b) => b.jpPerWeek - a.jpPerWeek);

    const conflicts: string[] = [];
    let totalGenerated = 0;

    // For each mapel assignment, try to distribute JPs evenly across days
    for (const asgn of sorted) {
      let remaining = asgn.jpPerWeek;
      const jpsPerDay = Math.ceil(asgn.jpPerWeek / hariAktif.length);

      // Try to place consecutive JPs per day for better scheduling
      // First pass: try to place evenly
      const dayOrder = [...hariAktif];
      // Shuffle slightly to vary results
      for (let i = dayOrder.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [dayOrder[i], dayOrder[j]] = [dayOrder[j], dayOrder[i]];
      }

      for (const hari of dayOrder) {
        if (remaining <= 0) break;
        const toPlace = Math.min(remaining, Math.max(1, jpsPerDay));
        let placed = 0;

        // Find consecutive available slots
        for (let startJp = 0; startJp < jpPerDay && placed < toPlace; startJp++) {
          if (grid[hari][startJp] !== null) continue;
          const jpNum = jpSlots[startJp]?.jp;
          if (!jpNum) continue;
          if (!isAvailable(asgn.guruId, hari, jpNum)) continue;

          // Place this JP
          grid[hari][startJp] = {
            mapelId: asgn.mapelId,
            guruId: asgn.guruId,
            mapelNama: asgn.mapelNama,
            guruNama: asgn.guruNama,
          };
          addLocal(asgn.guruId, hari, jpNum);
          placed++;
          remaining--;
        }
      }

      // Second pass: fill remaining anywhere possible
      if (remaining > 0) {
        for (const hari of hariAktif) {
          for (let idx = 0; idx < jpPerDay && remaining > 0; idx++) {
            if (grid[hari][idx] !== null) continue;
            const jpNum = jpSlots[idx]?.jp;
            if (!jpNum) continue;
            if (!isAvailable(asgn.guruId, hari, jpNum)) continue;

            grid[hari][idx] = {
              mapelId: asgn.mapelId,
              guruId: asgn.guruId,
              mapelNama: asgn.mapelNama,
              guruNama: asgn.guruNama,
            };
            addLocal(asgn.guruId, hari, jpNum);
            remaining--;
          }
        }
      }

      if (remaining > 0) {
        conflicts.push(`${asgn.mapelNama}: ${remaining} JP tidak bisa ditempatkan (konflik guru ${asgn.guruNama})`);
      }
    }

    // --- Save to database ---
    const records: { jadwal: string; kelas: string; hari: string; jamMulai: string; jamSelesai: string; mataPelajaran: string; guru: string }[] = [];

    for (const hari of hariAktif) {
      // Group consecutive same-mapel entries
      let i = 0;
      while (i < jpPerDay) {
        const cell = grid[hari][i];
        if (!cell) { i++; continue; }

        // Find consecutive same mapel+guru
        let end = i;
        while (end + 1 < jpPerDay && grid[hari][end + 1]?.mapelId === cell.mapelId && grid[hari][end + 1]?.guruId === cell.guruId) {
          end++;
        }

        const startSlot = jpSlots[i];
        const endSlot = jpSlots[end];
        if (startSlot && endSlot) {
          records.push({
            jadwal: `${hari} ${startSlot.mulai}-${endSlot.selesai}`,
            kelas: kelasId,
            hari: hari as any,
            jamMulai: startSlot.mulai,
            jamSelesai: endSlot.selesai,
            mataPelajaran: cell.mapelId,
            guru: cell.guruId,
          });
          totalGenerated++;
        }
        i = end + 1;
      }
    }

    // Bulk create in batches of 100
    for (let b = 0; b < records.length; b += 100) {
      const batch = records.slice(b, b + 100);
      await JadwalPelajaran.bulkCreate({ records: batch });
    }

    const msg = conflicts.length > 0
      ? `Berhasil generate ${totalGenerated} jadwal dengan ${conflicts.length} peringatan`
      : `Berhasil generate ${totalGenerated} jadwal tanpa konflik!`;

    return { success: true, generated: totalGenerated, conflicts, message: msg };
  },
});

