import { z } from 'zod';
import { createEndpoint, Kelas, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Hapus ruang kelas dan unassign siswa',
  authenticated: true,
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // Unassign students first
    const siswaResult = await Siswa.findAll({
      filters: { kelas: input.id },
      fields: ['id'],
      limit: 500,
    });
    for (const s of siswaResult.records) {
      await Siswa.update({ id: s.id, record: { kelas: '' } });
    }

    await Kelas.delete({ id: input.id });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, MataPelajaran } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get daftar mata pelajaran dengan pagination dan pencarian, diurutkan berdasarkan urutan',
  inputSchema: z.object({
    search: z.string().optional(),
    page: z.number().optional(),
    pageSize: z.number().optional(),
  }),
  outputSchema: z.object({
    records: z.array(z.object({
      id: z.string(),
      namaMapel: z.string().optional(),
      kodeMapel: z.string().optional(),
      kelompok: z.string().optional(),
      aktif: z.boolean().optional(),
      urutan: z.number().optional(),
    })),
    total: z.number(),
  }),
  execute: async ({ input }) => {
    const page = input.page ?? 1;
    const pageSize = input.pageSize ?? 999;
    const offset = (page - 1) * pageSize;

    const all = await MataPelajaran.findAll({ filters: {}, limit: 2000 });
    let records = all.records;

    if (input.search) {
      const q = input.search.toLowerCase();
      records = records.filter(r =>
        r.namaMapel?.toLowerCase().includes(q) ||
        r.kodeMapel?.toLowerCase().includes(q) ||
        r.kelompok?.toLowerCase().includes(q)
      );
    }

    // Sort by urutan (ascending), then by namaMapel
    records.sort((a, b) => {
      const ua = a.urutan ?? 9999;
      const ub = b.urutan ?? 9999;
      if (ua !== ub) return ua - ub;
      return (a.namaMapel || '').localeCompare(b.namaMapel || '');
    });

    const total = records.length;
    const paged = records.slice(offset, offset + pageSize);

    return {
      records: paged.map(r => ({
        id: r.id,
        namaMapel: r.namaMapel,
        kodeMapel: r.kodeMapel,
        kelompok: r.kelompok,
        aktif: r.aktif,
        urutan: r.urutan,
      })),
      total,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Sekolah, TahunAjaran } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  authenticated: true,
  description: 'Mengambil profil lengkap sekolah beserta tahun ajaran aktif',
  inputSchema: z.object({}),
  outputSchema: z.object({
    sekolah: z.object({
      id: z.string(),
      namaSekolah: z.string().optional(),
      npsn: z.string().optional(),
      jenjang: z.string().optional(),
      alamat: z.string().optional(),
      telepon: z.string().optional(),
      emailSekolah: z.string().optional(),
      kepalaSekolah: z.string().optional(),
      logo: z.array(z.object({ url: z.string() })).optional(),
      penyelenggara: z.string().optional(),
      statusSekolah: z.string().optional(),
      kurikulum: z.string().optional(),
      situsWeb: z.string().optional(),
      akreditasi: z.string().optional(),
    }).nullable(),
    tahunAjaranAktif: z.object({
      namaTahunAjaran: z.string().optional(),
      semester: z.string().optional(),
    }).nullable(),
  }),
  execute: async ({ context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah)
      ? context.user.sekolah[0]
      : context.user.sekolah;

    if (!userSekolahId) return { sekolah: null, tahunAjaranAktif: null };

    const [sekolah, tahunResult] = await Promise.all([
      Sekolah.findOne({ id: userSekolahId }),
      TahunAjaran.findAll({ filters: { sekolah: userSekolahId, active: true }, limit: 1 }),
    ]);

    const ta = tahunResult.records[0];
    const s = sekolah as any;

    return {
      sekolah: sekolah
        ? {
            id: sekolah.id,
            namaSekolah: sekolah.namaSekolah,
            npsn: sekolah.npsn,
            jenjang: sekolah.jenjang,
            alamat: sekolah.alamat,
            telepon: sekolah.telepon,
            emailSekolah: sekolah.emailSekolah,
            kepalaSekolah: sekolah.kepalaSekolah,
            logo: sekolah.logo,
            penyelenggara: s.penyelenggara,
            statusSekolah: s.statusSekolah,
            kurikulum: s.kurikulum,
            situsWeb: s.situsWeb,
            akreditasi: s.akreditasi,
          }
        : null,
      tahunAjaranAktif: ta
        ? { namaTahunAjaran: ta.namaTahunAjaran, semester: ta.semester }
        : null,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Mengambil siswa yang belum punya kelas atau yang sudah di kelas tertentu (untuk edit)',
  authenticated: true,
  inputSchema: z.object({
    kelasId: z.string().optional(),
  }),
  outputSchema: z.object({
    unassigned: z.array(z.object({ id: z.string(), nama: z.string(), nisn: z.string() })),
    assigned: z.array(z.object({ id: z.string(), nama: z.string(), nisn: z.string() })),
  }),
  execute: async ({ input }) => {
    const all = await Siswa.findAll({
      fields: ['id', 'namaLengkap', 'nisn', 'kelas', 'status'],
      limit: 2000,
    });

    const unassigned: { id: string; nama: string; nisn: string }[] = [];
    const assigned: { id: string; nama: string; nisn: string }[] = [];

    for (const s of all.records) {
      if (s.status && s.status !== 'Aktif') continue;
      const kelasId = Array.isArray(s.kelas) ? s.kelas[0] : s.kelas;
      const item = { id: s.id, nama: s.namaLengkap || '-', nisn: s.nisn || '-' };

      if (input.kelasId && kelasId === input.kelasId) {
        assigned.push(item);
      } else if (!kelasId) {
        unassigned.push(item);
      }
    }

    unassigned.sort((a, b) => a.nama.localeCompare(b.nama));
    assigned.sort((a, b) => a.nama.localeCompare(b.nama));

    return { unassigned, assigned };
  },
});

