import { z } from 'zod';
import { createEndpoint, Siswa, Guru, Kelas, AbsensiSiswa, TagihanSpp, JadwalPelajaran, JurnalMengajar } from 'zite-integrations-backend-sdk';

const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

export default createEndpoint({
  authenticated: true,
  description: 'Mengambil statistik untuk dashboard termasuk jurnal mengajar',
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalSiswa: z.number(),
    totalGuru: z.number(),
    totalKelas: z.number(),
    siswaAktif: z.number(),
    absensiHariIni: z.object({
      hadir: z.number(),
      izin: z.number(),
      sakit: z.number(),
      alpha: z.number(),
    }),
    tagihanBelumLunas: z.number(),
    jurnalHariIni: z.object({
      total: z.number(),
      terisi: z.number(),
      belum: z.number(),
    }),
  }),
  execute: async ({ context }) => {
    const userSekolahId = Array.isArray(context.user.sekolah)
      ? context.user.sekolah[0]
      : context.user.sekolah;

    const sekolahFilter = userSekolahId ? { sekolah: userSekolahId } : {};
    const today = new Date().toISOString().split('T')[0];
    const todayDow = new Date(today + 'T00:00:00').getDay();
    const hariName = DAY_NAMES[todayDow];

    const isGuru = context.user.role === 'Guru';

    // Find guru ID for current user
    let guruId: string | undefined;
    const guruRes = await Guru.findAll({ fields: ['id', 'namaLengkap', 'email'], limit: 500, filters: { ...sekolahFilter, active: true } });
    if (isGuru) {
      const g = guruRes.records.find(g => g.email === context.user.email);
      if (g) guruId = g.id;
    }

    const jadwalFilters: Record<string, any> = { hari: hariName };
    if (isGuru && guruId) jadwalFilters.guru = guruId;

    const [siswaResult, kelasResult, absensiResult, tagihanResult, jadwalResult, jurnalResult] = await Promise.all([
      Siswa.findAll({ filters: sekolahFilter, limit: 2000 }),
      Kelas.findAll({ filters: sekolahFilter, limit: 2000 }),
      AbsensiSiswa.findAll({ filters: { tanggal: today }, limit: 2000 }),
      TagihanSpp.findAll({ filters: { statusPembayaran: 'Belum Bayar' }, limit: 2000 }),
      JadwalPelajaran.findAll({ filters: jadwalFilters, limit: 500 }),
      JurnalMengajar.findAll({ filters: { tanggal: today, ...(isGuru && guruId ? { guru: guruId } : {}) }, limit: 500 }),
    ]);

    const totalJadwalToday = jadwalResult.records.length;
    const jurnalByJadwal = new Set<string>();
    for (const j of jurnalResult.records) {
      const jid = Array.isArray(j.jadwalPelajaran) ? j.jadwalPelajaran[0] : j.jadwalPelajaran;
      if (jid) jurnalByJadwal.add(jid);
    }
    const terisi = jadwalResult.records.filter(j => jurnalByJadwal.has(j.id)).length;

    return {
      totalSiswa: siswaResult.records.length,
      totalGuru: guruRes.records.length,
      totalKelas: kelasResult.records.length,
      siswaAktif: siswaResult.records.filter(s => s.status === 'Aktif').length,
      absensiHariIni: {
        hadir: absensiResult.records.filter(a => a.status === 'Hadir').length,
        izin: absensiResult.records.filter(a => a.status === 'Izin').length,
        sakit: absensiResult.records.filter(a => a.status === 'Sakit').length,
        alpha: absensiResult.records.filter(a => a.status === 'Alpha').length,
      },
      tagihanBelumLunas: tagihanResult.records.length,
      jurnalHariIni: {
        total: totalJadwalToday,
        terisi,
        belum: totalJadwalToday - terisi,
      },
    };
  },
});

import { z } from 'zod';
import { createEndpoint, JadwalPelajaran, Kelas, MataPelajaran, Guru } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get jadwal pelajaran for a specific kelas with resolved names',
  authenticated: true,
  inputSchema: z.object({
    kelasId: z.string().optional(),
  }),
  outputSchema: z.object({
    jadwal: z.array(z.object({
      id: z.string(),
      hari: z.string(),
      jamMulai: z.string(),
      jamSelesai: z.string(),
      mapelId: z.string(),
      mapelNama: z.string(),
      mapelKode: z.string().optional(),
      guruId: z.string(),
      guruNama: z.string(),
    })),
    kelasList: z.array(z.object({ id: z.string(), nama: z.string(), tingkat: z.string() })),
    mapelList: z.array(z.object({ id: z.string(), nama: z.string(), kode: z.string().optional() })),
    guruList: z.array(z.object({ id: z.string(), nama: z.string() })),
  }),
  execute: async ({ input }) => {
    // Fetch all reference data in parallel
    const hasKelas = input.kelasId && input.kelasId !== '__init__';
    const [jadwalRes, kelasRes, mapelRes, guruRes] = await Promise.all([
      hasKelas ? JadwalPelajaran.findAll({ filters: { kelas: input.kelasId! }, limit: 500 }) : Promise.resolve({ records: [] as any[] }),
      Kelas.findAll({ fields: ['id', 'namaKelas', 'tingkat'], limit: 500 }),
      MataPelajaran.findAll({ filters: { aktif: true }, fields: ['id', 'namaMapel', 'kodeMapel', 'urutan'], limit: 500 }),
      Guru.findAll({ fields: ['id', 'namaLengkap'], limit: 500 }),
    ]);

    // Build lookup maps
    const mapelMap: Record<string, { nama: string; kode?: string }> = {};
    for (const m of mapelRes.records) {
      mapelMap[m.id] = { nama: m.namaMapel || '', kode: m.kodeMapel };
    }

    const guruMap: Record<string, string> = {};
    for (const g of guruRes.records) {
      guruMap[g.id] = g.namaLengkap || '';
    }

    const jadwal = jadwalRes.records.map(j => {
      const mapelId = Array.isArray(j.mataPelajaran) ? j.mataPelajaran[0] : j.mataPelajaran;
      const guruId = Array.isArray(j.guru) ? j.guru[0] : j.guru;
      const mapel = mapelId ? mapelMap[mapelId] : undefined;
      return {
        id: j.id,
        hari: j.hari || '',
        jamMulai: j.jamMulai || '',
        jamSelesai: j.jamSelesai || '',
        mapelId: mapelId || '',
        mapelNama: mapel?.nama || '-',
        mapelKode: mapel?.kode,
        guruId: guruId || '',
        guruNama: guruId ? (guruMap[guruId] || '-') : '-',
      };
    });

    // Sort by day order then by jamMulai
    const dayOrder: Record<string, number> = { Senin: 1, Selasa: 2, Rabu: 3, Kamis: 4, Jumat: 5, Sabtu: 6 };
    jadwal.sort((a, b) => {
      const da = dayOrder[a.hari] ?? 99;
      const db = dayOrder[b.hari] ?? 99;
      if (da !== db) return da - db;
      return a.jamMulai.localeCompare(b.jamMulai);
    });

    const tingkatOrder = (t: string) => {
      const m = t.match(/(\d+)/);
      return m ? parseInt(m[1], 10) : 99;
    };

    const kelasList = kelasRes.records
      .map(k => ({ id: k.id, nama: k.namaKelas || '', tingkat: k.tingkat || '' }))
      .sort((a, b) => {
        const ta = tingkatOrder(a.tingkat);
        const tb = tingkatOrder(b.tingkat);
        if (ta !== tb) return ta - tb;
        return a.nama.localeCompare(b.nama);
      });

    const mapelList = mapelRes.records
      .map(m => ({ id: m.id, nama: m.namaMapel || '', kode: m.kodeMapel }))
      .sort((a, b) => a.nama.localeCompare(b.nama));

    const guruList = guruRes.records
      .filter(g => g.namaLengkap)
      .map(g => ({ id: g.id, nama: g.namaLengkap! }))
      .sort((a, b) => a.nama.localeCompare(b.nama));

    return { jadwal, kelasList, mapelList, guruList };
  },
});

