export function useIndonesiaRegions(
  provinsi: string,
  kabupaten: string,
  kecamatan: string
) {
  const [kabupatenList, setKabupatenList] = useState<Region[]>([]);
  const [kecamatanList, setKecamatanList] = useState<Region[]>([]);
  const [kelurahanList, setKelurahanList] = useState<Region[]>([]);
  const [loadingKabupaten, setLoadingKabupaten] = useState(false);
  const [loadingKecamatan, setLoadingKecamatan] = useState(false);
  const [loadingKelurahan, setLoadingKelurahan] = useState(false);

  useEffect(() => {
    if (!provinsi) {
      setKabupatenList([]);
      setKecamatanList([]);
      setKelurahanList([]);
      return;
    }
    const id = PROVINCE_ID_MAP[provinsi];
    if (!id) return;
    setLoadingKabupaten(true);
    fetch(`${BASE_URL}/regencies/${id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKabupatenList(data))
      .catch(() => setKabupatenList([]))
      .finally(() => setLoadingKabupaten(false));
  }, [provinsi]);

  useEffect(() => {
    if (!kabupaten || !kabupatenList.length) {
      setKecamatanList([]);
      setKelurahanList([]);
      return;
    }
    const item = kabupatenList.find((k) => k.name === kabupaten);
    if (!item) return;
    setLoadingKecamatan(true);
    fetch(`${BASE_URL}/districts/${item.id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKecamatanList(data))
      .catch(() => setKecamatanList([]))
      .finally(() => setLoadingKecamatan(false));
  }, [kabupaten, kabupatenList]);

  useEffect(() => {
    if (!kecamatan || !kecamatanList.length) {
      setKelurahanList([]);
      return;
    }
    const item = kecamatanList.find((k) => k.name === kecamatan);
    if (!item) return;
    setLoadingKelurahan(true);
    fetch(`${BASE_URL}/villages/${item.id}.json`)
      .then((r) => r.json())
      .then((data: Region[]) => setKelurahanList(data))
      .catch(() => setKelurahanList([]))
      .finally(() => setLoadingKelurahan(false));
  }, [kecamatan, kecamatanList]);

  return {
    kabupatenList,
    kecamatanList,
    kelurahanList,
    loadingKabupaten,
    loadingKecamatan,
    loadingKelurahan,
  };
}

