    for (const m of mapelRes.records) mapelMap[m.id] = { nama: m.namaMapel || '', kode: m.kodeMapel };

    const guruMap: Record<string, string> = {};
    for (const g of guruRes.records) guruMap[g.id] = g.namaLengkap || '';

    const tingkatOrder = (t: string) => { const m = t.match(/(\d+)/); return m ? parseInt(m[1], 10) : 99; };

    const kelasSorted = kelasRes.records
      .map(k => ({ id: k.id, nama: k.namaKelas || '', tingkat: k.tingkat || '' }))
      .sort((a, b) => {
        const ta = tingkatOrder(a.tingkat); const tb = tingkatOrder(b.tingkat);
        if (ta !== tb) return ta - tb;
        return a.nama.localeCompare(b.nama);
      });

    const dayOrder: Record<string, number> = { Senin: 1, Selasa: 2, Rabu: 3, Kamis: 4, Jumat: 5, Sabtu: 6 };

    const kelasJadwal = kelasSorted.map(kelas => {
      const entries = jadwalRes.records
        .filter(j => {
          const kid = Array.isArray(j.kelas) ? j.kelas[0] : j.kelas;
          return kid === kelas.id;
        })
        .map(j => {
          const mid = Array.isArray(j.mataPelajaran) ? j.mataPelajaran[0] : j.mataPelajaran;
          const gid = Array.isArray(j.guru) ? j.guru[0] : j.guru;
          const mapel = mid ? mapelMap[mid] : undefined;
          return {
            id: j.id,
            hari: j.hari || '',
            jamMulai: j.jamMulai || '',
            jamSelesai: j.jamSelesai || '',
            mapelNama: mapel?.nama || '-',
            mapelKode: mapel?.kode,
            guruNama: gid ? (guruMap[gid] || '-') : '-',
          };
        })
        .sort((a, b) => {
          const da = dayOrder[a.hari] ?? 99; const db = dayOrder[b.hari] ?? 99;
          if (da !== db) return da - db;
          return a.jamMulai.localeCompare(b.jamMulai);
        });

      return {
        kelasId: kelas.id,
        kelasNama: `${kelas.tingkat} – ${kelas.nama}`,
        tingkat: kelas.tingkat,
        jadwal: entries,
      };
    }).filter(k => k.jadwal.length > 0);

    return { sekolah: sekolahData, tahunAjaran, semester, kelasJadwal };
  },
});

import { z } from 'zod';
import { createEndpoint, Siswa } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get students for a class (for jurnal attendance)',
  authenticated: true,
  inputSchema: z.object({
    kelasId: z.string(),
  }),
  outputSchema: z.object({
    students: z.array(z.object({
      id: z.string(),
      nama: z.string(),
      nisn: z.string(),
    })),
  }),
  execute: async ({ input }) => {
    const res = await Siswa.findAll({
      filters: { kelas: input.kelasId, status: 'Aktif' },
      fields: ['id', 'namaLengkap', 'nisn'],
      limit: 500,
    });

    const students = res.records
      .map(s => ({ id: s.id, nama: s.namaLengkap || '-', nisn: s.nisn || '-' }))
      .sort((a, b) => a.nama.localeCompare(b.nama));

    return { students };
  },
});

import { useState, useEffect, useCallback } from 'react';
import { Plus, Pencil, Trash2, Loader2, Search, GripVertical, BookOpen } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Skeleton } from '@/components/ui/skeleton';
import { toast } from 'sonner';
import { getMataPelajaran, createMataPelajaran, updateMataPelajaran, deleteMataPelajaran, reorderMapel, toggleMapelAktif } from 'zite-endpoints-sdk';
import type { GetMataPelajaranOutputType } from 'zite-endpoints-sdk';
import MapelFormDialog from '@/components/mapel/MapelFormDialog';
import SortableMapelList from '@/components/mapel/SortableMapelList';

type MapelRecord = GetMataPelajaranOutputType['records'][0];

export default function MapelTab() {
  const [records, setRecords] = useState<MapelRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editData, setEditData] = useState<MapelRecord | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getMataPelajaran({ search });
      setRecords(res.records);
    } catch {
      toast.error('Gagal memuat data');
    } finally {
      setLoading(false);
    }
  }, [search]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSave = async (data: { namaMapel: string; kodeMapel?: string; kelompok?: string; aktif: boolean }) => {
    try {
      if (editData) {
        await updateMataPelajaran({ id: editData.id, ...data });
        toast.success('Mata pelajaran berhasil diperbarui');
      } else {
        await createMataPelajaran(data);
        toast.success('Mata pelajaran berhasil ditambahkan');
      }
      setShowForm(false);
      setEditData(null);
      fetchData();
    } catch {
      toast.error('Gagal menyimpan data');
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      await deleteMataPelajaran({ id: deleteId });
      toast.success('Mata pelajaran berhasil dihapus');
      setDeleteId(null);
      fetchData();
    } catch {
      toast.error('Gagal menghapus data');
    } finally {
      setDeleting(false);
    }
  };

  const handleToggleAktif = async (id: string, aktif: boolean) => {
    // Optimistic update
    setRecords(prev => prev.map(r => r.id === id ? { ...r, aktif } : r));
    try {
      await toggleMapelAktif({ id, aktif });
    } catch {
      setRecords(prev => prev.map(r => r.id === id ? { ...r, aktif: !aktif } : r));
      toast.error('Gagal mengubah status');
    }
  };

  const handleReorder = async (newOrder: MapelRecord[]) => {
    setRecords(newOrder);
    try {
      await reorderMapel({ orderedIds: newOrder.map(r => r.id) });
    } catch {
      toast.error('Gagal menyimpan urutan');
      fetchData();
    }
  };

  return (
    <>
      <Card className="p-5">
        <div className="flex items-center justify-between flex-wrap gap-3 mb-5">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Cari mata pelajaran..."
              className="pl-9"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <Button className="gap-2" onClick={() => { setEditData(null); setShowForm(true); }}>
            <Plus className="h-4 w-4" /> Tambah Mapel
          </Button>
        </div>

        {loading ? (
          <div className="space-y-3">
            {[1,2,3,4].map(i => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
          </div>
        ) : records.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-center">
            <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
              <BookOpen className="h-8 w-8 text-muted-foreground" />
            </div>
            <h3 className="text-lg font-semibold text-foreground mb-1">
              {search ? 'Tidak ditemukan' : 'Belum Ada Mata Pelajaran'}
            </h3>
            <p className="text-sm text-muted-foreground max-w-md">
              {search ? 'Coba ubah kata kunci pencarian.' : 'Tambahkan mata pelajaran baru dengan menekan tombol "Tambah Mapel" di atas.'}
            </p>
          </div>
        ) : (
          <SortableMapelList
            records={records}
            onReorder={handleReorder}
            onToggleAktif={handleToggleAktif}
            onEdit={(r) => { setEditData(r); setShowForm(true); }}
            onDelete={(id) => setDeleteId(id)}
            isDraggable={!search}
          />
        )}
      </Card>

      {showForm && (
        <MapelFormDialog
          data={editData}
          onSave={handleSave}
          onClose={() => { setShowForm(false); setEditData(null); }}
        />
      )}

      <AlertDialog open={!!deleteId} onOpenChange={v => !v && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Mata Pelajaran</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus mata pelajaran ini? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} disabled={deleting} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              {deleting && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

