type SiswaType = GetSiswaOutputType[0];

function StatusPill({ status, onClick }: { status: string; onClick?: () => void }) {
  const isAktif = status === 'Aktif';
  return (
    <button
      type="button"
      onClick={onClick}
      title={onClick ? 'Klik untuk mengubah status' : undefined}
      className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all select-none ${onClick ? 'cursor-pointer hover:opacity-80' : 'cursor-default'} ${isAktif ? 'bg-green-600 text-white' : 'bg-red-500 text-white'}`}
    >
      <span className={`w-2 h-2 rounded-full bg-white opacity-80 ${isAktif ? '' : 'order-last'}`} />
      {status || '-'}
    </button>
  );
}

function getPaginationPages(current: number, total: number): (number | '...')[] {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  const pages: (number | '...')[] = [1];
  if (current > 3) pages.push('...');
  for (let i = Math.max(2, current - 1); i <= Math.min(total - 1, current + 1); i++) pages.push(i);
  if (current < total - 2) pages.push('...');
  pages.push(total);
  return pages;
}

export default function SiswaPage() {
  const [siswa, setSiswa] = useState<SiswaType[]>([]);
  const [kelasList, setKelasList] = useState<GetKelasOutputType>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [kelasFilter, setKelasFilter] = useState('');
  const [pageLimit, setPageLimit] = useState('25');
  const [currentPage, setCurrentPage] = useState(1);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [detailDialogOpen, setDetailDialogOpen] = useState(false);
  const [importWizardOpen, setImportWizardOpen] = useState(false);
  const [editingSiswa, setEditingSiswa] = useState<SiswaType | null>(null);
  const [viewingSiswa, setViewingSiswa] = useState<SiswaType | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [resetSiswa, setResetSiswa] = useState<SiswaType | null>(null);
  const [exportDialogOpen, setExportDialogOpen] = useState(false);

  useEffect(() => {
    loadKelas();
    loadSiswa();
  }, []);

  const loadKelas = async () => {
    try {
      const data = await getKelas({});
      setKelasList(data);
    } catch (error) {
      console.error('Error loading kelas:', error);
    }
  };

  const loadSiswa = async (searchTerm?: string, status?: string, kelas?: string) => {
    try {
      setLoading(true);
      const data = await getSiswa({ search: searchTerm, status, kelas });
      setSiswa(data);
      setCurrentPage(1);
    } catch {
      toast.error('Gagal memuat data siswa');
    } finally {
      setLoading(false);
    }
  };

  const debouncedSearch = useDebouncedCallback((value: string) => {
    loadSiswa(value, statusFilter, kelasFilter);
  }, 500);

  const handleSearch = (value: string) => {
    setSearch(value);
    debouncedSearch(value);
  };

  const handleStatusFilter = (value: string) => {
    const actual = value === '__all__' ? '' : value;
    setStatusFilter(actual);
    loadSiswa(search, actual, kelasFilter);
  };

  const handleKelasFilter = (value: string) => {
    const actual = value === '__all__' ? '' : value;
    setKelasFilter(actual);
    loadSiswa(search, statusFilter, actual);
  };

  const handlePageLimitChange = (value: string) => {
    setPageLimit(value);
    setCurrentPage(1);
  };

  const handleToggleStatus = async (s: SiswaType) => {
    const newStatus = s.status === 'Aktif' ? 'Keluar' : 'Aktif';
    try {
      await updateSiswa({ id: s.id, status: newStatus });
      setSiswa((prev) => prev.map((x) => x.id === s.id ? { ...x, status: newStatus } : x));
    } catch {
      toast.error('Gagal mengubah status');
    }
  };

  const handleCreate = () => { setEditingSiswa(null); setDialogOpen(true); };
  const handleEdit = (s: SiswaType) => { setEditingSiswa(s); setDialogOpen(true); };
  const handleView = (s: SiswaType) => { setViewingSiswa(s); setDetailDialogOpen(true); };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await deleteSiswa({ id: deleteId });
      toast.success('Data siswa berhasil dihapus');
      loadSiswa(search, statusFilter, kelasFilter);
      setDeleteId(null);
    } catch {
      toast.error('Gagal menghapus data siswa');
    }
  };

  const handleSaveSuccess = () => {
    setDialogOpen(false);
    loadSiswa(search, statusFilter, kelasFilter);
  };

  // Pagination logic
  const limit = pageLimit === 'all' ? null : parseInt(pageLimit);
  const totalPages = limit ? Math.ceil(siswa.length / limit) : 1;
  const displayedSiswa = limit
    ? siswa.slice((currentPage - 1) * limit, currentPage * limit)
    : siswa;

  const EXCEL_COLS = [
    { label: 'Nama Lengkap', key: 'namaLengkap', width: 190 },
    { label: 'NISN', key: 'nisn', isText: true, width: 120 },
    { label: 'NIS Lokal', key: 'nisLokal', isText: true, width: 110 },
    { label: 'Kelas', key: 'kelasNama', width: 120 },
    { label: 'Jenis Kelamin', key: 'jenisKelamin', width: 130 },
    { label: 'Tempat Lahir', key: 'tempatLahir', width: 140 },
    { label: 'Tanggal Lahir', key: 'tanggalLahir', width: 130 },
    { label: 'Agama', key: 'agama', width: 110 },
    { label: 'Kewarganegaraan', key: 'kewarganegaraan', width: 140 },
    { label: 'NIK', key: 'nik', isText: true, width: 160 },
    { label: 'No HP/Whatsapp', key: 'noHpWhatsapp', isText: true, width: 150 },
    { label: 'Email Siswa', key: 'emailSiswa', width: 180 },
    { label: 'Alamat', key: 'alamat', width: 200 },
    { label: 'Status', key: 'status', width: 100 },
    { label: 'Nama Ayah', key: 'namaAyah', width: 160 },
    { label: 'Nama Ibu', key: 'namaIbu', width: 160 },
    { label: 'Username Siswa', key: 'usernameSiswa', width: 150 },
  ];

  const PDF_COLS = [
    { label: 'Nama Lengkap', key: 'namaLengkap', width: '170px' },
    { label: 'NISN', key: 'nisn', width: '90px' },
    { label: 'NIS', key: 'nisLokal', width: '75px' },
    { label: 'Kelas', key: 'kelasNama', width: '80px' },
    { label: 'JK', key: 'jenisKelamin', width: '65px' },
    { label: 'Tempat, Tgl Lahir', key: '_ttl', width: '140px' },
    { label: 'Agama', key: 'agama', width: '85px' },
    { label: 'Status', key: 'status', width: '70px' },
  ];

  const handleExport = async (format: ExportFormat) => {
    const result = await exportSiswa({});
    const dateStr = new Date().toISOString().slice(0, 10);
    const enriched = result.data.map(s => ({
      ...s,
      _ttl: s.tempatLahir && s.tanggalLahir
        ? `${s.tempatLahir}, ${new Date(s.tanggalLahir).toLocaleDateString('id-ID')}`
        : s.tempatLahir || s.tanggalLahir || '',
    }));
    if (format === 'excel') {
      generateDataExcel({ filename: `data_siswa_${dateStr}.xls`, title: 'DAFTAR DATA SISWA', schoolName: result.sekolah.namaSekolah, schoolAddress: result.sekolah.alamat, schoolPhone: result.sekolah.telepon, columns: EXCEL_COLS, data: enriched });
      toast.success(`${result.data.length} data siswa berhasil diekspor ke Excel`);
    } else {
      printToPdf('DAFTAR DATA SISWA', result.sekolah, PDF_COLS, enriched);
      toast.success('Halaman cetak PDF dibuka di tab baru');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Data Siswa</h2>
          <p className="text-muted-foreground">Kelola data siswa sekolah</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="outline" onClick={() => setExportDialogOpen(true)} className="gap-2">
            <Download className="h-4 w-4" /> Export
          </Button>
          <Button variant="outline" onClick={() => setImportWizardOpen(true)} className="gap-2">
            <Upload className="h-4 w-4" /> Import
          </Button>
          <Button onClick={handleCreate} className="gap-2">
            <Plus className="h-4 w-4" /> Tambah Siswa
          </Button>
        </div>
      </div>

      <Card className="p-6">
        {/* Filters */}
        <div className="flex flex-col sm:flex-row gap-3 mb-4 flex-wrap">
          <div className="flex-1 flex items-center gap-2 min-w-[200px]">
            <Search className="h-5 w-5 text-muted-foreground shrink-0" />
            <Input
              placeholder="Cari nama/NIS siswa..."
              value={search}
              onChange={(e) => handleSearch(e.target.value)}
              className="max-w-sm"
            />
          </div>
          <Select value={statusFilter || '__all__'} onValueChange={handleStatusFilter}>
            <SelectTrigger className="w-[160px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__all__">Semua Status</SelectItem>
              <SelectItem value="Aktif">Aktif</SelectItem>
              <SelectItem value="Lulus">Lulus</SelectItem>
              <SelectItem value="Pindah">Pindah</SelectItem>
              <SelectItem value="Keluar">Keluar</SelectItem>
            </SelectContent>
          </Select>
          <Select value={kelasFilter || '__all__'} onValueChange={handleKelasFilter}>
            <SelectTrigger className="w-[160px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__all__">Semua Kelas</SelectItem>
              {kelasList.map((k) => (
                <SelectItem key={k.id} value={k.id}>{k.namaKelas}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          {/* Row limit selector — inline style */}
          <div className="flex items-center gap-0 bg-muted rounded-lg border border-border overflow-hidden h-9 text-sm">
            <span className="px-2.5 text-muted-foreground whitespace-nowrap select-none">Tampilkan</span>
            <Select value={pageLimit} onValueChange={handlePageLimitChange}>
              <SelectTrigger className="h-full border-0 border-l border-border rounded-none bg-card w-[70px] text-foreground font-medium focus:ring-0 focus:ring-offset-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua</SelectItem>
                <SelectItem value="10">10</SelectItem>
                <SelectItem value="25">25</SelectItem>
                <SelectItem value="50">50</SelectItem>
                <SelectItem value="100">100</SelectItem>
              </SelectContent>
            </Select>
            <span className="px-2.5 text-muted-foreground whitespace-nowrap select-none">baris</span>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <>
            <div className="rounded-md border overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-10">No</TableHead>
                    <TableHead className="min-w-[120px]">NISN</TableHead>
                    <TableHead className="min-w-[90px]">NIS</TableHead>
                    <TableHead className="min-w-[160px]">Nama Siswa</TableHead>
                    <TableHead className="min-w-[90px]">Kelas</TableHead>
                    <TableHead className="min-w-[50px]">JK</TableHead>
                    <TableHead className="min-w-[160px]">Tempat, Tanggal Lahir</TableHead>
                    <TableHead className="min-w-[160px]">Wali</TableHead>
                    <TableHead className="min-w-[100px]">Status</TableHead>
                    <TableHead className="text-right">Aksi</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {displayedSiswa.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={10} className="text-center py-8 text-muted-foreground">
                        Tidak ada data siswa
                      </TableCell>
                    </TableRow>
                  ) : (
                    displayedSiswa.map((s, index) => {
                      const rowNum = limit ? (currentPage - 1) * limit + index + 1 : index + 1;
                      let waliNama = '-', waliHp = '';
                      if (s.statusWali === 'Sama dengan Ayah Kandung') {
                        waliNama = s.namaAyah || '-'; waliHp = s.noHpAyah || '';
                      } else if (s.statusWali === 'Sama dengan Ibu Kandung') {
                        waliNama = s.namaIbu || '-'; waliHp = s.noHpIbu || '';
                      } else if (s.namaWali) {
                        waliNama = s.namaWali; waliHp = s.noHpWali || '';
                      } else if (s.namaAyah) {
                        waliNama = s.namaAyah; waliHp = s.noHpAyah || '';
                      }
                      return (
                        <TableRow key={s.id}>
                          <TableCell className="text-muted-foreground text-sm">{rowNum}</TableCell>
                          <TableCell className="font-mono text-sm tracking-wider">
                            {s.nisn || '-'}
                          </TableCell>
                          <TableCell className="font-mono text-sm tracking-wider">
                            {s.nisLokal || '-'}
                          </TableCell>
                          <TableCell className="font-medium">{s.namaLengkap}</TableCell>
                          <TableCell>{s.kelasNama || '-'}</TableCell>
                          <TableCell className="font-medium">
                            {s.jenisKelamin === 'Laki-laki' ? 'L' : s.jenisKelamin === 'Perempuan' ? 'P' : '-'}
                          </TableCell>
                          <TableCell>
                            {s.tempatLahir && s.tanggalLahir
                              ? `${s.tempatLahir}, ${new Date(s.tanggalLahir).toLocaleDateString('id-ID')}`
                              : '-'}
                          </TableCell>
                          <TableCell>
                            <div>
                              <p className="font-medium text-sm">{waliNama}</p>
                              {waliHp && <p className="text-xs text-muted-foreground">{waliHp}</p>}
                            </div>
                          </TableCell>
                          <TableCell>
                            <StatusPill status={s.status || '-'} onClick={() => handleToggleStatus(s)} />
                          </TableCell>
                          <TableCell className="text-right">
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-8 w-8">
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-44">
                                <DropdownMenuItem onClick={() => handleView(s)} className="gap-2 cursor-pointer">
                                  <Eye className="h-4 w-4" /> Lihat Detail
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => handleEdit(s)} className="gap-2 cursor-pointer">
                                  <Edit className="h-4 w-4" /> Edit Data
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => setResetSiswa(s)} className="gap-2 cursor-pointer">
                                  <KeyRound className="h-4 w-4" /> Reset Akun
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem onClick={() => setDeleteId(s.id)} className="gap-2 cursor-pointer text-destructive focus:text-destructive">
                                  <Trash2 className="h-4 w-4" /> Hapus
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </div>

            {/* Footer: info + pagination */}
            <div className="mt-4 flex flex-col sm:flex-row items-center justify-between gap-3">
              <p className="text-sm text-muted-foreground">
                {limit
                  ? `Halaman ${currentPage} dari ${totalPages} · ${siswa.length} total data`
                  : `${siswa.length} total data`}
              </p>
              {totalPages > 1 && (
                <div className="flex items-center gap-1">
                  <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === 1} onClick={() => setCurrentPage(1)}>
                    <ChevronsLeft className="h-4 w-4" />
                  </Button>
                  <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)}>
                    <ChevronLeft className="h-4 w-4" />
                  </Button>
                  {getPaginationPages(currentPage, totalPages).map((page, i) =>
                    page === '...'
                      ? <span key={`e-${i}`} className="px-1.5 text-muted-foreground text-sm">…</span>
                      : <Button
                          key={page}
                          variant={currentPage === page ? 'default' : 'outline'}
                          size="icon"
                          className="h-8 w-8 text-sm"
                          onClick={() => setCurrentPage(page as number)}
                        >
                          {page}
                        </Button>
                  )}
                  <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)}>
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                  <Button variant="outline" size="icon" className="h-8 w-8" disabled={currentPage === totalPages} onClick={() => setCurrentPage(totalPages)}>
                    <ChevronsRight className="h-4 w-4" />
                  </Button>
                </div>
              )}
            </div>
          </>
        )}
      </Card>

      <SiswaFormDialog open={dialogOpen} onOpenChange={setDialogOpen} siswa={editingSiswa} onSuccess={handleSaveSuccess} />
      <SiswaDetailDialog open={detailDialogOpen} onOpenChange={setDetailDialogOpen} siswa={viewingSiswa} />
      {resetSiswa && (
        <ResetAkunSiswaDialog
          open={!!resetSiswa}
          onClose={() => setResetSiswa(null)}
          onSuccess={() => loadSiswa(search, statusFilter, kelasFilter)}
          siswaId={resetSiswa.id}
          currentUsername={resetSiswa.usernameSiswa || ''}
        />
      )}
      <ImportSiswaWizard open={importWizardOpen} onOpenChange={setImportWizardOpen} onSuccess={() => loadSiswa(search, statusFilter, kelasFilter)} />
      <ExportFormatDialog open={exportDialogOpen} onOpenChange={setExportDialogOpen} onExport={handleExport} title="Export Data Siswa" />
      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Data Siswa</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus data siswa ini? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Hapus</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

