type JurnalDataItem = GetJurnalDataOutputType['items'][0];

function toDateStr(d: Date): string {
  return d.toISOString().split('T')[0];
}

function getDateRange(period: string): { start: string; end: string } {
  const today = new Date();
  const end = toDateStr(today);
  switch (period) {
    case 'hari_ini': return { start: end, end };
    case 'minggu_ini': {
      const d = new Date(today);
      d.setDate(d.getDate() - d.getDay() + 1); // Monday
      return { start: toDateStr(d), end };
    }
    case 'bulan_ini': {
      const d = new Date(today.getFullYear(), today.getMonth(), 1);
      return { start: toDateStr(d), end };
    }
    case 'semua': {
      const d = new Date(today);
      d.setMonth(d.getMonth() - 6);
      return { start: toDateStr(d), end };
    }
    default: return { start: end, end };
  }
}

export default function JurnalMengajarPage() {
  const { user } = useAuth();
  const isGuru = user?.role === 'Guru';

  const [period, setPeriod] = useState('hari_ini');
  const [guruFilter, setGuruFilter] = useState('all');
  const [kelasFilter, setKelasFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [items, setItems] = useState<JurnalDataItem[]>([]);
  const [guruList, setGuruList] = useState<{ id: string; nama: string }[]>([]);
  const [kelasList, setKelasList] = useState<{ id: string; nama: string }[]>([]);
  const [loading, setLoading] = useState(true);
  const [exporting, setExporting] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [selected, setSelected] = useState<JurnalItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<JurnalItem | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const range = getDateRange(period);
      const res = await getJurnalData({
        tanggalMulai: range.start,
        tanggalSelesai: range.end,
        mode: isGuru ? 'guru' : 'admin',
        guruId: guruFilter !== 'all' ? guruFilter : undefined,
        kelasId: kelasFilter !== 'all' ? kelasFilter : undefined,
      });
      setItems(res.items);
      setGuruList(res.guruList);
      setKelasList(res.kelasList);
    } catch {
      toast.error('Gagal memuat data jurnal');
    }
    setLoading(false);
  }, [period, isGuru, guruFilter, kelasFilter]);

  useEffect(() => { load(); }, [load]);

  const handleDelete = async () => {
    if (!deleteTarget?.jurnalId) return;
    try {
      await deleteJurnal({ id: deleteTarget.jurnalId });
      toast.success('Jurnal berhasil dihapus');
      load();
    } catch { toast.error('Gagal menghapus jurnal'); }
    setDeleteTarget(null);
  };

  const handleExport = async (format: 'pdf' | 'excel') => {
    setExporting(true);
    try {
      const range = getDateRange(period);
      const res = await exportJurnalPdf({
        guruId: guruFilter !== 'all' ? guruFilter : undefined,
        tanggalMulai: range.start,
        tanggalSelesai: range.end,
        format,
      });
      if (format === 'pdf' && res.url) {
        window.open(res.url, '_blank');
      } else if (format === 'excel' && res.html) {
        const blob = new Blob([res.html], { type: 'application/vnd.ms-excel' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'Jurnal_Mengajar.xls';
        a.click();
        URL.revokeObjectURL(url);
      }
      toast.success(`Export ${format.toUpperCase()} berhasil`);
    } catch {
      toast.error('Gagal mengeksport data');
    }
    setExporting(false);
  };

  const filtered = items.filter(i => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return i.mapelNama.toLowerCase().includes(q) || i.guruNama.toLowerCase().includes(q) || i.kelasNama.toLowerCase().includes(q);
  });

  const filledCount = filtered.filter(i => i.status === 'Sudah Diisi').length;
  const totalCount = filtered.length;
  const pctFilled = totalCount > 0 ? Math.round((filledCount / totalCount) * 100) : 0;

  // Group by date
  const grouped: Record<string, JurnalDataItem[]> = {};
  for (const it of filtered) {
    if (!grouped[it.tanggal]) grouped[it.tanggal] = [];
    grouped[it.tanggal].push(it);
  }
  const sortedDates = Object.keys(grouped).sort((a, b) => b.localeCompare(a));

  const periodLabel: Record<string, string> = {
    hari_ini: 'Hari Ini',
    minggu_ini: 'Minggu Ini',
    bulan_ini: 'Bulan Ini',
    semua: 'Semua',
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Jurnal Mengajar</h2>
          <p className="text-muted-foreground">
            {isGuru ? 'Isi jurnal mengajar sesuai jadwal pelajaran Anda' : 'Monitoring & kelola jurnal mengajar guru'}
          </p>
        </div>
        {!isGuru && (
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={() => handleExport('excel')} disabled={exporting}>
              {exporting ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : <FileSpreadsheet className="h-4 w-4 mr-1.5" />}
              Excel
            </Button>
            <Button variant="outline" size="sm" onClick={() => handleExport('pdf')} disabled={exporting}>
              {exporting ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : <FileDown className="h-4 w-4 mr-1.5" />}
              PDF
            </Button>
          </div>
        )}
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <SummaryCard label="Total Jadwal" value={totalCount} icon={CalendarDays} variant="default" loading={loading} />
        <SummaryCard label="Sudah Terisi" value={filledCount} icon={CheckCircle2} variant="success" loading={loading} />
        <SummaryCard label="Belum Diisi" value={totalCount - filledCount} icon={AlertCircle} variant="danger" loading={loading} />
        <SummaryCard label="Persentase" value={`${pctFilled}%`} icon={BookOpen} variant="info" loading={loading} />
      </div>

      {/* Filters bar */}
      <Card className="p-3">
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2.5 flex-wrap">
          <Select value={period} onValueChange={setPeriod}>
            <SelectTrigger className="w-[150px] h-9">
              <Calendar className="h-3.5 w-3.5 mr-1.5 text-muted-foreground" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="hari_ini">Hari Ini</SelectItem>
              <SelectItem value="minggu_ini">Minggu Ini</SelectItem>
              <SelectItem value="bulan_ini">Bulan Ini</SelectItem>
              <SelectItem value="semua">Semua</SelectItem>
            </SelectContent>
          </Select>

          {!isGuru && (
            <>
              <Select value={guruFilter} onValueChange={setGuruFilter}>
                <SelectTrigger className="w-[180px] h-9">
                  <Filter className="h-3.5 w-3.5 mr-1.5 text-muted-foreground" />
                  <SelectValue placeholder="Semua Guru" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Semua Guru</SelectItem>
                  {guruList.map(g => <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>)}
                </SelectContent>
              </Select>
              <Select value={kelasFilter} onValueChange={setKelasFilter}>
                <SelectTrigger className="w-[160px] h-9">
                  <SelectValue placeholder="Semua Kelas" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Semua Kelas</SelectItem>
                  {kelasList.map(k => <SelectItem key={k.id} value={k.id}>{k.nama}</SelectItem>)}
                </SelectContent>
              </Select>
            </>
          )}

          {isGuru && (
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={() => handleExport('pdf')} disabled={exporting} className="h-9">
                {exporting ? <Loader2 className="h-4 w-4 animate-spin mr-1.5" /> : <FileDown className="h-4 w-4 mr-1.5" />}
                Export PDF
              </Button>
            </div>
          )}

          <div className="relative sm:ml-auto">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              placeholder="Cari mapel/guru/kelas..."
              className="pl-9 h-9 w-[200px]"
            />
          </div>
        </div>
      </Card>

      {/* Content */}
      {loading ? (
        <div className="space-y-3">
          {[1,2,3,4].map(i => <Skeleton key={i} className="h-20 w-full rounded-xl" />)}
        </div>
      ) : filtered.length === 0 ? (
        <Card className="p-12">
          <div className="flex flex-col items-center justify-center text-center">
            <div className="h-16 w-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
              <BookOpen className="h-8 w-8 text-muted-foreground" />
            </div>
            <h3 className="text-lg font-semibold mb-1">Tidak ada jadwal</h3>
            <p className="text-sm text-muted-foreground max-w-md">
              {isGuru ? 'Tidak ada jadwal mengajar untuk periode ini.' : 'Tidak ditemukan jadwal untuk filter yang dipilih.'}
            </p>
          </div>
        </Card>
      ) : (
        <div className="space-y-6">
          {sortedDates.map(date => (
            <JurnalCards
              key={date}
              date={date}
              items={grouped[date]}
              isGuru={isGuru}
              showDate={period !== 'hari_ini'}
              onFill={item => { setSelected(item as JurnalItem); setFormOpen(true); }}
              onView={item => { setSelected(item as JurnalItem); setDetailOpen(true); }}
              onEdit={item => { setSelected(item as JurnalItem); setFormOpen(true); }}
              onDelete={item => setDeleteTarget(item as JurnalItem)}
            />
          ))}
        </div>
      )}

      <JurnalFormDialog item={selected} open={formOpen} onClose={() => { setFormOpen(false); setSelected(null); }} onSaved={load} />
      <JurnalDetailDialog item={selected} open={detailOpen} onClose={() => { setDetailOpen(false); setSelected(null); }} />

      <AlertDialog open={!!deleteTarget} onOpenChange={v => { if (!v) setDeleteTarget(null); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Jurnal?</AlertDialogTitle>
            <AlertDialogDescription>Jurnal yang sudah dihapus tidak bisa dikembalikan.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Hapus</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

