            {entry.mapelNama}
          </p>
          <div className="flex items-center gap-1.5 mt-1 flex-wrap">
            {jpLabel && (
              <span className="text-[10px] font-bold bg-primary/10 text-primary px-1.5 py-0.5 rounded">
                {jpLabel}
              </span>
            )}
            <div className="flex items-center gap-1">
              <Clock className="h-3 w-3 text-muted-foreground flex-shrink-0" />
              <span className="text-xs text-muted-foreground font-medium">
                {entry.jamMulai} – {entry.jamSelesai}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-1 mt-0.5">
            <User className="h-3 w-3 text-muted-foreground flex-shrink-0" />
            <span className="text-xs text-muted-foreground truncate">
              {entry.guruNama}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button
            onClick={() => onEdit(entry)}
            className="h-6 w-6 rounded flex items-center justify-center hover:bg-background/80 transition-colors"
          >
            <Pencil className="h-3 w-3 text-muted-foreground" />
          </button>
          <button
            onClick={() => onDelete(entry.id)}
            className="h-6 w-6 rounded flex items-center justify-center hover:bg-destructive/10 transition-colors"
          >
            <Trash2 className="h-3 w-3 text-destructive" />
          </button>
        </div>
      </div>
