const REGULAR_COLUMNS: (ExcelColumn & { key: string; required: boolean })[] = [
  { key: 'namaLengkap', label: 'Nama Lengkap', required: true, example: 'Ahmad Fauzi S.Pd.', width: 200 },
  { key: 'nipnuptk', label: 'NIP/NUPTK', required: false, example: '198503152010011001', isText: true, width: 170 },
