            'flex flex-col items-center gap-1 min-w-[90px]',
            currentStep >= step.num ? 'text-primary' : 'text-muted-foreground'
          )}>
            <step.Icon className={cn(
              'h-7 w-7',
              currentStep >= step.num ? 'text-primary' : 'text-muted-foreground/50'
            )} />
            <span className="text-[10px] font-medium text-center leading-tight">{step.label}</span>
          </div>
          {idx < STEPS.length - 1 && (
            <ArrowRight className={cn(
              'h-4 w-4 mb-4 flex-shrink-0',
              currentStep > step.num ? 'text-primary' : 'text-muted-foreground/40'
            )} />
          )}
        </div>
      ))}
