  );
}

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export default function ImportGuruWizard({ open, onOpenChange, onSuccess }: Props) {
  const [step, setStep] = useState(1);
  const [importType, setImportType] = useState<'quick' | 'regular'>('regular');
  const [parsedRows, setParsedRows] = useState<Record<string, string>[]>([]);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ imported: number; errors: string[] } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const columns = importType === 'quick' ? QUICK_COLUMNS : REGULAR_COLUMNS;

  const handleOpen = (o: boolean) => {
    if (!o) {
      setStep(1); setImportType('regular');
      setParsedRows([]); setImportResult(null);
    }
    onOpenChange(o);
  };

  const handleDownloadSample = () => {
    generateExcelTemplate(`template_import_guru_${importType}.xls`, columns);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const rawRows = parseCSV(text);
      const mapped = rawRows.map(row => mapRowToFields(row, columns));
      setParsedRows(mapped);
      if (mapped.length > 0) toast.success(`${mapped.length} baris data berhasil dibaca`);
      else toast.error('Tidak ada data yang dapat dibaca dari file');
    };
    reader.readAsText(file, 'UTF-8');
    e.target.value = '';
  };

  const handleImport = async () => {
    setImporting(true);
    try {
      const result = await importGuru({
        statusKepegawaian: '',
        kategoriPegawai: [],
        rows: parsedRows.map(row => ({ namaLengkap: row.namaLengkap || '', ...row })),
      });
      setImportResult(result);
      toast.success(`${result.imported} data guru/tendik berhasil diimport`);
      if (result.errors.length > 0) toast.warning(`${result.errors.length} baris gagal diimport`);
      onSuccess();
    } catch {
      toast.error('Gagal mengimport data guru/tendik');
    } finally {
      setImporting(false);
    }
  };

  const canNext = () => {
    if (step === 3) return parsedRows.length > 0;
    return true;
  };

  return (
    <Dialog open={open} onOpenChange={handleOpen}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto p-0">
        <DialogHeader className="px-6 pt-6 pb-0">
          <DialogTitle className="flex items-center gap-2 text-primary">
            <Users className="h-5 w-5" />
            Import Data Guru & Tendik
          </DialogTitle>
        </DialogHeader>

        <StepIndicator currentStep={step} />

        <div className="px-6 py-6 min-h-[320px]">
          {/* Step 1: Jenis Import */}
          {step === 1 && (
            <div className="space-y-4">
              <h3 className="text-center text-lg font-semibold">Pilih Jenis Import</h3>
              <div className="grid grid-cols-2 gap-4">
                {(['quick', 'regular'] as const).map(type => (
                  <div
                    key={type}
                    className={cn(
                      'border-2 rounded-lg p-6 cursor-pointer transition-all',
                      importType === type ? 'border-primary bg-primary/5' : 'border-border'
                    )}
                    onClick={() => setImportType(type)}
                  >
                    <div className="flex items-center gap-3 mb-3">
                      <div className={cn(
                        'w-5 h-5 rounded-full border-2 flex items-center justify-center flex-shrink-0',
                        importType === type ? 'border-primary' : 'border-muted-foreground'
                      )}>
                        {importType === type && <div className="w-3 h-3 rounded-full bg-primary" />}
                      </div>
                      <span className="font-semibold">{type === 'quick' ? 'Quick Import' : 'Regular Import'}</span>
                      {type === 'quick'
                        ? <Zap className="h-5 w-5 ml-auto text-yellow-500" />
                        : <ClipboardList className="h-5 w-5 ml-auto text-blue-500" />
                      }
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {type === 'quick'
                        ? 'Quick Import adalah format import dengan kebutuhan data-data dasar saja (nama, username, password), lebih cepat dan efisien'
                        : 'Regular Import membutuhkan data informasi utama lengkap (NIP/NUPTK, NIK, kontak, dll)'}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Step 2: Download Sample */}
          {step === 2 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Download Template Excel</h3>
              <p className="text-sm text-muted-foreground">
                Download file template untuk <strong>{importType === 'quick' ? 'Quick Import' : 'Regular Import'}</strong>.
                Isi data guru/tendik sesuai format, lalu simpan sebagai <strong>.csv</strong> sebelum diupload.
              </p>
              <div className="border rounded-lg p-8 space-y-4">
                <FileSpreadsheet className="h-16 w-16 text-green-600 mx-auto" />
                <p className="font-medium">template_import_guru_{importType}.xls</p>
                <p className="text-xs text-muted-foreground">{columns.length} kolom · {columns.filter(c => c.required).length} wajib diisi</p>
                <div className="text-left bg-muted/40 rounded-lg p-3 space-y-1 max-h-40 overflow-y-auto">
                  <p className="text-xs font-medium text-muted-foreground mb-2">Kolom yang tersedia:</p>
                  {columns.map(col => (
                    <div key={col.key} className="flex items-center gap-2 text-xs">
                      <span className={cn('w-2 h-2 rounded-full flex-shrink-0', col.required ? 'bg-destructive' : 'bg-muted-foreground/40')} />
                      <span>{col.label}</span>
                      {col.required && <span className="text-destructive text-[10px]">*wajib</span>}
                      {col.isText && <span className="text-muted-foreground text-[10px]">(format teks)</span>}
                    </div>
                  ))}
                </div>
                <Button onClick={handleDownloadSample} className="gap-2 w-full">
                  <Download className="h-4 w-4" />
                  Download Template Excel
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
