          {/* Step 3: Upload Data */}
          {step === 3 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Upload Data Guru/Tendik</h3>
              <p className="text-sm text-muted-foreground">
                Upload file CSV yang sudah diisi dengan data guru/tendik
                <br />
                <span className="text-xs">(simpan file Excel sebagai .csv terlebih dahulu)</span>
              </p>
              <div
                className="border-2 border-dashed rounded-lg p-10 cursor-pointer hover:border-primary/50 transition-colors"
                onClick={() => fileInputRef.current?.click()}
              >
                <Upload className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="font-medium">Klik untuk upload file CSV</p>
                <p className="text-xs text-muted-foreground mt-1">Format: .csv</p>
                <input ref={fileInputRef} type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </div>
              {parsedRows.length > 0 && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4 flex items-center gap-3">
                  <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  <p className="text-sm text-green-700 font-medium">{parsedRows.length} baris data berhasil dibaca</p>
                </div>
              )}
            </div>
          )}

          {/* Step 4: Preview & Import */}
          {step === 4 && !importResult && (
            <div className="space-y-4">
              <h3 className="text-lg font-semibold">Preview Data ({parsedRows.length} data guru/tendik)</h3>
              <ScrollArea className="h-64 border rounded-lg">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-8">No</TableHead>
                      <TableHead>Nama Lengkap</TableHead>
                      <TableHead>NIP/NUPTK</TableHead>
                      <TableHead>NIK</TableHead>
                      <TableHead>No HP</TableHead>
                      <TableHead>Username</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {parsedRows.map((row, idx) => (
                      <TableRow key={idx}>
                        <TableCell>{idx + 1}</TableCell>
                        <TableCell className="font-medium">{row.namaLengkap || '-'}</TableCell>
                        <TableCell>{row.nipnuptk || '-'}</TableCell>
                        <TableCell>{row.nik || '-'}</TableCell>
                        <TableCell>{row.noHp || '-'}</TableCell>
                        <TableCell>{row.usernameGuru || '-'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollArea>
            </div>
          )}

          {/* Step 4: Result */}
          {step === 4 && importResult && (
            <div className="space-y-4 max-w-md mx-auto">
              <div className="flex items-center gap-4 p-5 rounded-lg bg-muted">
                <CheckCircle2 className="h-10 w-10 text-primary flex-shrink-0" />
                <div>
                  <p className="font-semibold text-lg">{importResult.imported} data berhasil diimport</p>
                  {importResult.errors.length > 0 && (
                    <p className="text-sm text-muted-foreground">{importResult.errors.length} baris dilewati karena error</p>
                  )}
                </div>
              </div>
              {importResult.errors.length > 0 && (
                <ScrollArea className="max-h-40 border rounded-lg p-3">
                  {importResult.errors.map((err, i) => (
                    <div key={i} className="flex items-start gap-2 text-sm text-destructive py-0.5">
                      <AlertCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
                      <span>{err}</span>
                    </div>
                  ))}
                </ScrollArea>
              )}
              <Button className="w-full" onClick={() => handleOpen(false)}>Selesai</Button>
            </div>
          )}
        </div>

        <div className="flex justify-between px-6 pb-6 pt-4 border-t">
          {step === 4 && importResult ? (
            <div />
          ) : (
            <>
              <Button variant="outline" onClick={() => step > 1 ? setStep(s => s - 1) : handleOpen(false)}>
                {step > 1 ? 'Kembali' : 'Batal'}
              </Button>
              {step < 4 ? (
                <Button onClick={() => setStep(s => s + 1)} disabled={!canNext()} className="gap-2">
                  Selanjutnya <ChevronRight className="h-4 w-4" />
                </Button>
              ) : (
                <Button onClick={handleImport} disabled={importing || parsedRows.length === 0} className="gap-2">
                  {importing
                    ? <><Loader2 className="h-4 w-4 animate-spin" />Mengimport...</>
                    : <><Upload className="h-4 w-4" />Import {parsedRows.length} Data</>
                  }
                </Button>
              )}
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

