                    <Pencil className="h-3.5 w-3.5 text-muted-foreground" />
                  </Button>
                  <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onDelete(j.id)}>
                    <Trash2 className="h-3.5 w-3.5 text-destructive" />
                  </Button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Check, ChevronsUpDown, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface Option {
  id: string;
  name: string;
}

interface Props {
  options: Option[];
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  disabledPlaceholder?: string;
  disabled?: boolean;
  loading?: boolean;
}

function toDisplayName(name: string): string {
  if (name !== name.toUpperCase()) return name;
  const prefixes = ['KABUPATEN ', 'KOTA ', 'KECAMATAN ', 'KELURAHAN ', 'DESA '];
  let display = name;
  for (const prefix of prefixes) {
    if (display.startsWith(prefix)) {
      display = display.substring(prefix.length);
      break;
    }
  }
  return display.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());
}

export default function SearchableSelect({
  options,
  value,
  onChange,
  placeholder = 'Pilih...',
  disabledPlaceholder,
  disabled = false,
  loading = false,
}: Props) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');

  const handleOpenChange = (v: boolean) => {
    if (disabled || loading) return;
    setOpen(v);
    if (!v) setSearch('');
  };

  const filtered = options.filter((o) =>
    toDisplayName(o.name).toLowerCase().includes(search.toLowerCase())
  );

  const selectedLabel = value
    ? toDisplayName(options.find((o) => o.name === value)?.name ?? value)
    : '';

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled || loading}
          className="w-full justify-between font-normal"
        >
          {loading ? (
            <span className="flex items-center gap-2 text-muted-foreground text-sm">
              <Loader2 className="h-3 w-3 animate-spin" /> Memuat...
            </span>
          ) : value ? (
            <span className="truncate">{selectedLabel}</span>
          ) : (
            <span className="text-muted-foreground">
              {disabled && disabledPlaceholder ? disabledPlaceholder : placeholder}
            </span>
          )}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="p-2"
        align="start"
        sideOffset={4}
        style={{ width: 'var(--radix-popover-trigger-width)' }}
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <Input
          placeholder="Ketik untuk mencari..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="mb-2"
          autoFocus
        />
        <div className="overflow-y-auto max-h-60">
          {filtered.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-4">Tidak ditemukan.</p>
          ) : (
            filtered.map((option) => (
              <div
                key={option.id}
                className={cn(
                  'flex items-center gap-2 px-2 py-1.5 rounded-sm text-sm cursor-pointer hover:bg-accent hover:text-accent-foreground',
                  value === option.name && 'bg-accent text-accent-foreground'
                )}
                onMouseDown={(e) => {
                  e.preventDefault();
                  onChange(option.name);
                  setOpen(false);
                  setSearch('');
                }}
              >
                <Check className={cn('h-4 w-4 shrink-0', value === option.name ? 'opacity-100' : 'opacity-0')} />
                {toDisplayName(option.name)}
              </div>
            ))
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

import { useState, useEffect, useCallback } from 'react';
