type MapelRecord = GetMataPelajaranOutputType['records'][0];

const KELOMPOK_COLORS: Record<string, string> = {
  'Mata Pelajaran Wajib': 'bg-blue-100 text-blue-700',
  'Mata Pelajaran Pilihan': 'bg-orange-100 text-orange-700',
  'Muatan Lokal': 'bg-green-100 text-green-700',
};

const PAGE_SIZE_OPTIONS = [
  { label: 'Tampilkan 10', value: 10 },
  { label: 'Tampilkan 25', value: 25 },
  { label: 'Tampilkan 100', value: 100 },
  { label: 'Semuanya', value: 99999 },
];

export default function MataPelajaranPage() {
  const [records, setRecords] = useState<MapelRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editData, setEditData] = useState<MapelRecord | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getMataPelajaran({ search, page, pageSize });
      setRecords(res.records);
      setTotal(res.total);
    } catch {
      toast.error('Gagal memuat data');
    } finally {
      setLoading(false);
    }
  }, [search, page, pageSize]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSave = async (data: { namaMapel: string; kodeMapel?: string; kelompok?: string; aktif: boolean }) => {
    try {
      if (editData) {
        await updateMataPelajaran({ id: editData.id, ...data });
        toast.success('Mata pelajaran berhasil diperbarui');
      } else {
        await createMataPelajaran(data);
        toast.success('Mata pelajaran berhasil ditambahkan');
      }
      setShowForm(false);
      setEditData(null);
      fetchData();
    } catch {
      toast.error('Gagal menyimpan data');
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await deleteMataPelajaran({ id: deleteId });
      toast.success('Mata pelajaran berhasil dihapus');
      setDeleteId(null);
      fetchData();
    } catch {
      toast.error('Gagal menghapus data');
    }
  };

  const totalPages = Math.ceil(total / pageSize);
  const startIndex = (page - 1) * pageSize + 1;
  const endIndex = Math.min(page * pageSize, total);

