            value={pageSize}
            onChange={e => { setPageSize(Number(e.target.value)); setPage(1); }}
          >
            {PAGE_SIZE_OPTIONS.map(s => (
              <option key={s.value} value={s.value}>{s.label}</option>
            ))}
          </select>
          <Button variant="outline" size="sm" className="gap-1.5">
            <Download className="h-4 w-4" />
            Export
          </Button>
          <Button size="sm" className="gap-1.5" onClick={() => { setEditData(null); setShowForm(true); }}>
            <Plus className="h-4 w-4" />
            Tambah
          </Button>
        </div>
      </div>

      {/* Search */}
      <div className="flex justify-end">
        <div className="flex items-center gap-2">
          <span className="text-sm text-muted-foreground">Pencarian:</span>
          <Input
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(1); }}
            className="w-48 h-8 text-sm"
          />
        </div>
      </div>

      {/* Table */}
      <div className="border border-border rounded overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-muted/50">
              <th className="text-left px-4 py-2.5 font-semibold text-foreground w-12">No</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground">Nama</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground w-28">Kode</th>
              <th className="text-left px-4 py-2.5 font-semibold text-foreground">Kelompok</th>
              <th className="text-center px-4 py-2.5 font-semibold text-foreground w-20">Aktif</th>
              <th className="text-center px-4 py-2.5 font-semibold text-foreground w-24">Action</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="text-center py-10 text-muted-foreground">Memuat data...</td>
              </tr>
            ) : records.length === 0 ? (
              <tr>
                <td colSpan={6} className="text-center py-10 text-muted-foreground">Tidak ada data</td>
              </tr>
            ) : (
              records.map((r, i) => (
                <tr key={r.id} className={i % 2 === 0 ? 'bg-background' : 'bg-muted/20'}>
                  <td className="px-4 py-2.5 text-primary font-medium">{startIndex + i}</td>
                  <td className="px-4 py-2.5 text-primary font-medium">{r.namaMapel}</td>
                  <td className="px-4 py-2.5 text-foreground">{r.kodeMapel}</td>
                  <td className="px-4 py-2.5">
                    {r.kelompok ? (
                      <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${KELOMPOK_COLORS[r.kelompok] ?? 'bg-muted text-muted-foreground'}`}>
                        {r.kelompok}
                      </span>
                    ) : '-'}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    {r.aktif !== false ? (
                      <Check className="h-4 w-4 text-primary mx-auto" />
                    ) : (
                      <X className="h-4 w-4 text-destructive mx-auto" />
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => { setEditData(r); setShowForm(true); }}
                        className="text-primary hover:text-primary/70 transition-colors"
                      >
                        <Pencil className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => setDeleteId(r.id)}
