import { useState, useEffect, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Clock, AlertCircle, Split } from 'lucide-react';
import type { JpSlot, JadwalSettings } from './PengaturanJadwalSheet';
import { isSpecialSlot } from './PengaturanJadwalSheet';
import type { JadwalEntry } from './TimetableGrid';

interface MapelItem { id: string; nama: string; kode?: string }
interface GuruItem { id: string; nama: string }

export interface JadwalFormData {
  id?: string;
  hari: string;
  jamMulai: string;
  jamSelesai: string;
  mapelId: string;
  guruId: string;
  jpMulai?: number;
  jpCount?: number;
}

export interface JpSegment {
  jpStart: number;
  jpEnd: number;
  jpCount: number;
  jamMulai: string;
  jamSelesai: string;
}

interface Props {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: JadwalFormData) => Promise<void>;
  onSubmitMulti?: (segments: JadwalFormData[]) => Promise<void>;
  initial?: JadwalFormData | null;
  mapelList: MapelItem[];
  guruList: GuruItem[];
  settings: JadwalSettings;
  existingJadwal: JadwalEntry[];
}

function computeSegments(startJp: number, count: number, allSlots: JpSlot[]): JpSegment[] {
  const jpSlots = allSlots.filter(s => !isSpecialSlot(s));
  const startIdx = jpSlots.findIndex(s => s.jp === startJp);
  if (startIdx < 0 || count <= 0) return [];

  const selectedJps = jpSlots.slice(startIdx, startIdx + count);
  if (selectedJps.length === 0) return [];

  const segments: JpSegment[] = [];
  let segStart = 0;

  for (let i = 0; i < selectedJps.length; i++) {
    const isLast = i === selectedJps.length - 1;
    let hasBreakAfter = false;

    if (!isLast) {
      const thisAllIdx = allSlots.findIndex(s => !isSpecialSlot(s) && s.jp === selectedJps[i].jp);
      const nextAllIdx = allSlots.findIndex(s => !isSpecialSlot(s) && s.jp === selectedJps[i + 1].jp);
      for (let j = thisAllIdx + 1; j < nextAllIdx; j++) {
        if (isSpecialSlot(allSlots[j])) {
          hasBreakAfter = true;
          break;
        }
      }
    }

    if (hasBreakAfter || isLast) {
      const segJps = selectedJps.slice(segStart, i + 1);
      segments.push({
        jpStart: segJps[0].jp,
        jpEnd: segJps[segJps.length - 1].jp,
        jpCount: segJps.length,
        jamMulai: segJps[0].mulai,
        jamSelesai: segJps[segJps.length - 1].selesai,
      });
      segStart = i + 1;
    }
  }
  return segments;
}

export default function JadwalFormDialog({
  open, onClose, onSubmit, onSubmitMulti, initial, mapelList, guruList, settings, existingJadwal,
}: Props) {
  const [hari, setHari] = useState('Senin');
  const [jpMulai, setJpMulai] = useState('');
  const [jpCount, setJpCount] = useState('1');
  const [mapelId, setMapelId] = useState('');
  const [guruId, setGuruId] = useState('');
  const [saving, setSaving] = useState(false);

  const isEditing = !!initial?.id;

  const jpSlots = useMemo(() => settings.slots.filter(s => !isSpecialSlot(s)), [settings.slots]);

  // Occupied JPs for selected day (excluding current entry when editing)
  const occupiedJps = useMemo(() => {
    const occupied = new Set<number>();
    const entriesForDay = existingJadwal.filter(j => j.hari === hari && j.id !== initial?.id);
    for (const entry of entriesForDay) {
      const startIdx = jpSlots.findIndex(s => s.mulai === entry.jamMulai);
      const endIdx = jpSlots.findIndex(s => s.selesai === entry.jamSelesai);
      if (startIdx >= 0 && endIdx >= 0) {
        for (let i = startIdx; i <= endIdx; i++) {
          occupied.add(jpSlots[i].jp);
        }
      }
    }
    return occupied;
  }, [existingJadwal, hari, initial?.id, jpSlots]);

  // Available JP slots (free slots the user can pick as start)
  const availableJpStarts = useMemo(() => {
    return jpSlots.filter(s => !occupiedJps.has(s.jp));
  }, [jpSlots, occupiedJps]);

  // First available JP
  const firstAvailableJp = useMemo(() => {
    return availableJpStarts.length > 0 ? availableJpStarts[0].jp : 0;
  }, [availableJpStarts]);

  // For editing, find the JP from the initial data
  const editJpMulai = useMemo(() => {
    if (!initial?.jamMulai) return 0;
    const match = jpSlots.find(s => s.mulai === initial.jamMulai);
    return match?.jp || 0;
  }, [initial, jpSlots]);

  const selectedJpMulai = jpMulai ? Number(jpMulai) : 0;

  // Max consecutive available JPs from selected start
  const maxConsecutive = useMemo(() => {
    if (!selectedJpMulai) return 0;
    const startIdx = jpSlots.findIndex(s => s.jp === selectedJpMulai);
    if (startIdx < 0) return 0;
    let count = 0;
    for (let i = startIdx; i < jpSlots.length && count < 8; i++) {
      if (occupiedJps.has(jpSlots[i].jp)) break;
      count++;
    }
    return count;
  }, [selectedJpMulai, jpSlots, occupiedJps]);

  const jpCountOptions = useMemo(() => {
    return Array.from({ length: Math.min(Math.max(maxConsecutive, 0), 8) }, (_, i) => i + 1);
  }, [maxConsecutive]);

  // Segments
  const segments = useMemo(() => {
    if (!selectedJpMulai || Number(jpCount) <= 0) return [];
    return computeSegments(selectedJpMulai, Number(jpCount), settings.slots);
  }, [selectedJpMulai, jpCount, settings.slots]);

  const hasSplit = segments.length > 1;

  const totalDuration = useMemo(() => {
    let total = 0;
    for (const seg of segments) {
      const [h1, m1] = seg.jamMulai.split(':').map(Number);
      const [h2, m2] = seg.jamSelesai.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  }, [segments]);

  // Initialize form
  useEffect(() => {
    if (!open) return;
    if (initial) {
      setHari(initial.hari || 'Senin');
      setMapelId(initial.mapelId || '');
      setGuruId(initial.guruId || '');
      if (isEditing && editJpMulai) {
        setJpMulai(String(editJpMulai));
        // Calculate JP count from times
        const matchStart = jpSlots.findIndex(s => s.mulai === initial.jamMulai);
        const matchEnd = jpSlots.findIndex(s => s.selesai === initial.jamSelesai);
        if (matchStart >= 0 && matchEnd >= 0) {
          setJpCount(String(matchEnd - matchStart + 1));
        } else {
          setJpCount('1');
        }
      } else {
        // New entry - auto-select first available
        setJpCount('1');
      }
    } else {
      setHari('Senin');
      setJpCount('1');
      setMapelId('');
      setGuruId('');
    }
  }, [open, initial, jpSlots, isEditing, editJpMulai]);

  // Set jpMulai after hari changes (delayed because availableJpStarts depends on hari)
  useEffect(() => {
    if (!open) return;
    if (isEditing && editJpMulai) {
      setJpMulai(String(editJpMulai));
    } else if (firstAvailableJp) {
      setJpMulai(String(firstAvailableJp));
    } else {
      setJpMulai('');
    }
  }, [open, hari, firstAvailableJp, isEditing, editJpMulai]);

  const handleHariChange = (newHari: string) => {
    setHari(newHari);
    setJpCount('1');
  };

  const handleJpMulaiChange = (val: string) => {
    setJpMulai(val);
    setJpCount('1');
  };

  // Adjust jpCount if it exceeds max
  useEffect(() => {
    if (Number(jpCount) > maxConsecutive && maxConsecutive > 0) {
      setJpCount(String(maxConsecutive));
    }
  }, [maxConsecutive, jpCount]);

  const handleSubmit = async () => {
    if (!hari || !mapelId || !guruId || segments.length === 0) return;
    setSaving(true);
    try {
      if (isEditing) {
        const seg = segments[0];
        await onSubmit({
          id: initial?.id,
          hari,
          jamMulai: seg.jamMulai,
          jamSelesai: seg.jamSelesai,
          mapelId,
          guruId,
          jpMulai: seg.jpStart,
          jpCount: seg.jpCount,
        });
        // If editing changed JP count and created extra segments, save them
        if (segments.length > 1 && onSubmitMulti) {
          const extraSegments: JadwalFormData[] = segments.slice(1).map(s => ({
            hari, jamMulai: s.jamMulai, jamSelesai: s.jamSelesai, mapelId, guruId,
            jpMulai: s.jpStart, jpCount: s.jpCount,
          }));
          await onSubmitMulti(extraSegments);
        } else if (segments.length > 1) {
          for (const s of segments.slice(1)) {
            await onSubmit({
              hari, jamMulai: s.jamMulai, jamSelesai: s.jamSelesai, mapelId, guruId,
              jpMulai: s.jpStart, jpCount: s.jpCount,
            });
          }
        }
      } else if (segments.length === 1) {
        const seg = segments[0];
        await onSubmit({
          hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
          jpMulai: seg.jpStart, jpCount: seg.jpCount,
        });
      } else if (onSubmitMulti) {
        const entries: JadwalFormData[] = segments.map(seg => ({
          hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
          jpMulai: seg.jpStart, jpCount: seg.jpCount,
        }));
        await onSubmitMulti(entries);
      } else {
        for (const seg of segments) {
          await onSubmit({
            hari, jamMulai: seg.jamMulai, jamSelesai: seg.jamSelesai, mapelId, guruId,
            jpMulai: seg.jpStart, jpCount: seg.jpCount,
          });
        }
      }
      onClose();
    } finally {
      setSaving(false);
    }
  };

  const isValid = hari && mapelId && guruId && segments.length > 0;
  const noSlots = availableJpStarts.length === 0 && !isEditing;

  return (
    <Dialog open={open} onOpenChange={v => !v && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{isEditing ? 'Edit Jadwal' : 'Tambah Jadwal'}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Hari */}
          <div className="space-y-1.5">
            <Label>Hari <span className="text-destructive">*</span></Label>
            <Select value={hari} onValueChange={handleHariChange}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {settings.hariAktif.map(h => (
                  <SelectItem key={h} value={h}>{h}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* JP Mulai */}
          <div className="space-y-1.5">
            <Label>JP Mulai <span className="text-destructive">*</span></Label>
            <Select value={jpMulai} onValueChange={handleJpMulaiChange} disabled={noSlots}>
              <SelectTrigger>
                <SelectValue placeholder="Pilih JP" />
              </SelectTrigger>
              <SelectContent>
                {availableJpStarts.map(s => (
                  <SelectItem key={s.jp} value={String(s.jp)}>
                    JP {s.jp} ({s.mulai} – {s.selesai})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Jumlah JP */}
          <div className="space-y-1.5">
            <Label>Jumlah JP <span className="text-destructive">*</span></Label>
            <Select value={jpCount} onValueChange={setJpCount} disabled={noSlots || !selectedJpMulai}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {jpCountOptions.map(n => (
                  <SelectItem key={n} value={String(n)}>
                    {n} JP
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* No slots warning */}
          {noSlots && (
            <div className="flex items-center gap-2 px-3 py-2.5 rounded-lg bg-destructive/5 border border-destructive/15 text-sm text-destructive">
              <AlertCircle className="h-4 w-4 flex-shrink-0" />
              Semua JP pada hari {hari} sudah terisi
            </div>
          )}

          {/* Time preview */}
          {segments.length > 0 && (
            <div className="space-y-1.5">
              {hasSplit && (
                <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <Split className="h-3.5 w-3.5" />
                  <span>Terbagi {segments.length} sesi karena jeda istirahat/sholat</span>
                </div>
              )}
              {segments.map((seg, i) => (
                <div key={i} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-primary/5 border border-primary/15">
                  <Clock className="h-4 w-4 text-primary flex-shrink-0" />
                  <div className="flex-1">
                    <span className="text-sm font-medium text-foreground">
                      {seg.jamMulai} – {seg.jamSelesai}
                    </span>
                    <span className="text-[10px] font-bold bg-primary/10 text-primary px-1.5 py-0.5 rounded ml-2">
                      JP {seg.jpStart === seg.jpEnd ? seg.jpStart : `${seg.jpStart}–${seg.jpEnd}`}
                    </span>
                  </div>
                  <span className="text-xs text-muted-foreground">
                    {seg.jpCount} JP
                  </span>
                </div>
              ))}
              <p className="text-xs text-muted-foreground text-right">
                Total: {totalDuration} menit ({segments.reduce((s, seg) => s + seg.jpCount, 0)} JP)
              </p>
            </div>
          )}

          {/* Mapel */}
          <div className="space-y-1.5">
            <Label>Mata Pelajaran <span className="text-destructive">*</span></Label>
            <Select value={mapelId} onValueChange={setMapelId}>
              <SelectTrigger><SelectValue placeholder="Pilih mata pelajaran" /></SelectTrigger>
              <SelectContent>
                {mapelList.map(m => (
                  <SelectItem key={m.id} value={m.id}>
                    {m.nama}{m.kode ? ` (${m.kode})` : ''}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Guru */}
          <div className="space-y-1.5">
            <Label>Guru Pengampu <span className="text-destructive">*</span></Label>
            <Select value={guruId} onValueChange={setGuruId}>
              <SelectTrigger><SelectValue placeholder="Pilih guru" /></SelectTrigger>
              <SelectContent>
                {guruList.map(g => (
                  <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving || !isValid}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {isEditing ? 'Simpan' : hasSplit ? `Tambah (${segments.length} sesi)` : 'Tambah'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Skeleton } from '@/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, CheckCircle2, BookOpen, Users, Clock, GraduationCap, ClipboardList } from 'lucide-react';
import { toast } from 'sonner';
import { getStudentsForJurnal, saveJurnal } from 'zite-endpoints-sdk';

export interface JurnalItem {
  id: string;
  tanggal: string;
  hari: string;
  jamMulai: string;
  jamSelesai: string;
  guruId: string;
  guruNama: string;
  kelasId: string;
  kelasNama: string;
  mapelId: string;
  mapelNama: string;
  jadwalId: string;
  tujuanPembelajaran?: string;
  materiKonten?: string;
  kegiatanPembelajaran?: string;
  catatan?: string;
  statusKehadiran?: string;
  detailKehadiran?: string;
  status?: string;
  jurnalId?: string;
}

interface Props {
  item: JurnalItem | null;
  open: boolean;
  onClose: () => void;
  onSaved: () => void;
}

interface StudentAttendance {
  id: string;
  nama: string;
  nisn: string;
  status: 'H' | 'I' | 'S' | 'A';
}

export default function JurnalFormDialog({ item, open, onClose, onSaved }: Props) {
  const [tujuan, setTujuan] = useState('');
  const [materi, setMateri] = useState('');
  const [kegiatan, setKegiatan] = useState('');
  const [catatan, setCatatan] = useState('');
  const [hadirSemua, setHadirSemua] = useState(true);
  const [students, setStudents] = useState<StudentAttendance[]>([]);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [saving, setSaving] = useState(false);

  // Penugasan state
  const [tambahTugas, setTambahTugas] = useState(false);
  const [judulTugas, setJudulTugas] = useState('');
  const [deskripsiTugas, setDeskripsiTugas] = useState('');
  const [jenisTugas, setJenisTugas] = useState('');
  const [deadlineTugas, setDeadlineTugas] = useState('');
  const [catatanTugas, setCatatanTugas] = useState('');

  const loadStudents = useCallback(async (kelasId: string) => {
    setLoadingStudents(true);
    try {
      const res = await getStudentsForJurnal({ kelasId });
      let parsed: Record<string, string> = {};
      if (item?.detailKehadiran) {
        try { parsed = JSON.parse(item.detailKehadiran); } catch {}
      }
      setStudents(res.students.map(s => ({
        id: s.id, nama: s.nama, nisn: s.nisn,
        status: (parsed[s.id] as any) || 'H',
      })));
    } catch { /* ignore */ }
    setLoadingStudents(false);
  }, [item?.detailKehadiran]);

  useEffect(() => {
    if (open && item) {
      setTujuan(item.tujuanPembelajaran || '');
      setMateri(item.materiKonten || '');
      setKegiatan(item.kegiatanPembelajaran || '');
      setCatatan(item.catatan || '');
      setHadirSemua(item.statusKehadiran !== 'Tidak Semua Hadir');
      loadStudents(item.kelasId);
      // Reset penugasan
      setTambahTugas(false);
      setJudulTugas('');
      setDeskripsiTugas('');
      setJenisTugas('');
      setDeadlineTugas('');
      setCatatanTugas('');
    }
  }, [open, item, loadStudents]);

  const updateStudentStatus = (studentId: string, status: 'H' | 'I' | 'S' | 'A') => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, status } : s));
  };

  const handleSave = async () => {
    if (!item) return;
    if (!tujuan.trim()) { toast.error('Tujuan Pembelajaran wajib diisi'); return; }
    if (!materi.trim()) { toast.error('Materi/Konten wajib diisi'); return; }
    if (tambahTugas) {
      if (!judulTugas.trim()) { toast.error('Judul tugas wajib diisi'); return; }
      if (!jenisTugas) { toast.error('Jenis tugas wajib dipilih'); return; }
      if (!deadlineTugas) { toast.error('Deadline tugas wajib diisi'); return; }
    }
    setSaving(true);
    try {
      const detailMap: Record<string, string> = {};
      if (!hadirSemua) {
        for (const s of students) detailMap[s.id] = s.status;
      }
      await saveJurnal({
        jurnalId: item.jurnalId,
        tanggal: item.tanggal,
        guruId: item.guruId,
        kelasId: item.kelasId,
        mapelId: item.mapelId,
        jadwalId: item.jadwalId,
        jamMulai: item.jamMulai,
        jamSelesai: item.jamSelesai,
        tujuanPembelajaran: tujuan,
        materiKonten: materi,
        kegiatanPembelajaran: kegiatan || undefined,
        catatan: catatan || undefined,
        statusKehadiran: hadirSemua ? 'Hadir Semua' : 'Tidak Semua Hadir',
        detailKehadiran: hadirSemua ? undefined : JSON.stringify(detailMap),
        penugasan: tambahTugas ? {
          judulTugas,
          deskripsi: deskripsiTugas || undefined,
          jenisTugas,
          deadline: deadlineTugas,
          catatan: catatanTugas || undefined,
        } : undefined,
      });
      toast.success(tambahTugas ? 'Jurnal & tugas berhasil disimpan' : 'Jurnal berhasil disimpan');
      onSaved();
      onClose();
    } catch {
      toast.error('Gagal menyimpan jurnal');
    }
    setSaving(false);
  };

  if (!item) return null;

  const absentCount = students.filter(s => s.status !== 'H').length;
  const dateStr = new Date(item.tanggal + 'T00:00:00').toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-2xl h-[90vh] flex flex-col p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 pt-5 pb-3 flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-lg">
            <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
              <BookOpen className="h-4 w-4 text-primary" />
            </div>
            {item.jurnalId ? 'Edit' : 'Isi'} Jurnal Mengajar
          </DialogTitle>
        </DialogHeader>

        <div className="px-6 pb-3 flex-shrink-0">
          <div className="flex flex-wrap gap-2">
            <InfoChip icon={GraduationCap} label={item.mapelNama} />
            <InfoChip icon={Users} label={item.kelasNama} />
            <InfoChip icon={Clock} label={`${item.jamMulai}–${item.jamSelesai}`} />
            <InfoChip label={`${item.hari}, ${dateStr}`} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-6 pb-4">
          <div className="space-y-5">
            <FormField label="Tujuan Pembelajaran" required>
              <Textarea value={tujuan} onChange={e => setTujuan(e.target.value)} placeholder="Tuliskan tujuan pembelajaran..." rows={3} className="resize-none" />
            </FormField>

            <FormField label="Materi / Konten" required>
              <Textarea value={materi} onChange={e => setMateri(e.target.value)} placeholder="Tuliskan materi yang diajarkan..." rows={3} className="resize-none" />
            </FormField>

            <FormField label="Kegiatan Pembelajaran" optional>
              <Textarea value={kegiatan} onChange={e => setKegiatan(e.target.value)} placeholder="Deskripsi kegiatan pembelajaran..." rows={2} className="resize-none" />
            </FormField>

            <FormField label="Catatan" optional>
              <Textarea value={catatan} onChange={e => setCatatan(e.target.value)} placeholder="Catatan tambahan..." rows={2} className="resize-none" />
            </FormField>

            {/* Kehadiran */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">Kehadiran Siswa</Label>
                <div className="flex items-center gap-2">
                  <Switch checked={hadirSemua} onCheckedChange={setHadirSemua} />
                  <span className="text-sm font-medium">{hadirSemua ? 'Hadir Semua' : 'Ada yang tidak hadir'}</span>
                </div>
              </div>
              {hadirSemua ? (
                <div className="flex items-center gap-2 rounded-lg border bg-accent/30 p-3">
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                  <span className="text-sm">Semua siswa hadir ({students.length} siswa)</span>
                </div>
              ) : (
                <AttendanceList students={students} loading={loadingStudents} absentCount={absentCount} onUpdate={updateStudentStatus} />
              )}
            </div>

            {/* Penugasan Section */}
            <div className="space-y-3 border-t pt-5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="h-7 w-7 rounded-md bg-accent flex items-center justify-center">
                    <ClipboardList className="h-3.5 w-3.5 text-accent-foreground" />
                  </div>
                  <Label className="text-sm font-semibold">Tambah Penugasan</Label>
                </div>
                <Switch checked={tambahTugas} onCheckedChange={setTambahTugas} />
              </div>

              {!tambahTugas ? (
                <p className="text-xs text-muted-foreground">Aktifkan untuk memberikan tugas langsung dari jurnal ini. Tugas akan otomatis masuk ke menu Tugas.</p>
              ) : (
                <div className="space-y-4 rounded-lg border bg-muted/20 p-4">
                  <FormField label="Judul Tugas" required>
                    <Input value={judulTugas} onChange={e => setJudulTugas(e.target.value)} placeholder="Contoh: Latihan Soal Bab 3" />
                  </FormField>
                  <div className="grid grid-cols-2 gap-3">
                    <FormField label="Jenis Tugas" required>
                      <Select value={jenisTugas} onValueChange={setJenisTugas}>
                        <SelectTrigger><SelectValue placeholder="Pilih jenis" /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Tugas Harian">Tugas Harian</SelectItem>
                          <SelectItem value="PR (Pekerjaan Rumah)">PR</SelectItem>
                          <SelectItem value="Proyek">Proyek</SelectItem>
                          <SelectItem value="Latihan">Latihan</SelectItem>
                          <SelectItem value="Ulangan">Ulangan</SelectItem>
                          <SelectItem value="Kuis">Kuis</SelectItem>
                        </SelectContent>
                      </Select>
                    </FormField>
                    <FormField label="Deadline" required>
                      <Input type="date" value={deadlineTugas} onChange={e => setDeadlineTugas(e.target.value)} min={item.tanggal} />
                    </FormField>
                  </div>
                  <FormField label="Deskripsi Tugas" optional>
                    <Textarea value={deskripsiTugas} onChange={e => setDeskripsiTugas(e.target.value)} placeholder="Jelaskan tugas yang diberikan..." rows={2} className="resize-none" />
                  </FormField>
                  <FormField label="Catatan untuk Siswa" optional>
                    <Textarea value={catatanTugas} onChange={e => setCatatanTugas(e.target.value)} placeholder="Catatan tambahan..." rows={2} className="resize-none" />
                  </FormField>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-2 px-6 py-3 border-t bg-card flex-shrink-0">
          <Button variant="outline" onClick={onClose} disabled={saving}>Batal</Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {tambahTugas ? 'Simpan Jurnal & Tugas' : 'Simpan Jurnal'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function InfoChip({ icon: Icon, label }: { icon?: React.ElementType; label: string }) {
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-3 py-1 text-xs font-medium text-foreground">
      {Icon && <Icon className="h-3 w-3 text-muted-foreground" />}
      {label}
    </span>
  );
}

function FormField({ label, required, optional, children }: { label: string; required?: boolean; optional?: boolean; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-sm">
        {label}
        {required && <span className="text-destructive ml-0.5">*</span>}
        {optional && <span className="text-muted-foreground text-xs ml-1">(opsional)</span>}
      </Label>
      {children}
    </div>
  );
}

function AttendanceList({ students, loading, absentCount, onUpdate }: {
  students: StudentAttendance[];
  loading: boolean;
  absentCount: number;
  onUpdate: (id: string, status: 'H' | 'I' | 'S' | 'A') => void;
}) {
  if (loading) return <div className="space-y-2">{[1,2,3].map(i => <Skeleton key={i} className="h-10 w-full" />)}</div>;
  if (students.length === 0) return <p className="text-sm text-muted-foreground py-3">Tidak ada data siswa di kelas ini</p>;

  const statusColors: Record<string, string> = {
    H: 'bg-primary text-primary-foreground',
    I: 'bg-accent text-accent-foreground ring-1 ring-border',
    S: 'bg-muted text-foreground ring-1 ring-border',
    A: 'bg-destructive text-destructive-foreground',
  };

  return (
    <div className="space-y-2">
      {absentCount > 0 && <p className="text-xs text-destructive font-medium">{absentCount} siswa tidak hadir</p>}
      <div className="border rounded-lg overflow-hidden">
        <div className="grid grid-cols-[1fr_auto] bg-muted px-3 py-2 text-xs font-semibold text-muted-foreground">
          <div>Nama Siswa</div>
          <div className="w-[140px] text-center">Status</div>
        </div>
        <div className="max-h-[200px] overflow-y-auto divide-y divide-border">
          {students.map((s, idx) => (
            <div key={s.id} className="grid grid-cols-[1fr_auto] items-center px-3 py-1.5 hover:bg-muted/30">
              <div className="text-sm truncate">
                <span className="text-muted-foreground mr-1.5 text-xs">{idx + 1}.</span>
                {s.nama}
              </div>
              <div className="w-[140px] flex gap-1 justify-center">
                {(['H', 'I', 'S', 'A'] as const).map(st => (
                  <button
                    key={st}
                    type="button"
                    onClick={() => onUpdate(s.id, st)}
                    className={`w-8 h-7 rounded text-xs font-bold transition-all ${
                      s.status === st ? statusColors[st] : 'bg-muted/50 text-muted-foreground hover:bg-muted'
                    }`}
                  >
                    {st}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useMemo } from 'react';
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable,
  arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Pencil, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { GetMataPelajaranOutputType } from 'zite-endpoints-sdk';

type MapelRecord = GetMataPelajaranOutputType['records'][0];

const KELOMPOK_COLORS: Record<string, string> = {
  'Mata Pelajaran Wajib': 'bg-primary/10 text-primary',
  'Mata Pelajaran Pilihan': 'bg-accent text-accent-foreground',
  'Muatan Lokal': 'bg-muted text-muted-foreground',
};

interface Props {
  records: MapelRecord[];
  onReorder: (newOrder: MapelRecord[]) => void;
  onToggleAktif: (id: string, aktif: boolean) => void;
  onEdit: (r: MapelRecord) => void;
  onDelete: (id: string) => void;
  isDraggable: boolean;
}

export default function SortableMapelList({ records, onReorder, onToggleAktif, onEdit, onDelete, isDraggable }: Props) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  const ids = useMemo(() => records.map(r => r.id), [records]);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const oldIndex = records.findIndex(r => r.id === active.id);
    const newIndex = records.findIndex(r => r.id === over.id);
    if (oldIndex === -1 || newIndex === -1) return;
    onReorder(arrayMove(records, oldIndex, newIndex));
  };

  const tableContent = (
    <div className="rounded-lg border border-border overflow-hidden">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-muted/40 border-b border-border">
            {isDraggable && <th className="w-10 px-2 py-3" />}
            <th className="w-14 text-center px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">No</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Nama Mapel</th>
            <th className="w-28 text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Kode</th>
            <th className="text-left px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Kelompok</th>
            <th className="text-center w-28 px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Status</th>
            <th className="text-center w-24 px-4 py-3 font-semibold text-muted-foreground text-xs uppercase tracking-wider">Aksi</th>
          </tr>
        </thead>
        {isDraggable ? (
          <SortableContext items={ids} strategy={verticalListSortingStrategy}>
            <tbody>
              {records.map((r, i) => (
                <SortableRow key={r.id} record={r} index={i} onToggleAktif={onToggleAktif} onEdit={onEdit} onDelete={onDelete} isDraggable />
              ))}
            </tbody>
          </SortableContext>
        ) : (
          <tbody>
            {records.map((r, i) => (
              <SortableRow key={r.id} record={r} index={i} onToggleAktif={onToggleAktif} onEdit={onEdit} onDelete={onDelete} isDraggable={false} />
            ))}
          </tbody>
        )}
      </table>
    </div>
  );

  if (isDraggable) {
    return (
      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        {tableContent}
      </DndContext>
    );
  }

  return tableContent;
}

function SortableRow({
  record: r,
  index: i,
  onToggleAktif,
  onEdit,
  onDelete,
  isDraggable,
}: {
  record: MapelRecord;
  index: number;
  onToggleAktif: (id: string, aktif: boolean) => void;
  onEdit: (r: MapelRecord) => void;
  onDelete: (id: string) => void;
  isDraggable: boolean;
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: r.id,
    disabled: !isDraggable,
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  const isAktif = r.aktif !== false;

  return (
    <tr ref={setNodeRef} style={style} className="group border-b border-border last:border-0 hover:bg-muted/30 transition-colors">
      {isDraggable && (
        <td className="w-10 px-2">
          <button {...attributes} {...listeners} className="cursor-grab active:cursor-grabbing p-1 text-muted-foreground hover:text-foreground">
            <GripVertical className="h-4 w-4" />
          </button>
        </td>
      )}
      <td className="text-center text-muted-foreground text-sm px-4 py-2.5">{i + 1}</td>
      <td className="font-medium px-4 py-2.5">{r.namaMapel}</td>
      <td className="text-muted-foreground px-4 py-2.5">{r.kodeMapel || '-'}</td>
      <td className="px-4 py-2.5">
        {r.kelompok ? (
          <span className={`inline-block px-2.5 py-0.5 rounded-full text-xs font-medium ${KELOMPOK_COLORS[r.kelompok] ?? 'bg-muted text-muted-foreground'}`}>
            {r.kelompok}
          </span>
        ) : '-'}
      </td>
      <td className="text-center px-4 py-2.5">
        <button
          onClick={() => onToggleAktif(r.id, !isAktif)}
          className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 cursor-pointer select-none ${
            isAktif
              ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400'
              : 'bg-muted text-muted-foreground hover:bg-muted/80'
          }`}
        >
          <span className={`h-2 w-2 rounded-full ${isAktif ? 'bg-emerald-500' : 'bg-muted-foreground/50'}`} />
          {isAktif ? 'Aktif' : 'Tidak Aktif'}
        </button>
      </td>
      <td className="px-4 py-2.5">
        <div className="flex items-center justify-center gap-1">
          <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(r)}>
            <Pencil className="h-3.5 w-3.5 text-muted-foreground" />
          </Button>
          <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onDelete(r.id)}>
            <Trash2 className="h-3.5 w-3.5 text-destructive" />
          </Button>
        </div>
      </td>
    </tr>
  );
}

