  { key: 'namaAyah', label: 'Nama Ayah', required: false, example: 'Budi Santoso', width: 160 },
  { key: 'namaIbu', label: 'Nama Ibu', required: false, example: 'Siti Rahayu', width: 160 },
];

type ColumnDef = typeof QUICK_COLUMNS[0];

function parseCSV(text: string): Record<string, string>[] {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim().split('\n');
  if (lines.length < 2) return [];

  const parseRow = (line: string): string[] => {
    const cells: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
        else inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        cells.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    cells.push(current.trim());
    return cells;
  };

  const headers = parseRow(lines[0]);
  return lines.slice(1)
    .map(line => {
      const cells = parseRow(line);
      const obj: Record<string, string> = {};
      headers.forEach((h, i) => { obj[h] = cells[i] || ''; });
      return obj;
    })
    .filter(row => Object.values(row).some(v => v !== ''));
}

function mapRowToFields(row: Record<string, string>, columns: ColumnDef[]): Record<string, string> {
  const result: Record<string, string> = {};
  columns.forEach(col => {
    const value = row[col.label];
    if (value !== undefined) result[col.key] = value;
  });
  return result;
}

