              </div>
              <p className="text-xs text-muted-foreground">
                * File CSV dapat dibuka dan diedit menggunakan Microsoft Excel atau Google Sheets
              </p>
            </div>
          )}

          {step === 4 && (
            <div className="space-y-6 max-w-md mx-auto text-center">
              <h3 className="text-lg font-semibold">Upload Data Siswa</h3>
              <p className="text-sm text-muted-foreground">Upload file CSV yang sudah diisi dengan data siswa</p>
              <div
                className="border-2 border-dashed rounded-lg p-10 cursor-pointer hover:border-primary/50 transition-colors"
                onClick={() => fileInputRef.current?.click()}
