import { useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { BookOpen, CheckCircle2, XCircle, Clock, Users, GraduationCap } from 'lucide-react';
import { getStudentsForJurnal } from 'zite-endpoints-sdk';
import type { JurnalItem } from './JurnalFormDialog';

interface Props {
  item: JurnalItem | null;
  open: boolean;
  onClose: () => void;
}

export default function JurnalDetailDialog({ item, open, onClose }: Props) {
  const [studentNames, setStudentNames] = useState<Record<string, string>>({});

  useEffect(() => {
    if (open && item?.kelasId && item.statusKehadiran === 'Tidak Semua Hadir') {
      getStudentsForJurnal({ kelasId: item.kelasId }).then(res => {
        const map: Record<string, string> = {};
        for (const s of res.students) map[s.id] = s.nama;
        setStudentNames(map);
      }).catch(() => {});
    }
  }, [open, item?.kelasId, item?.statusKehadiran]);

  if (!item) return null;

  let detailParsed: Record<string, string> = {};
  if (item.detailKehadiran) {
    try { detailParsed = JSON.parse(item.detailKehadiran); } catch {}
  }
  const absentStudents = Object.entries(detailParsed).filter(([_, st]) => st !== 'H');
  const dateStr = new Date(item.tanggal + 'T00:00:00').toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <Dialog open={open} onOpenChange={v => { if (!v) onClose(); }}>
      <DialogContent className="max-w-lg max-h-[85vh] flex flex-col p-0 gap-0 overflow-hidden">
        <DialogHeader className="px-6 pt-5 pb-3 flex-shrink-0">
          <DialogTitle className="flex items-center gap-2">
            <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
              <BookOpen className="h-4 w-4 text-primary" />
            </div>
            Detail Jurnal Mengajar
          </DialogTitle>
        </DialogHeader>

        <div className="px-6 pb-3 flex-shrink-0">
          <div className="flex flex-wrap gap-2">
            <InfoChip icon={GraduationCap} label={item.mapelNama} />
            <InfoChip icon={Users} label={item.kelasNama} />
            <InfoChip icon={Clock} label={`${item.jamMulai}–${item.jamSelesai}`} />
            <InfoChip label={dateStr} />
          </div>
          {item.guruNama && (
            <p className="text-xs text-muted-foreground mt-2">Guru: <span className="font-medium text-foreground">{item.guruNama}</span></p>
          )}
        </div>

        <div className="flex-1 overflow-y-auto px-6 pb-6">
          <div className="space-y-4">
            <Section title="Tujuan Pembelajaran" content={item.tujuanPembelajaran} />
            <Section title="Materi / Konten" content={item.materiKonten} />
            {item.kegiatanPembelajaran && <Section title="Kegiatan Pembelajaran" content={item.kegiatanPembelajaran} />}
            {item.catatan && <Section title="Catatan" content={item.catatan} />}

            <div className="space-y-2">
              <h4 className="font-semibold text-sm">Kehadiran</h4>
              {item.statusKehadiran === 'Hadir Semua' ? (
                <div className="flex items-center gap-2 rounded-lg border bg-accent/30 p-3">
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                  <span className="text-sm">Semua siswa hadir</span>
                </div>
              ) : absentStudents.length > 0 ? (
                <div className="rounded-lg border divide-y divide-border overflow-hidden">
                  {absentStudents.map(([id, st]) => (
                    <div key={id} className="flex items-center gap-2 px-3 py-2 text-sm">
                      <XCircle className="h-4 w-4 text-destructive flex-shrink-0" />
                      <span className="truncate flex-1">{studentNames[id] || id}</span>
                      <Badge variant={st === 'S' ? 'outline' : st === 'I' ? 'secondary' : 'destructive'} className="text-[10px]">
                        {st === 'I' ? 'Izin' : st === 'S' ? 'Sakit' : 'Alfa'}
                      </Badge>
                    </div>
                  ))}
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function InfoChip({ icon: Icon, label }: { icon?: React.ElementType; label: string }) {
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-3 py-1 text-xs font-medium text-foreground">
      {Icon && <Icon className="h-3 w-3 text-muted-foreground" />}
      {label}
    </span>
  );
}

function Section({ title, content }: { title: string; content?: string }) {
  return (
    <div className="space-y-1">
      <h4 className="font-semibold text-sm">{title}</h4>
      <p className="text-sm text-muted-foreground whitespace-pre-wrap">{content || '-'}</p>
    </div>
  );
}

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
