export type ExportFormat = 'excel' | 'pdf';

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onExport: (format: ExportFormat) => Promise<void>;
  title?: string;
}

export default function ExportFormatDialog({ open, onOpenChange, onExport, title = 'Export Data' }: Props) {
  const [format, setFormat] = useState<ExportFormat>('excel');
  const [loading, setLoading] = useState(false);

  const handleExport = async () => {
    setLoading(true);
    try {
      await onExport(format);
      onOpenChange(false);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={open => { if (!loading) onOpenChange(open); }}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-primary">
            <Download className="h-5 w-5" />
            {title}
          </DialogTitle>
          <DialogDescription>
            Pilih format file untuk mengekspor data
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-2 gap-4 py-2">
          {/* Excel option */}
          <div
            className={cn(
              'border-2 rounded-xl p-5 cursor-pointer transition-all text-center space-y-3',
              format === 'excel' ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'
            )}
            onClick={() => setFormat('excel')}
          >
            <div className={cn(
              'w-5 h-5 rounded-full border-2 mx-auto flex items-center justify-center',
              format === 'excel' ? 'border-primary' : 'border-muted-foreground'
            )}>
              {format === 'excel' && <div className="w-2.5 h-2.5 rounded-full bg-primary" />}
            </div>
            <FileSpreadsheet className="h-10 w-10 mx-auto text-green-600" />
            <div>
              <p className="font-semibold">Excel</p>
              <p className="text-xs text-muted-foreground mt-1">Format .xls dengan lebar kolom rapi dan format angka yang benar</p>
            </div>
          </div>

          {/* PDF option */}
          <div
            className={cn(
              'border-2 rounded-xl p-5 cursor-pointer transition-all text-center space-y-3',
              format === 'pdf' ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'
            )}
            onClick={() => setFormat('pdf')}
          >
            <div className={cn(
              'w-5 h-5 rounded-full border-2 mx-auto flex items-center justify-center',
              format === 'pdf' ? 'border-primary' : 'border-muted-foreground'
            )}>
              {format === 'pdf' && <div className="w-2.5 h-2.5 rounded-full bg-primary" />}
            </div>
            <FileText className="h-10 w-10 mx-auto text-red-500" />
            <div>
              <p className="font-semibold">PDF</p>
              <p className="text-xs text-muted-foreground mt-1">Dokumen dengan kop surat sekolah, logo, nama lembaga & alamat</p>
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={loading}>
            Batal
          </Button>
          <Button onClick={handleExport} disabled={loading} className="gap-2">
            {loading
              ? <><Loader2 className="h-4 w-4 animate-spin" />Memproses...</>
              : <><Download className="h-4 w-4" />Export {format === 'excel' ? 'Excel' : 'PDF'}</>
            }
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Eye, EyeOff } from 'lucide-react';
import { toast } from 'sonner';
import { resetAkunSiswa } from 'zite-endpoints-sdk';

interface Props {
  open: boolean;
  onClose: () => void;
  onSuccess: () => void;
  siswaId: string;
  currentUsername: string;
}

export default function ResetAkunSiswaDialog({ open, onClose, onSuccess, siswaId, currentUsername }: Props) {
  const [username, setUsername] = useState(currentUsername);
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [saving, setSaving] = useState(false);

  const handleSubmit = async () => {
    if (!username) return toast.error('Username wajib diisi');
    if (!password) return toast.error('Password wajib diisi');
    if (password !== confirm) return toast.error('Konfirmasi password tidak sesuai');
    setSaving(true);
    try {
      await resetAkunSiswa({ id: siswaId, usernameSiswa: username, passwordSiswa: password });
      toast.success('Akun siswa berhasil direset');
      onSuccess();
      onClose();
    } catch (e: unknown) {
      toast.error((e as Error).message || 'Gagal reset akun');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Reset Akun Siswa</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-1">
            <Label>Username Baru</Label>
            <Input value={username} onChange={(e) => setUsername(e.target.value)} />
          </div>
          <div className="space-y-1">
            <Label>Password Baru</Label>
            <div className="relative">
              <Input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="pr-10"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>
          <div className="space-y-1">
            <Label>Konfirmasi Password</Label>
            <div className="relative">
              <Input
                type={showConfirm ? 'text' : 'password'}
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                className={`pr-10 ${confirm && password !== confirm ? 'border-destructive' : ''}`}
              />
              <button
                type="button"
                onClick={() => setShowConfirm(!showConfirm)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                {showConfirm ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
            {confirm && password !== confirm && (
              <p className="text-xs text-destructive">Password tidak sesuai</p>
            )}
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} disabled={saving}>
            {saving ? 'Menyimpan...' : 'Reset Akun'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';

const TUGAS_GURU = ['Kepala Sekolah/Madrasah', 'Guru Kelas', 'Guru Mata Pelajaran', 'Guru BK'];
const TUGAS_TENDIK = ['Tata Usaha', 'Operator', 'Bendahara', 'Petugas Keamanan', 'Petugas Kebersihan', 'Pembina Ekskul', 'Lainnya'];
const TUGAS_TAMBAHAN = ['Wakil Kepala Sekolah/Madrasah', 'Kepala Pustakawan', 'Kepala Laboratorium', 'Wali Kelas', 'Guru Piket', 'Koordinator Projek', 'Guru Wali'];

interface Props {
  form: Record<string, unknown>;
  onChange: (key: string, value: unknown) => void;
}

export default function GuruFormKepegawaianTab({ form, onChange }: Props) {
  const kategori = form.kategoriPegawai as string;
  const tugasOptions = kategori === 'Tendik' ? TUGAS_TENDIK : TUGAS_GURU;
  const tugasTambahan = (form.tugasTambahan as string[]) || [];

  const toggleTugas = (val: string) => {
    const current = tugasTambahan;
    onChange('tugasTambahan', current.includes(val) ? current.filter((t) => t !== val) : [...current, val]);
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>Status Kepegawaian <span className="text-destructive">*</span></Label>
          <Select value={(form.statusKepegawaian as string) || ''} onValueChange={(v) => onChange('statusKepegawaian', v)}>
            <SelectTrigger><SelectValue placeholder="Pilih" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="PNS">PNS</SelectItem>
              <SelectItem value="PPPK">PPPK</SelectItem>
              <SelectItem value="Guru Tetap Yayasan (GTY)">Guru Tetap Yayasan (GTY)</SelectItem>
              <SelectItem value="Honorer">Honorer</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1">
          <Label>Kategori Pegawai <span className="text-destructive">*</span></Label>
          <div className="flex gap-3 pt-2">
            {['Guru', 'Tendik'].map((k) => (
              <button
                key={k}
                type="button"
                onClick={() => { onChange('kategoriPegawai', k); onChange('tugasUtama', ''); }}
                className={`px-4 py-2 rounded-lg border text-sm font-medium transition-colors ${
                  kategori === k ? 'bg-primary text-primary-foreground border-primary' : 'border-border hover:bg-muted'
                }`}
              >
                {k}
              </button>
            ))}
          </div>
        </div>
        <div className="col-span-2 space-y-1">
          <Label>Tugas Utama <span className="text-destructive">*</span></Label>
          <Select value={(form.tugasUtama as string) || ''} onValueChange={(v) => onChange('tugasUtama', v)}>
            <SelectTrigger><SelectValue placeholder="Pilih tugas utama" /></SelectTrigger>
            <SelectContent>
              {tugasOptions.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="space-y-2">
        <Label>Tugas Tambahan</Label>
        <div className="grid grid-cols-2 gap-2 p-3 border rounded-lg bg-muted/30">
          {TUGAS_TAMBAHAN.map((t) => (
            <div key={t} className="flex items-center gap-2">
              <Checkbox checked={tugasTambahan.includes(t)} onCheckedChange={() => toggleTugas(t)} id={`tt-${t}`} />
              <label htmlFor={`tt-${t}`} className="text-sm cursor-pointer">{t}</label>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-1">
          <Label>Mulai Bertugas</Label>
          <Input type="date" value={(form.mulaiBertugas as string) || ''} onChange={(e) => onChange('mulaiBertugas', e.target.value)} />
        </div>
        <div className="space-y-1">
          <Label>Akhir Bertugas</Label>
          <Input type="date" value={(form.akhirBertugas as string) || ''} onChange={(e) => onChange('akhirBertugas', e.target.value)} />
        </div>
        <div className="space-y-1">
          <Label>JP (Jam Pelajaran)</Label>
          <Input type="number" min={0} max={99} placeholder="0" value={(form.jp as number) ?? ''} onChange={(e) => onChange('jp', e.target.value ? Number(e.target.value) : undefined)} />
        </div>
        <div className="space-y-1">
          <Label>Pendidikan Terakhir</Label>
          <Input value={(form.pendidikanTerakhir as string) || ''} onChange={(e) => onChange('pendidikanTerakhir', e.target.value)} />
        </div>
        <div className="col-span-2 space-y-1">
          <Label>Alamat</Label>
          <Input value={(form.alamat as string) || ''} onChange={(e) => onChange('alamat', e.target.value)} />
        </div>
      </div>

      <div className="flex items-center gap-3 pt-2">
        <Switch
          checked={(form.active as boolean) ?? true}
          onCheckedChange={(v) => onChange('active', v)}
          id="active-switch"
        />
        <Label htmlFor="active-switch">
          Status: <span className={(form.active as boolean) !== false ? 'text-green-600 font-medium' : 'text-muted-foreground font-medium'}>
            {(form.active as boolean) !== false ? 'Aktif' : 'Non Aktif'}
          </span>
        </Label>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Sparkles, Trash2, Plus, AlertTriangle, CheckCircle2, ShieldAlert } from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { generateJadwal } from 'zite-endpoints-sdk';
import type { JadwalSettings } from './PengaturanJadwalSheet';
import { isSpecialSlot } from './PengaturanJadwalSheet';

interface MapelItem { id: string; nama: string; kode?: string }
interface GuruItem { id: string; nama: string }

interface Assignment {
  mapelId: string;
  guruId: string;
  jpPerWeek: number;
}

interface Constraint {
  guruId: string;
  hari: string;
  jpList: number[];
}

interface Props {
  open: boolean;
  onClose: () => void;
  onGenerated: () => void;
  kelasId: string;
  kelasLabel: string;
  mapelList: MapelItem[];
  guruList: GuruItem[];
  settings: JadwalSettings;
}

export default function GenerateJadwalDialog({
  open, onClose, onGenerated, kelasId, kelasLabel, mapelList, guruList, settings,
}: Props) {
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [constraints, setConstraints] = useState<Constraint[]>([]);
  const [clearExisting, setClearExisting] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [result, setResult] = useState<{ success: boolean; message: string; conflicts: string[] } | null>(null);

  const jpSlots = useMemo(() => settings.slots.filter(s => !isSpecialSlot(s)), [settings.slots]);
  const jpPerDay = jpSlots.length;

  // Assignment helpers
  const addAssignment = () => {
    const unused = mapelList.find(m => !assignments.some(a => a.mapelId === m.id));
    if (!unused) { toast.error('Semua mapel sudah ditambahkan'); return; }
    setAssignments(prev => [...prev, { mapelId: unused.id, guruId: guruList[0]?.id || '', jpPerWeek: 2 }]);
  };

  const updateAssignment = (idx: number, field: keyof Assignment, value: string | number) => {
    setAssignments(prev => prev.map((a, i) => i === idx ? { ...a, [field]: value } : a));
  };

  const removeAssignment = (idx: number) => {
    setAssignments(prev => prev.filter((_, i) => i !== idx));
  };

  // Constraint helpers
  const addConstraint = () => {
    if (guruList.length === 0) return;
    setConstraints(prev => [...prev, { guruId: guruList[0].id, hari: settings.hariAktif[0] || 'Senin', jpList: [] }]);
  };

  const updateConstraint = (idx: number, field: keyof Constraint, value: any) => {
    setConstraints(prev => prev.map((c, i) => i === idx ? { ...c, [field]: value } : c));
  };

  const removeConstraint = (idx: number) => {
    setConstraints(prev => prev.filter((_, i) => i !== idx));
  };

  const toggleJpInConstraint = (idx: number, jp: number) => {
    setConstraints(prev => prev.map((c, i) => {
      if (i !== idx) return c;
      const has = c.jpList.includes(jp);
      return { ...c, jpList: has ? c.jpList.filter(j => j !== jp) : [...c.jpList, jp] };
    }));
  };

  const totalJp = assignments.reduce((s, a) => s + a.jpPerWeek, 0);
  const maxJp = settings.hariAktif.length * jpPerDay;

  const handleGenerate = async () => {
    if (assignments.length === 0) { toast.error('Tambahkan minimal 1 mapel'); return; }
    if (totalJp > maxJp) { toast.error(`Total JP (${totalJp}) melebihi kapasitas (${maxJp})`); return; }

    setGenerating(true);
    setResult(null);
    try {
      const res = await generateJadwal({
        kelasId,
        assignments: assignments.map(a => ({
          mapelId: a.mapelId,
          mapelNama: mapelList.find(m => m.id === a.mapelId)?.nama || '-',
          guruId: a.guruId,
          guruNama: guruList.find(g => g.id === a.guruId)?.nama || '-',
          jpPerWeek: a.jpPerWeek,
        })),
        constraints: constraints.filter(c => c.jpList.length > 0),
        hariAktif: settings.hariAktif,
        jpPerDay,
        clearExisting,
        slots: jpSlots.map(s => ({ jp: s.jp, mulai: s.mulai, selesai: s.selesai, isSpecial: false })),
      });
      setResult(res);
      if (res.success) {
        onGenerated();
      }
    } catch {
      toast.error('Gagal generate jadwal');
    } finally {
      setGenerating(false);
    }
  };

  const handleClose = () => {
    setResult(null);
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={v => !v && handleClose()}>
      <DialogContent className="max-w-2xl max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            Generate Jadwal Otomatis
          </DialogTitle>
          <DialogDescription>
            Kelas: <strong>{kelasLabel}</strong> · Kapasitas: {maxJp} JP/minggu ({settings.hariAktif.length} hari × {jpPerDay} JP)
          </DialogDescription>
        </DialogHeader>

        <ScrollArea className="flex-1 -mx-6 px-6 max-h-[60vh]">
          <div className="space-y-6 pb-4">
            {/* Result display */}
            {result && (
              <div className={`rounded-lg border p-4 ${result.conflicts.length > 0 ? 'bg-amber-50 border-amber-200' : 'bg-emerald-50 border-emerald-200'}`}>
                <div className="flex items-start gap-2">
                  {result.conflicts.length > 0 ? (
                    <AlertTriangle className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
                  ) : (
                    <CheckCircle2 className="h-5 w-5 text-emerald-600 flex-shrink-0 mt-0.5" />
                  )}
                  <div>
                    <p className="font-semibold text-sm">{result.message}</p>
                    {result.conflicts.length > 0 && (
                      <ul className="mt-2 space-y-1">
                        {result.conflicts.map((c, i) => (
                          <li key={i} className="text-xs text-amber-700">• {c}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                </div>
              </div>
            )}

            {/* Assignments */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">Daftar Mata Pelajaran & Guru</Label>
                <Badge variant="outline" className={totalJp > maxJp ? 'border-destructive text-destructive' : ''}>
                  {totalJp}/{maxJp} JP
                </Badge>
              </div>

              {assignments.length === 0 && (
                <div className="text-center py-6 text-muted-foreground text-sm border border-dashed rounded-lg">
                  Belum ada mapel. Klik tombol di bawah untuk menambahkan.
                </div>
              )}

              <div className="space-y-2">
                {assignments.map((asgn, idx) => (
                  <div key={idx} className="flex items-center gap-2 p-2.5 rounded-lg border border-border bg-card">
                    <div className="flex-1 min-w-0">
                      <Select value={asgn.mapelId} onValueChange={v => updateAssignment(idx, 'mapelId', v)}>
                        <SelectTrigger className="h-8 text-xs">
                          <SelectValue placeholder="Mapel" />
                        </SelectTrigger>
                        <SelectContent>
                          {mapelList.map(m => (
                            <SelectItem key={m.id} value={m.id}>{m.nama}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="flex-1 min-w-0">
                      <Select value={asgn.guruId} onValueChange={v => updateAssignment(idx, 'guruId', v)}>
                        <SelectTrigger className="h-8 text-xs">
                          <SelectValue placeholder="Guru" />
                        </SelectTrigger>
                        <SelectContent>
                          {guruList.map(g => (
                            <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="w-20">
                      <Input
                        type="number" min={1} max={20}
                        value={asgn.jpPerWeek}
                        onChange={e => updateAssignment(idx, 'jpPerWeek', Number(e.target.value) || 1)}
                        className="h-8 text-xs text-center"
                      />
                    </div>
                    <span className="text-xs text-muted-foreground whitespace-nowrap">JP</span>
                    <button onClick={() => removeAssignment(idx)} className="h-8 w-8 flex items-center justify-center rounded hover:bg-destructive/10">
                      <Trash2 className="h-3.5 w-3.5 text-destructive" />
                    </button>
                  </div>
                ))}
              </div>

              <Button variant="outline" size="sm" className="gap-2 w-full" onClick={addAssignment}>
                <Plus className="h-3.5 w-3.5" /> Tambah Mapel
              </Button>
            </div>

            {/* Constraints */}
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <ShieldAlert className="h-4 w-4 text-muted-foreground" />
                <Label className="text-sm font-semibold">Kendala Guru (Opsional)</Label>
              </div>
              <p className="text-xs text-muted-foreground">
                Tentukan hari & jam dimana guru tidak bisa mengajar.
              </p>

              {constraints.map((con, idx) => (
                <div key={idx} className="p-3 rounded-lg border border-border bg-card space-y-2">
                  <div className="flex items-center gap-2">
                    <div className="flex-1">
                      <Select value={con.guruId} onValueChange={v => updateConstraint(idx, 'guruId', v)}>
                        <SelectTrigger className="h-8 text-xs">
                          <SelectValue placeholder="Guru" />
                        </SelectTrigger>
                        <SelectContent>
                          {guruList.map(g => (
                            <SelectItem key={g.id} value={g.id}>{g.nama}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="w-28">
                      <Select value={con.hari} onValueChange={v => updateConstraint(idx, 'hari', v)}>
                        <SelectTrigger className="h-8 text-xs">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {settings.hariAktif.map(h => (
                            <SelectItem key={h} value={h}>{h}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <button onClick={() => removeConstraint(idx)} className="h-8 w-8 flex items-center justify-center rounded hover:bg-destructive/10">
                      <Trash2 className="h-3.5 w-3.5 text-destructive" />
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {jpSlots.map(s => {
                      const active = con.jpList.includes(s.jp);
                      return (
                        <button
                          key={s.jp}
                          onClick={() => toggleJpInConstraint(idx, s.jp)}
                          className={`px-2 py-1 rounded text-xs font-medium border transition-all ${
                            active
                              ? 'bg-destructive text-destructive-foreground border-destructive'
                              : 'bg-card text-muted-foreground border-border hover:border-destructive/40'
                          }`}
                        >
                          JP {s.jp}
                        </button>
                      );
                    })}
                  </div>
                  {con.jpList.length === 0 && (
                    <p className="text-[11px] text-muted-foreground">Klik JP di atas untuk menandai jam yang tidak tersedia</p>
                  )}
                </div>
              ))}

              <Button variant="outline" size="sm" className="gap-2" onClick={addConstraint}>
                <Plus className="h-3.5 w-3.5" /> Tambah Kendala
              </Button>
            </div>

            {/* Options */}
            <div className="flex items-center justify-between p-3 rounded-lg border border-border bg-card">
              <div>
                <p className="text-sm font-medium">Hapus jadwal lama</p>
                <p className="text-xs text-muted-foreground">Hapus semua jadwal kelas ini sebelum generate</p>
              </div>
              <Switch checked={clearExisting} onCheckedChange={setClearExisting} />
            </div>
          </div>
        </ScrollArea>

        <DialogFooter className="border-t pt-4">
          <Button variant="outline" onClick={handleClose} disabled={generating}>Tutup</Button>
          <Button onClick={handleGenerate} disabled={generating || assignments.length === 0} className="gap-2">
            {generating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
            {generating ? 'Generating...' : 'Generate Jadwal'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetFooter } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { Plus, Trash2, Clock, RotateCcw, ChevronDown } from 'lucide-react';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { toast } from 'sonner';

const ALL_DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const DAY_SHORT: Record<string, string> = {
  Senin: 'Sen', Selasa: 'Sel', Rabu: 'Rab', Kamis: 'Kam', Jumat: 'Jum', Sabtu: 'Sab',
};

export type SpecialSlotType = 'istirahat' | 'upacara' | 'sholat';

export interface JpSlot {
  jp: number;
  mulai: string;
  selesai: string;
  isIstirahat?: boolean;
  slotType?: SpecialSlotType;
  label?: string;
}

export interface JadwalSettings {
  hariAktif: string[];
  durasiJp: number;
  jamMulai: string;
  slots: JpSlot[];
}

const STORAGE_KEY = 'jadwal-settings';

export const SPECIAL_SLOT_CONFIG: Record<SpecialSlotType, { icon: string; label: string; color: string; borderColor: string }> = {
  istirahat: { icon: '🍽️', label: 'Istirahat', color: 'bg-amber-50 dark:bg-amber-950/30', borderColor: 'border-amber-200 dark:border-amber-800' },
  upacara: { icon: '🏳️', label: 'Upacara', color: 'bg-blue-50 dark:bg-blue-950/30', borderColor: 'border-blue-200 dark:border-blue-800' },
  sholat: { icon: '🕌', label: 'Sholat', color: 'bg-emerald-50 dark:bg-emerald-950/30', borderColor: 'border-emerald-200 dark:border-emerald-800' },
};

export function isSpecialSlot(s: JpSlot): boolean {
  return !!(s.isIstirahat || s.slotType);
}

export function getSlotType(s: JpSlot): SpecialSlotType | 'jp' {
  if (s.slotType) return s.slotType;
  if (s.isIstirahat) return 'istirahat';
  return 'jp';
}

export function getDefaultSettings(): JadwalSettings {
  return {
    hariAktif: ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat'],
    durasiJp: 40,
    jamMulai: '07:00',
    slots: generateDefaultSlots(),
  };
}

function generateDefaultSlots(): JpSlot[] {
  const slots: JpSlot[] = [];
  let current = '07:00';
  // Upacara first (Senin only)
  slots.push({ jp: 0, mulai: current, selesai: addMinutes(current, 30), isIstirahat: true, slotType: 'upacara', label: 'Upacara' });
  current = addMinutes(current, 30);

  for (let i = 1; i <= 10; i++) {
    const selesai = addMinutes(current, 40);
    slots.push({ jp: i, mulai: current, selesai });
    current = selesai;
    if (i === 3) {
      slots.push({ jp: 0, mulai: current, selesai: addMinutes(current, 15), isIstirahat: true, slotType: 'istirahat', label: 'Istirahat' });
      current = addMinutes(current, 15);
    }
    if (i === 6) {
      slots.push({ jp: 0, mulai: current, selesai: addMinutes(current, 30), isIstirahat: true, slotType: 'sholat', label: 'Sholat & Istirahat' });
      current = addMinutes(current, 30);
    }
  }
  return slots;
}

export function loadSettings(): JadwalSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      // Migrate old format: ensure slotType is set
      if (parsed.slots) {
        for (const s of parsed.slots) {
          if (s.isIstirahat && !s.slotType) {
            s.slotType = 'istirahat';
          }
        }
      }
      return parsed;
    }
  } catch { /* ignore */ }
  return getDefaultSettings();
}

export function saveSettings(s: JadwalSettings) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(s));
}

export function addMinutes(time: string, mins: number): string {
  const [h, m] = time.split(':').map(Number);
  const total = h * 60 + m + mins;
  const hh = Math.floor(total / 60) % 24;
  const mm = total % 60;
  return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
}

export function timeDiffMinutes(start: string, end: string): number {
  const [h1, m1] = start.split(':').map(Number);
  const [h2, m2] = end.split(':').map(Number);
  return (h2 * 60 + m2) - (h1 * 60 + m1);
}

interface Props {
  open: boolean;
  onClose: () => void;
  onSave: (settings: JadwalSettings) => void;
  initialSettings: JadwalSettings;
}

export default function PengaturanJadwalSheet({ open, onClose, onSave, initialSettings }: Props) {
  const [hariAktif, setHariAktif] = useState<string[]>(initialSettings.hariAktif);
  const [durasiJp, setDurasiJp] = useState(initialSettings.durasiJp);
  const [jamMulai, setJamMulai] = useState(initialSettings.jamMulai);
  const [slots, setSlots] = useState<JpSlot[]>(initialSettings.slots);

  useEffect(() => {
    if (open) {
      setHariAktif(initialSettings.hariAktif);
      setDurasiJp(initialSettings.durasiJp);
      setJamMulai(initialSettings.jamMulai);
      setSlots(initialSettings.slots);
    }
  }, [open, initialSettings]);

  const toggleDay = (day: string) => {
    setHariAktif(prev =>
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const regenerateSlots = useCallback(() => {
    // Preserve special slots structure, recalculate times
    const newSlots: JpSlot[] = [];
    let current = jamMulai;

    for (const slot of slots) {
      if (isSpecialSlot(slot)) {
        const dur = timeDiffMinutes(slot.mulai, slot.selesai);
        newSlots.push({ ...slot, mulai: current, selesai: addMinutes(current, dur) });
        current = addMinutes(current, dur);
      } else {
        newSlots.push({ ...slot, mulai: current, selesai: addMinutes(current, durasiJp) });
        current = addMinutes(current, durasiJp);
      }
    }
    setSlots(newSlots);
  }, [jamMulai, durasiJp, slots]);

  const addSpecialSlotAfter = (index: number, type: SpecialSlotType) => {
    const afterSlot = slots[index];
    if (!afterSlot) return;
    const config = SPECIAL_SLOT_CONFIG[type];
    const defaultDur = type === 'upacara' ? 30 : type === 'sholat' ? 30 : 15;
    const newSlot: JpSlot = {
      jp: 0,
      mulai: afterSlot.selesai,
      selesai: addMinutes(afterSlot.selesai, defaultDur),
      isIstirahat: true,
      slotType: type,
      label: config.label,
    };
    const updated = [...slots];
    updated.splice(index + 1, 0, newSlot);
    recalcFrom(updated, index + 2, durasiJp);
    setSlots(updated);
  };

  const addSpecialSlotAtStart = (type: SpecialSlotType) => {
    const config = SPECIAL_SLOT_CONFIG[type];
    const defaultDur = type === 'upacara' ? 30 : type === 'sholat' ? 30 : 15;
    const newSlot: JpSlot = {
      jp: 0,
      mulai: jamMulai,
      selesai: addMinutes(jamMulai, defaultDur),
      isIstirahat: true,
      slotType: type,
      label: config.label,
    };
    const updated = [newSlot, ...slots];
    recalcFrom(updated, 1, durasiJp);
    setSlots(updated);
  };

  const removeSlot = (index: number) => {
    const updated = [...slots];
    updated.splice(index, 1);
    if (index > 0) recalcFrom(updated, index, durasiJp);
    else if (updated.length > 0) {
      // Recalc from beginning
      let current = jamMulai;
      for (let i = 0; i < updated.length; i++) {
        const dur = isSpecialSlot(updated[i]) ? timeDiffMinutes(updated[i].mulai, updated[i].selesai) : durasiJp;
        updated[i].mulai = current;
        updated[i].selesai = addMinutes(current, dur);
        current = updated[i].selesai;
      }
    }
    // Renumber JPs
    let jpN = 1;
    for (const s of updated) {
      if (!isSpecialSlot(s)) {
        s.jp = jpN++;
      }
    }
    setSlots(updated);
  };

  const addJp = () => {
    const last = slots[slots.length - 1];
    const start = last ? last.selesai : jamMulai;
    const jpNum = slots.filter(s => !isSpecialSlot(s)).length + 1;
    setSlots([...slots, { jp: jpNum, mulai: start, selesai: addMinutes(start, durasiJp) }]);
  };

  const updateSpecialDuration = (index: number, mins: number) => {
    const updated = [...slots];
    updated[index] = { ...updated[index], selesai: addMinutes(updated[index].mulai, mins) };
    recalcFrom(updated, index + 1, durasiJp);
    setSlots(updated);
  };

  const updateSpecialLabel = (index: number, label: string) => {
    const updated = [...slots];
    updated[index] = { ...updated[index], label };
    setSlots(updated);
  };

  const handleSave = () => {
    if (hariAktif.length === 0) {
      toast.error('Pilih minimal 1 hari aktif');
      return;
    }
    const settings: JadwalSettings = { hariAktif, durasiJp, jamMulai, slots };
    saveSettings(settings);
    onSave(settings);
    toast.success('Pengaturan jadwal berhasil disimpan');
    onClose();
  };

  const totalJp = slots.filter(s => !isSpecialSlot(s)).length;
  const lastSlot = slots[slots.length - 1];

  return (
    <Sheet open={open} onOpenChange={v => !v && onClose()}>
      <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2">
            <Clock className="h-5 w-5 text-primary" />
            Pengaturan Jadwal
          </SheetTitle>
        </SheetHeader>

        <div className="space-y-6 py-4">
          {/* Hari Aktif */}
          <div className="space-y-3">
            <Label className="text-sm font-semibold">Hari Aktif</Label>
            <div className="flex flex-wrap gap-2">
              {ALL_DAYS.map(day => (
                <button
                  key={day}
                  onClick={() => toggleDay(day)}
                  className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${
                    hariAktif.includes(day)
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'bg-card text-muted-foreground border-border hover:border-primary/40'
                  }`}
                >
                  {DAY_SHORT[day]}
                </button>
              ))}
            </div>
          </div>

          <Separator />

          {/* Durasi & Jam Mulai */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label className="text-sm font-semibold">Durasi per JP</Label>
              <div className="flex items-center gap-2">
                <Input
                  type="number"
                  min={20}
                  max={90}
                  value={durasiJp}
                  onChange={e => setDurasiJp(Number(e.target.value) || 40)}
                  className="w-20"
                />
                <span className="text-sm text-muted-foreground">menit</span>
              </div>
            </div>
            <div className="space-y-2">
              <Label className="text-sm font-semibold">Jam Mulai</Label>
              <Input type="time" value={jamMulai} onChange={e => setJamMulai(e.target.value)} />
            </div>
          </div>

          <Button variant="outline" size="sm" className="gap-2" onClick={regenerateSlots}>
            <RotateCcw className="h-3.5 w-3.5" />
            Hitung Ulang Jam
          </Button>

          <Separator />

          {/* JP Slots */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-semibold">
                Jam Pelajaran ({totalJp} JP)
              </Label>
              {lastSlot && (
                <span className="text-xs text-muted-foreground">
                  Selesai {lastSlot.selesai}
                </span>
              )}
            </div>

            <div className="space-y-1.5">
              {slots.map((slot, idx) => (
                <SlotRow
                  key={`${idx}-${slot.jp}-${getSlotType(slot)}`}
                  slot={slot}
                  index={idx}
                  durasiJp={durasiJp}
                  onRemove={() => removeSlot(idx)}
                  onAddSpecial={(type) => addSpecialSlotAfter(idx, type)}
                  onUpdateDuration={(mins) => updateSpecialDuration(idx, mins)}
                  onUpdateLabel={(label) => updateSpecialLabel(idx, label)}
                  canAddSpecial={!isSpecialSlot(slot) && idx < slots.length - 1 && !isSpecialSlot(slots[idx + 1])}
                />
              ))}
            </div>

            <div className="flex gap-2">
              <Button variant="outline" size="sm" className="flex-1 gap-2" onClick={addJp}>
                <Plus className="h-3.5 w-3.5" />
                Tambah JP
              </Button>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm" className="gap-1">
                    <Plus className="h-3.5 w-3.5" />
                    Sisipkan
                    <ChevronDown className="h-3 w-3" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuItem onClick={() => addSpecialSlotAtStart('upacara')}>
                    🏳️ Upacara <span className="text-xs text-muted-foreground ml-1">(Khusus Senin)</span>
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => {
                    const lastIdx = slots.length - 1;
                    if (lastIdx >= 0) addSpecialSlotAfter(lastIdx, 'istirahat');
                    else addSpecialSlotAtStart('istirahat');
                  }}>
                    🍽️ Istirahat
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => {
                    const lastIdx = slots.length - 1;
                    if (lastIdx >= 0) addSpecialSlotAfter(lastIdx, 'sholat');
                    else addSpecialSlotAtStart('sholat');
                  }}>
                    🕌 Sholat
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
        </div>

        <SheetFooter className="pt-4 border-t border-border">
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSave}>Simpan Pengaturan</Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

function recalcFrom(arr: JpSlot[], fromIndex: number, durasiJp: number) {
  for (let i = fromIndex; i < arr.length; i++) {
    const prev = arr[i - 1];
    if (!prev) continue;
    const dur = isSpecialSlot(arr[i]) ? timeDiffMinutes(arr[i].mulai, arr[i].selesai) : durasiJp;
    arr[i].mulai = prev.selesai;
    arr[i].selesai = addMinutes(prev.selesai, dur);
  }
}

function SlotRow({
  slot, index, durasiJp, onRemove, onAddSpecial, onUpdateDuration, onUpdateLabel, canAddSpecial,
}: {
  slot: JpSlot;
  index: number;
  durasiJp: number;
  onRemove: () => void;
  onAddSpecial: (type: SpecialSlotType) => void;
  onUpdateDuration: (mins: number) => void;
  onUpdateLabel: (label: string) => void;
  canAddSpecial: boolean;
}) {
  const type = getSlotType(slot);

  if (type !== 'jp') {
    const config = SPECIAL_SLOT_CONFIG[type];
    const dur = timeDiffMinutes(slot.mulai, slot.selesai);
    return (
      <div className={`flex items-center gap-2 px-3 py-2 rounded-lg border ${config.color} ${config.borderColor}`}>
        <div className="flex-1 flex items-center gap-2 flex-wrap">
          <span className="text-sm">{config.icon}</span>
          <Input
            value={slot.label || config.label}
            onChange={e => onUpdateLabel(e.target.value)}
            className="h-7 text-xs font-semibold w-32 bg-transparent border-none shadow-none px-1"
          />
          <span className="text-xs text-muted-foreground">{slot.mulai} – {slot.selesai}</span>
          <div className="flex items-center gap-1 ml-auto">
            <Input
              type="number"
              min={5}
              max={60}
              value={dur}
              onChange={e => onUpdateDuration(Number(e.target.value) || 15)}
              className="w-14 h-7 text-xs"
            />
            <span className="text-xs text-muted-foreground">mnt</span>
          </div>
        </div>
        <button onClick={onRemove} className="h-6 w-6 flex items-center justify-center rounded hover:bg-destructive/10 transition-colors">
          <Trash2 className="h-3 w-3 text-destructive" />
        </button>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-card border border-border hover:border-primary/30 transition-colors group">
      <span className="text-xs font-bold text-primary w-10">JP {slot.jp}</span>
      <span className="text-sm text-foreground font-medium">{slot.mulai} – {slot.selesai}</span>
      <div className="ml-auto flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        {canAddSpecial && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="h-6 px-2 rounded text-xs text-muted-foreground hover:bg-accent hover:text-foreground transition-colors">
                + Sisip
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-[140px]">
              <DropdownMenuItem onClick={() => onAddSpecial('istirahat')}>🍽️ Istirahat</DropdownMenuItem>
              <DropdownMenuItem onClick={() => onAddSpecial('sholat')}>🕌 Sholat</DropdownMenuItem>
              <DropdownMenuItem onClick={() => onAddSpecial('upacara')}>🏳️ Upacara</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
        <button onClick={onRemove} className="h-6 w-6 flex items-center justify-center rounded hover:bg-destructive/10 transition-colors">
          <Trash2 className="h-3 w-3 text-destructive" />
        </button>
      </div>
    </div>
  );
}

import { Label } from '@/components/ui/label';
import { useIndonesiaRegions } from '@/lib/useIndonesiaRegions';
import SearchableSelect from './SearchableSelect';

interface Props {
  provinsi: string;
  kabupaten: string;
  kecamatan: string;
  kelurahan: string;
  onKabupatenChange: (kabupaten: string, kecamatan: string, kelurahan: string) => void;
  onKecamatanChange: (kecamatan: string, kelurahan: string) => void;
  onKelurahanChange: (kelurahan: string) => void;
}

export default function CascadingAddressFields({
  provinsi, kabupaten, kecamatan, kelurahan,
  onKabupatenChange, onKecamatanChange, onKelurahanChange,
}: Props) {
  const {
    kabupatenList, kecamatanList, kelurahanList,
    loadingKabupaten, loadingKecamatan, loadingKelurahan,
  } = useIndonesiaRegions(provinsi, kabupaten, kecamatan);

  return (
    <>
      {/* Kabupaten | Kecamatan */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Kabupaten/Kota</Label>
          <SearchableSelect
            options={kabupatenList}
            value={kabupaten}
            onChange={(v) => onKabupatenChange(v, '', '')}
            placeholder="Pilih Kabupaten/Kota"
            disabledPlaceholder="Pilih provinsi dahulu"
            disabled={!provinsi}
            loading={loadingKabupaten}
          />
        </div>
        <div className="space-y-2">
          <Label>Kecamatan</Label>
          <SearchableSelect
            options={kecamatanList}
            value={kecamatan}
            onChange={(v) => onKecamatanChange(v, '')}
            placeholder="Pilih Kecamatan"
            disabledPlaceholder="Pilih kabupaten dahulu"
            disabled={!kabupaten}
            loading={loadingKecamatan}
          />
        </div>
      </div>

      {/* Kelurahan — full width for readability */}
      <div className="space-y-2">
        <Label>Kelurahan/Desa</Label>
        <SearchableSelect
          options={kelurahanList}
          value={kelurahan}
          onChange={onKelurahanChange}
          placeholder="Pilih Kelurahan/Desa"
          disabledPlaceholder="Pilih kecamatan dahulu"
          disabled={!kecamatan}
          loading={loadingKelurahan}
        />
      </div>
    </>
  );
}

